insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '诗篇', 19, 104, 30, 'あなたが御霊を送られると彼らは創造されます。あなたは地の面を新しくされます。'),
('JPN', '诗篇', 19, 104, 31, '主の栄光がとこしえにありますように。主がご自分のみわざを喜ばれますように。'),
('JPN', '诗篇', 19, 104, 32, '主が地に目を注がれると地は震え山々に触れられるとそれは煙を上げます。'),
('JPN', '诗篇', 19, 104, 33, '私はいのちの限り主に歌い生きるかぎり私の神をほめ歌います。'),
('JPN', '诗篇', 19, 104, 34, '私の心の思いがみこころにかないますように。私は主を喜びます。'),
('JPN', '诗篇', 19, 104, 35, '罪人らが地から絶え果て悪しき者どもがもはやいなくなりますように。わがたましいよ主をほめたたえよ。ハレルヤ。'),
('JPN', '诗篇', 19, 105, 1, '主に感謝し御名を呼び求めよ。そのみわざを諸国の民の間に知らせよ。'),
('JPN', '诗篇', 19, 105, 2, '主に歌え。主にほめ歌を歌え。そのすべての奇しいみわざを語れ。'),
('JPN', '诗篇', 19, 105, 3, '主の聖なる御名を誇りとせよ。主を慕い求める者たちの心よ喜べ。'),
('JPN', '诗篇', 19, 105, 4, '主とその御力を尋ね求めよ。絶えず御顔を慕い求めよ。'),
('JPN', '诗篇', 19, 105, 5, '主が行われた奇しいみわざを思い起こせ。その奇跡と御口のさばきを。'),
('JPN', '诗篇', 19, 105, 6, '主のしもべアブラハムの裔よ。主に選ばれた者ヤコブの子らよ。'),
('JPN', '诗篇', 19, 105, 7, 'この方こそ私たちの神主。そのさばきは全地にわたる。'),
('JPN', '诗篇', 19, 105, 8, '主はご自分の契約をとこしえに覚えておられる。命じられたみことばを千代までも。'),
('JPN', '诗篇', 19, 105, 9, 'それはアブラハムと結んだ契約イサクへの誓い。'),
('JPN', '诗篇', 19, 105, 10, '主はそれをヤコブへの定めとして立てられた。イスラエルへの永遠の契約として。'),
('JPN', '诗篇', 19, 105, 11, 'そのとき主は言われた。「わたしはあなたにカナンの地を与える。あなたがたへのゆずりの地として。」'),
('JPN', '诗篇', 19, 105, 12, 'そのころ彼らの数は少なく実にわずかでそこでは寄留者であった。'),
('JPN', '诗篇', 19, 105, 13, '彼らは国から国へ一つの王国からほかの民のところへと渡り歩いた。'),
('JPN', '诗篇', 19, 105, 14, 'しかし主はだれにも彼らを虐げさせず彼らのために王たちを戒められた。'),
('JPN', '诗篇', 19, 105, 15, '「わたしの油注がれた者たちに触れるな。わたしの預言者たちに危害を加えるな。」'),
('JPN', '诗篇', 19, 105, 16, 'こうして主は飢饉を地の上に招きパンの蓄えをことごとくなくされた。'),
('JPN', '诗篇', 19, 105, 17, '主は一人の人を彼らに先駆けて送られた。ヨセフが奴隷に売られたのだ。'),
('JPN', '诗篇', 19, 105, 18, 'ヨセフの足は苦しみのかせをはめられその首は鉄のかせに入れられた。'),
('JPN', '诗篇', 19, 105, 19, '彼のことばがそのとおりになるときまで主のことばは彼を錬った。'),
('JPN', '诗篇', 19, 105, 20, '王は使いを送ってヨセフを解放した。諸国の民の支配者はそうして彼を自由にした。'),
('JPN', '诗篇', 19, 105, 21, '主人である王はヨセフに自分の家を任せ自分の全財産を治める者とした。'),
('JPN', '诗篇', 19, 105, 22, 'それはヨセフが意のままに王の高官を縛り王の長老たちに知恵を与えるためであった。'),
('JPN', '诗篇', 19, 105, 23, 'イスラエルもエジプトにやって来てヤコブはハムの地に寄留することになった。'),
('JPN', '诗篇', 19, 105, 24, '主はご自分の民を大いに増やし彼らの敵よりも強くされた。'),
('JPN', '诗篇', 19, 105, 25, '主は人々の心を変えてご自分の民を憎ませご自分のしもべたちを悪賢く扱うようにされた。'),
('JPN', '诗篇', 19, 105, 26, '主はそのしもべモーセとご自分が選んだアロンを遣わされた。'),
('JPN', '诗篇', 19, 105, 27, '彼らは人々の間で主の数々のしるしを行いハムの地でもろもろの奇跡を行った。'),
('JPN', '诗篇', 19, 105, 28, '主は闇を送って暗くされた。人々は主のことばに逆らわなかった。'),
('JPN', '诗篇', 19, 105, 29, '主が彼らの水を血に変えられたのでその魚は死んだ。'),
('JPN', '诗篇', 19, 105, 30, '彼らの地には蛙が群がった。王族たちの奥の間にまでも。'),
('JPN', '诗篇', 19, 105, 31, '主が命じられるとあぶの群れが来てぶよが国中いたるところに湧いて出た。'),
('JPN', '诗篇', 19, 105, 32, '主は雨に代えて雹を彼らに降らせ燃える火を彼らの地に下された。'),
('JPN', '诗篇', 19, 105, 33, '主は彼らのぶどうの木といちじくの木を打ち彼らの国の木々を砕かれた。'),
('JPN', '诗篇', 19, 105, 34, '主が命じられるといなごが来た。若いいなごがしかも無数に。'),
('JPN', '诗篇', 19, 105, 35, 'それが彼らの国の緑を食い尽くし彼らの大地の実りを食い尽くした。'),
('JPN', '诗篇', 19, 105, 36, '主は彼らの国の長子をことごとく打たれた。彼らのすべての力の初穂を。'),
('JPN', '诗篇', 19, 105, 37, '主は銀と金を持たせて御民を導き出された。主の諸部族の中でよろける者は一人もなかった。'),
('JPN', '诗篇', 19, 105, 38, 'エジプトは彼らが出て行ったとき喜んだ。エジプトに彼らへの恐れが下ったからだ。'),
('JPN', '诗篇', 19, 105, 39, '主は雲を広げて仕切りの幕とし夜には火を与えて照らされた。'),
('JPN', '诗篇', 19, 105, 40, '民が願い求めると主はうずらをもたらしまた天からのパンで彼らを満ち足らせた。'),
('JPN', '诗篇', 19, 105, 41, '主が岩を開かれると水がほとばしり川となって砂漠を流れた。'),
('JPN', '诗篇', 19, 105, 42, 'これらのことは主がそのしもべアブラハムへの聖なることばを覚えておられたからである。'),
('JPN', '诗篇', 19, 105, 43, '主は御民を喜びのうちに導き出された。その選ばれた民を喜びの叫びのうちに。'),
('JPN', '诗篇', 19, 105, 44, '主は彼らに国々の地を与えられた。国々の民の労苦の実を彼らが受け継ぐために。'),
('JPN', '诗篇', 19, 105, 45, 'これは彼らが主のおきてを守りそのみおしえを保つためである。ハレルヤ。'),
('JPN', '诗篇', 19, 106, 1, 'ハレルヤ。主に感謝せよ。主はまことにいつくしみ深い。その恵みはとこしえまで。'),
('JPN', '诗篇', 19, 106, 2, 'だれが主の大能のわざを告げ主の誉れのすべてを語り聞かせることができよう。'),
('JPN', '诗篇', 19, 106, 3, '幸いなことよさばきを守る人々いかなるときにも正義を行う人は。'),
('JPN', '诗篇', 19, 106, 4, '主よあなたが御民を受け入れてくださるときに私を心に留めあなたの御救いのときに私を顧みてください。'),
('JPN', '诗篇', 19, 106, 5, 'そのとき私はあなたに選ばれた者たちの幸せを見あなたの国民の喜びを喜びとしあなたのゆずりの民とともに誇ることができます。'),
('JPN', '诗篇', 19, 106, 6, '私たちは先祖と同じように罪を犯し不義を行い悪を行ってきました。'),
('JPN', '诗篇', 19, 106, 7, '私たちの先祖はエジプトであなたの奇しいみわざを悟らずあなたの豊かな恵みを思い出さずかえって海のほとり葦の海で逆らいました。'),
('JPN', '诗篇', 19, 106, 8, 'しかし主は御名のゆえに彼らを救われた。ご自分の力を知らせるために。'),
('JPN', '诗篇', 19, 106, 9, '主が葦の海を叱ると海は干上がり主は彼らに深みの底を歩かせられた。まるで荒野を行くように。'),
('JPN', '诗篇', 19, 106, 10, '主は憎む者の手から彼らを救い敵の手から彼らを贖われた。'),
('JPN', '诗篇', 19, 106, 11, '水は彼らの敵を包み彼らの一人さえも残らなかった。'),
('JPN', '诗篇', 19, 106, 12, 'すると彼らはみことばを信じ主への賛美を歌った。'),
('JPN', '诗篇', 19, 106, 13, 'しかし彼らはすぐにみわざを忘れ主のさとしを待ち望まなかった。'),
('JPN', '诗篇', 19, 106, 14, '彼らは荒野で激しい欲望にかられ荒れ地で神を試みた。'),
('JPN', '诗篇', 19, 106, 15, 'そこで主は彼らにその欲するものを与え彼らのいのちを衰えさせた。'),
('JPN', '诗篇', 19, 106, 16, '彼らが宿営で主の聖徒モーセとアロンをねたんだとき'),
('JPN', '诗篇', 19, 106, 17, '地は口を開けダタンを吞み込みアビラムの仲間を包んでしまった。'),
('JPN', '诗篇', 19, 106, 18, 'その仲間の間で火が燃え上がり炎が悪者どもを焼き尽くした。'),
('JPN', '诗篇', 19, 106, 19, '彼らはホレブで子牛を造り鋳物の像を拝んだ。'),
('JPN', '诗篇', 19, 106, 20, 'こうして彼らは自分たちの神の栄光を草を食らう雄牛の像と取り替えた。'),
('JPN', '诗篇', 19, 106, 21, '彼らは自分たちの救い主である神を忘れた。エジプトで大いなることをなさった方を。'),
('JPN', '诗篇', 19, 106, 22, 'ハムの地で奇しいみわざを葦の海のほとりで恐るべきみわざを行われた方を。'),
('JPN', '诗篇', 19, 106, 23, 'それで神は「彼らを根絶やしにする」と言われた。もし神に選ばれた人モーセが滅ぼそうとする激しい憤りを収めていただくために御前の破れに立たなかったならどうなっていたことか。'),
('JPN', '诗篇', 19, 106, 24, 'しかも彼らは尊い地を蔑み神のみことばを信じず'),
('JPN', '诗篇', 19, 106, 25, '自分たちの天幕の中で不平を言い主の御声を聞かなかった。'),
('JPN', '诗篇', 19, 106, 26, 'それで主は彼らにこう誓われた。彼らを荒野で打ち倒し'),
('JPN', '诗篇', 19, 106, 27, 'その子孫を国々の間に投げ散らし彼らを地にあまねくまき散らそうと。'),
('JPN', '诗篇', 19, 106, 28, '彼らはまたバアル・ペオルとくびきをともにし死者へのいけにえを食べた。'),
('JPN', '诗篇', 19, 106, 29, 'こうして自らの行いによって御怒りを引き起こし彼らに主の罰が下った。'),
('JPN', '诗篇', 19, 106, 30, 'そのときピネハスが立ち仲立ちをしたので主の罰は終わった。'),
('JPN', '诗篇', 19, 106, 31, 'このことは代々にわたり永遠に彼の義と認められた。'),
('JPN', '诗篇', 19, 106, 32, '彼らはメリバの水のほとりで主を怒らせた。モーセは彼らのゆえにわざわいを被った。'),
('JPN', '诗篇', 19, 106, 33, '彼らが主の御霊に逆らったとき彼が軽率なことを口にしたのである。'),
('JPN', '诗篇', 19, 106, 34, '彼らは主が命じられたのに諸国の民を滅ぼさず'),
('JPN', '诗篇', 19, 106, 35, 'かえって異邦の民と交わりその習わしに倣い'),
('JPN', '诗篇', 19, 106, 36, 'その偶像に仕えた。それが彼らにとって罠となった。'),
('JPN', '诗篇', 19, 106, 37, '彼らは自分たちの息子と娘を悪霊へのいけにえとして献げ'),
('JPN', '诗篇', 19, 106, 38, '咎なき者の血を流した。彼らの息子や娘たちの血それをカナンの偶像のいけにえとした。こうしてその国土は血で汚された。'),
('JPN', '诗篇', 19, 106, 39, 'このように彼らはその行いによって自分を汚しそのわざによって姦淫を犯した。'),
('JPN', '诗篇', 19, 106, 40, 'それで主の怒りは御民に向かって燃え上がり主はご自分のゆずりの民を忌み嫌われた。'),
('JPN', '诗篇', 19, 106, 41, '主は彼らを国々の手に渡されたので彼らを憎む者たちが彼らを支配した。'),
('JPN', '诗篇', 19, 106, 42, '敵どもが彼らを虐げたので彼らは征服され敵の手に下った。'),
('JPN', '诗篇', 19, 106, 43, '主は幾たびとなく彼らを救い出されたが彼らは相謀って逆らい自分たちの不義の中におぼれた。'),
('JPN', '诗篇', 19, 106, 44, 'それでも彼らの叫びを聞いたとき主は彼らの苦しみに目を留められた。'),
('JPN', '诗篇', 19, 106, 45, '主は彼らのためにご自分の契約を思い起こし豊かな恵みにしたがって彼らをあわれまれた。'),
('JPN', '诗篇', 19, 106, 46, '彼らを捕らえ移したすべての者たちから彼らがあわれまれるようにしてくださった。'),
('JPN', '诗篇', 19, 106, 47, '私たちの神主よ私たちをお救いください。国々から私たちを集めてください。あなたの聖なる御名に感謝しあなたの誉れを勝ち誇るために。'),
('JPN', '诗篇', 19, 106, 48, 'ほむべきかなイスラエルの神主。とこしえからとこしえまで。民はみな「アーメン」と言え。ハレルヤ。'),
('JPN', '诗篇', 19, 107, 1, '「主に感謝せよ。主はまことにいつくしみ深い。その恵みはとこしえまで。」'),
('JPN', '诗篇', 19, 107, 2, '主に贖われた者はそう言え。主は彼らを敵の手から贖い'),
('JPN', '诗篇', 19, 107, 3, '国々から彼らを集められた。東からも西からも北からも南からも。'),
('JPN', '诗篇', 19, 107, 4, '彼らは荒野や荒れ地をさまよい人が住む町への道を見出せなかった。'),
('JPN', '诗篇', 19, 107, 5, '飢えと渇きによって彼らのたましいは衰え果てた。'),
('JPN', '诗篇', 19, 107, 6, 'この苦しみのときに彼らが主に向かって叫ぶと主は彼らを苦悩から救い出された。'),
('JPN', '诗篇', 19, 107, 7, '彼らをまっすぐな道に導き人が住む町へ向かわせた。'),
('JPN', '诗篇', 19, 107, 8, '主に感謝せよ。その恵みのゆえに。人の子らへの奇しいみわざのゆえに。'),
('JPN', '诗篇', 19, 107, 9, 'まことに主は渇いたたましいを満ち足らせ飢えたたましいを良いもので満たされた。'),
('JPN', '诗篇', 19, 107, 10, '闇と死の陰に座す者苦しみの鉄のかせに縛られている者'),
('JPN', '诗篇', 19, 107, 11, '彼らは神のことばに逆らいいと高き方のさとしを退けた。'),
('JPN', '诗篇', 19, 107, 12, 'それで主は苦役によって彼らの心を低くされた。彼らはよろけたがだれも助けなかった。'),
('JPN', '诗篇', 19, 107, 13, 'この苦しみのときに彼らが主に向かって叫ぶと主は彼らを苦悩から救われた。'),
('JPN', '诗篇', 19, 107, 14, '主は彼らを闇と死の陰から導き出し彼らのかせを打ち砕かれた。'),
('JPN', '诗篇', 19, 107, 15, '主に感謝せよ。その恵みのゆえに。人の子らへの奇しいみわざのゆえに。'),
('JPN', '诗篇', 19, 107, 16, 'まことに主は青銅の扉を打ち砕き鉄のかんぬきをへし折られた。'),
('JPN', '诗篇', 19, 107, 17, '愚か者は自分の背きの道のためまた咎のために苦しみを受けた。'),
('JPN', '诗篇', 19, 107, 18, 'あらゆる食物を彼らの喉は受けつけずついに死の門に至った。'),
('JPN', '诗篇', 19, 107, 19, 'この苦しみのときに彼らが主に向かって叫ぶと主は彼らを苦悩から救われた。'),
('JPN', '诗篇', 19, 107, 20, '主はみことばを送って彼らを癒やし滅びの穴から彼らを助け出された。'),
('JPN', '诗篇', 19, 107, 21, '主に感謝せよ。その恵みのゆえに。人の子らへの奇しいみわざのゆえに。'),
('JPN', '诗篇', 19, 107, 22, '感謝のいけにえを献げ喜び叫びながら主のみわざを語れ。'),
('JPN', '诗篇', 19, 107, 23, '船に乗って海に出る者大海で商いする者'),
('JPN', '诗篇', 19, 107, 24, '彼らは見た。主のみわざを深い海でその奇しいみわざを。'),
('JPN', '诗篇', 19, 107, 25, '主が命じて激しい暴風を起こされると風が波を高くした。'),
('JPN', '诗篇', 19, 107, 26, '彼らは天に上り深みに下りそのたましいはみじめにも溶け去った。'),
('JPN', '诗篇', 19, 107, 27, '彼らは酔った人のようによろめき知恵はことごとく吞み込まれた。'),
('JPN', '诗篇', 19, 107, 28, 'この苦しみのときに彼らが主に向かって叫ぶと主は彼らを苦悩から導き出された。'),
('JPN', '诗篇', 19, 107, 29, '主が嵐を鎮められると波は穏やかになった。'),
('JPN', '诗篇', 19, 107, 30, '波が凪いだので彼らは喜んだ。主は彼らをその望む港に導かれた。'),
('JPN', '诗篇', 19, 107, 31, '主に感謝せよ。その恵みのゆえに。人の子らへの奇しいみわざのゆえに。'),
('JPN', '诗篇', 19, 107, 32, '民の集会で主をあがめ長老たちの座で主を賛美せよ。'),
('JPN', '诗篇', 19, 107, 33, '主は豊かな川を荒野に水の湧き上がる所を潤いのない地に'),
('JPN', '诗篇', 19, 107, 34, '肥沃な地を不毛の土地に変えられる。そこに住む者たちの悪のゆえに。'),
('JPN', '诗篇', 19, 107, 35, '主は荒野を水のある沢に砂漠の地を水の湧き上がる所に変え'),
('JPN', '诗篇', 19, 107, 36, 'そこに飢えた者を住まわせる。彼らは人が住む町を堅く立て'),
('JPN', '诗篇', 19, 107, 37, '畑に種を蒔きぶどう畑を作り豊かな実りを得る。'),
('JPN', '诗篇', 19, 107, 38, '主が祝福されると彼らは大いに増え主はその家畜を減らされない。'),
('JPN', '诗篇', 19, 107, 39, '虐げとわざわいと悲しみにより彼らは減ってうなだれる。'),
('JPN', '诗篇', 19, 107, 40, '主は君主たちを低くし道なき荒れ地をさまよわせる。'),
('JPN', '诗篇', 19, 107, 41, 'しかし貧しい者を困窮から高く上げその一族を羊の群れのようにそこに置かれる。'),
('JPN', '诗篇', 19, 107, 42, '直ぐな人はそれを見て喜び不正な者はみな口をつぐむ。'),
('JPN', '诗篇', 19, 107, 43, '知恵のある者はだれか。これらのことに心を留めよ。主の数々の恵みを見極めよ。'),
('JPN', '诗篇', 19, 108, 1, '神よ私の心は揺るぎません。私は歌いほめ歌います。私の心の底も。'),
('JPN', '诗篇', 19, 108, 2, '琴よ竪琴よ目を覚ませ。私は暁を呼び覚まそう。'),
('JPN', '诗篇', 19, 108, 3, '主よ私は諸国の民の間であなたに感謝しもろもろの国民の間であなたをほめ歌います。'),
('JPN', '诗篇', 19, 108, 4, 'あなたの恵みは大きく天の上に及びあなたのまことは雲にまで及ぶからです。'),
('JPN', '诗篇', 19, 108, 5, '神よあなたが天であなたの栄光が全地であがめられますように。'),
('JPN', '诗篇', 19, 108, 6, 'あなたの愛する者たちが助け出されるようあなたの右の手で救い私に答えてください。'),
('JPN', '诗篇', 19, 108, 7, '神は聖所から告げられました。「わたしは喜んでシェケムを分けスコテの平原を測ろう。'),
('JPN', '诗篇', 19, 108, 8, 'ギルアデはわたしのもの。マナセもわたしのもの。エフライムはわたしの頭のかぶと。ユダはわたしの王笏。'),
('JPN', '诗篇', 19, 108, 9, 'モアブはわたしの足を洗うたらい。エドムの上にわたしの履き物を投げつけペリシテの上でわたしは勝ちどきを上げよう。」'),
('JPN', '诗篇', 19, 108, 10, 'だれが私を要塞の町に連れて行くのでしょうか。だれが私をエドムまで導くのでしょうか。'),
('JPN', '诗篇', 19, 108, 11, '神よあなたは私たちを拒まれるのですか。神よあなたはもはや私たちとともに出陣なさらないのですか。'),
('JPN', '诗篇', 19, 108, 12, 'どうか敵から私たちを助けてください。人による救いはむなしいのです。'),
('JPN', '诗篇', 19, 108, 13, '神にあって私たちは力ある働きをします。神こそが私たちの敵を踏みつけてくださいます。'),
('JPN', '诗篇', 19, 109, 1, '私の賛美である神よ。沈黙しないでください。'),
('JPN', '诗篇', 19, 109, 2, '彼らは邪悪な口と欺きの口を私に向けて開き偽りの舌をもって私に語るからです。'),
('JPN', '诗篇', 19, 109, 3, '彼らは憎しみのことばで私を取り囲みゆえもなく私に挑んできます。'),
('JPN', '诗篇', 19, 109, 4, '私の愛に代えて彼らは告発で応じます。私は祈るばかりです。'),
('JPN', '诗篇', 19, 109, 5, '彼らは善に代えて悪を愛に代えて憎しみを私に返しました。'),
('JPN', '诗篇', 19, 109, 6, 'どうか彼に対して悪しき者を遣わし告発する者が彼の右に立つようにしてください。'),
('JPN', '诗篇', 19, 109, 7, '彼がさばかれるとき有罪が宣告され彼の祈りが罪と見なされますように。'),
('JPN', '诗篇', 19, 109, 8, '彼の日数はわずかとなりその務めは他人が取り'),
('JPN', '诗篇', 19, 109, 9, '子どもたちはみなしごとなり妻はやもめとなりますように。'),
('JPN', '诗篇', 19, 109, 10, '彼の子らはさまよいながら物乞いをし荒れ果てた家を離れ施しを求め続けますように。'),
('JPN', '诗篇', 19, 109, 11, '金貸しが彼のすべての財産を没収し見知らぬ者が労苦の実を奪い取りますように。'),
('JPN', '诗篇', 19, 109, 12, '彼には恵みを施す者もなくそのみなしごをあわれむ者もいませんように。'),
('JPN', '诗篇', 19, 109, 13, 'その後の子孫は断ち切られ次の世代には彼らの名が消し去られますように。'),
('JPN', '诗篇', 19, 109, 14, '彼の父たちの咎が主に覚えられその母の罪が消し去られませんように。'),
('JPN', '诗篇', 19, 109, 15, 'それらがいつも主の御前にあり主が彼らの記憶を地から消されますように。'),
('JPN', '诗篇', 19, 109, 16, 'それは彼が恵みのわざを行うことに心を留めず苦しむ者貧しい者心ひしがれた者を追いつめ殺そうとしたからです。'),
('JPN', '诗篇', 19, 109, 17, '彼が呪いを愛したのでそれは自分に返って来ました。祝福を喜ばなかったのでそれは彼から遠く離れました。'),
('JPN', '诗篇', 19, 109, 18, '衣のように彼は呪いを身にまとい水のようにそれは彼の内臓に油のように骨にまでしみ込みました。'),
('JPN', '诗篇', 19, 109, 19, 'それが彼をおおう服となりいつも締めている帯となりますように。'),
('JPN', '诗篇', 19, 109, 20, 'このようなことが私を告発する者たちへの主からの報いでありますように。私のたましいにわざわいを告げる者たちへの。'),
('JPN', '诗篇', 19, 109, 21, 'しかし神よ私の主よあなたは御名のために私にみわざを行ってください。御恵みのすばらしさのゆえに私を救い出してください。'),
('JPN', '诗篇', 19, 109, 22, '私は苦しみそして貧しく私の心は私のうちで傷ついています。'),
('JPN', '诗篇', 19, 109, 23, '私は伸びていく夕日の影のように去り行きいなごのように振り払われます。'),
('JPN', '诗篇', 19, 109, 24, '私の膝は断食のためによろけ肉は削げ落ち痩せ衰えました。'),
('JPN', '诗篇', 19, 109, 25, '私は彼らのそしりの的となり彼らは私を見て頭を振ります。'),
('JPN', '诗篇', 19, 109, 26, '私の神主よ私を助けてください。あなたの恵みによって私をお救いください。'),
('JPN', '诗篇', 19, 109, 27, 'こうして彼らが知るようにしてください。これはあなたの御手。主よあなたがそれをなされたのだと。'),
('JPN', '诗篇', 19, 109, 28, '彼らは呪います。しかしあなたは祝福してくださいます。彼らは立ち上がり恥を見ます。しかしあなたのしもべは喜びます。'),
('JPN', '诗篇', 19, 109, 29, '私を告発する者たちが侮辱を被り恥を上着として身にまといますように。'),
('JPN', '诗篇', 19, 109, 30, '私はこの口で大いに主に感謝し多くの人々のただ中で主を賛美します。'),
('JPN', '诗篇', 19, 109, 31, '主が貧しい人の右に立ち死を宣告する者たちから彼を救われるからです。'),
('JPN', '诗篇', 19, 110, 1, '主は私の主に言われた。「あなたはわたしの右の座に着いていなさい。わたしがあなたの敵をあなたの足台とするまで。」'),
('JPN', '诗篇', 19, 110, 2, '主はあなたの力の杖をシオンから伸ばされる。「あなたの敵のただ中で治めよ」と。'),
('JPN', '诗篇', 19, 110, 3, 'あなたの民はあなたの戦いの日に喜んで仕える。聖なる威光をまとって夜明け前から。あなたの若さは朝露のようだ。'),
('JPN', '诗篇', 19, 110, 4, '主は誓われた。思い直されることはない。「あなたはメルキゼデクの例に倣いとこしえに祭司である。」'),
('JPN', '诗篇', 19, 110, 5, 'あなたの右におられる主は御怒りの日に王たちを打ち砕かれる。'),
('JPN', '诗篇', 19, 110, 6, '国々をさばき屍で満たし広い地を治める首領を打ち砕かれる。'),
('JPN', '诗篇', 19, 110, 7, '主は道の傍らで流れから水を飲まれる。こうしてその頭を高く上げられる。'),
('JPN', '诗篇', 19, 111, 1, 'ハレルヤ。私は心を尽くして主に感謝をささげよう。直ぐな人の交わり主の会衆において。'),
('JPN', '诗篇', 19, 111, 2, '主のみわざは偉大。それを喜ぶすべての人に尋ね求められるもの。'),
('JPN', '诗篇', 19, 111, 3, 'そのみわざは威厳と威光。その義は永遠に立つ。'),
('JPN', '诗篇', 19, 111, 4, '主はその奇しいみわざを人の心に刻まれた。主は情け深くあわれみ深い。'),
('JPN', '诗篇', 19, 111, 5, '主を恐れる者に食べ物を与えご自分の契約をとこしえに覚えておられる。'),
('JPN', '诗篇', 19, 111, 6, '国々のゆずりの地をご自分の民に与え彼らにそのみわざの力を告げ知らされた。'),
('JPN', '诗篇', 19, 111, 7, '御手のわざは真実と公正そのすべての戒めは確かである。'),
('JPN', '诗篇', 19, 111, 8, 'それらは世々限りなく保たれ真実と正しさをもって行われる。'),
('JPN', '诗篇', 19, 111, 9, '主は御民のために贖いを送りご自分の契約をとこしえに定められた。主の御名は聖であり恐れ多い。'),
('JPN', '诗篇', 19, 111, 10, '知恵の初めそれは主を恐れること。これを行う人はみな賢明さを得る。主の誉れは永遠に立つ。'),
('JPN', '诗篇', 19, 112, 1, 'ハレルヤ。幸いなことよ主を恐れその仰せを大いに喜ぶ人は。'),
('JPN', '诗篇', 19, 112, 2, 'その子孫は地の上で勇士となり直ぐな人たちの世代は祝福される。'),
('JPN', '诗篇', 19, 112, 3, '繁栄と富はその家にあり彼の義は永遠に堅く立つ。'),
('JPN', '诗篇', 19, 112, 4, '直ぐな人たちのために光は闇の中に輝き昇る。主は情け深くあわれみ深く正しくあられる。'),
('JPN', '诗篇', 19, 112, 5, '幸せなことよ。情け深く人に貸し自分に関わることを公正に扱う人は。'),
('JPN', '诗篇', 19, 112, 6, 'その人はとこしえまでも揺るがされない。正しい人はとこしえに覚えられる。'),
('JPN', '诗篇', 19, 112, 7, 'その人は悪い知らせを恐れず主に信頼して心は揺るがない。'),
('JPN', '诗篇', 19, 112, 8, 'その心は堅固で恐れることなく自分の敵を平然と見るまでになる。'),
('JPN', '诗篇', 19, 112, 9, '彼は貧しい人々に惜しみなく分け与えた。彼の義は永遠に堅く立ち彼の角は栄光のうちに高く上げられる。'),
('JPN', '诗篇', 19, 112, 10, '悪しき者はそれを見て苛立ち歯ぎしりして消え去る。悪しき者の願いは滅び失せる。'),
('JPN', '诗篇', 19, 113, 1, 'ハレルヤ。主のしもべたちよほめたたえよ。主の御名をほめたたえよ。'),
('JPN', '诗篇', 19, 113, 2, '今よりとこしえまで主の御名がほめられるように。'),
('JPN', '诗篇', 19, 113, 3, '日の昇るところから沈むところまで主の御名がほめたたえられるように。'),
('JPN', '诗篇', 19, 113, 4, '主はすべての国々の上に高くおられその栄光は天の上にある。'),
('JPN', '诗篇', 19, 113, 5, 'だれが私たちの神主のようであろうか。主は高い御位に座し'),
('JPN', '诗篇', 19, 113, 6, '身を低くして天と地をご覧になる。'),
('JPN', '诗篇', 19, 113, 7, '主は弱い者をちりから起こし貧しい人をあくたから引き上げ'),
('JPN', '诗篇', 19, 113, 8, '彼らを高貴な人々とともに御民の高貴な人々とともに座に着かせられる。'),
('JPN', '诗篇', 19, 113, 9, '主は子のいない女を子を持って喜ぶ母とし家に住まわせてくださる。ハレルヤ。'),
('JPN', '诗篇', 19, 114, 1, 'イスラエルがエジプトからヤコブの家がことばの異なる民のうちから出て来たとき'),
('JPN', '诗篇', 19, 114, 2, 'ユダは神の聖所となりイスラエルは神の領地となった。'),
('JPN', '诗篇', 19, 114, 3, '海は見て逃げ去りヨルダン川は引き返した。'),
('JPN', '诗篇', 19, 114, 4, '山々は雄羊のように丘は子羊のように跳ね回った。'),
('JPN', '诗篇', 19, 114, 5, 'どうしたことか。海よおまえが逃げ去るとは。ヨルダン川よおまえが引き返すとは。'),
('JPN', '诗篇', 19, 114, 6, '山々よなぜおまえは雄羊のように跳ねるのか。丘よなぜ子羊のように跳ねるのか。'),
('JPN', '诗篇', 19, 114, 7, '地よ主の御前におののけ。ヤコブの神の御前に。'),
('JPN', '诗篇', 19, 114, 8, '神は岩を水の潤う沢に変えられた。硬い岩を水のあふれる泉に。'),
('JPN', '诗篇', 19, 115, 1, '私たちにではなく主よ私たちにではなくただあなたの御名に栄光を帰してください。あなたの恵みとまことのゆえに。'),
('JPN', '诗篇', 19, 115, 2, 'なぜ国々は言うのか。「彼らの神はいったいどこにいるのか」と。'),
('JPN', '诗篇', 19, 115, 3, '私たちの神は天におられその望むところをことごとく行われる。'),
('JPN', '诗篇', 19, 115, 4, '彼らの偶像は銀や金。人の手のわざにすぎない。'),
('JPN', '诗篇', 19, 115, 5, '口があっても語れず目があっても見えない。'),
('JPN', '诗篇', 19, 115, 6, '耳があっても聞こえず鼻があっても嗅げない。'),
('JPN', '诗篇', 19, 115, 7, '手があってもさわれず足があっても歩けない。喉があっても声をたてることができない。'),
('JPN', '诗篇', 19, 115, 8, 'これを造る者も信頼する者もみなこれと同じ。'),
('JPN', '诗篇', 19, 115, 9, 'イスラエルよ主に信頼せよ。主こそ助けまた盾。'),
('JPN', '诗篇', 19, 115, 10, 'アロンの家よ主に信頼せよ。主こそ助けまた盾。'),
('JPN', '诗篇', 19, 115, 11, '主を恐れる者たちよ主に信頼せよ。主こそ助けまた盾。'),
('JPN', '诗篇', 19, 115, 12, '主は私たちをみこころに留め祝福してくださる。イスラエルの家を祝福しアロンの家を祝福し'),
('JPN', '诗篇', 19, 115, 13, '主を恐れる者を祝福してくださる。小さな者も大いなる者も。'),
('JPN', '诗篇', 19, 115, 14, '主があなたがたを増やしてくださるように。あなたがたとあなたがたの子孫とを。'),
('JPN', '诗篇', 19, 115, 15, 'あなたがたが祝福されるように。天と地を造られた方主によって。'),
('JPN', '诗篇', 19, 115, 16, '天は主の天。地は主が人の子らに与えられた。'),
('JPN', '诗篇', 19, 115, 17, '死人は主をほめたたえることがない。沈黙へ下る者たちも。'),
('JPN', '诗篇', 19, 115, 18, 'しかし私たちは主をほめたたえる。今よりとこしえに至るまで。ハレルヤ。'),
('JPN', '诗篇', 19, 116, 1, '私は主を愛している。主は私の声私の願いを聞いてくださる。'),
('JPN', '诗篇', 19, 116, 2, '主が私に耳を傾けてくださるので私は生きているかぎり主を呼び求める。'),
('JPN', '诗篇', 19, 116, 3, '死の綱が私を取り巻きよみの恐怖が私を襲い私は苦しみと悲しみの中にあった。'),
('JPN', '诗篇', 19, 116, 4, 'そのとき私は主の御名を呼び求めた。「主よどうか私のいのちを助け出してください。」'),
('JPN', '诗篇', 19, 116, 5, '主は情け深く正しい。まことに私たちの神はあわれみ深い。'),
('JPN', '诗篇', 19, 116, 6, '主は浅はかな者をも守られる。私がおとしめられたとき私を救ってくださった。'),
('JPN', '诗篇', 19, 116, 7, '私のたましいよおまえの全きいこいに戻れ。主がおまえに良くしてくださったのだから。'),
('JPN', '诗篇', 19, 116, 8, 'まことにあなたは私のたましいを死から私の目を涙から私の足をつまずきから救い出してくださいました。'),
('JPN', '诗篇', 19, 116, 9, '私は生ける者の地で主の御前を歩みます。'),
('JPN', '诗篇', 19, 116, 10, '私は信じています。まことに私は語ります。私は大いに苦しんでいました。'),
('JPN', '诗篇', 19, 116, 11, 'この私は恐れうろたえて言いました。「人はだれでも偽りを言う」と。'),
('JPN', '诗篇', 19, 116, 12, '主が私に良くしてくださったすべてに対し私は主に何と応えたらよいのでしょう。'),
('JPN', '诗篇', 19, 116, 13, '私は救いの杯を掲げ主の御名を呼び求めます。'),
('JPN', '诗篇', 19, 116, 14, '私は自分の誓いを主に果たします。御民すべての目の前で。'),
('JPN', '诗篇', 19, 116, 15, '主の聖徒たちの死は主の目に尊い。'),
('JPN', '诗篇', 19, 116, 16, 'ああ主よ私はまことにあなたのしもべです。あなたのしもべあなたのはしための子です。あなたは私のかせを解いてくださいました。'),
('JPN', '诗篇', 19, 116, 17, '私はあなたに感謝のいけにえを献げ主の御名を呼び求めます。'),
('JPN', '诗篇', 19, 116, 18, '私は自分の誓いを主に果たします。御民すべての目の前で。'),
('JPN', '诗篇', 19, 116, 19, '主の家の大庭で。エルサレムよあなたのただ中で。ハレルヤ。'),
('JPN', '诗篇', 19, 117, 1, 'すべての国々よ主をほめたたえよ。すべての国民よ主をほめ歌え。'),
('JPN', '诗篇', 19, 117, 2, '主の恵みは私たちに大きい。主のまことはとこしえまで。ハレルヤ。'),
('JPN', '诗篇', 19, 118, 1, '主に感謝せよ。主はまことにいつくしみ深い。その恵みはとこしえまで。'),
('JPN', '诗篇', 19, 118, 2, 'さあイスラエルよ言え。「主の恵みはとこしえまで。」'),
('JPN', '诗篇', 19, 118, 3, 'さあアロンの家よ言え。「主の恵みはとこしえまで。」'),
('JPN', '诗篇', 19, 118, 4, 'さあ主を恐れる者たちよ言え。「主の恵みはとこしえまで。」'),
('JPN', '诗篇', 19, 118, 5, '苦しみのうちから私は主を呼び求めた。主は答えて私を広やかな地へ導かれた。'),
('JPN', '诗篇', 19, 118, 6, '主は私の味方。私は恐れない。人は私に何ができよう。'),
('JPN', '诗篇', 19, 118, 7, '主は私の味方私を助ける方。私は私を憎む者をものともしない。'),
('JPN', '诗篇', 19, 118, 8, '主に身を避けることは人に信頼するよりも良い。'),
('JPN', '诗篇', 19, 118, 9, '主に身を避けることは君主たちに信頼するよりも良い。'),
('JPN', '诗篇', 19, 118, 10, 'すべての国々が私を取り囲んだ。しかし主の御名によって私は彼らを断ち切る。'),
('JPN', '诗篇', 19, 118, 11, '彼らは私を取り囲んだ。まことに私を取り囲んだ。しかし主の御名によって私は彼らを断ち切る。'),
('JPN', '诗篇', 19, 118, 12, '蜂のように彼らは私を取り囲んだが茨の火のように消された。主の御名によって私は彼らを断ち切る。'),
('JPN', '诗篇', 19, 118, 13, 'おまえは私を激しく押し倒そうとしたが主が私を助けられた。'),
('JPN', '诗篇', 19, 118, 14, '主は私の力またほめ歌。主は私の救いとなられた。'),
('JPN', '诗篇', 19, 118, 15, '喜びと救いの声は正しい者の幕屋の内にある。主の右の手は力ある働きをする。'),
('JPN', '诗篇', 19, 118, 16, '主の右の手は高く上げられ主の右の手は力ある働きをする。'),
('JPN', '诗篇', 19, 118, 17, '私は死ぬことなくかえって生きて主のみわざを語り告げよう。'),
('JPN', '诗篇', 19, 118, 18, '主は私を厳しく懲らしめられた。しかし私を死に渡されはしなかった。'),
('JPN', '诗篇', 19, 118, 19, '義の門よ私のために開け。私はそこから入り主に感謝しよう。'),
('JPN', '诗篇', 19, 118, 20, 'これこそ主の門。正しい者たちはここから入る。'),
('JPN', '诗篇', 19, 118, 21, '私はあなたに感謝します。あなたが私に答え私の救いとなられたからです。'),
('JPN', '诗篇', 19, 118, 22, '家を建てる者たちが捨てた石それが要の石となった。'),
('JPN', '诗篇', 19, 118, 23, 'これは主がなさったこと。私たちの目には不思議なことだ。'),
('JPN', '诗篇', 19, 118, 24, 'これは主が設けられた日。この日を楽しみ喜ぼう。'),
('JPN', '诗篇', 19, 118, 25, 'ああ主よどうか救ってください。ああ主よどうか栄えさせてください。'),
('JPN', '诗篇', 19, 118, 26, '祝福あれ主の御名によって来られる方に。私たちは主の家からあなたがたを祝福する。'),
('JPN', '诗篇', 19, 118, 27, '主こそ神。主は私たちに光を与えられた。枝をもって祭りの行列を組め。祭壇の角のところまで。'),
('JPN', '诗篇', 19, 118, 28, 'あなたは私の神。私はあなたに感謝します。あなたは私の神。私はあなたをあがめます。'),
('JPN', '诗篇', 19, 118, 29, '主に感謝せよ。主はまことにいつくしみ深い。その恵みはとこしえまで。'),
('JPN', '诗篇', 19, 119, 1, '幸いなことよ全き道を行く人々主のみおしえに歩む人々。'),
('JPN', '诗篇', 19, 119, 2, '幸いなことよ主のさとしを守り心を尽くして主を求める人々。'),
('JPN', '诗篇', 19, 119, 3, 'まことに彼らは不正を行わず主の道を歩みます。'),
('JPN', '诗篇', 19, 119, 4, 'あなたは戒めを仰せつけられました。それらを堅く守るように。'),
('JPN', '诗篇', 19, 119, 5, 'どうか私の道が堅くされますように。あなたのおきてを守るために。'),
('JPN', '诗篇', 19, 119, 6, 'そうすればあなたのすべての仰せを見て私は恥じることがありません。'),
('JPN', '诗篇', 19, 119, 7, 'あなたの義のさばきを学ぶとき私は直ぐな心であなたに感謝します。'),
('JPN', '诗篇', 19, 119, 8, '私はあなたのおきてを守ります。どうか私を見捨てないでください。'),
('JPN', '诗篇', 19, 119, 9, 'どのようにして若い人は自分の道を清く保つことができるでしょうか。あなたのみことばのとおりに道を守ることです。'),
('JPN', '诗篇', 19, 119, 10, '私は心を尽くしてあなたを求めています。どうかあなたの仰せから私が迷い出ないようにしてください。'),
('JPN', '诗篇', 19, 119, 11, '私はあなたのみことばを心に蓄えます。あなたの前に罪ある者とならないために。'),
('JPN', '诗篇', 19, 119, 12, '主よあなたはほむべき方。あなたのおきてを私に教えてください。'),
('JPN', '诗篇', 19, 119, 13, '私はこの唇で語ります。あなたの御口のさばきすべてを。'),
('JPN', '诗篇', 19, 119, 14, '私はあなたのさとしの道をどんな宝よりも楽しんでいます。'),
('JPN', '诗篇', 19, 119, 15, '私はあなたの戒めに思いを潜めあなたの道に私の目を留めます。'),
('JPN', '诗篇', 19, 119, 16, '私はあなたのおきてを喜びとしあなたのみことばを忘れません。'),
('JPN', '诗篇', 19, 119, 17, 'あなたのしもべに豊かに報い私を生かし私があなたのみことばを守るようにしてください。'),
('JPN', '诗篇', 19, 119, 18, '私の目を開いてください。私が目を留めるようにしてください。あなたのみおしえのうちにある奇しいことに。'),
('JPN', '诗篇', 19, 119, 19, '私は地では旅人です。あなたの仰せを私に隠さないでください。'),
('JPN', '诗篇', 19, 119, 20, 'いつのときもあなたのさばきを慕い求めて私のたましいは押しつぶされるほどです。'),
('JPN', '诗篇', 19, 119, 21, 'あなたはあなたの仰せから迷い出る高ぶる者のろわれるべき者をおとがめになります。'),
('JPN', '诗篇', 19, 119, 22, '私からそしりと蔑みを取り去ってください。私はあなたのさとしを守っているからです。'),
('JPN', '诗篇', 19, 119, 23, 'たとえ君主たちが座して私に敵対して語り合ってもこのしもべはあなたのおきてに思いを潜めます。'),
('JPN', '诗篇', 19, 119, 24, 'あなたのさとしこそ私の喜び私の助言者です。'),
('JPN', '诗篇', 19, 119, 25, '私のたましいはちりに打ち伏しています。みことばのとおりに私を生かしてください。'),
('JPN', '诗篇', 19, 119, 26, '私は自分の道を申し述べました。するとあなたは私に答えてくださいました。どうかあなたのおきてを私に教えてください。'),
('JPN', '诗篇', 19, 119, 27, 'あなたの戒めの道を私に悟らせてください。私があなたの奇しいみわざを語り伝えることができるように。'),
('JPN', '诗篇', 19, 119, 28, '私のたましいは悲しみのために溶け去ります。みことばのとおりに私を強めてください。'),
('JPN', '诗篇', 19, 119, 29, '私から偽りの道を取り除いてください。みおしえをもって私をあわれんでください。'),
('JPN', '诗篇', 19, 119, 30, '私は真実の道を選び取りあなたの定めを自らの前に置きました。'),
('JPN', '诗篇', 19, 119, 31, '私はあなたのさとしに固くすがります。主よどうか私に恥を見させないでください。'),
('JPN', '诗篇', 19, 119, 32, '私はあなたの仰せの道を走ります。あなたが私の心を広くしてくださるからです。'),
('JPN', '诗篇', 19, 119, 33, '主よあなたのおきての道を教えてください。そうすれば私はそれを終わりまで守ります。'),
('JPN', '诗篇', 19, 119, 34, '私に悟らせてください。私があなたのみおしえから目を離さず心を尽くしてそれを守るために。'),
('JPN', '诗篇', 19, 119, 35, '私にあなたの仰せの道を踏み行かせてください。私はその道を喜んでいますから。'),
('JPN', '诗篇', 19, 119, 36, '私の心をあなたのさとしに傾かせ不正な利得に傾かないようにしてください。'),
('JPN', '诗篇', 19, 119, 37, 'むなしいものを見ないように私の目をそらせあなたの道に私を生かしてください。'),
('JPN', '诗篇', 19, 119, 38, 'あなたのしもべへの仰せのことばが成り私があなたを恐れるようにしてください。'),
('JPN', '诗篇', 19, 119, 39, '私がおびえているそしりを取り去ってください。あなたのさばきはすぐれて良いからです。'),
('JPN', '诗篇', 19, 119, 40, 'ご覧ください。私はあなたの戒めを慕っています。あなたの義のわざにより私を生かしてください。'),
('JPN', '诗篇', 19, 119, 41, '主よあなたの恵みが私にもたらされますように。あなたの救いがみことばのとおりに。'),
('JPN', '诗篇', 19, 119, 42, 'そうすれば私をそしる者に対して言い返すことができます。私はあなたのみことばに信頼していますから。'),
('JPN', '诗篇', 19, 119, 43, '私の口から真理のみことばを取り去ってしまわないでください。私はあなたのさばきを待ち望んでいるのです。'),
('JPN', '诗篇', 19, 119, 44, 'こうして私はあなたのみおしえをいつもとこしえまでも守ります。'),
('JPN', '诗篇', 19, 119, 45, 'そうして私は広やかな所に歩いて行きます。あなたの戒めを私が求めているからです。'),
('JPN', '诗篇', 19, 119, 46, '私はあなたのさとしを王たちの前で述べしかも恥を見ることはありません。'),
('JPN', '诗篇', 19, 119, 47, '私はあなたの仰せを喜びます。それを私は愛します。'),
('JPN', '诗篇', 19, 119, 48, '私は愛するあなたの仰せを求めて両手を上げあなたのおきてに思いを潜めます。'),
('JPN', '诗篇', 19, 119, 49, 'どうかあなたのしもべへのみことばを心に留めてください。あなたは私がそれを待ち望むようになさいました。'),
('JPN', '诗篇', 19, 119, 50, 'これこそ悩みのときの私の慰め。まことにあなたのみことばは私を生かします。'),
('JPN', '诗篇', 19, 119, 51, '高ぶる者はひどく私を嘲ります。しかし私はあなたのみおしえからそれません。'),
('JPN', '诗篇', 19, 119, 52, '主よ私はあなたのとこしえからのさばきを心に留め慰めを得ます。'),
('JPN', '诗篇', 19, 119, 53, '悪しき者あなたのみおしえを捨てる者のゆえに激しい怒りが私をとらえます。'),
('JPN', '诗篇', 19, 119, 54, 'あなたのおきては私の旅の家で私の歌となりました。'),
('JPN', '诗篇', 19, 119, 55, '主よ夜にはあなたの御名を思い起こしあなたのみおしえを守ります。'),
('JPN', '诗篇', 19, 119, 56, 'これこそ私のもの。私があなたの戒めを守っているからです。'),
('JPN', '诗篇', 19, 119, 57, '主は私への割り当てです。私はあなたのみことばを守ると申し上げました。'),
('JPN', '诗篇', 19, 119, 58, '私は心を尽くしてあなたに乞い求めます。みことばのとおりに私をあわれんでください。'),
('JPN', '诗篇', 19, 119, 59, '私は自分の道を顧みてあなたのさとしの方へ足の向きを変えました。'),
('JPN', '诗篇', 19, 119, 60, '私はすぐためらわずにあなたの仰せを守りました。'),
('JPN', '诗篇', 19, 119, 61, '悪しき者の綱が私に巻き付いてもあなたのみおしえを私は忘れませんでした。'),
('JPN', '诗篇', 19, 119, 62, '真夜中に私は起きてあなたに感謝します。あなたの正しいさばきのゆえに。'),
('JPN', '诗篇', 19, 119, 63, '私はあなたを恐れるすべての人あなたの戒めを守る人たちの仲間です。'),
('JPN', '诗篇', 19, 119, 64, '主よ地はあなたの恵みに満ちています。あなたのおきてを私に教えてください。'),
('JPN', '诗篇', 19, 119, 65, '主よあなたはみことばのとおりにあなたのしもべに良くしてくださいました。'),
('JPN', '诗篇', 19, 119, 66, '良い判断と知識を私に教えてください。私はあなたの仰せを信じています。'),
('JPN', '诗篇', 19, 119, 67, '苦しみにあう前には私は迷い出ていました。しかし今はあなたのみことばを守ります。'),
('JPN', '诗篇', 19, 119, 68, 'あなたはいつくしみ深く良くしてくださるお方です。どうかあなたのおきてを私に教えてください。'),
('JPN', '诗篇', 19, 119, 69, '高ぶる者は私を偽りで塗り固めましたが私は心を尽くしてあなたの戒めを守ります。'),
('JPN', '诗篇', 19, 119, 70, '彼らの心は脂肪のように鈍感です。しかし私はあなたのみおしえを喜んでいます。'),
('JPN', '诗篇', 19, 119, 71, '苦しみにあったことは私にとって幸せでした。それにより私はあなたのおきてを学びました。'),
('JPN', '诗篇', 19, 119, 72, 'あなたの御口のみおしえは私にとって幾千もの金銀にまさります。'),
('JPN', '诗篇', 19, 119, 73, 'あなたの御手が私を造り私を整えてくださいました。どうか私に悟らせ私があなたの仰せを学ぶようにしてください。'),
('JPN', '诗篇', 19, 119, 74, 'あなたを恐れる人々は私を見て喜ぶでしょう。私がみことばを待ち望んでいるからです。'),
('JPN', '诗篇', 19, 119, 75, '主よ私は知っています。あなたのさばきが正しいこととあなたが真実をもって私を苦しめられたことを。'),
('JPN', '诗篇', 19, 119, 76, 'どうかこのしもべへの約束にしたがってあなたの恵みが私の慰めとなりますように。'),
('JPN', '诗篇', 19, 119, 77, 'どうかあわれみを私に臨ませ私を生かしてください。あなたのみおしえは私の喜びです。'),
('JPN', '诗篇', 19, 119, 78, 'どうか高ぶる者が恥を見ますように。彼らは偽りで私を曲げたからです。しかし私はあなたの戒めに思いを潜めます。'),
('JPN', '诗篇', 19, 119, 79, 'どうかあなたを恐れる人々とあなたのさとしを知る者たちが私のところに帰って来ますように。'),
('JPN', '诗篇', 19, 119, 80, 'どうかあなたのおきてのうちに私の心が全きものとなりますように。私が恥を見ることのないためです。'),
('JPN', '诗篇', 19, 119, 81, '私のたましいはあなたの救いを慕って絶え入るばかりです。私はあなたのみことばを待ち望んでいます。'),
('JPN', '诗篇', 19, 119, 82, '私の目はあなたのみことばを慕って絶え入るばかりです。私は言います。「いつあなたは私を慰めてくださるのですか」と。'),
('JPN', '诗篇', 19, 119, 83, 'たとえ煙の中の皮袋のようになっても私はあなたのおきてを忘れません。'),
('JPN', '诗篇', 19, 119, 84, 'このしもべの日数はどれだけでしょうか。あなたはいつ私を迫害する者どもにさばきを行われるのでしょうか。'),
('JPN', '诗篇', 19, 119, 85, '高ぶる者は私に対して穴を掘りました。彼らはあなたのみおしえに従わないのです。'),
('JPN', '诗篇', 19, 119, 86, 'あなたの仰せはことごとく真実です。彼らは偽りで私を迫害します。どうか私を助けてください。'),
('JPN', '诗篇', 19, 119, 87, '彼らはこの地上で私を滅ぼそうとしています。しかし私はあなたの戒めを捨てませんでした。'),
('JPN', '诗篇', 19, 119, 88, 'あなたの恵みによって私を生かしてください。私はあなたの御口のさとしを守ります。'),
('JPN', '诗篇', 19, 119, 89, '主よあなたのみことばはとこしえから天において定まっています。'),
('JPN', '诗篇', 19, 119, 90, 'あなたの真実は代々に至ります。あなたが地を据えられたので地は堅く立っています。'),
('JPN', '诗篇', 19, 119, 91, 'それらは今日もあなたの定めにしたがって堅く立っています。万物はあなたのしもべだからです。'),
('JPN', '诗篇', 19, 119, 92, 'もしあなたのみおしえが私の喜びでなかったらそれなら私は私の苦しみの中で滅んだでしょう。'),
('JPN', '诗篇', 19, 119, 93, '私は決してあなたの戒めを忘れません。それによってあなたが私を生かしてくださったからです。'),
('JPN', '诗篇', 19, 119, 94, '私はあなたのもの。どうか私をお救いください。私はあなたの戒めを求めています。'),
('JPN', '诗篇', 19, 119, 95, '悪者どもは私を滅ぼそうと狙っています。しかし私はあなたのさとしを聞き分けます。'),
('JPN', '诗篇', 19, 119, 96, '私はどんな全きものにも終わりがあることを見ました。しかしあなたの仰せは実に広いのです。'),
('JPN', '诗篇', 19, 119, 97, 'どれほど私はあなたのみおしえを愛していることでしょう。それがいつも私の思いとなっています。'),
('JPN', '诗篇', 19, 119, 98, 'あなたの仰せは私を敵よりも賢くします。それがとこしえに私のものだからです。'),
('JPN', '诗篇', 19, 119, 99, '私には私のすべての師にまさる賢さがあります。あなたのさとしが私の思いだからです。'),
('JPN', '诗篇', 19, 119, 100, '私は老人たちよりも見極めができます。私があなたの戒めを守っているからです。'),
('JPN', '诗篇', 19, 119, 101, '私はいかなる悪の道にも足を踏み入れません。あなたのみことばを守るためです。'),
('JPN', '诗篇', 19, 119, 102, '私はあなたの定めから外れませんでした。あなたが私を教えられたからです。'),
('JPN', '诗篇', 19, 119, 103, 'あなたのみことばは私の上あごになんと甘いことでしょう。蜜よりも私の口に甘いのです。'),
('JPN', '诗篇', 19, 119, 104, '私にはあなたの戒めがあり見極めができます。それゆえ私は偽りの道をことごとく憎みます。'),
('JPN', '诗篇', 19, 119, 105, 'あなたのみことばは私の足のともしび私の道の光です。'),
('JPN', '诗篇', 19, 119, 106, '私は誓いまたそれを果たします。あなたの義の定めを守ることを。'),
('JPN', '诗篇', 19, 119, 107, '私はひどく苦しんでいます。主よみことばのとおりに私を生かしてください。'),
('JPN', '诗篇', 19, 119, 108, 'どうか私の口から出る進んで献げるものを受け入れてください。主よ。あなたのさばきを私に教えてください。'),
('JPN', '诗篇', 19, 119, 109, '私はいつもいのちがけです。それでもあなたのみおしえを忘れません。'),
('JPN', '诗篇', 19, 119, 110, '悪者どもは私に対して罠を設けました。それでも私はあなたの戒めから迷い出ません。'),
('JPN', '诗篇', 19, 119, 111, '私はあなたのさとしを永遠に受け継ぎました。これこそ私の心の喜びです。'),
('JPN', '诗篇', 19, 119, 112, '私はあなたのおきてを行うことに心を傾けます。いつまでも終わりまでも。'),
('JPN', '诗篇', 19, 119, 113, '私は二心のある人たちを憎みあなたのみおしえを愛します。'),
('JPN', '诗篇', 19, 119, 114, 'あなたは私の隠れ場私の盾。私はあなたのみことばを待ち望みます。'),
('JPN', '诗篇', 19, 119, 115, '悪を行う者どもよ私から遠ざかれ。この私は私の神の仰せを守る。'),
('JPN', '诗篇', 19, 119, 116, 'あなたのみことばのとおりに私を支え生かしてください。私の望みのことで私を辱めないようにしてください。'),
('JPN', '诗篇', 19, 119, 117, '私を支えてください。そうすれば私は救われ絶えずあなたのおきてを見つめることができます。'),
('JPN', '诗篇', 19, 119, 118, 'あなたはあなたのおきてから迷い出る者をみな退けられます。彼らの偽りは欺きだからです。'),
('JPN', '诗篇', 19, 119, 119, 'あなたは地の上のすべての悪しき者を金かすのように取り除かれます。それゆえ私はあなたのさとしを愛します。'),
('JPN', '诗篇', 19, 119, 120, '私の肉はあなたへの恐れで震えています。私はあなたのさばきを恐れています。'),
('JPN', '诗篇', 19, 119, 121, '私は公正と義を行います。私を虐げる者どもに私を委ねないでください。'),
('JPN', '诗篇', 19, 119, 122, 'あなたのしもべの幸いの保証人となってください。高ぶる者が私を虐げないようにしてください。'),
('JPN', '诗篇', 19, 119, 123, '私の目はあなたの救いとあなたの義のみことばを慕って絶え入るばかりです。'),
('JPN', '诗篇', 19, 119, 124, 'あなたの恵みによってあなたのしもべを取り扱ってください。私にあなたのおきてを教えてください。'),
('JPN', '诗篇', 19, 119, 125, '私はあなたのしもべです。私に悟らせてください。そうすれば私はあなたのさとしを知るでしょう。'),
('JPN', '诗篇', 19, 119, 126, '今こそ主が事をなさる時です。彼らはあなたのみおしえを破りました。'),
('JPN', '诗篇', 19, 119, 127, 'それゆえ私はあなたの仰せを愛します。金よりも純金よりも。'),
('JPN', '诗篇', 19, 119, 128, 'それゆえ私はすべてにおいて戒めにしたがってまっすぐに歩み偽りの道をことごとく憎みます。'),
('JPN', '诗篇', 19, 119, 129, 'あなたのさとしは奇しくそれゆえ私のたましいはそれに目を留めます。'),
('JPN', '诗篇', 19, 119, 130, 'みことばの戸が開くと光が差し浅はかな者に悟りを与えます。'),
('JPN', '诗篇', 19, 119, 131, '私は口を大きく開けてあえぎます。まことに私はあなたの仰せを慕います。'),
('JPN', '诗篇', 19, 119, 132, '御名を愛する者のために定めておられるように私に御顔を向け私をあわれんでください。'),
('JPN', '诗篇', 19, 119, 133, 'みことばによって私の歩みを確かにしどんな不法にも私を支配させないでください。'),
('JPN', '诗篇', 19, 119, 134, '私を人の虐げから贖い出しあなたの戒めを守るようにしてください。'),
('JPN', '诗篇', 19, 119, 135, '御顔をあなたのしもべの上に照り輝かせあなたのおきてを教えてください。'),
('JPN', '诗篇', 19, 119, 136, '私の目から涙がとめどなく流れ落ちます。彼らがあなたのみおしえを守らないからです。'),
('JPN', '诗篇', 19, 119, 137, '主よあなたは正しくあられます。あなたのさばきは真っ直ぐです。'),
('JPN', '诗篇', 19, 119, 138, '義をもってあなたはさとしを与えられました。この上もない真実をもって。'),
('JPN', '诗篇', 19, 119, 139, '私の激しい思いは私を滅ぼし尽くすほどです。私の敵があなたのみことばを忘れているからです。'),
('JPN', '诗篇', 19, 119, 140, 'あなたのみことばはよく錬られていてあなたのしもべはそれを愛しています。'),
('JPN', '诗篇', 19, 119, 141, '私は取るに足りない者で蔑まれています。しかしあなたの戒めを忘れてはいません。'),
('JPN', '诗篇', 19, 119, 142, 'あなたの義のわざは永遠の義あなたのみおしえはまことです。'),
('JPN', '诗篇', 19, 119, 143, '苦難と窮乏が私に襲いかかっています。しかしあなたの仰せは私の喜びです。'),
('JPN', '诗篇', 19, 119, 144, 'あなたのさとしは永遠に義です。私に悟らせ私を生かしてください。'),
('JPN', '诗篇', 19, 119, 145, '私は心を尽くして呼び求めます。主よ私に答えてください。私はあなたのおきてを守ります。'),
('JPN', '诗篇', 19, 119, 146, '私はあなたを呼び求めます。私をお救いください。私はあなたのさとしを守ります。'),
('JPN', '诗篇', 19, 119, 147, '私は夜明け前に起きて叫び求めます。あなたのみことばを待ち望んでいます。'),
('JPN', '诗篇', 19, 119, 148, '私は夜明けの見張りよりも先に目覚めあなたのみことばに思いを潜めます。'),
('JPN', '诗篇', 19, 119, 149, 'あなたの恵みによって私の声を聞いてください。主よあなたの定めにしたがって私を生かしてください。'),
('JPN', '诗篇', 19, 119, 150, '悪意を遂げようとする者が近づきました。彼らはあなたのみおしえから遠く離れています。'),
('JPN', '诗篇', 19, 119, 151, 'しかし主よあなたがそばにおられます。あなたの仰せはことごとくまことです。'),
('JPN', '诗篇', 19, 119, 152, '私は昔からあなたのさとしで知っています。あなたが永遠にこれを定めておられることを。'),
('JPN', '诗篇', 19, 119, 153, '私の苦しみをご覧になり私を助け出してください。私はあなたのみおしえを忘れません。'),
('JPN', '诗篇', 19, 119, 154, '私の言い分を取り上げ私を贖ってください。あなたのみことばにしたがって私を生かしてください。'),
('JPN', '诗篇', 19, 119, 155, '救いは悪しき者から遠く離れています。彼らがあなたのおきてを求めないからです。'),
('JPN', '诗篇', 19, 119, 156, 'あなたのあわれみは偉大です。主よあなたの定めにしたがって私を生かしてください。'),
('JPN', '诗篇', 19, 119, 157, '私を迫害し敵とする者が多くいます。しかし私はあなたのさとしからそれません。'),
('JPN', '诗篇', 19, 119, 158, '私は裏切る者どもを見て忌み嫌います。彼らがあなたのみことばを守らないからです。'),
('JPN', '诗篇', 19, 119, 159, 'ご覧ください。どんなに私があなたの戒めを愛しているかを。主よあなたの恵みによって私を生かしてください。'),
('JPN', '诗篇', 19, 119, 160, 'みことばのすべては真実です。あなたの義のさばきはことごとくとこしえに至ります。'),
('JPN', '诗篇', 19, 119, 161, '君主たちはゆえもなく私を迫害します。しかし私の心はあなたのみことばにおののいています。'),
('JPN', '诗篇', 19, 119, 162, '私は大きな獲物を見つけた者のようにあなたのみことばを喜びます。'),
('JPN', '诗篇', 19, 119, 163, '私は偽りを憎み忌み嫌います。私はあなたのみおしえを愛しています。'),
('JPN', '诗篇', 19, 119, 164, 'あなたの義のさばきのゆえに私は日に七度あなたをほめたたえます。'),
('JPN', '诗篇', 19, 119, 165, 'あなたのみおしえを愛する者には豊かな平安がありつまずきがありません。'),
('JPN', '诗篇', 19, 119, 166, '主よ私はあなたの救いを待ち望んでいます。私はあなたの仰せを行っています。'),
('JPN', '诗篇', 19, 119, 167, '私のたましいはあなたのさとしを守っています。限りなくそれを愛しています。'),
('JPN', '诗篇', 19, 119, 168, '私はあなたの戒めとさとしを守っています。私の道はことごとく御前にあるからです。'),
('JPN', '诗篇', 19, 119, 169, '主よ私の叫びが御前に近づきますように。あなたのみことばのとおりに私に悟りを与えてください。'),
('JPN', '诗篇', 19, 119, 170, '私の切なる願いが御前に届きますように。あなたのみことばのとおりに私を救い出してください。'),
('JPN', '诗篇', 19, 119, 171, '私の唇に賛美が湧きあふれるようにしてください。あなたが私にあなたのおきてを教えてくださるからです。'),
('JPN', '诗篇', 19, 119, 172, '私の舌があなたのみことばを歌うようにしてください。あなたの仰せはことごとく正しいからです。'),
('JPN', '诗篇', 19, 119, 173, 'あなたの御手が私の助けとなりますように。まことに私はあなたの戒めを選びました。'),
('JPN', '诗篇', 19, 119, 174, '主よ私はあなたの救いを慕っています。あなたのみおしえは私の喜びです。'),
('JPN', '诗篇', 19, 119, 175, '私のたましいが生きあなたをほめたたえますように。そしてあなたのさばきが私の助けとなりますように。'),
('JPN', '诗篇', 19, 119, 176, '私は滅びる羊のようにさまよっています。どうかこのしもべを捜してください。私はあなたの仰せを忘れません。'),
('JPN', '诗篇', 19, 120, 1, '苦しみのうちに私が主を呼び求めると主は私に答えてくださった。'),
('JPN', '诗篇', 19, 120, 2, '主よ私のたましいを偽りの唇欺きの舌から救い出してください。'),
('JPN', '诗篇', 19, 120, 3, '欺きの舌よおまえに何が与えられおまえに何が加えられるだろうか。'),
('JPN', '诗篇', 19, 120, 4, '勇士の鋭い矢そしてえにしだの炭火だ。'),
('JPN', '诗篇', 19, 120, 5, 'ああ嘆かわしいこの身よ。メシェクに寄留しケダルの天幕に身を寄せるとは。'),
('JPN', '诗篇', 19, 120, 6, 'この身は平和を憎む者とともにあって久しい。'),
('JPN', '诗篇', 19, 120, 7, '私が平和を──と語りかければ彼らは戦いを求めるのだ。'),
('JPN', '诗篇', 19, 121, 1, '私は山に向かって目を上げる。私の助けはどこから来るのか。'),
('JPN', '诗篇', 19, 121, 2, '私の助けは主から来る。天地を造られたお方から。'),
('JPN', '诗篇', 19, 121, 3, '主はあなたの足をよろけさせずあなたを守る方はまどろむこともない。'),
('JPN', '诗篇', 19, 121, 4, '見よイスラエルを守る方はまどろむこともなく眠ることもない。'),
('JPN', '诗篇', 19, 121, 5, '主はあなたを守る方。主はあなたの右手をおおう陰。'),
('JPN', '诗篇', 19, 121, 6, '昼も日があなたを打つことはなく夜も月があなたを打つことはない。'),
('JPN', '诗篇', 19, 121, 7, '主はすべてのわざわいからあなたを守りあなたのたましいを守られる。'),
('JPN', '诗篇', 19, 121, 8, '主はあなたを行くにも帰るにも今よりとこしえまでも守られる。'),
('JPN', '诗篇', 19, 122, 1, '「さあ主の家に行こう。」人々が私にそう言ったとき私は喜んだ。'),
('JPN', '诗篇', 19, 122, 2, 'エルサレムよ私たちの足はあなたの門の内に立っている。'),
('JPN', '诗篇', 19, 122, 3, 'エルサレムそれは一つによくまとまった都として建てられている。'),
('JPN', '诗篇', 19, 122, 4, 'そこには多くの部族主の部族が上って来る。イスラエルである証しとして主の御名に感謝するために。'),
('JPN', '诗篇', 19, 122, 5, 'そこにはさばきの座ダビデの家の王座があるからだ。'),
('JPN', '诗篇', 19, 122, 6, 'エルサレムの平和のために祈れ。「あなたを愛する人々が安らかであるように。'),
('JPN', '诗篇', 19, 122, 7, 'あなたの城壁の内に平和があるように。あなたの宮殿の内が平穏であるように。」'),
('JPN', '诗篇', 19, 122, 8, '私の兄弟友のためにさあ私は言おう。「あなたのうちに平和があるように。」'),
('JPN', '诗篇', 19, 122, 9, '私たちの神主の家のために私はあなたの幸いを祈り求めよう。'),
('JPN', '诗篇', 19, 123, 1, 'あなたに向かって私は目を上げます。天の御座に着いておられる方よ。'),
('JPN', '诗篇', 19, 123, 2, 'まことにしもべたちの目が主人の手に向けられ仕える女の目が女主人の手に向けられるように私たちの目は私たちの神主に向けられています。主が私たちをあわれんでくださるまで。'),
('JPN', '诗篇', 19, 123, 3, 'あわれんでください主よあわれんでください。私たちは蔑みでいっぱいです。'),
('JPN', '诗篇', 19, 123, 4, '私たちのたましいは安逸を貪る者たちの嘲りと高ぶる者たちの蔑みでいっぱいです。'),
('JPN', '诗篇', 19, 124, 1, '「もしも主が私たちの味方でなかったなら。」さあイスラエルは言え。'),
('JPN', '诗篇', 19, 124, 2, '「もしも主が私たちの味方でなかったなら人々が敵対してきたとき'),
('JPN', '诗篇', 19, 124, 3, 'そのとき彼らは私たちを生きたまま丸吞みにしていたであろう。彼らの怒りが私たちに向かって燃え上がったとき'),
('JPN', '诗篇', 19, 124, 4, 'そのとき大水は私たちを押し流し濁流は私たちを越えて行ったであろう。'),
('JPN', '诗篇', 19, 124, 5, 'そのとき荒れ狂う水は私たちを越えて行ったであろう。」'),
('JPN', '诗篇', 19, 124, 6, 'ほむべきかな主。主は私たちを彼らの歯の餌食にされなかった。'),
('JPN', '诗篇', 19, 124, 7, '鳥のように私たちのたましいは仕掛けられた罠から助け出された。罠は破られ私たちは助け出された。'),
('JPN', '诗篇', 19, 124, 8, '私たちの助けは天地を造られた主の御名にある。'),
('JPN', '诗篇', 19, 125, 1, '主に信頼する人々はシオンの山のようだ。揺るぐことなくとこしえにながらえる。'),
('JPN', '诗篇', 19, 125, 2, 'エルサレムを山々が取り囲んでいるように主は御民を今よりとこしえまでも囲まれる。'),
('JPN', '诗篇', 19, 125, 3, 'それは悪の杖が正しい人の割り当て地の上にとどまることがなく正しい人が不正なことに手を伸ばさないようにするためだ。'),
('JPN', '诗篇', 19, 125, 4, '主よ善良な人々や心の直ぐな人々にいつくしみを施してください。'),
('JPN', '诗篇', 19, 125, 5, '主は曲がった道にそれる者どもを不法を行う者どもとともに追い出される。イスラエルの上に平和があるように。'),
('JPN', '诗篇', 19, 126, 1, '主がシオンを復興してくださったとき私たちは夢を見ている者のようであった。'),
('JPN', '诗篇', 19, 126, 2, 'そのとき私たちの口は笑いで満たされ私たちの舌は喜びの叫びで満たされた。そのとき諸国の人々は言った。「主は彼らのために大いなることをなさった。」'),
('JPN', '诗篇', 19, 126, 3, '主が私たちのために大いなることをなさったので私たちは喜んだ。'),
('JPN', '诗篇', 19, 126, 4, '主よネゲブの流れのように私たちを元どおりにしてください。'),
('JPN', '诗篇', 19, 126, 5, '涙とともに種を蒔く者は喜び叫びながら刈り取る。'),
('JPN', '诗篇', 19, 126, 6, '種入れを抱え泣きながら出て行く者は束を抱え喜び叫びながら帰って来る。'),
('JPN', '诗篇', 19, 127, 1, '主が家を建てるのでなければ建てる者の働きはむなしい。主が町を守るのでなければ守る者の見張りはむなしい。'),
('JPN', '诗篇', 19, 127, 2, 'あなたがたが早く起き遅く休み労苦の糧を食べたとしてもそれはむなしい。実に主は愛する者に眠りを与えてくださる。'),
('JPN', '诗篇', 19, 127, 3, '見よ子どもたちは主の賜物胎の実は報酬。'),
('JPN', '诗篇', 19, 127, 4, '若いときの子どもたちは実に勇士の手にある矢のようだ。'),
('JPN', '诗篇', 19, 127, 5, '幸いなことよ矢筒をその矢で満たしている人は。彼らは門で敵と論じるとき恥を見ることがない。'),
('JPN', '诗篇', 19, 128, 1, '幸いなことよ主を恐れ主の道を歩むすべての人は。'),
('JPN', '诗篇', 19, 128, 2, 'あなたがその手で労した実りを食べることそれはあなたの幸いあなたへの恵み。'),
('JPN', '诗篇', 19, 128, 3, 'あなたの妻は家の奥でたわわに実るぶどうの木のようだ。あなたの子どもたちは食卓を囲むときまるでオリーブの若木のようだ。'),
('JPN', '诗篇', 19, 128, 4, '見よ主を恐れる人は確かにこのように祝福を受ける。'),
('JPN', '诗篇', 19, 128, 5, '主がシオンからあなたを祝福されるように。あなたはいのちの日の限りエルサレムへのいつくしみを見よ。'),
('JPN', '诗篇', 19, 128, 6, 'あなたの子らの子たちを見よ。イスラエルの上に平和があるように。'),
('JPN', '诗篇', 19, 129, 1, '「彼らは私が若いころからひどく私を苦しめた。」さあイスラエルは言え。'),
('JPN', '诗篇', 19, 129, 2, '「彼らは私が若いころからひどく私を苦しめた。しかし彼らは私に勝てなかった。'),
('JPN', '诗篇', 19, 129, 3, '耕す者たちは私の背に鋤をあて長いあぜを作ったが。」'),
('JPN', '诗篇', 19, 129, 4, '主は正しくあられ悪しき者の綱を断ち切られた。'),
('JPN', '诗篇', 19, 129, 5, 'シオンを憎む者はみな恥を受けて退け。'),
('JPN', '诗篇', 19, 129, 6, '彼らは伸びないうちに枯れる屋根の草のようになれ。'),
('JPN', '诗篇', 19, 129, 7, 'そのようなものを刈り取る者はつかまず束ねる者も抱えることはない。'),
('JPN', '诗篇', 19, 129, 8, '通りがかりの人も「あなたがたに主の祝福があるように。主の名によって祝福あれ」と言うことはない。'),
('JPN', '诗篇', 19, 130, 1, '主よ深い淵から私はあなたを呼び求めます。'),
('JPN', '诗篇', 19, 130, 2, '主よ私の声を聞いてください。私の願いの声に耳を傾けてください。'),
('JPN', '诗篇', 19, 130, 3, '主よあなたがもし不義に目を留められるなら主よだれが御前に立てるでしょう。'),
('JPN', '诗篇', 19, 130, 4, 'しかしあなたが赦してくださるゆえにあなたは人に恐れられます。'),
('JPN', '诗篇', 19, 130, 5, '私は主を待ち望みます。私のたましいは待ち望みます。主のみことばを私は待ちます。'),
('JPN', '诗篇', 19, 130, 6, '私のたましいは夜回りが夜明けをまことに夜回りが夜明けを待つのにまさって主を待ちます。'),
('JPN', '诗篇', 19, 130, 7, 'イスラエルよ主を待て。主には恵みがあり豊かな贖いがある。'),
('JPN', '诗篇', 19, 130, 8, '主はすべての不義からイスラエルを贖い出される。'),
('JPN', '诗篇', 19, 131, 1, '主よ私の心はおごらず私の目は高ぶりません。及びもつかない大きなことや奇しいことに私は足を踏み入れません。'),
('JPN', '诗篇', 19, 131, 2, 'まことに私は私のたましいを和らげ静めました。乳離れした子が母親とともにいるように乳離れした子のように私のたましいは私とともにあります。'),
('JPN', '诗篇', 19, 131, 3, 'イスラエルよ今よりとこしえまで主を待ち望め。'),
('JPN', '诗篇', 19, 132, 1, '主よダビデのために彼のすべての苦しみを思い出してください。'),
('JPN', '诗篇', 19, 132, 2, '彼は主に誓いヤコブの力強き方に誓いを立てました。'),
('JPN', '诗篇', 19, 132, 3, '「私は決して私の家の天幕に入りません。私のために備えられた寝床にも上がりません。'),
('JPN', '诗篇', 19, 132, 4, '私の目に眠りを与えません。私のまぶたにまどろみさえ。'),
('JPN', '诗篇', 19, 132, 5, '主のために一つの場所をヤコブの力強き方のために御住まいを私が見出すまでは。」'),
('JPN', '诗篇', 19, 132, 6, '今や私たちはエフラテでそれを聞きヤアルの野でそれを見出した。'),
('JPN', '诗篇', 19, 132, 7, 'さあ主の住まいに行き主の足台のもとにひれ伏そう。'),
('JPN', '诗篇', 19, 132, 8, '主よ立ち上がってください。あなたの安息の場所にお入りください。あなたとあなたの御力の箱も。'),
('JPN', '诗篇', 19, 132, 9, 'あなたの祭司たちが義をまといあなたにある敬虔な者たちが喜び歌いますように。'),
('JPN', '诗篇', 19, 132, 10, 'あなたのしもべダビデのためにあなたに油注がれた者を退けないでください。'),
('JPN', '诗篇', 19, 132, 11, '主はダビデに誓われた。それは主が取り消すことのない真実。「あなたの身から出る子をあなたの位に就かせる。'),
('JPN', '诗篇', 19, 132, 12, 'もしあなたの子らがわたしの契約とわたしが教えるさとしを守るなら彼らの子らもとこしえにあなたの位に就く。」'),
('JPN', '诗篇', 19, 132, 13, '主はシオンを選びそれをご自分の住まいとして望まれた。'),
('JPN', '诗篇', 19, 132, 14, '「これはとこしえにわたしの安息の場所。ここにわたしは住む。わたしがそれを望んだから。'),
('JPN', '诗篇', 19, 132, 15, 'わたしは豊かにシオンの食物を祝福しその貧しい者をパンで満ち足らせる。'),
('JPN', '诗篇', 19, 132, 16, 'その祭司たちに救いをまとわせる。その敬虔な者たちは高らかに喜び歌う。'),
('JPN', '诗篇', 19, 132, 17, 'そこにわたしはダビデのために一つの角を生えさせる。わたしに油注がれた者のためにともしびを整える。'),
('JPN', '诗篇', 19, 132, 18, 'わたしは彼の敵に恥をまとわせる。しかし彼の上には王冠が光り輝く。」'),
('JPN', '诗篇', 19, 133, 1, '見よ。なんという幸せなんという楽しさだろう。兄弟たちが一つになってともに生きることは。'),
('JPN', '诗篇', 19, 133, 2, 'それは頭に注がれた貴い油のようだ。それはひげにアロンのひげに流れて衣の端にまで流れ滴る。'),
('JPN', '诗篇', 19, 133, 3, 'それはまたヘルモンからシオンの山々に降りる露のようだ。主がそこにとこしえのいのちの祝福を命じられたからである。'),
('JPN', '诗篇', 19, 134, 1, 'さあ主をほめたたえよ。主のすべてのしもべたち夜ごとに主の家で仕える者たちよ。'),
('JPN', '诗篇', 19, 134, 2, '聖所に向かってあなたがたの手を上げ主をほめたたえよ。'),
('JPN', '诗篇', 19, 134, 3, '天地を造られた主がシオンからあなたを祝福されるように。'),
('JPN', '诗篇', 19, 135, 1, 'ハレルヤ主の御名をほめたたえよ。ほめたたえよ主のしもべたち。'),
('JPN', '诗篇', 19, 135, 2, '主の家で仕え私たちの神の家の大庭で仕える者よ。'),
('JPN', '诗篇', 19, 135, 3, 'ハレルヤ主はまことにいつくしみ深い。主の御名にほめ歌を歌え。その御名は実に麗しい。'),
('JPN', '诗篇', 19, 135, 4, '主はヤコブをご自分のために選びイスラエルをご自分の宝として選ばれた。'),
('JPN', '诗篇', 19, 135, 5, 'まことに私は知っている。主は大いなる方私たちの主はすべての神々にまさっておられる。'),
('JPN', '诗篇', 19, 135, 6, '主は望むところをことごとく行われる。天と地で海とすべての深淵で。'),
('JPN', '诗篇', 19, 135, 7, '主は地の果てから雲を上らせ雨のために稲妻を造りその倉から風を出される。'),
('JPN', '诗篇', 19, 135, 8, '主はエジプトの初子を人から家畜に至るまで打たれた。'),
('JPN', '诗篇', 19, 135, 9, 'エジプトよおまえの真っただ中に主はしるしと奇跡を送られた。ファラオとそのすべてのしもべらに。'),
('JPN', '诗篇', 19, 135, 10, '主は多くの国々を打ち力ある王たちを殺された。'),
('JPN', '诗篇', 19, 135, 11, 'アモリ人の王シホンバシャンの王オグカナンのすべての王国を。'),
('JPN', '诗篇', 19, 135, 12, '主は彼らの地をゆずりとして与えられた。御民イスラエルにゆずりとして。'),
('JPN', '诗篇', 19, 135, 13, '主よあなたの御名はとこしえに主よあなたの呼び名は代々に至ります。'),
('JPN', '诗篇', 19, 135, 14, 'まことに主はご自分の民をさばきそのしもべらをあわれまれます。'),
('JPN', '诗篇', 19, 135, 15, '異邦の民の偶像は銀や金。人の手のわざにすぎない。'),
('JPN', '诗篇', 19, 135, 16, '口があっても語れず目があっても見えない。'),
('JPN', '诗篇', 19, 135, 17, '耳があっても聞こえずまたその口には息がない。'),
('JPN', '诗篇', 19, 135, 18, 'これを造る者もこれに信頼する者もみなこれと同じ。'),
('JPN', '诗篇', 19, 135, 19, 'イスラエルの家よ主をほめたたえよ。アロンの家よ主をほめたたえよ。'),
('JPN', '诗篇', 19, 135, 20, 'レビの家よ主をほめたたえよ。主を恐れる者たちよ主をほめたたえよ。'),
('JPN', '诗篇', 19, 135, 21, 'シオンで主がほめたたえられるように。エルサレムに住まわれる方が。ハレルヤ。'),
('JPN', '诗篇', 19, 136, 1, '主に感謝せよ。主はまことにいつくしみ深い。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 2, '神の神であられる方に感謝せよ。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 3, '主の主であられる方に感謝せよ。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 4, 'ただひとり大いなる不思議を行われる方に。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 5, '英知をもって天を造られた方に感謝せよ。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 6, '地を水の上に敷かれた方に。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 7, '大きな光る物を造られた方に。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 8, '昼を治める太陽を。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 9, '夜を治める月と星を。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 10, 'エジプトの長子を打たれた方に感謝せよ。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 11, '主はイスラエルをその地から導き出された。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 12, '力強い御手と伸ばされた御腕をもって。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 13, '葦の海を二つに分けられた方に感謝せよ。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 14, 'こうして主はイスラエルにその中を通らせた。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 15, 'ファラオとその軍勢を葦の海に投げ込まれた。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 16, '荒野で御民を導かれた方に感謝せよ。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 17, '大いなる王たちを打たれた方に。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 18, '主は力ある王たちを殺された。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 19, 'アモリ人の王シホンを。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 20, 'バシャンの王オグを。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 21, 'こうして彼らの地をゆずりとして与えられた。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 22, '主のしもべイスラエルにゆずりとして。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 23, '私たちが卑しめられたとき主は心に留められた。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 24, 'そして主は私たちを敵から解き放たれた。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 25, '主はすべての肉なる者に食物を与える方。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 136, 26, '天の神に感謝せよ。主の恵みはとこしえまで。'),
('JPN', '诗篇', 19, 137, 1, 'バビロンの川のほとりそこに私たちは座りシオンを思い出して泣いた。'),
('JPN', '诗篇', 19, 137, 2, '街中の柳の木々に私たちは竪琴を掛けた。'),
('JPN', '诗篇', 19, 137, 3, 'それは私たちを捕らえて来た者たちがそこで私たちに歌を求め私たちを苦しめる者たちが余興に「シオンの歌を一つ歌え」と言ったからだ。'),
('JPN', '诗篇', 19, 137, 4, 'どうして私たちが異国の地で主の歌を歌えるだろうか。'),
('JPN', '诗篇', 19, 137, 5, 'エルサレムよもしも私があなたを忘れてしまうならこの右手もその巧みさを忘れるがよい。'),
('JPN', '诗篇', 19, 137, 6, 'もしも私があなたを思い出さずエルサレムを至上の喜びとしないなら私の舌は上あごについてしまえばよい。'),
('JPN', '诗篇', 19, 137, 7, '主よ思い出してください。エルサレムの日に「破壊せよ破壊せよ。その基までも」と言ったエドムの子らを。'),
('JPN', '诗篇', 19, 137, 8, '娘バビロンよ荒らされるべき者よ。幸いなことよおまえが私たちにしたことに仕返しする人は。'),
('JPN', '诗篇', 19, 137, 9, '幸いなことよおまえの幼子たちを捕らえ岩に打ちつける人は。'),
('JPN', '诗篇', 19, 138, 1, '心を尽くして私はあなたに感謝をささげます。御使いたちの前であなたをほめ歌います。'),
('JPN', '诗篇', 19, 138, 2, '私はあなたの聖なる宮に向かってひれ伏し恵みとまことのゆえに御名に感謝します。あなたがご自分のすべての御名のゆえにあなたのみことばを高く上げられたからです。'),
('JPN', '诗篇', 19, 138, 3, '私が呼んだその日にあなたは私に答え私のたましいに力を与えて強くされました。'),
('JPN', '诗篇', 19, 138, 4, '主よ地のすべての王はあなたに感謝するでしょう。彼らがあなたの口のみことばを聞いたからです。'),
('JPN', '诗篇', 19, 138, 5, '彼らは主の道について歌うでしょう。主の栄光が大きいからです。'),
('JPN', '诗篇', 19, 138, 6, 'まことに主は高くあられますが低い者を顧みてくださいます。しかし高ぶる者を遠くから見抜かれます。'),
('JPN', '诗篇', 19, 138, 7, '私が苦しみの中を歩いてもあなたは私を生かしてくださいます。私の敵の怒りに向かって御手を伸ばしあなたの右の手が私を救ってくださいます。'),
('JPN', '诗篇', 19, 138, 8, '主は私のためにすべてを成し遂げてくださいます。主よあなたの恵みはとこしえにあります。あなたの御手のわざをやめないでください。'),
('JPN', '诗篇', 19, 139, 1, '主よあなたは私を探り知っておられます。'),
('JPN', '诗篇', 19, 139, 2, 'あなたは私の座るのも立つのも知っておられ遠くから私の思いを読み取られます。'),
('JPN', '诗篇', 19, 139, 3, 'あなたは私が歩くのも伏すのも見守り私の道のすべてを知り抜いておられます。'),
('JPN', '诗篇', 19, 139, 4, 'ことばが私の舌にのぼる前になんと主よあなたはそのすべてを知っておられます。'),
('JPN', '诗篇', 19, 139, 5, 'あなたは前からうしろから私を取り囲み御手を私の上に置かれました。'),
('JPN', '诗篇', 19, 139, 6, 'そのような知識は私にとってあまりにも不思議あまりにも高くて及びもつきません。'),
('JPN', '诗篇', 19, 139, 7, '私はどこへ行けるでしょう。あなたの御霊から離れて。どこへ逃れられるでしょう。あなたの御前を離れて。'),
('JPN', '诗篇', 19, 139, 8, 'たとえ私が天に上ってもそこにあなたはおられ私がよみに床を設けてもそこにあなたはおられます。'),
('JPN', '诗篇', 19, 139, 9, '私が暁の翼を駆って海の果てに住んでも'),
('JPN', '诗篇', 19, 139, 10, 'そこでもあなたの御手が私を導きあなたの右の手が私を捕らえます。'),
('JPN', '诗篇', 19, 139, 11, 'たとえ私が「おお闇よ私をおおえ。私の周りの光よ夜となれ」と言っても'),
('JPN', '诗篇', 19, 139, 12, 'あなたにとっては闇も暗くなく夜は昼のように明るいのです。暗闇も光も同じことです。'),
('JPN', '诗篇', 19, 139, 13, 'あなたこそ私の内臓を造り母の胎の内で私を組み立てられた方です。'),
('JPN', '诗篇', 19, 139, 14, '私は感謝します。あなたは私に奇しいことをなさって恐ろしいほどです。私のたましいはそれをよく知っています。'),
('JPN', '诗篇', 19, 139, 15, '私が隠れた所で造られ地の深い所で織り上げられたとき私の骨組みはあなたに隠れてはいませんでした。'),
('JPN', '诗篇', 19, 139, 16, 'あなたの目は胎児の私を見られあなたの書物にすべてが記されました。私のために作られた日々がしかもその一日もないうちに。'),
('JPN', '诗篇', 19, 139, 17, '神よあなたの御思いを知るのはなんと難しいことでしょう。そのすべてはなんと多いことでしょう。'),
('JPN', '诗篇', 19, 139, 18, '数えようとしてもそれは砂よりも数多いのです。私が目覚めるとき私はなおもあなたとともにいます。'),
('JPN', '诗篇', 19, 139, 19, '神よどうか悪者を殺してください。人の血を流す者どもよ私から遠ざかれ。'),
('JPN', '诗篇', 19, 139, 20, '彼らは敵意をもってあなたに語りあなたの敵はみだりに御名を口にします。'),
('JPN', '诗篇', 19, 139, 21, '主よ私はあなたを憎む者たちを憎まないでしょうか。あなたに立ち向かう者を嫌わないでしょうか。'),
('JPN', '诗篇', 19, 139, 22, '私は憎しみの限りを尽くして彼らを憎みます。彼らは私の敵となりました。'),
('JPN', '诗篇', 19, 139, 23, '神よ私を探り私の心を知ってください。私を調べ私の思い煩いを知ってください。'),
('JPN', '诗篇', 19, 139, 24, '私のうちに傷のついた道があるかないかを見て私をとこしえの道に導いてください。'),
('JPN', '诗篇', 19, 140, 1, '主よ私をよこしまな人から助け出し暴虐を行う者から守ってください。'),
('JPN', '诗篇', 19, 140, 2, '彼らは心の中で悪を企み日ごとに戦いを仕掛けてきます。'),
('JPN', '诗篇', 19, 140, 3, '蛇のようにその舌を鋭くし唇の下にはまむしの毒があります。セラ'),
('JPN', '诗篇', 19, 140, 4, '主よ悪しき者の手から私を守り暴虐を行う者からお守りください。彼らは私の足をつまずかせようと企んでいます。'),
('JPN', '诗篇', 19, 140, 5, '高ぶる者は私に罠を仕掛け綱で網を広げ道端に落とし穴を設けました。セラ'),
('JPN', '诗篇', 19, 140, 6, '私は主に申し上げます。「あなたは私の神。主よ私の願いの声を聞いてください。'),
('JPN', '诗篇', 19, 140, 7, '私の主神私の救いの力よ。あなたは私が武器を取る日に私の頭をおおってくださいました。'),
('JPN', '诗篇', 19, 140, 8, '主よ悪者の願いをかなえさせずその企みを遂げさせないでください。彼らは高ぶっています。セラ'),
('JPN', '诗篇', 19, 140, 9, '私を取り囲んでいる者たちの頭。これを自らの唇の害悪がおおいますように。'),
('JPN', '诗篇', 19, 140, 10, '燃える炭火が彼らの上に降りかかりますように。彼らが火の中に深い淵に落とされ立ち上がれないようにしてください。'),
('JPN', '诗篇', 19, 140, 11, 'そしる者が地上で栄えませんように。わざわいがすぐにも暴虐を行う者を捕らえるようにしてください。」'),
('JPN', '诗篇', 19, 140, 12, '私は知っています。主が苦しむ者の訴えを支持し貧しい者のためにさばきを行われることを。'),
('JPN', '诗篇', 19, 140, 13, 'まことに正しい人はあなたの御名に感謝し直ぐな人はあなたの御前に住むでしょう。'),
('JPN', '诗篇', 19, 141, 1, '主よ私はあなたを呼び求めています。私のところに急いでください。私があなたに呼び求めるときに私の声に耳を傾けてください。'),
('JPN', '诗篇', 19, 141, 2, '私の祈りが御前への香として手を上げる祈りが夕べのささげ物として立ち上りますように。'),
('JPN', '诗篇', 19, 141, 3, '主よ私の口に見張りを置き私の唇の戸を守ってください。'),
('JPN', '诗篇', 19, 141, 4, '私の心を悪に向けさせず不法を行う者たちとともに悪い行いに携わらないようにしてください。私が彼らのごちそうを食べないようにしてください。'),
('JPN', '诗篇', 19, 141, 5, '正しい人が真実の愛をもって私を打ち頭に注ぐ油で私を戒めてくれますように。私の頭がそれを拒まないようにしてください。彼らが悪行を重ねてもなおも私は祈ります。'),
('JPN', '诗篇', 19, 141, 6, '彼らのさばき人たちが岩の傍らに投げ落とされるとき彼らは私のことばがどんなに優しいものだったかを知るでしょう。'),
('JPN', '诗篇', 19, 141, 7, '人が地を掘り起こして砕くときのように私たちの骨はよみの入り口にまき散らされました。'),
('JPN', '诗篇', 19, 141, 8, '私の主神よまことに私の目はあなたに向いています。私はあなたに身を避けています。私のたましいを危険にさらさないでください。'),
('JPN', '诗篇', 19, 141, 9, 'どうか彼らが私に仕掛けた罠から不法を行う者の落とし穴から私を守ってください。'),
('JPN', '诗篇', 19, 141, 10, '私が無事に通り過ぎるとき悪者が自分の網に陥りますように。'),
('JPN', '诗篇', 19, 142, 1, '声をあげて私は主に叫びます。声をあげて私は主にあわれみを乞います。'),
('JPN', '诗篇', 19, 142, 2, '私は御前に自分の嘆きを注ぎ出し私の苦しみを御前に言い表します。'),
('JPN', '诗篇', 19, 142, 3, '私の霊が私のうちで衰え果てたときにもあなたは私の道をよく知っておられます。私が歩くその道に彼らは罠を仕掛けています。'),
('JPN', '诗篇', 19, 142, 4, 'ご覧ください私の右に目を注いでください。私には顧みてくれる人がいません。私は逃げ場さえも失って私のいのちを気にかける人もいないのです。'),
('JPN', '诗篇', 19, 142, 5, '主よ私はあなたに叫びます。「あなたこそ私の避け所生ける者の地での私の受ける分。'),
('JPN', '诗篇', 19, 142, 6, 'どうか私の叫びに耳を傾けてください。私はひどくおとしめられていますから。私を迫害する者から救い出してください。彼らは私よりも強いのです。'),
('JPN', '诗篇', 19, 142, 7, '私のたましいを牢獄から助け出し私があなたの御名に感謝するようにしてください。正しい人たちは私の周りに集まるでしょう。あなたが私に良くしてくださるからです。」'),
('JPN', '诗篇', 19, 143, 1, '主よ私の祈りを聞き私の願いに耳を傾けてください。あなたの真実と義によって私に答えてください。'),
('JPN', '诗篇', 19, 143, 2, 'あなたのしもべをさばきにかけないでください。生ける者はだれ一人あなたの前に正しいと認められないからです。'),
('JPN', '诗篇', 19, 143, 3, '敵は私のたましいを追いつめ私のいのちを地に打ちつけ死んで久しい者のように私を闇にとどめます。'),
('JPN', '诗篇', 19, 143, 4, 'それゆえ私の霊は私のうちで衰え果て心は私の中で荒れすさんでしまいました。'),
('JPN', '诗篇', 19, 143, 5, '私は昔の日々を思い起こしあなたのすべてのみわざに思いを巡らしあなたの御手のわざを静かに考えています。'),
('JPN', '诗篇', 19, 143, 6, 'あなたに向かって私は手を伸べ広げ私のたましいは乾ききった地のようにあなたを慕います。セラ'),
('JPN', '诗篇', 19, 143, 7, '主よ早く私に答えてください。私の霊は滅びてしまいます。どうか御顔を私に隠さないでください。私が穴に下る者と等しくならないように。'),
('JPN', '诗篇', 19, 143, 8, '朝にあなたの恵みを聞かせてください。私はあなたに信頼していますから。行くべき道を知らせてください。私のたましいはあなたを仰いでいますから。'),
('JPN', '诗篇', 19, 143, 9, '主よ私を敵から救い出してください。私はあなたのうちに身を隠します。'),
('JPN', '诗篇', 19, 143, 10, 'あなたのみこころを行うことを教えてください。あなたは私の神であられますから。あなたのいつくしみ深い霊が平らな地に私を導いてくださいますように。'),
('JPN', '诗篇', 19, 143, 11, '主よあなたの御名のゆえに私を生かしあなたの義によって私のたましいを苦しみから助け出してください。'),
('JPN', '诗篇', 19, 143, 12, 'あなたの恵みによって私の敵を滅ぼし私のたましいに敵対するすべての者を消し去ってください。私はあなたのしもべですから。'),
('JPN', '诗篇', 19, 144, 1, 'わが岩なる主がほめたたえられますように。戦いのために私の手を戦のために私の指を鍛えられる方が。'),
('JPN', '诗篇', 19, 144, 2, '主は私の恵み私の砦私のやぐら私の救い主私の盾私の避け所私の民を私に服させる方。'),
('JPN', '诗篇', 19, 144, 3, '主よ人とは何ものなのでしょう。あなたがこれを知っておられるとは。人の子とはいったい何ものなのでしょう。あなたがこれを顧みられるとは。'),
('JPN', '诗篇', 19, 144, 4, '人は息にすぎずその日々は影のように過ぎ去ります。'),
('JPN', '诗篇', 19, 144, 5, '主よあなたの天を押し曲げて降りて来てください。山々に触れて噴煙を上げさせてください。'),
('JPN', '诗篇', 19, 144, 6, '稲妻を放って彼らを散らしあなたの矢を放って彼らをかき乱してください。'),
('JPN', '诗篇', 19, 144, 7, 'いと高き所からあなたの御手を伸べ大水からまた異国人の手から私を解き放ち救い出してください。'),
('JPN', '诗篇', 19, 144, 8, '彼らの口は噓を言いその右の手は偽りの右手です。'),
('JPN', '诗篇', 19, 144, 9, '神よあなたに私は新しい歌を歌い十弦の琴に合わせてほめ歌を歌います。'),
('JPN', '诗篇', 19, 144, 10, '神は王たちに救いを与え神のしもべダビデを悪の剣から解き放たれます。'),
('JPN', '诗篇', 19, 144, 11, '私を異国人の手から解き放ち救い出してください。彼らの口は噓を言いその右の手は偽りの右手です。'),
('JPN', '诗篇', 19, 144, 12, '私たちの息子らが若いうちからよく育てられた植木のようになりますように。私たちの娘らが宮殿にふさわしく刻まれた隅の柱のようになりますように。'),
('JPN', '诗篇', 19, 144, 13, '私たちの倉はもろもろの産物で満ちますように。私たちの羊の群れは私たちの野で幾千幾万となりますように。'),
('JPN', '诗篇', 19, 144, 14, '私たちの牛が子牛をよくはらみ早産も流産もなく哀れな叫び声が私たちの町にありませんように。'),
('JPN', '诗篇', 19, 144, 15, '幸いなことよこのようになる民は。幸いなことよ主を自らの神とする民は。'),
('JPN', '诗篇', 19, 145, 1, '私の神王よ私はあなたをあがめます。あなたの御名を世々限りなくほめたたえます。'),
('JPN', '诗篇', 19, 145, 2, '日ごとにあなたをほめたたえあなたの御名を世々限りなく賛美します。'),
('JPN', '诗篇', 19, 145, 3, '主は大いなる方。大いに賛美されるべき方。その偉大さは測り知ることもできません。'),
('JPN', '诗篇', 19, 145, 4, '代は代へとあなたのみわざをほめ歌いあなたの大能のわざを告げ知らせます。'),
('JPN', '诗篇', 19, 145, 5, '私はあなたの主権の栄光の輝きあなたの奇しいみわざを語り伝えます。'),
('JPN', '诗篇', 19, 145, 6, '人々はあなたの恐ろしいみわざの力を告げ私はあなたの偉大さを語ります。'),
('JPN', '诗篇', 19, 145, 7, '人々はあなたの豊かないつくしみの思い出をあふれるばかりに語りあなたの義を高らかに歌います。'),
('JPN', '诗篇', 19, 145, 8, '主は情け深くあわれみ深く怒るのに遅く恵みに富んでおられます。'),
('JPN', '诗篇', 19, 145, 9, '主はすべてのものにいつくしみ深くそのあわれみは造られたすべてのものの上にあります。'),
('JPN', '诗篇', 19, 145, 10, '主よあなたが造られたすべてのものはあなたに感謝しあなたにある敬虔な者たちはあなたをほめたたえます。'),
('JPN', '诗篇', 19, 145, 11, '彼らはあなたの王国の栄光を告げあなたの大能のわざを語ります。'),
('JPN', '诗篇', 19, 145, 12, 'こうして人の子らに主の大能のわざと主の王国の輝かしい栄光を知らせます。'),
('JPN', '诗篇', 19, 145, 13, 'あなたの王国は永遠にわたる王国。あなたの統治は代々限りなく続きます。'),
('JPN', '诗篇', 19, 145, 14, '主は倒れる者をみな支えかがんでいる者をみな起こされます。'),
('JPN', '诗篇', 19, 145, 15, 'すべての目はあなたを待ち望んでいます。あなたは時にかなって彼らに食物を与えられます。'),
('JPN', '诗篇', 19, 145, 16, 'あなたは御手を開き生けるものすべての願いを満たされます。'),
('JPN', '诗篇', 19, 145, 17, '主はご自分のすべての道において正しくそのすべてのみわざにおいて恵み深い方。'),
('JPN', '诗篇', 19, 145, 18, '主を呼び求める者すべてまことをもって主を呼び求める者すべてに主は近くあられます。'),
('JPN', '诗篇', 19, 145, 19, 'また主を恐れる者の願いをかなえ彼らの叫びを聞いて救われます。'),
('JPN', '诗篇', 19, 145, 20, 'すべて主を愛する者は主が守られます。しかし悪しき者はみな滅ぼされます。'),
('JPN', '诗篇', 19, 145, 21, '私の口が主の誉れを語りすべて肉なる者が聖なる御名を世々限りなくほめたたえますように。'),
('JPN', '诗篇', 19, 146, 1, 'ハレルヤ。わがたましいよ主をほめたたえよ。'),
('JPN', '诗篇', 19, 146, 2, '私は生きているかぎり主をほめたたえる。いのちのあるかぎり私の神にほめ歌を歌う。'),
('JPN', '诗篇', 19, 146, 3, 'あなたがたは君主を頼みとしてはならない。救いのない人間の子を。'),
('JPN', '诗篇', 19, 146, 4, '霊が出て行くと人は自分の土に帰りその日のうちに彼の計画は滅び失せる。'),
('JPN', '诗篇', 19, 146, 5, '幸いなことよヤコブの神を助けとしその神主に望みを置く人。'),
('JPN', '诗篇', 19, 146, 6, '主は天と地と海またそれらの中のすべてのものを造られた方。とこしえまでも真実を守り'),
('JPN', '诗篇', 19, 146, 7, '虐げられている者のためにさばきを行い飢えている者にパンを与える方。主は捕らわれ人を解放される。'),
('JPN', '诗篇', 19, 146, 8, '主は目の見えない者たちの目を開け主はかがんでいる者たちを起こされる。主は正しい者たちを愛し'),
('JPN', '诗篇', 19, 146, 9, '主は寄留者を守りみなしごとやもめを支えられる。しかし悪しき者の道は主が曲げられる。'),
('JPN', '诗篇', 19, 146, 10, '主はとこしえに統べ治められる。シオンよあなたの神は代々に統べ治められる。ハレルヤ。'),
('JPN', '诗篇', 19, 147, 1, 'ハレルヤ。まことにわれらの神にほめ歌を歌うのは良い。まことに楽しく賛美は麗しい。'),
('JPN', '诗篇', 19, 147, 2, '主はエルサレムを建てイスラエルの散らされた者たちを集められる。'),
('JPN', '诗篇', 19, 147, 3, '主は心の打ち砕かれた者を癒やし彼らの傷を包まれる。'),
('JPN', '诗篇', 19, 147, 4, '主は星の数を数えそのすべてに名をつけられる。'),
('JPN', '诗篇', 19, 147, 5, 'われらの主は偉大であり力強くその英知は測り知れない。'),
('JPN', '诗篇', 19, 147, 6, '主は心の貧しい者を支え悪しき者を地面に引き降ろされる。'),
('JPN', '诗篇', 19, 147, 7, '感謝をもって主に歌え。竪琴に合わせてわれらの神にほめ歌を歌え。'),
('JPN', '诗篇', 19, 147, 8, '神は濃い雲で天をおおい地のために雨を備えまた山々に草を生えさせ'),
('JPN', '诗篇', 19, 147, 9, '獣にまた鳴く烏の子に食物を与える方。'),
('JPN', '诗篇', 19, 147, 10, '神は馬の力を喜ばず人の足の速さを好まれない。'),
('JPN', '诗篇', 19, 147, 11, '主を恐れる者と御恵みを待ち望む者とを主は好まれる。'),
('JPN', '诗篇', 19, 147, 12, 'エルサレムよ主をほめ歌え。シオンよあなたの神をほめたたえよ。'),
('JPN', '诗篇', 19, 147, 13, '主はあなたの門のかんぬきを強めあなたの中にいる子らを祝福しておられるからだ。'),
('JPN', '诗篇', 19, 147, 14, '主はあなたの地境に平和を置き最良の小麦であなたを満たされる。'),
('JPN', '诗篇', 19, 147, 15, '主は地に仰せのことばを送りそのみことばは速やかに走る。'),
('JPN', '诗篇', 19, 147, 16, '主は羊毛のように雪を降らせ灰のように霜をまかれる。'),
('JPN', '诗篇', 19, 147, 17, '主は氷をパン屑のように投げつけられる。だれがその寒さに耐えられるだろうか。'),
('JPN', '诗篇', 19, 147, 18, '主がみことばを送ってこれらを溶かしご自分の風を吹かせると水は流れる。'),
('JPN', '诗篇', 19, 147, 19, '主はヤコブにはみことばをイスラエルにはおきてとさばきを告げられる。'),
('JPN', '诗篇', 19, 147, 20, '主はどのような国々にもこのようにはなさらなかった。さばきについて彼らは知らない。ハレルヤ。'),
('JPN', '诗篇', 19, 148, 1, 'ハレルヤ。天において主をほめたたえよ。いと高き所で主をほめたたえよ。'),
('JPN', '诗篇', 19, 148, 2, '主をほめたたえよすべての御使いよ。主をほめたたえよ主の万軍よ。'),
('JPN', '诗篇', 19, 148, 3, '日よ月よ主をほめたたえよ。主をほめたたえよすべての輝く星よ。'),
('JPN', '诗篇', 19, 148, 4, '天の天よ主をほめたたえよ。天の上にある水よ。'),
('JPN', '诗篇', 19, 148, 5, '主の御名をほめたたえよ。主が命じてそれらは創造されたのだ。'),
('JPN', '诗篇', 19, 148, 6, '主はそれらを世々限りなく立てられた。主は去りゆくことのない定めを置かれた。'),
('JPN', '诗篇', 19, 148, 7, '地において主をほめたたえよ。海の巨獣よすべての淵よ。'),
('JPN', '诗篇', 19, 148, 8, '火よ雹よ雪よ煙よ。みことばを行う激しい風よ。'),
('JPN', '诗篇', 19, 148, 9, '山々よすべての丘よ。実のなる木よすべての杉よ。'),
('JPN', '诗篇', 19, 148, 10, '獣よすべての家畜よ。這うものよ翼のある鳥よ。'),
('JPN', '诗篇', 19, 148, 11, '地の王たちよすべての国民よ。君主たちよ地をさばくすべての者たちよ。'),
('JPN', '诗篇', 19, 148, 12, '若い男よ若い女よ。年老いた者と幼い者よ。'),
('JPN', '诗篇', 19, 148, 13, '主の御名をほめたたえよ。主の御名だけがあがめられる。その威光が地と天の上で。'),
('JPN', '诗篇', 19, 148, 14, '主は御民の角を上げられた。主にある敬虔な者すべての賛美を主の近くにいる民イスラエルの子らの賛美を。ハレルヤ。'),
('JPN', '诗篇', 19, 149, 1, 'ハレルヤ。新しい歌を主に歌え。敬虔な者たちの集まりで主への賛美を。'),
('JPN', '诗篇', 19, 149, 2, 'イスラエルは自らの造り主にあって喜べ。シオンの子らは自らの王にあって楽しめ。'),
('JPN', '诗篇', 19, 149, 3, '踊りをもって主の御名をほめたたえよ。タンバリンと竪琴に合わせて主にほめ歌を歌え。'),
('JPN', '诗篇', 19, 149, 4, '主はご自分の民を愛し貧しい者たちを救いをもって装われる。'),
('JPN', '诗篇', 19, 149, 5, '敬虔な者たちは栄光の中で喜び躍れ。自らの床の上で高らかに歌え。'),
('JPN', '诗篇', 19, 149, 6, '彼らの口には神への称賛があり彼らの手には両刃の剣があるように。'),
('JPN', '诗篇', 19, 149, 7, 'それは国々に復讐しもろもろの国民を懲らしめるため'),
('JPN', '诗篇', 19, 149, 8, '彼らの王たちを鎖に彼らの貴族たちを鉄のかせにつなぐため'),
('JPN', '诗篇', 19, 149, 9, 'また書き記されたさばきを彼らの間で行うため。これは主にある敬虔な者すべての誉れである。ハレルヤ。'),
('JPN', '诗篇', 19, 150, 1, 'ハレルヤ。神の聖所で神をほめたたえよ。御力の大空で神をほめたたえよ。'),
('JPN', '诗篇', 19, 150, 2, 'その大能のみわざのゆえに神をほめたたえよ。その比類なき偉大さにふさわしく神をほめたたえよ。'),
('JPN', '诗篇', 19, 150, 3, '角笛を吹き鳴らして神をほめたたえよ。琴と竪琴に合わせて神をほめたたえよ。'),
('JPN', '诗篇', 19, 150, 4, 'タンバリンと踊りをもって神をほめたたえよ。弦をかき鳴らし笛を吹いて神をほめたたえよ。'),
('JPN', '诗篇', 19, 150, 5, '音の高いシンバルで神をほめたたえよ。鳴り響くシンバルで神をほめたたえよ。'),
('JPN', '诗篇', 19, 150, 6, '息のあるものはみな主をほめたたえよ。ハレルヤ。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '箴言', 20, 1, 1, 'イスラエルの王、ダビデの子ソロモンの箴言。'),
('JPN', '箴言', 20, 1, 2, 'これは、知恵と訓戒を知り、悟りのことばを理解するため、'),
('JPN', '箴言', 20, 1, 3, '義とさばきと公正において、訓戒を受けて、さとくなるため、'),
('JPN', '箴言', 20, 1, 4, '浅はかな者を賢くし、若い者に知識と思慮を得させるためのもの。'),
('JPN', '箴言', 20, 1, 5, '知恵のある者は聞いて洞察を深め、分別のある者は導きを得る。'),
('JPN', '箴言', 20, 1, 6, 'こうして、箴言と比喩、知恵のある者のことばと謎を理解する。'),
('JPN', '箴言', 20, 1, 7, '主を恐れることは知識の初め。愚か者は知恵と訓戒を蔑む。'),
('JPN', '箴言', 20, 1, 8, 'わが子よ、父の訓戒に聞き従え。母の教えを捨ててはならない。'),
('JPN', '箴言', 20, 1, 9, 'それらは、あなたの頭に戴く麗しい花の冠、首にかける飾りだから。'),
('JPN', '箴言', 20, 1, 10, 'わが子よ。罪人たちがあなたを惑わしても、それに応じてはならない。'),
('JPN', '箴言', 20, 1, 11, 'もし彼らがこう言っても。「一緒に来い。人の血を流すために待ち伏せしよう。咎なき者を、理由なしにひそかに狙い、'),
('JPN', '箴言', 20, 1, 12, 'よみのように、彼らを生きたままで吞み込もう。全き者たちを、墓に下る者のようにして。'),
('JPN', '箴言', 20, 1, 13, '値打ちのある物は何でも見つけ出し、奪った物でわれわれの家を満たそう。'),
('JPN', '箴言', 20, 1, 14, 'われわれはくじで分け合い、皆で一つの金入れを持とう。」'),
('JPN', '箴言', 20, 1, 15, 'わが子よ、彼らと一緒に道を歩いてはならない。彼らの通り道に、足を踏み入れてはならない。'),
('JPN', '箴言', 20, 1, 16, '彼らの足は悪に走り、人の血を流すのに速いからだ。'),
('JPN', '箴言', 20, 1, 17, '網を張るのは無駄なこと。すべて翼あるものの目の前では。'),
('JPN', '箴言', 20, 1, 18, '彼らが待ち伏せしているのは自分の血を流すため、隠れ狙っているのは自らのたましい。'),
('JPN', '箴言', 20, 1, 19, '不正な利得を貪る者の道はみな、このようなもの。それを得る者たちはたましいを取り去られる。'),
('JPN', '箴言', 20, 1, 20, '知恵は大通りで叫び、広場でその声をあげ、'),
('JPN', '箴言', 20, 1, 21, '騒々しい街角で叫び、町の門の入り口で、そのことばを語る。'),
('JPN', '箴言', 20, 1, 22, '「浅はかな者よ、おまえたちは、いつまで浅はかなことを愛するのか。嘲る者は、いつまで嘲ることを欲するのか。分別のない者は、いつまで知識を憎むのか。'),
('JPN', '箴言', 20, 1, 23, 'わたしの叱責に立ち返れ。おまえたちにわたしの霊を注ぎ、わたしのことばを知らせよう。'),
('JPN', '箴言', 20, 1, 24, 'わたしが呼んだのに、おまえたちは拒んだ。手を差し伸べたのに、耳を傾ける者はなかった。'),
('JPN', '箴言', 20, 1, 25, 'おまえたちはわたしの忠告をすべてなおざりにし、わたしの叱責を一つも受け入れなかった。'),
('JPN', '箴言', 20, 1, 26, 'わたしも、おまえたちが災難にあうときに笑い、恐怖がおまえたちを襲うとき、あざ笑う。'),
('JPN', '箴言', 20, 1, 27, '恐怖が嵐のようにおまえたちを襲うとき、災難がつむじ風のようにおまえたちに来るとき、苦難と苦悩がおまえたちを襲うとき、'),
('JPN', '箴言', 20, 1, 28, 'そのとき、わたしを呼んでも、わたしは答えない。わたしを捜し求めても、見出すことはできない。'),
('JPN', '箴言', 20, 1, 29, 'それは、彼らが知識を憎み、主を恐れることを選ばず、'),
('JPN', '箴言', 20, 1, 30, 'わたしの忠告を受け入れようとせず、わたしの叱責をことごとく侮ったからだ。'),
('JPN', '箴言', 20, 1, 31, 'それで、彼らは自分の行いの実を食らい、自分が企んだことで腹を満たす。'),
('JPN', '箴言', 20, 1, 32, '浅はかな者の背信は自分を殺し、愚かな者の安心は自分を滅ぼす。'),
('JPN', '箴言', 20, 1, 33, 'しかし、わたしに聞き従う者は、安全に住み、わざわいを恐れることなく、安らかである。」'),
('JPN', '箴言', 20, 2, 1, 'わが子よ。もしあなたが私のことばを受け入れ、私の命令をあなたのうちに蓄え、'),
('JPN', '箴言', 20, 2, 2, 'あなたの耳を知恵に傾け、心を英知に向けるなら、'),
('JPN', '箴言', 20, 2, 3, 'もしあなたが悟りに呼びかけ、英知に向かって声をあげ、'),
('JPN', '箴言', 20, 2, 4, '銀のように、これを探し、隠された宝のように探り出すなら、'),
('JPN', '箴言', 20, 2, 5, 'そのとき、あなたは主を恐れることをわきまえ知り、神を知ることを見出すようになる。'),
('JPN', '箴言', 20, 2, 6, '主が知恵を与え、御口から知識と英知が出るからだ。'),
('JPN', '箴言', 20, 2, 7, '主は正直な人のために、すぐれた知性を蓄え、誠実に歩む人たちの盾となり、'),
('JPN', '箴言', 20, 2, 8, '公正の道筋を保ち、主にある敬虔な人たちの道を守られる。'),
('JPN', '箴言', 20, 2, 9, 'そのとき、あなたは義とさばきと公正を、またすべての良い道筋をわきまえ知る。'),
('JPN', '箴言', 20, 2, 10, '知恵があなたの心に入り、知識がたましいに喜びとなるからだ。'),
('JPN', '箴言', 20, 2, 11, '思慮はあなたを守り、英知はあなたを保つ。'),
('JPN', '箴言', 20, 2, 12, 'それらはあなたを悪の道から、ねじれごとを語る者たちから救い出す。'),
('JPN', '箴言', 20, 2, 13, 'その者たちはまっすぐな進路を捨てて闇の道に歩み、'),
('JPN', '箴言', 20, 2, 14, '悪を行うことを楽しみとし、悪しきねじれごとを喜んでいる。'),
('JPN', '箴言', 20, 2, 15, 'その進む道は曲がり、彼らは道筋を誤る。'),
('JPN', '箴言', 20, 2, 16, 'また思慮と英知は、あなたをよその女から、ことばの滑らかな見知らぬ女から救い出す。'),
('JPN', '箴言', 20, 2, 17, 'この女は若いころの連れ合いを捨てて、自分の神との契約を忘れている。'),
('JPN', '箴言', 20, 2, 18, '彼女の家は死へと、その道筋は死者の霊の国へと下る。'),
('JPN', '箴言', 20, 2, 19, 'この女のもとへ行く者はだれも帰って来ない。いのちの道に至ることはない。'),
('JPN', '箴言', 20, 2, 20, 'こうして、あなたは善良な人たちの道に歩み、正しい人たちの進む道を守る。'),
('JPN', '箴言', 20, 2, 21, '正直な人たちは地に住まいを得、全き人たちは地に生き残る。'),
('JPN', '箴言', 20, 2, 22, 'しかし、悪しき者たちは地から断たれ、裏切り者たちは地から引き抜かれる。'),
('JPN', '箴言', 20, 3, 1, 'わが子よ、私の教えを忘れるな。心に私の命令を保つようにせよ。'),
('JPN', '箴言', 20, 3, 2, '長い日々と、いのちと平安の年月が、あなたに増し加えられるからだ。'),
('JPN', '箴言', 20, 3, 3, '恵みとまことがあなたを捨てないようにせよ。それをあなたの首に結び、心の板に書き記せ。'),
('JPN', '箴言', 20, 3, 4, '神と人の前に好意を得、聡明であれ。'),
('JPN', '箴言', 20, 3, 5, '心を尽くして主に拠り頼め。自分の悟りに頼るな。'),
('JPN', '箴言', 20, 3, 6, 'あなたの行く道すべてにおいて、主を知れ。主があなたの進む道をまっすぐにされる。'),
('JPN', '箴言', 20, 3, 7, '自分を知恵のある者と考えるな。主を恐れ、悪から遠ざかれ。'),
('JPN', '箴言', 20, 3, 8, 'それは、あなたのからだに癒やしとなり、あなたの骨に潤いとなる。'),
('JPN', '箴言', 20, 3, 9, 'あなたの財産で主をあがめよ。あなたのすべての収穫の初物で。'),
('JPN', '箴言', 20, 3, 10, 'そうすれば、あなたの倉は豊かさで満たされ、あなたの石がめは新しいぶどう酒であふれる。'),
('JPN', '箴言', 20, 3, 11, 'わが子よ、主の懲らしめを拒むな。その叱責を嫌うな。'),
('JPN', '箴言', 20, 3, 12, '父がいとしい子を叱るように、主は愛する者を叱る。'),
('JPN', '箴言', 20, 3, 13, '幸いなことよ、知恵を見出す人、英知をいただく人は。'),
('JPN', '箴言', 20, 3, 14, '知恵で得るものは金で得るものにまさり、その収穫は黄金にまさるからだ。'),
('JPN', '箴言', 20, 3, 15, '知恵は真珠よりも尊く、あなたが喜ぶどんなものも、それと比べられない。'),
('JPN', '箴言', 20, 3, 16, '知恵の右の手には長寿があり、左の手には富と誉れがある。'),
('JPN', '箴言', 20, 3, 17, '知恵の道は楽しい道。その通り道はみな平安である。'),
('JPN', '箴言', 20, 3, 18, '知恵は、これを握りしめる者にはいのちの木。これをつかんでいる者は幸いである。'),
('JPN', '箴言', 20, 3, 19, '主は知恵をもって地の基を定め、英知をもって天を堅く立てられた。'),
('JPN', '箴言', 20, 3, 20, '主の知識によって深淵は張り裂け、雲は露を滴らせる。'),
('JPN', '箴言', 20, 3, 21, 'わが子よ、見失ってはならない。知性と思慮をよく見守れ。'),
('JPN', '箴言', 20, 3, 22, 'それらは、たましいのいのちとなり、あなたの首に麗しさを添える。'),
('JPN', '箴言', 20, 3, 23, 'こうして、安心して自分の道を歩み、あなたの足はつまずかない。'),
('JPN', '箴言', 20, 3, 24, '横たわるとき、あなたに恐れはない。休むとき、眠りは心地よい。'),
('JPN', '箴言', 20, 3, 25, 'にわかに起こる恐怖に、悪しき者たちの来襲に、おびえるな。'),
('JPN', '箴言', 20, 3, 26, '主があなたの頼みであり、足が罠にかからないように、守ってくださるから。'),
('JPN', '箴言', 20, 3, 27, 'あなたの手に善を行う力があるとき、受けるべき者にそれを控えてはならない。'),
('JPN', '箴言', 20, 3, 28, 'あなたに物があるとき、隣人に向かって、「帰って、また来なさい。明日あげよう」と言うな。'),
('JPN', '箴言', 20, 3, 29, '隣人が、あなたのそばで安心して住んでいるとき、その人に悪を企むな。'),
('JPN', '箴言', 20, 3, 30, 'あなたに悪い仕打ちをしていないのなら、理由もなく人と争うな。'),
('JPN', '箴言', 20, 3, 31, '暴虐を行う者を羨むな。彼の道をどれ一つ選ぶな。'),
('JPN', '箴言', 20, 3, 32, '主は、曲がった者を忌み嫌い、直ぐな人と親しくされるからだ。'),
('JPN', '箴言', 20, 3, 33, '悪しき者の家には、主ののろいがある。正しい人の住まいは、主が祝福される。'),
('JPN', '箴言', 20, 3, 34, '嘲る者を主は嘲り、へりくだった者には恵みを与えられる。'),
('JPN', '箴言', 20, 3, 35, '知恵のある者は誉れを受け継ぎ、愚かな者は恥辱を高く掲げる。'),
('JPN', '箴言', 20, 4, 1, '子たちよ、父の訓戒に聞き従え。耳を傾け、悟りを得よ。'),
('JPN', '箴言', 20, 4, 2, '私が良い教訓をあなたがたに授けるからだ。私の教えを捨ててはならない。'),
('JPN', '箴言', 20, 4, 3, '私が、父にとっては息子であり、母にとっては、かよわいひとり子であったとき、'),
('JPN', '箴言', 20, 4, 4, '父は私を教えて言った。「私のことばがおまえの心を支えるように。私の命令を守って生きよ。'),
('JPN', '箴言', 20, 4, 5, '知恵を得よ。悟りを得よ。忘れてはならない。私の口のことばからそれてはならない。'),
('JPN', '箴言', 20, 4, 6, '知恵を捨てるな。これがあなたを守る。これを愛せ。これがあなたを保つ。'),
('JPN', '箴言', 20, 4, 7, '知恵の初めに、知恵を買え。あなたが得たものすべてに換えて、悟りを買え。'),
('JPN', '箴言', 20, 4, 8, 'それを尊べ。それはあなたを高める。それを抱きしめると、それはあなたに誉れを与える。'),
('JPN', '箴言', 20, 4, 9, 'それは頭に麗しい花の冠を与え、輝かしい冠をあなたに授ける。」'),
('JPN', '箴言', 20, 4, 10, 'わが子よ、聞け。私の言うことを受け入れよ。そうすれば、あなたのいのちの年月は増す。'),
('JPN', '箴言', 20, 4, 11, '私は知恵の道をあなたに教え、まっすぐな道筋にあなたを導いた。'),
('JPN', '箴言', 20, 4, 12, 'あなたが歩むとき、その歩みは妨げられず、走っても、つまずくことはない。'),
('JPN', '箴言', 20, 4, 13, '訓戒を握りしめて、手放すな。それを保て。それはあなたのいのちだから。'),
('JPN', '箴言', 20, 4, 14, '悪しき者たちの進む道に入るな。悪人たちの道を行ってはならない。'),
('JPN', '箴言', 20, 4, 15, 'それを無視せよ。そこを通るな。それを避けて通れ。'),
('JPN', '箴言', 20, 4, 16, 'まことに、彼らは悪を行わなければ眠れず、人をつまずかせなければ、その眠りが奪われる。'),
('JPN', '箴言', 20, 4, 17, 'まことに、彼らは不義のパンを食べ、暴虐の酒を飲む。'),
('JPN', '箴言', 20, 4, 18, '正しい人の進む道は、あけぼのの光のようだ。いよいよ輝きを増して真昼となる。'),
('JPN', '箴言', 20, 4, 19, '悪しき者の道は暗闇のよう。彼らは何につまずくかを知らない。'),
('JPN', '箴言', 20, 4, 20, 'わが子よ、注意して私のことばを聞け。私の言うことに耳を傾けよ。'),
('JPN', '箴言', 20, 4, 21, 'それらを見失うな。自分の心のただ中に保て。'),
('JPN', '箴言', 20, 4, 22, 'それらは、見出す者にとっていのちとなり、全身の癒やしとなるからだ。'),
('JPN', '箴言', 20, 4, 23, '何を見張るよりも、あなたの心を見守れ。いのちの泉はこれから湧く。'),
('JPN', '箴言', 20, 4, 24, '曲がったことを言う口をあなたから取り除き、ゆがんだことを言う唇をあなたから遠ざけよ。'),
('JPN', '箴言', 20, 4, 25, 'あなたの目が前方を見つめ、まぶたがまっすぐ前を向くようにせよ。'),
('JPN', '箴言', 20, 4, 26, 'あなたの足の道筋に心を向けよ。そうすれば、あなたのすべての道は堅く定まる。'),
('JPN', '箴言', 20, 4, 27, '右にも左にもそれてはならない。あなたの足を悪から遠ざけよ。'),
('JPN', '箴言', 20, 5, 1, 'わが子よ、注意して私の知恵を聞け。私の英知に耳を傾けよ。'),
('JPN', '箴言', 20, 5, 2, 'あなたが思慮深さを守り、あなたの唇が知識を保つために。'),
('JPN', '箴言', 20, 5, 3, 'よその女の唇は蜂の巣の蜜を滴らせ、その口は油よりも滑らかだが、'),
('JPN', '箴言', 20, 5, 4, '終わりには苦よもぎのように苦くなり、両刃の剣のように鋭くなるからだ。'),
('JPN', '箴言', 20, 5, 5, 'この女の足は死に下って行き、その足取りはよみをつかみ取る。'),
('JPN', '箴言', 20, 5, 6, 'その女はいのちの道に心を向けない。彼女が通う道はあてどもなくさまよう。しかし彼女は、それを知らない。'),
('JPN', '箴言', 20, 5, 7, '子たちよ、今、私に聞け。私の口のことばから離れるな。'),
('JPN', '箴言', 20, 5, 8, 'あなたの道をこの女から遠ざけ、その家の戸口に近づくな。'),
('JPN', '箴言', 20, 5, 9, 'そうでないと、あなたは自分の誉れを他人に渡し、あなたの年月を残忍な者に渡すことになる。'),
('JPN', '箴言', 20, 5, 10, 'また、他人があなたの富で満たされ、あなたの労苦の実は見知らぬ者の家に渡る。'),
('JPN', '箴言', 20, 5, 11, 'そして、あなたの終わりにあなたはうめく。あなたの肉とからだが滅びるとき。'),
('JPN', '箴言', 20, 5, 12, 'そのとき、あなたは言う。「ああ、私は訓戒を憎み、私の心は叱責を侮った。'),
('JPN', '箴言', 20, 5, 13, '自分の教師の声に聞き従わず、自分を教える者に耳を傾けなかった。'),
('JPN', '箴言', 20, 5, 14, '私は、集会、会衆のただ中にあっても、ほとんど最悪の状況であった」と。'),
('JPN', '箴言', 20, 5, 15, 'あなた自身の水溜めから水を飲め。流れ出る水を、あなた自身の井戸から。'),
('JPN', '箴言', 20, 5, 16, 'あなたの泉を外に散らし、広場を水路にしてよいものか。'),
('JPN', '箴言', 20, 5, 17, 'それを自分だけのものにせよ。あなたのところにいる他人のものにするな。'),
('JPN', '箴言', 20, 5, 18, 'あなたの泉を祝福されたものとし、あなたの若いときからの妻と喜び楽しめ。'),
('JPN', '箴言', 20, 5, 19, '愛らしい雌鹿、麗しいかもしか。彼女の乳房がいつもあなたを潤すように。あなたはいつも彼女の愛に酔うがよい。'),
('JPN', '箴言', 20, 5, 20, 'わが子よ。どうしてよその女に夢中になり、見知らぬ女の胸を抱くのか。'),
('JPN', '箴言', 20, 5, 21, '人の道は主の御目の前にあり、主はその道筋のすべてに心を向けてくださる。'),
('JPN', '箴言', 20, 5, 22, '悪しき者は自分の咎に捕らえられ、自分の罪の縄に捕まえられる。'),
('JPN', '箴言', 20, 5, 23, 'その人は訓戒を受け入れることなく死に、あまりの愚かさゆえに道から迷い出る。'),
('JPN', '箴言', 20, 6, 1, 'わが子よ。もし、あなたが隣人のために保証人となり、他人のために誓約をし、'),
('JPN', '箴言', 20, 6, 2, '自分の口のことばによって、自分が罠にかかり、自分の口のことばによって、捕らえられたなら、'),
('JPN', '箴言', 20, 6, 3, 'わが子よ、そのときにはすぐにこうして、自分を救い出せ。あなたは隣人の手に陥ったのだから。さあ行って、伏して隣人にしつこくせがめ。'),
('JPN', '箴言', 20, 6, 4, 'あなたの目を眠らせず、そのまぶたにまどろみを与えるな。'),
('JPN', '箴言', 20, 6, 5, '自分を救い出せ。かもしかが狩人の手から逃れるように、鳥がそれを捕る者の手から逃れるように。'),
('JPN', '箴言', 20, 6, 6, '怠け者よ、蟻のところへ行け。そのやり方を見て、知恵を得よ。'),
('JPN', '箴言', 20, 6, 7, '蟻には首領もつかさも支配者もいないが、'),
('JPN', '箴言', 20, 6, 8, '夏のうちに食物を確保し、刈り入れ時に食糧を集める。'),
('JPN', '箴言', 20, 6, 9, '怠け者よ、いつまで寝ているのか。いつ目を覚まして起き上がるのか。'),
('JPN', '箴言', 20, 6, 10, '少し眠り、少しまどろみ、少し腕を組んで、横になる。'),
('JPN', '箴言', 20, 6, 11, 'すると、付きまとう者のように貧しさが、武装した者のように乏しさがやって来る。'),
('JPN', '箴言', 20, 6, 12, 'よこしまな者や不法の者は、曲がったことを言って歩き回り、'),
('JPN', '箴言', 20, 6, 13, '目くばせをし、足で合図し、指でさす。'),
('JPN', '箴言', 20, 6, 14, 'そのねじれた心は、いつも悪を企み、争いをまき散らす。'),
('JPN', '箴言', 20, 6, 15, 'それゆえ、破局は突然やって来る。たちまち彼は滅ぼされ、癒やされることはない。'),
('JPN', '箴言', 20, 6, 16, '主の憎むものが六つある。いや、主ご自身が忌み嫌うものが七つある。'),
('JPN', '箴言', 20, 6, 17, '高ぶる目、偽りの舌、咎なき者の血を流す手、'),
('JPN', '箴言', 20, 6, 18, '邪悪な計画をめぐらす心、悪へと急ぎ走る足、'),
('JPN', '箴言', 20, 6, 19, 'まやかしを吹聴する偽りの証人、兄弟の間に争いを引き起こす者。'),
('JPN', '箴言', 20, 6, 20, 'わが子よ、あなたの父の命令を守れ。あなたの母の教えを捨ててはならない。'),
('JPN', '箴言', 20, 6, 21, 'それをいつも心に結び、首に結び付けよ。'),
('JPN', '箴言', 20, 6, 22, 'あなたが歩くときには、それがあなたを導き、寝ているときには、あなたを見守り、目覚めるときには、あなたに話しかける。'),
('JPN', '箴言', 20, 6, 23, '命令はともしび、おしえは光、訓戒のための叱責は、いのちの道であるからだ。'),
('JPN', '箴言', 20, 6, 24, 'それはあなたを悪い女から、見知らぬ女の滑らかな舌から守る。'),
('JPN', '箴言', 20, 6, 25, 'その女の美しさを心に慕うな。そのまぶたに捕らえられないようにせよ。'),
('JPN', '箴言', 20, 6, 26, '遊女の代償はひとかたまりのパンだが、人妻は尊いいのちをつけ狙うからだ。'),
('JPN', '箴言', 20, 6, 27, '人が火を懐にかき込んだら、その衣服は焼けないだろうか。'),
('JPN', '箴言', 20, 6, 28, 'もし人が、燃えている炭火の上を歩いたら、その足は焼けないだろうか。'),
('JPN', '箴言', 20, 6, 29, '隣人の妻と姦淫する者は、これと同じこと。その女に触れる者はだれも罰を免れない。'),
('JPN', '箴言', 20, 6, 30, '盗人が飢え、食欲を満たすために盗みをしたら、人々はその者を蔑まないだろうか。'),
('JPN', '箴言', 20, 6, 31, '見つかったら、彼は七倍を償い、自分の家の全財産を与えなければならない。'),
('JPN', '箴言', 20, 6, 32, '女と姦淫する者は良識がない。自分自身を滅ぼす者がこれを行う。'),
('JPN', '箴言', 20, 6, 33, '彼は傷と恥辱を受ける。彼の汚名は消し去ることができない。'),
('JPN', '箴言', 20, 6, 34, '女の夫は嫉妬から激しく憤り、復讐するとき、容赦をしない。'),
('JPN', '箴言', 20, 6, 35, '彼はどんな償い物も受けつけず、あなたが多くの贈り物をしても、受け入れない。'),
('JPN', '箴言', 20, 7, 1, 'わが子よ。私のことばを守り、私の命令をあなたのうちに蓄えよ。'),
('JPN', '箴言', 20, 7, 2, '私の命令を守って生きよ。私の教えを、自分の瞳のように守れ。'),
('JPN', '箴言', 20, 7, 3, 'それを自分の指に結び、心の板に書き記せ。'),
('JPN', '箴言', 20, 7, 4, '知恵に向かって「あなたは妹だ」と言い、英知に向かって「身内」と呼べ。'),
('JPN', '箴言', 20, 7, 5, '自分をよその女から守り、ことばの滑らかな、見知らぬ女から守るために。'),
('JPN', '箴言', 20, 7, 6, '私が家の窓から、格子窓から見下ろして、'),
('JPN', '箴言', 20, 7, 7, '浅はかな者たちを見ていると、若者たちのうちに、良識のない一人の若い者がいるのに気づいた。'),
('JPN', '箴言', 20, 7, 8, '彼は、女の家への曲がり角近くの街路を通って、その家に至る道を進んで行った。'),
('JPN', '箴言', 20, 7, 9, 'それは、たそがれの、日の沈むころ、夜と暗闇の始まるころだった。'),
('JPN', '箴言', 20, 7, 10, 'すると、遊女の装いをして、本心を隠したある女が彼を迎えた。'),
('JPN', '箴言', 20, 7, 11, 'この女は騒がしく、頑なで、その足は自分の家にとどまらず、'),
('JPN', '箴言', 20, 7, 12, 'あるときは通りに、あるときは広場にいて、あちこちの角のところで待ち構えていた。'),
('JPN', '箴言', 20, 7, 13, 'この女は彼を捕まえて口づけし、臆面もなく彼に言う。'),
('JPN', '箴言', 20, 7, 14, '「交わりのいけにえを献げなければならないので、私は今日、自分の誓願を果たしました。'),
('JPN', '箴言', 20, 7, 15, 'それで私はあなたに会いに出て来ました。あなたを捜し求めて、やっと見つけました。'),
('JPN', '箴言', 20, 7, 16, '私は長椅子に敷き物を、あや織りのエジプトの亜麻布を敷き、'),
('JPN', '箴言', 20, 7, 17, '寝床を没薬、アロエ、シナモンで香らせました。'),
('JPN', '箴言', 20, 7, 18, 'さあ、私たちは朝まで愛に酔いしれ、愛の喜びを互いに味わいましょう。'),
('JPN', '箴言', 20, 7, 19, '夫は遠くへ旅に出ていて、家にはいませんから。'),
('JPN', '箴言', 20, 7, 20, '金の袋を持って行きました。満月のころに帰って来るでしょう」と。'),
('JPN', '箴言', 20, 7, 21, '彼女は心動かすことばで彼を誘惑し、滑らかな唇で彼をいざなう。'),
('JPN', '箴言', 20, 7, 22, '彼はただちに、彼女の後について行く。牛が屠り場に引かれて行くように、足かせが愚か者を懲らしめているかのように。'),
('JPN', '箴言', 20, 7, 23, '最後は矢が彼の肝を射抜く。それは、自分のいのちがかかっているのを知らずに、鳥が罠に飛び込むようなものだ。'),
('JPN', '箴言', 20, 7, 24, '子たちよ。今、私に聞き従い、注意して私の口のことばを聞け。'),
('JPN', '箴言', 20, 7, 25, '彼女の道に、心がそれて行ってはならない。その通り道に迷い込んではならない。'),
('JPN', '箴言', 20, 7, 26, 'この女は多くの者を切り倒し、殺された者は数えきれない。'),
('JPN', '箴言', 20, 7, 27, 'その女の家はよみへの道。死の部屋に下って行く。'),
('JPN', '箴言', 20, 8, 1, '知恵は呼びかけないだろうか。英知はその声をあげないだろうか。'),
('JPN', '箴言', 20, 8, 2, '知恵は、道の傍らにある丘の上、通りの四つ角に立ち、'),
('JPN', '箴言', 20, 8, 3, '町の入り口にある門のそば、正門の入り口で高らかに言う。'),
('JPN', '箴言', 20, 8, 4, '「人々よ、わたしはあなたがたに呼びかける。人の子らに向かって声をあげる。'),
('JPN', '箴言', 20, 8, 5, '浅はかな者たちよ、賢さを身につけよ。愚かな者たちよ、良識をわきまえよ。'),
('JPN', '箴言', 20, 8, 6, '聞け。わたしは高貴なことを語り、わたしの唇からは公正が出るからだ。'),
('JPN', '箴言', 20, 8, 7, 'まことに、わたしの口は真実を告げ、わたしの唇は不義を忌み嫌う。'),
('JPN', '箴言', 20, 8, 8, 'わたしの口のことばはみな正しい。そこには、ねじれたことや曲がったことはない。'),
('JPN', '箴言', 20, 8, 9, 'これらはみな、悟る者には当然のこと。知識を見出す者には正しいこと。'),
('JPN', '箴言', 20, 8, 10, '金ではなく、わたしの訓戒を受けよ。選り抜きの黄金よりも、知識を受けよ。'),
('JPN', '箴言', 20, 8, 11, '知恵は真珠にまさり、どんな喜びも、これとは比べられないからだ。'),
('JPN', '箴言', 20, 8, 12, '知恵であるわたしは賢さを住まいとする。そこには知識と思慮がある。'),
('JPN', '箴言', 20, 8, 13, '主を恐れることは悪を憎むこと。わたしは高ぶりと、おごりと、悪の道と、ねじれごとを言う口を憎む。'),
('JPN', '箴言', 20, 8, 14, '摂理と知性はわたしのもの。わたしは英知であり、わたしには力がある。'),
('JPN', '箴言', 20, 8, 15, 'わたしによって、王たちは治め、君主たちは正義を定める。'),
('JPN', '箴言', 20, 8, 16, 'わたしによって、君主たちは支配する。高貴な人々も、義のすべてのさばき人もそうだ。'),
('JPN', '箴言', 20, 8, 17, 'わたしを愛する者を、わたしは愛する。わたしを熱心に捜す者は、わたしを見出す。'),
('JPN', '箴言', 20, 8, 18, '富と誉れはわたしとともにある。朽ちない財宝も義も。'),
('JPN', '箴言', 20, 8, 19, 'わたしの果実は黄金よりも、純金よりも良く、わたしの産物は選り抜きの銀にまさる。'),
('JPN', '箴言', 20, 8, 20, 'わたしは義の道を歩む。公正の通り道のただ中を。'),
('JPN', '箴言', 20, 8, 21, 'それは、わたしを愛する者に財産を受け継がせ、彼らの宝庫を満たすためである。'),
('JPN', '箴言', 20, 8, 22, '主は、ご自分の働きのはじめに、そのみわざの最初に、わたしを得ておられた。'),
('JPN', '箴言', 20, 8, 23, 'わたしは、大昔に、初めに、大地の始まりの前に、立てられていた。'),
('JPN', '箴言', 20, 8, 24, 'まだ深淵もなく、水のみなぎる源もなかったとき、わたしは生み出された。'),
('JPN', '箴言', 20, 8, 25, '山が立てられる前に、丘より先に、わたしは生み出された。'),
('JPN', '箴言', 20, 8, 26, '主がまだ地も野原も、世界の最初のちりも造っておられなかったときに。'),
('JPN', '箴言', 20, 8, 27, '主が天を堅く立てられたとき、わたしはそこにいた。主が深淵の面に円を描かれたとき、'),
('JPN', '箴言', 20, 8, 28, '上の方に大空を固め、深淵の源を堅く定められたとき、'),
('JPN', '箴言', 20, 8, 29, '海にその境界を置き、その水が主の仰せを越えないようにし、地の基を定められたとき、'),
('JPN', '箴言', 20, 8, 30, 'わたしは神の傍らで、これを組み立てる者であった。わたしは毎日喜び、いつも御前で楽しんでいた。'),
('JPN', '箴言', 20, 8, 31, '主の地、この世界で楽しみ、人の子らを喜んだ。'),
('JPN', '箴言', 20, 8, 32, '子たちよ、今、わたしに聞き従え。幸いなことよ、わたしの道を守る者は。'),
('JPN', '箴言', 20, 8, 33, '訓戒を聞け。知恵を得よ。これをなおざりにしてはならない。'),
('JPN', '箴言', 20, 8, 34, '幸いなことよ。日々わたしの戸の傍らで見張り、わたしの門の柱のわきで見守って、わたしの言うことを聞く人は。'),
('JPN', '箴言', 20, 8, 35, 'なぜなら、わたしを見出す者はいのちを見出し、主から恵みをいただくが、'),
('JPN', '箴言', 20, 8, 36, 'わたしに背を向ける者は自分自身を痛めつけ、わたしを憎む者はみな、死を愛するからだ。」'),
('JPN', '箴言', 20, 9, 1, '知恵は自分の家を建て、石の柱を七本、切り出し、'),
('JPN', '箴言', 20, 9, 2, 'いけにえを屠り、ぶどう酒を混ぜ合わせ、その食卓も整え、'),
('JPN', '箴言', 20, 9, 3, '侍女たちにことづけて、町の最も高い所で呼びかけさせた。'),
('JPN', '箴言', 20, 9, 4, '「浅はかな者はみな、ここに来なさい」と。また、良識のない者に言った。'),
('JPN', '箴言', 20, 9, 5, '「さあ、わたしのパンを食べなさい。わたしが混ぜ合わせたぶどう酒を飲みなさい。'),
('JPN', '箴言', 20, 9, 6, '浅はかさを捨てて、生きなさい。分別のある道を、まっすぐに歩みなさい」と。'),
('JPN', '箴言', 20, 9, 7, '嘲る者を戒める者は、自分が恥辱を受け、悪しき者を叱る者は、自分が傷を受ける。'),
('JPN', '箴言', 20, 9, 8, '嘲る者を叱るな。彼があなたを憎まないために。知恵のある者を叱れ。彼はあなたを愛する。'),
('JPN', '箴言', 20, 9, 9, '知恵のある者に与えよ。彼はますます知恵ある者となる。正しい人を教えよ。彼は洞察を深める。'),
('JPN', '箴言', 20, 9, 10, '主を恐れることは知恵の初め、聖なる方を知ることは悟ることである。'),
('JPN', '箴言', 20, 9, 11, 'わたしによって、あなたの日は多くなり、あなたのいのちの年が加えられるからだ。'),
('JPN', '箴言', 20, 9, 12, 'あなたが知恵を得るなら、自分のために知恵を得ることになり、嘲るなら、自分だけが責めを負うことになる。'),
('JPN', '箴言', 20, 9, 13, '愚かな女は騒がしく、わきまえがなく、何も知らない。'),
('JPN', '箴言', 20, 9, 14, 'その女は自分の家の戸口に座り、町の高い所にある座に着き、'),
('JPN', '箴言', 20, 9, 15, '道行く人々に呼びかけて言う。自分の道をまっすぐ歩く人々に。'),
('JPN', '箴言', 20, 9, 16, '「浅はかな者はみな、ここに来なさい」と。また良識のない者に向かって、この女は言う。'),
('JPN', '箴言', 20, 9, 17, '「盗んだ水は甘く、こっそり食べるパンはうまい」と。'),
('JPN', '箴言', 20, 9, 18, 'しかし彼は、そこに死者の霊がいることを、その女の客がよみの深みにいることを、知らない。'),
('JPN', '箴言', 20, 10, 1, 'ソロモンの箴言。知恵のある子は父を喜ばせ、愚かな子は母の悲しみとなる。'),
('JPN', '箴言', 20, 10, 2, '不義によって得た財宝は役に立たない。義のわざは人を死から救い出す。'),
('JPN', '箴言', 20, 10, 3, '主は正しい人を飢えさせず、悪しき者の欲を突き放される。'),
('JPN', '箴言', 20, 10, 4, '無精者の手は人を貧乏にし、勤勉な者の手は人を富ませる。'),
('JPN', '箴言', 20, 10, 5, '夏のうちに集める者は賢い子。刈り入れ時に眠る者は恥知らずな子。'),
('JPN', '箴言', 20, 10, 6, '正しい人の頭には祝福があり、悪しき者の口は不法を隠す。'),
('JPN', '箴言', 20, 10, 7, '正しい人の呼び名は祝福となり、悪しき者たちの名は朽ち果てる。'),
('JPN', '箴言', 20, 10, 8, '心に知恵のある者は命令を受け入れ、無駄口をたたく愚か者は滅びに落ちる。'),
('JPN', '箴言', 20, 10, 9, '誠実に歩む者の歩みは安全だが、自分の道を曲げる者は思い知らされる。'),
('JPN', '箴言', 20, 10, 10, '目で合図する者は人に痛みをもたらし、無駄口をたたく愚か者は滅びに落ちる。'),
('JPN', '箴言', 20, 10, 11, '正しい人の口はいのちの泉。悪しき者の口は不法を隠す。'),
('JPN', '箴言', 20, 10, 12, '憎しみは争いを引き起こし、愛はすべての背きをおおう。'),
('JPN', '箴言', 20, 10, 13, '悟りのある者の唇には知恵があり、良識のない者の背中にはむちがある。'),
('JPN', '箴言', 20, 10, 14, '知恵のある者は知識を蓄える。愚か者の口には滅びが迫る。'),
('JPN', '箴言', 20, 10, 15, '富む者の財産はその人の堅固な城。貧しい者の恐れは自らの貧困。'),
('JPN', '箴言', 20, 10, 16, '正しい人の報酬はいのち。悪しき者の収穫は罪。'),
('JPN', '箴言', 20, 10, 17, '訓戒を大事にする者はいのちへの道にあり、叱責を捨てる者は人を迷わせる。'),
('JPN', '箴言', 20, 10, 18, '憎しみを隠す者は偽りの唇を持ち、そしりを口に出す者は愚かな者である。'),
('JPN', '箴言', 20, 10, 19, 'ことば数が多いところには、背きがつきもの。自分の唇を制する者は賢い人。'),
('JPN', '箴言', 20, 10, 20, '正しい人の舌は選り抜きの銀。悪しき者の心は無価値に等しい。'),
('JPN', '箴言', 20, 10, 21, '正しい人の唇は多くの人を養い、愚か者は良識がないために死ぬ。'),
('JPN', '箴言', 20, 10, 22, '人を富ませるのは主の祝福。人の苦労は何も増し加えない。'),
('JPN', '箴言', 20, 10, 23, '愚かな者には悪事が楽しみ。英知のある者には知恵が楽しみ。'),
('JPN', '箴言', 20, 10, 24, '悪しき者の恐れることはその身に降りかかり、正しい人の望むことはかなえられる。'),
('JPN', '箴言', 20, 10, 25, 'つむじ風が過ぎ去ると、悪しき者はいなくなる。正しい人は永遠の礎である。'),
('JPN', '箴言', 20, 10, 26, '怠け者は、これを遣わす者にとって、歯に酢、目に煙のようなもの。'),
('JPN', '箴言', 20, 10, 27, '主への恐れは日数を増やす。悪しき者の年は短くなる。'),
('JPN', '箴言', 20, 10, 28, '正しい人の望みは喜び。悪しき者の期待は消え失せる。'),
('JPN', '箴言', 20, 10, 29, '主の道は、誠実な人には砦、不法を行う者には滅びである。'),
('JPN', '箴言', 20, 10, 30, '正しい人は永遠に揺るがされることがない。しかし、悪しき者は地に住むことができない。'),
('JPN', '箴言', 20, 10, 31, '正しい人の口は知恵を実らせる。しかし、ねじれた舌は抜かれる。'),
('JPN', '箴言', 20, 10, 32, '正しい人の唇は好意を知っており、悪しき者の口はねじれごとを知っている。'),
('JPN', '箴言', 20, 11, 1, '欺きの秤は主に忌み嫌われ、正しい重りは主に喜ばれる。'),
('JPN', '箴言', 20, 11, 2, '高ぶりが来れば、辱めも来る。知恵はへりくだる者とともにある。'),
('JPN', '箴言', 20, 11, 3, '直ぐな人の誠実は、その人を導き、裏切り者のよこしまは、その人を破滅させる。'),
('JPN', '箴言', 20, 11, 4, '財産は御怒りの日には役に立たない。義のわざは人を死から救い出す。'),
('JPN', '箴言', 20, 11, 5, '誠実な人の義なるわざは、その人の道を平らにし、悪しき者は、自分の悪事によって倒れる。'),
('JPN', '箴言', 20, 11, 6, '直ぐな人は、その正しさによって救い出され、裏切り者は、自分の欲によって捕らえられる。'),
('JPN', '箴言', 20, 11, 7, '悪者が死ぬとき、その望みは消え失せ、財力への期待も消え失せる。'),
('JPN', '箴言', 20, 11, 8, '正しい人は苦しみから救い出され、彼に代わって悪しき者がそれに陥る。'),
('JPN', '箴言', 20, 11, 9, '神を敬わない者は、その口によって友を滅ぼし、正しい人は、知識によって助け出される。'),
('JPN', '箴言', 20, 11, 10, '町は、正しい人の繁栄に小躍りし、悪しき者が滅びると、喜びの声をあげる。'),
('JPN', '箴言', 20, 11, 11, '直ぐな人の祝福によって、町は高く上げられ、悪しき者の口によって、破壊される。'),
('JPN', '箴言', 20, 11, 12, '隣人を蔑む者は良識がない。英知のある者は沈黙を守る。'),
('JPN', '箴言', 20, 11, 13, '人を中傷して回る者は秘密を漏らすが、霊が忠実な人は事を秘める。'),
('JPN', '箴言', 20, 11, 14, '指導がないことによって民は倒れ、多くの助言者によって救いを得る。'),
('JPN', '箴言', 20, 11, 15, '他人の保証人になると苦しみにあう。保証を嫌う者は安全だ。'),
('JPN', '箴言', 20, 11, 16, '優しい女は誉れをつかみ、横暴な者は富をつかむ。'),
('JPN', '箴言', 20, 11, 17, '誠実な人は自分のたましいに報いを得るが、残忍な者は自分の身にわざわいをもたらす。'),
('JPN', '箴言', 20, 11, 18, '悪しき者は偽りの報酬を得るが、義を蒔く者は確かな賃金を得る。'),
('JPN', '箴言', 20, 11, 19, '実に、義を追い求める者はいのちに至り、悪を追い求める者は死に至る。'),
('JPN', '箴言', 20, 11, 20, '心の曲がった者は主に忌み嫌われ、まっすぐな道を歩む者は主に喜ばれる。'),
('JPN', '箴言', 20, 11, 21, '悪人が罰を免れることは決してない。正しい人の裔は救いを得る。'),
('JPN', '箴言', 20, 11, 22, '豚の鼻にある金の輪。美しいが、たしなみのない女。'),
('JPN', '箴言', 20, 11, 23, '正しい人の願いは、ただ良いこと。悪しき者の望みは、激しい怒り。'),
('JPN', '箴言', 20, 11, 24, '気前よく施して、なお富む人があり、正当な支払いを惜しんで、かえって乏しくなる者がある。'),
('JPN', '箴言', 20, 11, 25, 'おおらかな人は豊かにされ、他人を潤す人は自分も潤される。'),
('JPN', '箴言', 20, 11, 26, '穀物を売り惜しむ者を民は呪う。しかし、それを売る者の頭には祝福がある。'),
('JPN', '箴言', 20, 11, 27, '熱心に善を求める者は恵みを慕い求める。悪を求める者には悪が来る。'),
('JPN', '箴言', 20, 11, 28, '自分の富に拠り頼む者は倒れ、正しい人は若葉のように芽を出す。'),
('JPN', '箴言', 20, 11, 29, '自分の家族にわざわいをもたらす者は、風を相続し、愚か者は、心に知恵のある者のしもべとなる。'),
('JPN', '箴言', 20, 11, 30, '正しい人の結ぶ実はいのちの木。知恵のある者は人の心をとらえる。'),
('JPN', '箴言', 20, 11, 31, '正しい人が地で報いを受けるなら、悪しき者や罪人はなおさらのこと。'),
('JPN', '箴言', 20, 12, 1, '訓戒を愛する人は知識を愛する。叱責を憎む者は間抜け者。'),
('JPN', '箴言', 20, 12, 2, '善人は主から恵みをいただき、悪を企む者は不義に定められる。'),
('JPN', '箴言', 20, 12, 3, '人は悪で身を堅く立てることはできない。正しい人の根は揺るがない。'),
('JPN', '箴言', 20, 12, 4, 'しっかりした妻は夫の冠。恥をもたらす妻は、夫の骨の中の腐れのようだ。'),
('JPN', '箴言', 20, 12, 5, '正しい人の考えは公正。悪しき者の助言は欺瞞。'),
('JPN', '箴言', 20, 12, 6, '悪しき者のことばは血に飢え、心の直ぐな人の口は自分を救い出す。'),
('JPN', '箴言', 20, 12, 7, '悪しき者は打ち倒されて、いなくなる。しかし、正しい人の家は立ち続ける。'),
('JPN', '箴言', 20, 12, 8, '人はその賢明さによってほめられるが、心のねじけた者は蔑まれる。'),
('JPN', '箴言', 20, 12, 9, '身分が低くても、しもべを持つ者は、高ぶっていて食に事欠く者にまさる。'),
('JPN', '箴言', 20, 12, 10, '正しい人は、自分の家畜のいのちを知っている。悪しき者は、そのあわれみさえ残忍である。'),
('JPN', '箴言', 20, 12, 11, '自分の畑を耕す者は食に満足するが、空しいものを追い求める者は良識がない。'),
('JPN', '箴言', 20, 12, 12, '悪しき者は悪人たちの分捕り物を欲しがるが、正しい人の根は芽を出す。'),
('JPN', '箴言', 20, 12, 13, '悪人は唇で背いて罠にかかる。正しい人は苦しみから逃れ出る。'),
('JPN', '箴言', 20, 12, 14, '人は、口のことばによって良いものに満ち足りる。人の手の働きはその人に報いをもたらす。'),
('JPN', '箴言', 20, 12, 15, '愚か者には自分の歩みがまっすぐに見える。しかし、知恵のある者は忠告を聞き入れる。'),
('JPN', '箴言', 20, 12, 16, '愚か者は自分の怒りをすぐ表す。賢い人は辱めを気に留めない。'),
('JPN', '箴言', 20, 12, 17, '真実の申し立てをする人は正しいことを言い、偽りの証人は噓を告げる。'),
('JPN', '箴言', 20, 12, 18, '軽率に話して人を剣で刺すような者がいる。しかし、知恵のある人の舌は人を癒やす。'),
('JPN', '箴言', 20, 12, 19, '真実の唇はとこしえまでも堅く立つ。偽りの舌はまばたきの間だけ。'),
('JPN', '箴言', 20, 12, 20, '悪を企む者の心には欺きがあり、平和を図る人には喜びがある。'),
('JPN', '箴言', 20, 12, 21, '正しい人には何の害悪も降りかからない。悪しき者はわざわいで満ちる。'),
('JPN', '箴言', 20, 12, 22, '偽りの唇は主に忌み嫌われ、真実を行う者は主に喜ばれる。'),
('JPN', '箴言', 20, 12, 23, '賢い人は知識を隠し、愚かな者は自分の愚かさを言いふらす。'),
('JPN', '箴言', 20, 12, 24, '勤勉な者の手は支配するが、無精者は苦役に服する。'),
('JPN', '箴言', 20, 12, 25, '心の不安は人を落ち込ませ、親切なことばは人を喜ばせる。'),
('JPN', '箴言', 20, 12, 26, '正しい人はその友の道案内。悪しき者の道は自らを迷わせる。'),
('JPN', '箴言', 20, 12, 27, '無精者は獲物を火であぶらない。勤勉さは人間の貴重な財産である。'),
('JPN', '箴言', 20, 12, 28, '義の道にはいのちがあり、その道筋には死がない。'),
('JPN', '箴言', 20, 13, 1, '知恵のある子は父の訓戒を聞き、嘲る者は叱責を聞かない。'),
('JPN', '箴言', 20, 13, 2, '人はその口の実によって良きものを食べるが、裏切り者は不法を貪る。'),
('JPN', '箴言', 20, 13, 3, '自分の口を見張る者はたましいを守る。唇を大きく開く者には滅びが来る。'),
('JPN', '箴言', 20, 13, 4, '怠け者の心は欲を起こしても何も得ない。勤勉な者の心は豊かに満たされる。'),
('JPN', '箴言', 20, 13, 5, '正しい人は偽りのことばを憎む。悪しき者は悪臭を放ち、恥ずべきふるまいをする。'),
('JPN', '箴言', 20, 13, 6, '義のわざは誠実な道を保ち、悪のわざは道を誤らせて罪に導く。'),
('JPN', '箴言', 20, 13, 7, '富んでいるふりをして、何も持たない者がいる。貧しいふりをして、多くの財産を持つ者がいる。'),
('JPN', '箴言', 20, 13, 8, '富はその人のいのちの身代金である。しかし、貧しい者は脅しを聞くこともない。'),
('JPN', '箴言', 20, 13, 9, '正しい人の光は輝き、悪しき者のともしびは消える。'),
('JPN', '箴言', 20, 13, 10, '高ぶりがあると、ただ争いが生じるだけ。知恵は勧告を聞く者とともにある。'),
('JPN', '箴言', 20, 13, 11, '急に得た財産は減るが、少しずつ集める者は、それを増す。'),
('JPN', '箴言', 20, 13, 12, '期待が長引くと、心は病む。望みがかなうことは、いのちの木。'),
('JPN', '箴言', 20, 13, 13, 'みことばを蔑む者は身を滅ぼし、命令を尊ぶ者は報われる。'),
('JPN', '箴言', 20, 13, 14, '知恵のある者のおしえはいのちの泉。これによって、死の罠から逃れることができる。'),
('JPN', '箴言', 20, 13, 15, '深い思慮は好意を生む。裏切り者の道は滅びに至る。'),
('JPN', '箴言', 20, 13, 16, 'すべて賢い人は知識によって行動し、愚かな者は自分の愚かさを言い広める。'),
('JPN', '箴言', 20, 13, 17, '悪い使者はわざわいに陥り、忠実な使者は人を癒やす。'),
('JPN', '箴言', 20, 13, 18, '貧乏と恥は訓戒をなおざりにする者に来る。しかし、叱責を大事にする者は誉れを得る。'),
('JPN', '箴言', 20, 13, 19, '望みがかなえられるのは心地よい。愚かな者は悪から離れることを忌み嫌う。'),
('JPN', '箴言', 20, 13, 20, '知恵のある者とともに歩む者は知恵を得る。愚かな者の友となる者は害を受ける。'),
('JPN', '箴言', 20, 13, 21, 'わざわいは罪人を追いかけるが、正しい人は幸いで報われる。'),
('JPN', '箴言', 20, 13, 22, '善良な人は子孫に遺産を残す。罪人の財産は正しい人のために蓄えられている。'),
('JPN', '箴言', 20, 13, 23, '貧しい者の耕地に、多くの食糧があっても、それは不当に取り去られる。'),
('JPN', '箴言', 20, 13, 24, 'むちを控える者は自分の子を憎む者。子を愛する者は努めてこれを懲らしめる。'),
('JPN', '箴言', 20, 13, 25, '正しい人は食べてその食欲を満たし、悪しき者は腹をすかせる。'),
('JPN', '箴言', 20, 14, 1, '知恵のある女は家を建て、愚かな女は自分の手でこれを壊す。'),
('JPN', '箴言', 20, 14, 2, 'まっすぐ歩む者は主を恐れ、曲がった道を行く者は主を侮る。'),
('JPN', '箴言', 20, 14, 3, '愚か者の口には、高ぶりへのむち。知恵のある者の唇は自分を守る。'),
('JPN', '箴言', 20, 14, 4, '牛がいなければ飼葉桶はきれいだが、豊かな収穫は牛の力による。'),
('JPN', '箴言', 20, 14, 5, '真実な証人は偽りを言わない。偽りの証人は偽りを吹聴する。'),
('JPN', '箴言', 20, 14, 6, '嘲る者は知恵を求めても得られない。悟る者には知識を得るのは易しい。'),
('JPN', '箴言', 20, 14, 7, '愚かな者の前を離れ去れ。知識の唇は、そこに見出せない。'),
('JPN', '箴言', 20, 14, 8, '賢い人の知恵は自分の道をわきまえること。愚かな者の愚かさは欺きにある。'),
('JPN', '箴言', 20, 14, 9, '愚か者は罪の償いを嘲る。心の直ぐな人たちの間には恩寵がある。'),
('JPN', '箴言', 20, 14, 10, '心はその人自身の辛さを知っている。その喜びにほかの者はあずかれない。'),
('JPN', '箴言', 20, 14, 11, '悪しき者の家は滅ぼし尽くされ、心の直ぐな人の天幕は栄える。'),
('JPN', '箴言', 20, 14, 12, '人の目にはまっすぐに見えるが、その終わりが死となる道がある。'),
('JPN', '箴言', 20, 14, 13, '笑うときにも心は痛み、その終わりには、喜びが悲しみとなる。'),
('JPN', '箴言', 20, 14, 14, '心の放埒な者は自分の道に満足する。善良な人は彼から離れる。'),
('JPN', '箴言', 20, 14, 15, '浅はかな者はどんなことばも信じるが、賢い人は自分の歩みを見極める。'),
('JPN', '箴言', 20, 14, 16, '知恵のある者は慎重で、悪を避けるが、愚かな者は怒りやすく、自信が強い。'),
('JPN', '箴言', 20, 14, 17, '短気な者は愚かなことをし、悪を企む者は憎まれる。'),
('JPN', '箴言', 20, 14, 18, '浅はかな者は愚かさを受け継ぎ、賢い人は知識の冠をかぶる。'),
('JPN', '箴言', 20, 14, 19, '悪人は善良な人の前で、悪しき者は正しい人の門で、身をかがめる。'),
('JPN', '箴言', 20, 14, 20, '貧しい者はその隣人にさえ憎まれるが、富む者は多くの者に愛される。'),
('JPN', '箴言', 20, 14, 21, '自分の隣人を蔑む者は罪人。貧しい者をあわれむ人は幸いだ。'),
('JPN', '箴言', 20, 14, 22, '悪を企む者はさまよわないだろうか。しかし、善を図る者には恵みとまことがある。'),
('JPN', '箴言', 20, 14, 23, 'いかなる労苦にも利益がある。無駄口は損失を招くだけ。'),
('JPN', '箴言', 20, 14, 24, '知恵のある者の冠はその者の富。愚かな者の愚かさは、ただ愚かさ。'),
('JPN', '箴言', 20, 14, 25, '真実な証人は人のたましいを救う。欺く者は偽りを吹聴する。'),
('JPN', '箴言', 20, 14, 26, '力ある拠り所は主を恐れることにあり、それは主の子らの避け所となる。'),
('JPN', '箴言', 20, 14, 27, '主を恐れることはいのちの泉、死の罠から離れさせる。'),
('JPN', '箴言', 20, 14, 28, '王の栄えは民が多いこと。君主の滅びは国民がいなくなること。'),
('JPN', '箴言', 20, 14, 29, '怒りを遅くする者には豊かな英知がある。気の短い者は愚かさを増す。'),
('JPN', '箴言', 20, 14, 30, '穏やかな心は、からだのいのち。ねたみは骨をむしばむ。'),
('JPN', '箴言', 20, 14, 31, '弱い者を虐げる者は自分の造り主をそしり、貧しい者をあわれむ者は造り主を敬う。'),
('JPN', '箴言', 20, 14, 32, '悪しき者は自分の悪によって押し倒されるが、正しい人は自分の死の中にも逃れ場がある。'),
('JPN', '箴言', 20, 14, 33, '知恵は悟る者の心のうちに安らぎを得る。愚かな者の間でもそれは知られている。'),
('JPN', '箴言', 20, 14, 34, '正義は国を高め、罪は国民を辱める。'),
('JPN', '箴言', 20, 14, 35, '王の好意は賢明なしもべに、王の激怒は恥知らずの者に。'),
('JPN', '箴言', 20, 15, 1, '柔らかな答えは憤りを鎮め、激しいことばは怒りをあおる。'),
('JPN', '箴言', 20, 15, 2, '知恵のある者の舌は知識をうまく用い、愚かな者の口は愚かさを吐き出す。'),
('JPN', '箴言', 20, 15, 3, '主の目はどこにもあり、悪人と善人を見張っている。'),
('JPN', '箴言', 20, 15, 4, '穏やかな舌はいのちの木。舌のねじれは霊の破れ。'),
('JPN', '箴言', 20, 15, 5, '愚か者は自分の父の訓戒を侮る。叱責を大事にする者は賢くなる。'),
('JPN', '箴言', 20, 15, 6, '正しい人の家には多くの富がある。悪しき者の収穫はわざわいをもたらす。'),
('JPN', '箴言', 20, 15, 7, '知恵のある者の唇は知識を広める。愚かな者の心はそうではない。'),
('JPN', '箴言', 20, 15, 8, '悪者のいけにえは主に忌み嫌われ、心の直ぐな人の祈りは主に受け入れられる。'),
('JPN', '箴言', 20, 15, 9, '主は悪しき者の道を忌み嫌い、義を追い求める者を愛される。'),
('JPN', '箴言', 20, 15, 10, '道を捨てる者には厳しい懲らしめがあり、叱責を憎む者は死に至る。'),
('JPN', '箴言', 20, 15, 11, 'よみと滅びの淵は主の前にある。人の子らの心はなおさらのこと。'),
('JPN', '箴言', 20, 15, 12, '嘲る者は叱られることを好まない。知恵のある者にも近づかない。'),
('JPN', '箴言', 20, 15, 13, '喜んでいる心は、顔色を良くする。心の痛みの中には、打ちひしがれた霊がある。'),
('JPN', '箴言', 20, 15, 14, '悟りのある者の心は知識を求めるが、愚かな者の口は愚かさを食いあさる。'),
('JPN', '箴言', 20, 15, 15, '悩み苦しむ者の毎日は悪いことのみ。心に楽しみのある人には毎日が祝宴。'),
('JPN', '箴言', 20, 15, 16, 'わずかな物を持って主を恐れることは、豊かな財宝を持って混乱するよりも良い。'),
('JPN', '箴言', 20, 15, 17, '野菜を食べて愛し合うのは、肥えた牛を食べて憎み合うのにまさる。'),
('JPN', '箴言', 20, 15, 18, '激しやすい者は口論を引き起こし、怒りを遅くする者は争い事を鎮める。'),
('JPN', '箴言', 20, 15, 19, '怠け者の道は茨の生け垣のよう。直ぐな人の進む道は平らな大路。'),
('JPN', '箴言', 20, 15, 20, '知恵のある子は父を喜ばせ、愚かな人はその母を蔑む。'),
('JPN', '箴言', 20, 15, 21, '良識のない者には愚かさが喜び。英知のある者はまっすぐ歩む。'),
('JPN', '箴言', 20, 15, 22, 'よく相談しなければ、計画は倒れる。多くの助言者によって、それは成功する。'),
('JPN', '箴言', 20, 15, 23, '適切な返事をすることは、その人の喜び。時宜にかなったことばは、なんと麗しいことか。'),
('JPN', '箴言', 20, 15, 24, '賢明な者はいのちの道を上って行く。下にあるよみから離れるためだ。'),
('JPN', '箴言', 20, 15, 25, '主は高ぶる者の家を根こそぎにし、やもめの地境を決める。'),
('JPN', '箴言', 20, 15, 26, '悪人の計画は主に忌み嫌われる。親切なことばは、きよい。'),
('JPN', '箴言', 20, 15, 27, '利得を貪る者は自分の家族を困らせ、賄賂を憎む者は生きながらえる。'),
('JPN', '箴言', 20, 15, 28, '正しい人の心は、どう答えるかを思い巡らす。悪しき者の口は悪を吐き出す。'),
('JPN', '箴言', 20, 15, 29, '主は悪しき者から遠くにおられ、正しい人の祈りを聞かれる。'),
('JPN', '箴言', 20, 15, 30, '目の光は心を喜ばせ、良い知らせは人を健やかにする。'),
('JPN', '箴言', 20, 15, 31, 'いのちに至る叱責を聞く耳は、知恵のある者の間に宿る。'),
('JPN', '箴言', 20, 15, 32, '訓戒を無視する者は自分自身をないがしろにする。叱責を聞き入れる者は良識を得る。'),
('JPN', '箴言', 20, 15, 33, '主を恐れることは知恵の訓戒。謙遜は栄誉に先立つ。'),
('JPN', '箴言', 20, 16, 1, '人は心に計画を持つ。しかし、舌への答えは主から来る。'),
('JPN', '箴言', 20, 16, 2, '人には自分の行いがみな純粋に見える。しかし、主は人の霊の値打ちを量られる。'),
('JPN', '箴言', 20, 16, 3, 'あなたのわざを主にゆだねよ。そうすれば、あなたの計画は堅く立つ。'),
('JPN', '箴言', 20, 16, 4, 'すべてのものを、主はご自分の目的のために造り、悪しき者さえ、わざわいの日のために造られた。'),
('JPN', '箴言', 20, 16, 5, '心の高ぶりはすべて主に忌み嫌われる。断じて罰を免れない。'),
('JPN', '箴言', 20, 16, 6, '恵みとまことによって、咎は赦され、主を恐れることによって、人は悪を離れる。'),
('JPN', '箴言', 20, 16, 7, '主が人の行いを喜ぶとき、敵さえもその人と和らがせる。'),
('JPN', '箴言', 20, 16, 8, '正義によるわずかなものは、不正による多くの収穫にまさる。'),
('JPN', '箴言', 20, 16, 9, '人は心に自分の道を思い巡らす。しかし、主が人の歩みを確かにされる。'),
('JPN', '箴言', 20, 16, 10, '王の唇には神々しさがある。さばくときに、その口は神の信頼を裏切らない。'),
('JPN', '箴言', 20, 16, 11, '正しい天秤と秤は主のもの。袋の中の重り石もみな、主が造られたもの。'),
('JPN', '箴言', 20, 16, 12, '悪を行うことは王たちの忌み嫌うこと。王座は正義によって堅く立つからだ。'),
('JPN', '箴言', 20, 16, 13, '正しい唇は王たちの喜び。真っ直ぐなことを語る者は愛される。'),
('JPN', '箴言', 20, 16, 14, '王の憤りは死の使い。知恵のある人がそれをなだめる。'),
('JPN', '箴言', 20, 16, 15, '王の顔の光にはいのちがある。彼のいつくしみは後の雨をもたらす密雲のようだ。'),
('JPN', '箴言', 20, 16, 16, '知恵を得ることは、黄金を得るよりはるかに良い。悟りを得ることは、銀を得るよりも望ましい。'),
('JPN', '箴言', 20, 16, 17, '直ぐな人の大路は悪から遠ざかっている。自分のたましいを守る者は自分の道を見張る。'),
('JPN', '箴言', 20, 16, 18, '高慢は破滅に先立ち、高ぶった霊は挫折に先立つ。'),
('JPN', '箴言', 20, 16, 19, 'へりくだって、貧しい者とともにいるのは、高ぶる者とともに分捕り物を分け合うのにまさる。'),
('JPN', '箴言', 20, 16, 20, 'みことばによく通じた者は幸いを見出す。主に拠り頼む者は幸いである。'),
('JPN', '箴言', 20, 16, 21, '心に知恵のある者は、悟りのある者と呼ばれ、そのことばの心地よさは理解を増し加える。'),
('JPN', '箴言', 20, 16, 22, '賢明さは、これを持つ者にはいのちの泉。愚かさは、愚か者への懲らしめ。'),
('JPN', '箴言', 20, 16, 23, '知恵のある者の心はその口を賢くし、その唇に洞察を深める。'),
('JPN', '箴言', 20, 16, 24, '親切なことばは蜂蜜。たましいに甘く、骨を健やかにする。'),
('JPN', '箴言', 20, 16, 25, '人の目にはまっすぐに見えるが、その終わりが死となる道がある。'),
('JPN', '箴言', 20, 16, 26, '苦労する者は食欲のために働く。その口が彼を駆り立てるからだ。'),
('JPN', '箴言', 20, 16, 27, 'よこしまな者は悪を企む。その唇の上にあるものは焼き尽くす火のようだ。'),
('JPN', '箴言', 20, 16, 28, 'ねじれ者は争いを巻き起こし、陰口をたたく者は親しい友を離れさせる。'),
('JPN', '箴言', 20, 16, 29, '暴虐を行う者は自分の隣人を惑わし、良くない道へ導く。'),
('JPN', '箴言', 20, 16, 30, '目で合図する者はねじれごとを企み、唇をすぼめる者は悪をやり遂げた者だ。'),
('JPN', '箴言', 20, 16, 31, '白髪は栄えの冠。それは正義の道に見出される。'),
('JPN', '箴言', 20, 16, 32, '怒りを遅くする者は勇士にまさり、自分の霊を治める者は町を攻め取る者にまさる。'),
('JPN', '箴言', 20, 16, 33, 'くじは膝に投げられるが、そのすべての決定は主から来る。'),
('JPN', '箴言', 20, 17, 1, '乾いたパンが一切れあって平穏なのは、ごちそうと争いに満ちた家にまさる。'),
('JPN', '箴言', 20, 17, 2, '賢明なしもべは、恥知らずな子をも治め、兄弟たちの間にあって、資産の分け前にあずかる。'),
('JPN', '箴言', 20, 17, 3, '銀にはるつぼ、金には炉、人の心を試すのは主。'),
('JPN', '箴言', 20, 17, 4, '悪を行う者は邪悪な唇に聞き入り、偽り者は破滅の舌に耳を傾ける。'),
('JPN', '箴言', 20, 17, 5, '貧しい者を嘲る者は自分の造り主をそしる。人の災難を喜ぶ者は罰を免れない。'),
('JPN', '箴言', 20, 17, 6, '孫たちは老人の冠。父祖たちは子らの栄え。'),
('JPN', '箴言', 20, 17, 7, '愚か者に雄弁な舌はふさわしくない。高貴な人に偽りの唇はなおふさわしくない。'),
('JPN', '箴言', 20, 17, 8, '賄賂は、その贈り主の目には宝石。その向かうところ、どこにおいても、うまくいく。'),
('JPN', '箴言', 20, 17, 9, '愛を追い求める者は背きの罪をおおう。同じことを蒸し返す者は親しい友を離れさせる。'),
('JPN', '箴言', 20, 17, 10, '分別のある者を一回叱ることは、愚かな者を百回むち打つよりも効き目がある。'),
('JPN', '箴言', 20, 17, 11, '悪人はただ逆らうことだけを求める。その者には残忍な使者が送られる。'),
('JPN', '箴言', 20, 17, 12, '愚かさにふける愚かな者に会うより、子を奪われた雌熊に出会うほうがましだ。'),
('JPN', '箴言', 20, 17, 13, '善に代えて悪を返すなら、その者の家から悪は離れない。'),
('JPN', '箴言', 20, 17, 14, '口論の始まりは水が吹き出すようなもの。争い事が起こらないうちにやめよ。'),
('JPN', '箴言', 20, 17, 15, '悪しき者を正しいとする者、正しい人を悪いとする者、主はこの両者を忌み嫌われる。'),
('JPN', '箴言', 20, 17, 16, '愚かな者が良識もないのに、知恵を買おうとして、手に代金を持っている。これはどうしたことか。'),
('JPN', '箴言', 20, 17, 17, '友はどんなときにも愛するもの。兄弟は苦難を分け合うために生まれる。'),
('JPN', '箴言', 20, 17, 18, '良識のない人は、すぐ誓約をし、隣人の前で保証人となる。'),
('JPN', '箴言', 20, 17, 19, '背きの罪を愛する者はけんかを愛する。自分の門を高くする者は破滅を求める。'),
('JPN', '箴言', 20, 17, 20, '心の曲がった者は幸いを見つけない。二枚舌の者はわざわいに陥る。'),
('JPN', '箴言', 20, 17, 21, '愚かな者を生む者には悲しみがあり、愚か者の父には喜びがない。'),
('JPN', '箴言', 20, 17, 22, '喜んでいる心は健康を良くし、打ちひしがれた霊は骨を枯らす。'),
('JPN', '箴言', 20, 17, 23, '悪しき者は人の懐から賄賂を受け取り、さばきの道を曲げる。'),
('JPN', '箴言', 20, 17, 24, '悟りのある者はその顔を知恵に向け、愚かな者は目を地の果てに注ぐ。'),
('JPN', '箴言', 20, 17, 25, '愚かな子はその父の憂い、これを産んだ母の痛み。'),
('JPN', '箴言', 20, 17, 26, '正しい人に罰金を科すことが良いことでないなら、高貴な人を実直さゆえに打つのは、なおのこと。'),
('JPN', '箴言', 20, 17, 27, 'ことばを控える人は知識を持つ者。霊において冷静な人は英知のある者。'),
('JPN', '箴言', 20, 17, 28, '愚か者でも黙っていれば、知恵のある者と思われ、その唇を閉じていれば、分別のある者と思われる。'),
('JPN', '箴言', 20, 18, 1, '自らを閉ざす者は自分の欲望のままに求め、すべての知性と仲たがいする。'),
('JPN', '箴言', 20, 18, 2, '愚かな者は英知を喜ばず、自分の心がさらけ出されることを喜ぶ。'),
('JPN', '箴言', 20, 18, 3, '悪しき者が来ると、侮りも来る。辱めとともに、そしりも。'),
('JPN', '箴言', 20, 18, 4, '人の口のことばは深い水。知恵の泉は湧いて流れる川。'),
('JPN', '箴言', 20, 18, 5, '悪しき者をえこひいきすることも、正しい人をさばきで退けることも良くない。'),
('JPN', '箴言', 20, 18, 6, '愚かな者の唇は争い事に入って行き、その口はむち打つ者を呼び寄せる。'),
('JPN', '箴言', 20, 18, 7, '愚かな者の口は自らの滅びを招き、その唇は自分のたましいの罠となる。'),
('JPN', '箴言', 20, 18, 8, '陰口をたたく者のことばは、おいしい食べ物。腹の奥に下って行く。'),
('JPN', '箴言', 20, 18, 9, '自分の仕事をさえ怠ける者は、滅びをもたらす者の兄弟である。'),
('JPN', '箴言', 20, 18, 10, '主の名は堅固なやぐら。正しい人はその中に駆け込み、保護される。'),
('JPN', '箴言', 20, 18, 11, '富む者の財産はその堅固な城。自分ではそそり立つ城壁のように思い描いている。'),
('JPN', '箴言', 20, 18, 12, '人の心の高慢は破滅に先立ち、謙遜は栄誉に先立つ。'),
('JPN', '箴言', 20, 18, 13, 'よく聞かないで返事をする者は、愚かであり、恥を見る。'),
('JPN', '箴言', 20, 18, 14, '人の霊は病苦も忍ぶ。しかし、打ちひしがれた霊はだれが担えるだろう。'),
('JPN', '箴言', 20, 18, 15, '悟りのある者の心は知識を得、知恵のある者の耳は知識を求める。'),
('JPN', '箴言', 20, 18, 16, '人の贈り物はその人のために道を開き、身分の高い人の前にも彼を導く。'),
('JPN', '箴言', 20, 18, 17, '最初に訴える者は、相手が来て彼を調べるまでは、正しく見える。'),
('JPN', '箴言', 20, 18, 18, 'くじは争いをやめさせ、強い者の間に決着をつける。'),
('JPN', '箴言', 20, 18, 19, '反抗する兄弟は堅固な城よりも近寄りにくい。争いは宮殿のかんぬきのようだ。'),
('JPN', '箴言', 20, 18, 20, '人はその口の結ぶ実によって腹を満たし、その唇の収穫で満ち足りる。'),
('JPN', '箴言', 20, 18, 21, '死と生は舌に支配される。どちらかを愛して、人はその実を食べる。'),
('JPN', '箴言', 20, 18, 22, '妻を見つける者は幸せを見つけ、主から恵みをいただく。'),
('JPN', '箴言', 20, 18, 23, '貧しい者は哀願するが、富む者は荒々しく答える。'),
('JPN', '箴言', 20, 18, 24, '多くの友に関わる人は身を滅ぼす。しかし、兄弟以上に親密な友人もいる。'),
('JPN', '箴言', 20, 19, 1, '貧しくても誠実に歩む者は、唇の曲がった愚かな者にまさる。'),
('JPN', '箴言', 20, 19, 2, 'たましいに知識がないことは良くない。急ぎ足の者は罪に陥る。'),
('JPN', '箴言', 20, 19, 3, '人の愚かさは自らの道を滅ぼす。その心は主に向かって激しく怒る。'),
('JPN', '箴言', 20, 19, 4, '財産は多くの友を増し加え、貧しい者はその友からも引き離される。'),
('JPN', '箴言', 20, 19, 5, '偽りの証人は罰を免れない。まやかしを吹聴する者も逃れられない。'),
('JPN', '箴言', 20, 19, 6, '高貴な人の好意を求める者は多い。だれもが、贈り物をしてくれる人の友となる。'),
('JPN', '箴言', 20, 19, 7, '貧しい者は自分のすべての兄弟たちに憎まれる。友人が彼から遠く離れるのは、なおさらのこと。彼がことばをもって追い求めても、彼らはいない。'),
('JPN', '箴言', 20, 19, 8, '良識を得る者は自分自身を愛する者。英知を保つ者は幸いを見つける。'),
('JPN', '箴言', 20, 19, 9, '偽りの証人は罰を免れない。まやかしを吹聴する者は滅びる。'),
('JPN', '箴言', 20, 19, 10, '愚かな者にぜいたくな暮らしはふさわしくない。奴隷が君主を支配するのは、なおさらのこと。'),
('JPN', '箴言', 20, 19, 11, '人に賢明さがあれば、怒りを遅くする。その人の栄誉は、背きを見過ごすことにある。'),
('JPN', '箴言', 20, 19, 12, '王の激しい怒りは若い獅子がうなるよう。しかし、その好意は草の上の露のよう。'),
('JPN', '箴言', 20, 19, 13, '愚かな息子は父にとって破滅。妻のいさかい好きは、滴り続ける雨漏り。'),
('JPN', '箴言', 20, 19, 14, '家と財産は先祖から受け継ぐもの。賢明な妻は主からのもの。'),
('JPN', '箴言', 20, 19, 15, '怠惰は人を深い眠りに陥らせ、怠け者は飢える。'),
('JPN', '箴言', 20, 19, 16, '命令を守る者は自分のたましいを保ち、自分の道を蔑む者は死ぬ。'),
('JPN', '箴言', 20, 19, 17, '貧しい者に施しをするのは、主に貸すこと。主がその行いに報いてくださる。'),
('JPN', '箴言', 20, 19, 18, '望みのあるうちに、自分の子を懲らしめよ。しかし、殺そうとまで考えてはならない。'),
('JPN', '箴言', 20, 19, 19, '激しく憤る者は罰を受ける。たとえ彼を救い出しても、ただ、これを繰り返すことになる。'),
('JPN', '箴言', 20, 19, 20, '忠告を聞き、訓戒を受け入れよ。そうすれば、あなたは後で知恵を得る。'),
('JPN', '箴言', 20, 19, 21, '人の心には多くの思いがある。しかし、主の計画こそが実現する。'),
('JPN', '箴言', 20, 19, 22, '人の欲望は自らへの辱め。貧しい人はまやかし者にまさる。'),
('JPN', '箴言', 20, 19, 23, '主を恐れるなら、いのちに至る。満ち足りて住み、わざわいにあわない。'),
('JPN', '箴言', 20, 19, 24, '怠け者は皿に手を伸ばしても、その手を口に持って行こうとさえしない。'),
('JPN', '箴言', 20, 19, 25, '嘲る者を打て。そうすれば、浅はかな者は賢くなる。悟りのある者を叱責せよ。そうすれば、彼は知識をわきまえ知ることになる。'),
('JPN', '箴言', 20, 19, 26, '父に乱暴し、母を追い出す者は、恥と屈辱をもたらす子。'),
('JPN', '箴言', 20, 19, 27, 'わが子よ、訓戒を聞くのをやめてみよ。あなたは知識のことばから迷い出ることになる。'),
('JPN', '箴言', 20, 19, 28, 'よこしまな証人は、さばきを嘲り、悪しき者の口は、不法を吞み込む。'),
('JPN', '箴言', 20, 19, 29, 'さばきは嘲る者のために、むち打ちは愚かな者の背のために備えられている。'),
('JPN', '箴言', 20, 20, 1, 'ぶどう酒は嘲る者。強い酒は騒ぎ立てる者。これにおぼれる者はみな、知恵がない。'),
('JPN', '箴言', 20, 20, 2, '王の恐ろしさは若い獅子がうなるよう。彼を怒らせる者は、代償としていのちを失う。'),
('JPN', '箴言', 20, 20, 3, '争いを避けることは人の誉れ。愚か者はみな、争いを引き起こす。'),
('JPN', '箴言', 20, 20, 4, '怠け者は冬に耕さない。刈り入れ時に求めても、何もない。'),
('JPN', '箴言', 20, 20, 5, '人の心にある計画は深い水。英知のある人はこれを汲み出す。'),
('JPN', '箴言', 20, 20, 6, '多くの人は自分の親切を吹聴する。だれが忠実な人を見つけられるだろうか。'),
('JPN', '箴言', 20, 20, 7, '正しい人は誠実に歩む。彼の子孫はなんと幸いなことか。'),
('JPN', '箴言', 20, 20, 8, 'さばきの座に着く王は、自分の目ですべての悪をふるい分ける。'),
('JPN', '箴言', 20, 20, 9, 'だれが、「私は自分の心を清めた。私は罪から離れ、きよくなった」と言えるだろうか。'),
('JPN', '箴言', 20, 20, 10, '異なる二種類の重り、異なる二種類の升、そのどちらも主は忌み嫌われる。'),
('JPN', '箴言', 20, 20, 11, '幼子でさえ、何かするとき、その行いが純粋かどうか、真っ直ぐかどうかを識別する。'),
('JPN', '箴言', 20, 20, 12, '聞く耳と見る目は、二つとも主が造られた。'),
('JPN', '箴言', 20, 20, 13, '眠りを愛するな。貧しくならないために。目を開け。そうすればパンに満ち足りる。'),
('JPN', '箴言', 20, 20, 14, '買う者は「悪い、悪い」と言うが、その場を離れると、それを自慢する。'),
('JPN', '箴言', 20, 20, 15, '金があり、多くの真珠があっても、知識の唇こそ宝の器。'),
('JPN', '箴言', 20, 20, 16, '他人の保証人となるときは、その人の上着を取れ。見知らぬ女のためにも、上着を抵当に取れ。'),
('JPN', '箴言', 20, 20, 17, 'だまし取ったパンはうまい。しかし、後でその口は砂利でいっぱいになる。'),
('JPN', '箴言', 20, 20, 18, '協議によって計画は確かなものとなる。すぐれた指揮のもとに戦いを交えよ。'),
('JPN', '箴言', 20, 20, 19, '人を中傷して回る者は秘密を漏らす。唇を開く者とは交わるな。'),
('JPN', '箴言', 20, 20, 20, '自分の父や母をののしる者、そのともしびは、闇が近づくと消える。'),
('JPN', '箴言', 20, 20, 21, '初めに急に得た相続財産は、終わりには祝福されない。'),
('JPN', '箴言', 20, 20, 22, '「悪に報いてやろう」と言ってはならない。主を待ち望め。主があなたを救われる。'),
('JPN', '箴言', 20, 20, 23, '異なる二種類の重りは主に忌み嫌われる。欺きの秤は良くない。'),
('JPN', '箴言', 20, 20, 24, '人の歩みは主によって定められる。人はどうして自分の道を悟ることができるだろう。'),
('JPN', '箴言', 20, 20, 25, '軽々しく「これは聖なるもの」と言い、誓願を立てた後で吟味する者は、罠にかかっている。'),
('JPN', '箴言', 20, 20, 26, '知恵のある王は悪しき者をふるいにかけ、彼らの上で車輪を引き回す。'),
('JPN', '箴言', 20, 20, 27, '人間の息は主のともしび。腹の底まで探り出す。'),
('JPN', '箴言', 20, 20, 28, '恵みとまことは王を保つ。恵みによってその王位は支えられる。'),
('JPN', '箴言', 20, 20, 29, '若い男の栄誉は彼らの力。老人の輝きはその白髪。'),
('JPN', '箴言', 20, 20, 30, '傷つくまで打てば、悪は取り除かれる。腹の底まで打ちたたけば。'),
('JPN', '箴言', 20, 21, 1, '王の心は、主の手の中にあって水の流れのよう。主はみこころのままに、その向きを変えられる。'),
('JPN', '箴言', 20, 21, 2, '人には自分の歩みがみなまっすぐに見える。しかし、主は人の心を評価される。'),
('JPN', '箴言', 20, 21, 3, '義と公正を行うことは、主の前で、いけにえより望ましい。'),
('JPN', '箴言', 20, 21, 4, '高ぶる目とおごる心。悪しき者のともしびは罪。'),
('JPN', '箴言', 20, 21, 5, '勤勉な人の計画は利益をもたらし、すべて慌てる者は損失を招くだけだ。'),
('JPN', '箴言', 20, 21, 6, '偽りの舌をもって財宝を得る者は、吹き払われるもやのよう。死を追い求める者だ。'),
('JPN', '箴言', 20, 21, 7, '悪しき者たちは自らの暴力に引きずられる。公正を行おうとしないからだ。'),
('JPN', '箴言', 20, 21, 8, '罪人の道はねじれている。しかし、純粋な人の行いは真っ直ぐだ。'),
('JPN', '箴言', 20, 21, 9, '争い好きな女と一緒に家にいるよりは、屋上の片隅に住むほうがよい。'),
('JPN', '箴言', 20, 21, 10, '悪しき者のたましいは悪事に憧れ、その目に隣人へのあわれみはない。'),
('JPN', '箴言', 20, 21, 11, '嘲る者が罰を受けると、浅はかな者が知恵を得る。知恵のある人が賢くなると、その人は知識を加える。'),
('JPN', '箴言', 20, 21, 12, '正しい方は悪者の家を見抜き、悪者どもをわざわいに導かれる。'),
('JPN', '箴言', 20, 21, 13, '貧しい者の叫びに耳を閉ざす者は、自分が呼ぶときにも答えてもらえない。'),
('JPN', '箴言', 20, 21, 14, 'ひそかな贈り物は怒りを鎮め、懐の賄賂は激しい憤りを鎮める。'),
('JPN', '箴言', 20, 21, 15, '公正が行われることは、正しい人には喜び、不法を行う者には恐怖。'),
('JPN', '箴言', 20, 21, 16, '賢明さへの道から迷い出る人は、死者の霊たちの集いで安らぐ。'),
('JPN', '箴言', 20, 21, 17, '快楽を愛する者は貧しい人となり、ぶどう酒や油を愛する者は富むことがない。'),
('JPN', '箴言', 20, 21, 18, '悪しき者が正しい人のための身代金となり、裏切り者が直ぐな人の身代わりとなる。'),
('JPN', '箴言', 20, 21, 19, '争い好きで、苛立つ女といるよりは、荒野に住むほうがまだましだ。'),
('JPN', '箴言', 20, 21, 20, '知恵のある者の住まいには、好ましい財宝と油がある。しかし、愚かな人はこれを吞み尽くす。'),
('JPN', '箴言', 20, 21, 21, '義と恵みを追い求める者は、いのちと義と誉れを見出す。'),
('JPN', '箴言', 20, 21, 22, '知恵のある者は勇士たちの町に攻め上り、その頼みとする砦を崩す。'),
('JPN', '箴言', 20, 21, 23, '自分の口と舌を守る者は、自分自身を守って苦難にあわない。'),
('JPN', '箴言', 20, 21, 24, '横柄で不遜な者、その名は「嘲る者」。彼は憤然として横柄にふるまう。'),
('JPN', '箴言', 20, 21, 25, '怠け者の欲望はその身を殺す。その手が、働くことを拒むからだ。'),
('JPN', '箴言', 20, 21, 26, 'この者は一日中、自分の欲望に明け暮れる。しかし、正しい人は人に与えて惜しまない。'),
('JPN', '箴言', 20, 21, 27, '悪しき者のいけにえは忌み嫌われる。悪意をもって献げるときは、なおさらのこと。'),
('JPN', '箴言', 20, 21, 28, '偽りの証人は滅びる。しかし、よく聞く者は正しく語り続ける。'),
('JPN', '箴言', 20, 21, 29, '悪しき者は厚かましいが、直ぐな人は自分の道をわきまえる。'),
('JPN', '箴言', 20, 21, 30, 'どんな知恵も英知も、はかりごとも、主の前では無きに等しい。'),
('JPN', '箴言', 20, 21, 31, '戦いの日のためには馬が備えられる。しかし、救いは主による。'),
('JPN', '箴言', 20, 22, 1, '名声は多くの富より望ましく、愛顧を受けることは銀や金にまさる。'),
('JPN', '箴言', 20, 22, 2, '富む者と貧しい者が出会う。どちらもみな、造られたのは主である。'),
('JPN', '箴言', 20, 22, 3, '賢い者はわざわいを見て身を隠し、浅はかな者は入って行って痛い目にあう。'),
('JPN', '箴言', 20, 22, 4, 'へりくだりと、主を恐れることの報いは、富と誉れといのち。'),
('JPN', '箴言', 20, 22, 5, '曲がった者の道には茨と罠がある。たましいを守る者はこれらから遠く離れる。'),
('JPN', '箴言', 20, 22, 6, '若者をその行く道にふさわしく教育せよ。そうすれば、年老いても、それから離れない。'),
('JPN', '箴言', 20, 22, 7, '富む者は貧しい者を支配する。借りる者は貸す者のしもべとなる。'),
('JPN', '箴言', 20, 22, 8, '不正を蒔く者はわざわいを刈り取る。こうして彼への激しい怒りのむちは終わる。'),
('JPN', '箴言', 20, 22, 9, '善意の人は祝福を受ける。自分のパンを貧しい者に与えるからだ。'),
('JPN', '箴言', 20, 22, 10, '嘲る者を追い出せ。争いは出て行く。もめごとも辱めも終わる。'),
('JPN', '箴言', 20, 22, 11, '心のきよさを愛し、優しく話をする者は、王がその友となる。'),
('JPN', '箴言', 20, 22, 12, '主の目は知識を見守り、裏切り者のことばをくつがえす。'),
('JPN', '箴言', 20, 22, 13, '怠け者は言う。「獅子が通りにいる。私は広場で殺される」と。'),
('JPN', '箴言', 20, 22, 14, 'よその女の口車は深い穴。主の憤りに触れた者がそこに落ち込む。'),
('JPN', '箴言', 20, 22, 15, '愚かさは子どもの心に絡み付いている。懲らしめのむちがこれを子どもから遠ざける。'),
('JPN', '箴言', 20, 22, 16, '自分を富ませるために貧しい人を虐げる者、富む人に与える者──どちらも欠乏に至るのみ。'),
('JPN', '箴言', 20, 22, 17, '耳を傾けて、知恵のある者たちのことばを聞け。私の知識に心を向けよ。'),
('JPN', '箴言', 20, 22, 18, 'これらをあなたのうちに保つのは楽しいこと。これらをみな、あなたの唇に備えよ。'),
('JPN', '箴言', 20, 22, 19, 'あなたが主に拠り頼むことができるように、私は今日、特にあなたに教える。'),
('JPN', '箴言', 20, 22, 20, '私はあなたのために、勧告と知識についての三十句を書いたではないか。'),
('JPN', '箴言', 20, 22, 21, 'これは、あなたに真理のことばの確かさを教え、あなたを遣わした者に、真理のことばを持ち帰らせるためである。'),
('JPN', '箴言', 20, 22, 22, '貧しい者からかすめ取るな。彼が貧しいからといって。苦しむ者を門のところで踏みにじるな。'),
('JPN', '箴言', 20, 22, 23, '主が彼らの訴えを取り上げ、彼らから奪う者のいのちを、奪われるからだ。'),
('JPN', '箴言', 20, 22, 24, '怒りっぽい者と交わるな。激しやすい者と一緒に行くな。'),
('JPN', '箴言', 20, 22, 25, 'あなたがその道に倣って、自分が罠にかからないために。'),
('JPN', '箴言', 20, 22, 26, 'あなたは人と誓約をしてはならない。負債の保証人となってはならない。'),
('JPN', '箴言', 20, 22, 27, 'あなたに償うものがないとき、人があなたの下から寝床を奪ってもよいだろうか。'),
('JPN', '箴言', 20, 22, 28, '昔からの地境を移してはならない。それはあなたの先祖が設けたものだ。'),
('JPN', '箴言', 20, 22, 29, '仕事に熟練した人を見たことがあるか。その人は王の前に立つが、無名の人の前には立たない。'),
('JPN', '箴言', 20, 23, 1, 'あなたが支配者と食事の席に着くときは、前にある物によく注意するがよい。'),
('JPN', '箴言', 20, 23, 2, 'あなたが食欲の盛んな人であるなら、自分の喉に短刀を当てよ。'),
('JPN', '箴言', 20, 23, 3, 'そのごちそうを欲しがってはならない。それは偽りの食物である。'),
('JPN', '箴言', 20, 23, 4, '富を得ようと苦労してはならない。自分の分別によって、これをやめよ。'),
('JPN', '箴言', 20, 23, 5, 'あなたがこれに目を留めると、それはもうないではないか。富は必ず翼をつけて、鷲のように天へ飛んで行く。'),
('JPN', '箴言', 20, 23, 6, '物惜しみする人のパンを食べるな。彼のごちそうを欲しがるな。'),
('JPN', '箴言', 20, 23, 7, '彼は、心のうちでは勘定ずくだから。あなたに「食え、飲め」と言っても、その心はあなたとともにない。'),
('JPN', '箴言', 20, 23, 8, 'あなたは、食べた食物を吐き出し、ほめことばを無駄にすることになる。'),
('JPN', '箴言', 20, 23, 9, '愚かな者に話しかけるな。彼はあなたの思慮深いことばを蔑むからだ。'),
('JPN', '箴言', 20, 23, 10, '昔からの地境を移してはならない。みなしごの畑に入り込んではならない。'),
('JPN', '箴言', 20, 23, 11, '彼らの贖い主は力強く、彼らの訴えを取り上げて、あなたと争うからだ。'),
('JPN', '箴言', 20, 23, 12, 'あなたは訓戒に心を用い、知識のことばに耳を傾けよ。'),
('JPN', '箴言', 20, 23, 13, '子どもを懲らしめることを差し控えてはならない。むちで打っても、死ぬことはない。'),
('JPN', '箴言', 20, 23, 14, 'あなたがむちでその子を打つなら、その子のいのちをよみから救い出すことができる。'),
('JPN', '箴言', 20, 23, 15, 'わが子よ。もし、あなたの心に知恵があれば、私の心も喜び、'),
('JPN', '箴言', 20, 23, 16, 'あなたの唇が公正を語るなら、私の心は喜びに躍る。'),
('JPN', '箴言', 20, 23, 17, '心のうちで罪人を羨んではならない。いつも、ただ主を恐れていよ。'),
('JPN', '箴言', 20, 23, 18, 'あなたには確かに将来がある。あなたの望みは断たれることはない。'),
('JPN', '箴言', 20, 23, 19, 'わが子よ。よく聞いて、知恵を得よ。あなたの心が道をまっすぐ進むようにせよ。'),
('JPN', '箴言', 20, 23, 20, '大酒飲みや、肉を貪り食う者と交わるな。'),
('JPN', '箴言', 20, 23, 21, '大酒飲みや、貪り食う者は貧しくなり、惰眠を貪る者はぼろをまとうようになるからだ。'),
('JPN', '箴言', 20, 23, 22, 'あなたを生んだ父の言うことを聞け。あなたの母が年老いても蔑んではならない。'),
('JPN', '箴言', 20, 23, 23, '真理を買え。それを売ってはならない。知恵と訓戒と分別も。'),
('JPN', '箴言', 20, 23, 24, '正しい人の父は心躍らせ、知恵のある子を生んだ人はその子を喜ぶ。'),
('JPN', '箴言', 20, 23, 25, 'あなたの父と母を喜ばせ、あなたを産んだ人を楽しませよ。'),
('JPN', '箴言', 20, 23, 26, 'わが子よ、あなたの心をわたしにゆだねよ。あなたの目が、わたしの道を喜ぶようにせよ。'),
('JPN', '箴言', 20, 23, 27, '遊女は深い穴、見知らぬ女は狭い井戸だから。'),
('JPN', '箴言', 20, 23, 28, 'その女は強盗のように待ち伏せ、人々の間に裏切り者を増やす。'),
('JPN', '箴言', 20, 23, 29, '嘆く者はだれか。悲嘆の中にある者はだれか。争いを好む者はだれか。不平を言う者はだれか。理由もなく傷ついている者はだれか。血走った目をしている者はだれか。'),
('JPN', '箴言', 20, 23, 30, 'ぶどう酒をいつまでも飲み続ける者、混ぜ合わせた酒の味見をしに行く者だ。'),
('JPN', '箴言', 20, 23, 31, 'ぶどう酒が赤いとき、杯の中で輝くとき、滑らかにこぼれるとき、それを見てはならない。'),
('JPN', '箴言', 20, 23, 32, '後になると、これが蛇のようにかみつき、まむしのように刺す。'),
('JPN', '箴言', 20, 23, 33, 'あなたの目は異様な物を見、あなたの心はねじれごとを語り、'),
('JPN', '箴言', 20, 23, 34, '海の真ん中で寝ている人のように、帆柱のてっぺんで寝ている人のようになる。'),
('JPN', '箴言', 20, 23, 35, '「私は打たれたが、痛くなかった。殴られたが、知らなかった。いつ、私は目を覚ますだろうか。もっと飲みたいものだ。」'),
('JPN', '箴言', 20, 24, 1, '悪い者たちを羨んではならない。彼らとともにいることを望んではならない。'),
('JPN', '箴言', 20, 24, 2, '彼らの心は暴行を企み、唇は邪悪を語るからだ。'),
('JPN', '箴言', 20, 24, 3, '家は知恵によって建てられ、英知によって堅くされる。'),
('JPN', '箴言', 20, 24, 4, '部屋は知識によって、尊く好ましいあらゆる宝物で満たされる。'),
('JPN', '箴言', 20, 24, 5, '知恵のある男は力強い。知識のある人は力を増す。'),
('JPN', '箴言', 20, 24, 6, 'あなたはすぐれた指揮のもとに戦いを交え、多くの助言者によって勝利を得る。'),
('JPN', '箴言', 20, 24, 7, '愚か者には知恵は珊瑚のよう。彼は町の門で、口を開くことができない。'),
('JPN', '箴言', 20, 24, 8, '悪事を働こうと企む者は、陰謀家と呼ばれる。'),
('JPN', '箴言', 20, 24, 9, '愚かなはかりごとは罪。嘲る者は人に忌み嫌われる。'),
('JPN', '箴言', 20, 24, 10, 'もしあなたが苦難の日に気落ちしたら、あなたの力は弱い。'),
('JPN', '箴言', 20, 24, 11, '死に渡されるために捕らえられた者を救い出し、殺されようとしてよろめき歩く者を助け出せ。'),
('JPN', '箴言', 20, 24, 12, 'あなたが「そのことを知らなかった」と言っても、人の心を評価する方は、それを見抜いておられないだろうか。あなたのたましいを見守る方は、それをご存じないだろうか。人の行いに応じて、報いをされないだろうか。'),
('JPN', '箴言', 20, 24, 13, 'わが子よ、蜜を食べよ。それはおいしい。蜂の巣の蜜はあなたの口に甘い。'),
('JPN', '箴言', 20, 24, 14, '知恵もあなたのたましいには同じだと知れ。それを見つけるなら、あなたには将来があり、あなたの望みが断たれることはない。'),
('JPN', '箴言', 20, 24, 15, '悪しき者よ、正しい人の住まいを狙うな。彼の伏す所を荒らすな。'),
('JPN', '箴言', 20, 24, 16, '正しい人は七度倒れても、また起き上がり、悪しき者はわざわいでつまずくからだ。'),
('JPN', '箴言', 20, 24, 17, 'あなたの敵が倒れるとき、喜んではならない。彼がつまずくとき、心躍らせてはならない。'),
('JPN', '箴言', 20, 24, 18, '主がそれを見て心を痛め、彼への怒りをやめられるといけない。'),
('JPN', '箴言', 20, 24, 19, '悪を行う者に対して腹を立てるな。悪しき者を羨むな。'),
('JPN', '箴言', 20, 24, 20, '悪者には将来がなく、悪しき者のともしびは消えるからだ。'),
('JPN', '箴言', 20, 24, 21, 'わが子よ、主と王を恐れよ。そうしない者たちと交わってはならない。'),
('JPN', '箴言', 20, 24, 22, '彼らには、突然終局が訪れるからだ。主と王から来るわざわいをだれが知るだろうか。'),
('JPN', '箴言', 20, 24, 23, 'これらも、知恵のある者たちによる。さばくときに、人を偏り見るのは良くない。'),
('JPN', '箴言', 20, 24, 24, '悪者に向かって「あなたは正しい」と言う者を、人々はののしり、国々の民は呪う。'),
('JPN', '箴言', 20, 24, 25, 'しかし、悪者を叱責する者たちは喜ばれ、すばらしい祝福が臨む。'),
('JPN', '箴言', 20, 24, 26, '率直な答えをする者は、その唇に口づけされる。'),
('JPN', '箴言', 20, 24, 27, '外であなたの仕事を確かなものとし、あなたの畑を整え、その後で、あなたは家を建てよ。'),
('JPN', '箴言', 20, 24, 28, 'あなたは、あなたの隣人に対し、根拠を持たない証人となってはならない。あなたのその唇で惑わそうとするのか。'),
('JPN', '箴言', 20, 24, 29, '「彼が私にしたように、私も彼にしよう。彼の行いに応じて、仕返しをしよう」と言ってはならない。'),
('JPN', '箴言', 20, 24, 30, '私は怠け者の畑のそばを、良識のない者のぶどう畑のそばを通った。'),
('JPN', '箴言', 20, 24, 31, '見よ。茨が一面に生え、いらくさが地面をおおい、その石垣は壊れていた。'),
('JPN', '箴言', 20, 24, 32, '私はこれを見て心に留め、これを見て戒めを受けた。'),
('JPN', '箴言', 20, 24, 33, '少し眠り、少しまどろみ、少し腕を組んで横になる。'),
('JPN', '箴言', 20, 24, 34, 'すると、付きまとう者のように貧しさが、武装した者のように乏しさがやって来る。'),
('JPN', '箴言', 20, 25, 1, '次もソロモンの箴言であり、ユダの王ヒゼキヤのもとにある人々が書き写したものである。'),
('JPN', '箴言', 20, 25, 2, '事を隠すのは神の誉れ。事を探るのは王たちの誉れ。'),
('JPN', '箴言', 20, 25, 3, '天が高く、地が深いように、王の心は測り知れない。'),
('JPN', '箴言', 20, 25, 4, '銀から金かすを除け。そうすれば細工人に、良い器ができあがる。'),
('JPN', '箴言', 20, 25, 5, '王の前から悪しき者を除け。そうすれば、王座は義によって堅く据えられる。'),
('JPN', '箴言', 20, 25, 6, '王の前で横柄にふるまってはならない。身分の高い人のいる所に立ってはならない。'),
('JPN', '箴言', 20, 25, 7, '高貴な人の前で下に下げられるよりは、「ここに上って来なさい」と言われるほうがよいからだ。あなたがその目で見たことを'),
('JPN', '箴言', 20, 25, 8, '急いで訴え出るな。さもないと、後になって隣人があなたに恥ずかしい思いをさせたとき、あなたはどうしようというのか。'),
('JPN', '箴言', 20, 25, 9, 'あなたは隣人と争っても、ほかの人の秘密を漏らしてはならない。'),
('JPN', '箴言', 20, 25, 10, 'そうでないと、聞く者があなたを侮辱し、あなたの悪いうわさは取り返しがつかなくなる。'),
('JPN', '箴言', 20, 25, 11, '時宜にかなって語られることばは、銀の彫り物にはめられた金のりんご。'),
('JPN', '箴言', 20, 25, 12, '知恵をもって叱責する者は、聞く者の耳にとって金の耳輪、黄金の飾り。'),
('JPN', '箴言', 20, 25, 13, '忠実な使者は、これを遣わす者にとって、刈り入れ時の冷たい雪のよう。その人は主人の心を生き返らせる。'),
('JPN', '箴言', 20, 25, 14, '贈りもしない贈り物を自慢する者は、雨を降らせない雲や風のようだ。'),
('JPN', '箴言', 20, 25, 15, '忍耐強く説けば、首領も納得する。柔らかな舌は骨を砕く。'),
('JPN', '箴言', 20, 25, 16, '蜜を見つけたら、必要なだけ食べよ。食べ過ぎて吐き出すことのないように。'),
('JPN', '箴言', 20, 25, 17, '隣人の家にあまり足を運ぶな。その人がうんざりして、あなたを憎まないように。'),
('JPN', '箴言', 20, 25, 18, '隣人について偽りの証言をする人は、こん棒、剣、また鋭い矢のようだ。'),
('JPN', '箴言', 20, 25, 19, '苦難の日に、裏切り者に拠り頼むのは、悪い歯やよろける足を頼みとするようなもの。'),
('JPN', '箴言', 20, 25, 20, '心配している人の前で歌を歌うのは、寒い日に服を脱ぐようなもの、ソーダの上に酢を注ぐようなものだ。'),
('JPN', '箴言', 20, 25, 21, 'あなたを憎む者が飢えているなら、パンを食べさせ、渇いているなら、水を飲ませよ。'),
('JPN', '箴言', 20, 25, 22, 'なぜなら、あなたは彼の頭上に燃える炭火を積むことになり、主があなたに報いてくださるからだ。'),
('JPN', '箴言', 20, 25, 23, '北風は大雨を起こし、陰口をたたく舌は怒り顔を生む。'),
('JPN', '箴言', 20, 25, 24, '争い好きな女と一緒に家にいるよりは、屋上の片隅に住むほうがよい。'),
('JPN', '箴言', 20, 25, 25, '遠い国からの良い消息は、疲れたたましいへの冷たい水。'),
('JPN', '箴言', 20, 25, 26, '正しい人が悪しき者の前に屈服するのは、汚された泉、荒らされた井戸のようなもの。'),
('JPN', '箴言', 20, 25, 27, '蜜を食べ過ぎるのは良いことではない。自分の誉れを探るのは、誉れあることではない。'),
('JPN', '箴言', 20, 25, 28, '自分の霊を制することができない人は、城壁のない、打ち破られた町。'),
('JPN', '箴言', 20, 26, 1, '夏の雪、刈り入れ時の雨のように、誉れは愚かな者にふさわしくない。'),
('JPN', '箴言', 20, 26, 2, '逃げる雀のように、飛び去る燕のように、理由なしに、のろいが来ることはない。'),
('JPN', '箴言', 20, 26, 3, '馬にはむち。ろばにはくつわ。愚かな者の背中にはむち。'),
('JPN', '箴言', 20, 26, 4, '愚かな者には、その愚かさに合わせて答えるな。あなたも彼と同じようにならないためだ。'),
('JPN', '箴言', 20, 26, 5, '愚かな者には、その愚かさに合わせて答えよ。そうすれば彼は、自分を知恵のある者と思わないだろう。'),
('JPN', '箴言', 20, 26, 6, '愚かな者に託して言い送る者は、両足を切られ、暴行を受ける。'),
('JPN', '箴言', 20, 26, 7, '愚かな者が口にする箴言は、足の萎えた者の垂れ下がった足。'),
('JPN', '箴言', 20, 26, 8, '愚かな者に誉れを与えるのは、石投げ器に石を結わえ付けるようなもの。'),
('JPN', '箴言', 20, 26, 9, '愚かな者が口にする箴言は、酔った人が手に取り上げる茨。'),
('JPN', '箴言', 20, 26, 10, '愚かな者や通りすがりの者を雇う者は、だれかれかまわず射抜く射手のよう。'),
('JPN', '箴言', 20, 26, 11, '犬が自分の吐いた物に戻って来るように、愚かな者は自分の愚かさを繰り返す。'),
('JPN', '箴言', 20, 26, 12, '自分を知恵のある者と思っている人を見たか。彼よりも、愚かな者のほうが、まだ望みがある。'),
('JPN', '箴言', 20, 26, 13, '怠け者は「道に獅子がいる。広場に雄獅子がいる」と言う。'),
('JPN', '箴言', 20, 26, 14, '戸はちょうつがいで向きを変える。怠け者は寝床の上で。'),
('JPN', '箴言', 20, 26, 15, '怠け者は皿に手を伸ばしても、その手を口に持って行くのを面倒がる。'),
('JPN', '箴言', 20, 26, 16, '怠け者は、良識ある答えをする七人の者よりも、自分を知恵のある者と思う。'),
('JPN', '箴言', 20, 26, 17, '自分に関係のない争いにいきり立つ者は、通りすがりの犬の耳をつかむ者のようだ。'),
('JPN', '箴言', 20, 26, 18, '気がふれた者は、燃え木を死の矢として投げるが、'),
('JPN', '箴言', 20, 26, 19, '隣人をだましながら、「ただ、戯れただけではないか」と言う者も、それと同じ。'),
('JPN', '箴言', 20, 26, 20, '薪がなければ火が消えるように、陰口をたたく者がいなければ争いはやむ。'),
('JPN', '箴言', 20, 26, 21, '炭火に炭を、火に薪をくべるように、口論好きな人は争いをかき立てる。'),
('JPN', '箴言', 20, 26, 22, '陰口をたたく者のことばは、おいしい食べ物のよう。腹の奥に下って行く。'),
('JPN', '箴言', 20, 26, 23, '燃える唇も、心が悪いなら、質の悪い銀を塗った土の器。'),
('JPN', '箴言', 20, 26, 24, '憎んでいる者は、唇で身を装うが、心のうちに欺きを潜めている。'),
('JPN', '箴言', 20, 26, 25, '声を和らげて語りかけてきても、信じるな。その心には七つの忌み嫌われるものがある。'),
('JPN', '箴言', 20, 26, 26, '憎しみはうまくごまかし隠せても、彼の悪は集いの中で現れる。'),
('JPN', '箴言', 20, 26, 27, '穴を掘る者は、自分がその穴に陥り、石を転がす者は、自分の上にそれを転がす。'),
('JPN', '箴言', 20, 26, 28, '偽りの舌は、虐げられている者を憎み、滑らかな口は滅びを招く。'),
('JPN', '箴言', 20, 27, 1, '明日のことを誇るな。一日のうちに何が起こるか、あなたは知らないのだから。'),
('JPN', '箴言', 20, 27, 2, '自分の口でではなく、ほかの者にあなたをほめさせよ。自分の唇でではなく、よその人によって。'),
('JPN', '箴言', 20, 27, 3, '石は重く、砂にも重みがある。しかし、愚か者の苛立ちはどちらよりも重い。'),
('JPN', '箴言', 20, 27, 4, '憤りは残忍で、怒りはあふれ出る。しかし、ねたみの前には、だれが立ちはだかることができるだろうか。'),
('JPN', '箴言', 20, 27, 5, 'あからさまに責めるのは、ひそかに愛するより良い。'),
('JPN', '箴言', 20, 27, 6, '愛する者が傷つけるのは誠実による。憎む者は多くの口づけでもてなす。'),
('JPN', '箴言', 20, 27, 7, '満ち足りている者は蜂の巣の蜜も踏みつけ、飢えている者には苦い物もみな甘い。'),
('JPN', '箴言', 20, 27, 8, '自分の巣を離れてさまよう鳥のように、人は自分の家を離れてさまよう。'),
('JPN', '箴言', 20, 27, 9, '香油も香も心を喜ばせる。友の慰めは自分の考えにまさる。'),
('JPN', '箴言', 20, 27, 10, 'あなたの友、あなたの父の友を捨てるな。あなたが災難にあうとき、兄弟の家に行くな。近くにいる隣人は、遠くにいる兄弟にまさる。'),
('JPN', '箴言', 20, 27, 11, 'わが子よ、知恵を得よ。私の心を喜ばせよ。そうすれば、私をそしる者に、私は言い返すことができるだろう。'),
('JPN', '箴言', 20, 27, 12, '賢い人はわざわいを見て身を隠し、浅はかな者は入って行って痛い目にあう。'),
('JPN', '箴言', 20, 27, 13, '他人の保証人となるときは、その者の服を取れ。見知らぬ女のためにも、服を抵当に取れ。'),
('JPN', '箴言', 20, 27, 14, '朝早くから、大声で隣人を祝福すると、かえって呪いと見なされる。'),
('JPN', '箴言', 20, 27, 15, '長雨の日に滴り続ける雨漏りは、争い好きな女に似ている。'),
('JPN', '箴言', 20, 27, 16, 'その女を制する者は、風を制し、右手に油をつかむことができる。'),
('JPN', '箴言', 20, 27, 17, '鉄は鉄によって研がれ、人はその友によって研がれる。'),
('JPN', '箴言', 20, 27, 18, 'いちじくの木の番人はその実を食う。主人の身を守る者は誉れを得る。'),
('JPN', '箴言', 20, 27, 19, '顔が、水に映る顔と同じであるように、人の心は、その人に映る。'),
('JPN', '箴言', 20, 27, 20, 'よみと滅びの地は飽くことがなく、人の目も飽くことがない。'),
('JPN', '箴言', 20, 27, 21, '銀にはるつぼ、金には炉があるように、人は他人の称賛によって試される。'),
('JPN', '箴言', 20, 27, 22, '愚か者を臼に入れ、きねでこれを麦と一緒についても、その愚かさは彼から離れない。'),
('JPN', '箴言', 20, 27, 23, 'あなたの羊の様子をよく知り、群れを心に留めておけ。'),
('JPN', '箴言', 20, 27, 24, '富は永久に続くものではなく、王冠も代々に続かないからだ。'),
('JPN', '箴言', 20, 27, 25, '草が刈り取られ、若草が現れ、山々の青草も集められると、'),
('JPN', '箴言', 20, 27, 26, '子羊はあなたに服を着させ、やぎは畑の代価となる。'),
('JPN', '箴言', 20, 27, 27, 'やぎの乳は十分あって、あなたの食物、あなたの家の者たちの食物となり、あなたの召使いの女たちを養う。'),
('JPN', '箴言', 20, 28, 1, '悪しき者は、追う者もいないのに逃げるが、正しい人は若獅子のように頼もしい。'),
('JPN', '箴言', 20, 28, 2, '国に背きがあるときは、首長が多くなるが、判断力と知識のある一人の人により、安定は続く。'),
('JPN', '箴言', 20, 28, 3, '弱い者を虐げる貧しい者は、押し流して食物を残さない豪雨のようだ。'),
('JPN', '箴言', 20, 28, 4, 'おしえを捨てる者は悪しき者をほめる。おしえを守る者は彼らに敵対する。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '箴言', 20, 28, 5, '悪人はさばきをわきまえない。主を尋ね求める者はすべてのことをわきまえる。'),
('JPN', '箴言', 20, 28, 6, '貧しくて、誠実に歩む者は、富んでいて、曲がった道を歩む者にまさる。'),
('JPN', '箴言', 20, 28, 7, '分別のある子はおしえを大切にする。放蕩する者と交わる者は、父に恥をかかせる。'),
('JPN', '箴言', 20, 28, 8, '利息や高利によって財産を増やす者は、貧しい者たちに恵む者のためにそれを蓄える。'),
('JPN', '箴言', 20, 28, 9, '耳を背けておしえを聞かない者は、その祈りさえ忌み嫌われる。'),
('JPN', '箴言', 20, 28, 10, '直ぐな人を悪い道に迷わす者は、自分の掘った穴に陥る。しかし、誠実な人たちは幸せを受け継ぐ。'),
('JPN', '箴言', 20, 28, 11, '富む者には自分が知恵のある者に見える。しかし、分別のある貧しい者は、彼を調べる。'),
('JPN', '箴言', 20, 28, 12, '正しい人が喜ぶと、大いなる栄えがあり、悪しき者が立ち上がると、人は身を潜める。'),
('JPN', '箴言', 20, 28, 13, '自分の背きを隠す者は成功しない。告白して捨てる者はあわれみを受ける。'),
('JPN', '箴言', 20, 28, 14, '幸いなことよ、いつも恐れる心を持つ人は。しかし、心を頑なにする者はわざわいに陥る。'),
('JPN', '箴言', 20, 28, 15, '貧しい民を治める悪しき支配者は、うなる雄獅子、襲いかかる熊のようだ。'),
('JPN', '箴言', 20, 28, 16, '英知を欠く君主は、多くの物を強奪する。不正な利得を憎む者は、齢を延ばす。'),
('JPN', '箴言', 20, 28, 17, '流血の咎に苦しむ者は、墓まで逃げる。だれも彼を助けてはならない。'),
('JPN', '箴言', 20, 28, 18, '誠実に歩む者は救われ、その道が曲がっている者はただちに倒れる。'),
('JPN', '箴言', 20, 28, 19, '自分の土地を耕す者は食糧に満ち足り、空しいものを追い求める者は貧しさに満ち足りる。'),
('JPN', '箴言', 20, 28, 20, '忠実な人は多くの祝福を得る。しかし、富を得ようと急ぐ者は罰を免れない。'),
('JPN', '箴言', 20, 28, 21, '人を偏り見るのは良くない。人は一切れのパンで背く。'),
('JPN', '箴言', 20, 28, 22, '貪欲な人は財産を得ようと焦り、欠乏が自分に来るのを知らない。'),
('JPN', '箴言', 20, 28, 23, '人を叱責する者は、後になって、舌でへつらう者よりも恵みを得る。'),
('JPN', '箴言', 20, 28, 24, '父母の物をかすめていながら、「背いていない」と言う者は、滅びをもたらす者の仲間。'),
('JPN', '箴言', 20, 28, 25, '欲の深い人は争いを引き起こす。しかし、主に拠り頼む人は豊かにされる。'),
('JPN', '箴言', 20, 28, 26, '自分の心に頼る者は愚かな者、知恵をもって歩む者は救われる。'),
('JPN', '箴言', 20, 28, 27, '貧しい者に施す者は不足することがなく、目をそらす者は多くののろいを受ける。'),
('JPN', '箴言', 20, 28, 28, '悪しき者が勢いを増すと、人は身を隠し、彼らが滅びると、正しい人が増える。'),
('JPN', '箴言', 20, 29, 1, '叱責されても、なお、うなじを固くする者は、突然打ち砕かれて、癒やされることがない。'),
('JPN', '箴言', 20, 29, 2, '正しい人が増えると、民は喜び、悪しき者が治めると、民はうめく。'),
('JPN', '箴言', 20, 29, 3, '知恵を愛する人は、その父を喜ばせ、遊女と交わる者は、財産を滅ぼす。'),
('JPN', '箴言', 20, 29, 4, '正義によって王は国を建てる。重税を取る者は国を壊す。'),
('JPN', '箴言', 20, 29, 5, '隣人にへつらう者は、自分の足もとに網を張る。'),
('JPN', '箴言', 20, 29, 6, '悪人は背きを犯して自分に罠をかける。正しい人は声をあげて喜び歌う。'),
('JPN', '箴言', 20, 29, 7, '正しい人は弱い者のためのさばきを知っている。悪しき者はそのような知識をわきまえない。'),
('JPN', '箴言', 20, 29, 8, '嘲る者たちは町を騒がし、知恵のある人たちは怒りを鎮める。'),
('JPN', '箴言', 20, 29, 9, '知恵のある人が愚か者を訴えて争うと、愚か者は怒ってあざ笑い、安まることがない。'),
('JPN', '箴言', 20, 29, 10, '血に飢えた者たちは誠実な人を憎み、心の直ぐな人のいのちを狙う。'),
('JPN', '箴言', 20, 29, 11, '愚かな者は感情のすべてをぶちまけ、知恵のある人はそれを内に収める。'),
('JPN', '箴言', 20, 29, 12, '支配者が偽りのことばに聞き入るなら、従者たちもみな悪しき者になる。'),
('JPN', '箴言', 20, 29, 13, '貧しい者と抑圧する者は出会う。主は、この両者の目に光を与えられる。'),
('JPN', '箴言', 20, 29, 14, '真実をもって弱い者をさばく王、その王座はとこしえまでも堅く立つ。'),
('JPN', '箴言', 20, 29, 15, 'むちと叱責は知恵を与える。放っておかれた子は母に恥を見させる。'),
('JPN', '箴言', 20, 29, 16, '悪しき者が増えると、背きも増す。しかし、正しい人は彼らの滅びを見る。'),
('JPN', '箴言', 20, 29, 17, 'あなたの子を戒めよ。そうすれば、彼はあなたを安らかにし、あなたの心に喜びを与える。'),
('JPN', '箴言', 20, 29, 18, '幻がなければ、民は好き勝手にふるまう。しかし、みおしえを守る者は幸いである。'),
('JPN', '箴言', 20, 29, 19, 'しもべは、ことばだけで戒めることはできない。それが分かっても、反応しない。'),
('JPN', '箴言', 20, 29, 20, '軽率に話をする人を見たか。彼よりも愚かな者のほうが、まだ望みがある。'),
('JPN', '箴言', 20, 29, 21, '自分のしもべを幼い時から甘やかすと、ついには手に負えない者になる。'),
('JPN', '箴言', 20, 29, 22, '怒る者は争いを引き起こす。憤る者には多くの背きがある。'),
('JPN', '箴言', 20, 29, 23, '人の高ぶりはその人を低くし、へりくだった人は誉れをつかむ。'),
('JPN', '箴言', 20, 29, 24, '盗人にくみする者は自分自身を憎む者。その人はのろいを聞いても何も言わない。'),
('JPN', '箴言', 20, 29, 25, '人を恐れると罠にかかる。しかし、主に信頼する者は高い所にかくまわれる。'),
('JPN', '箴言', 20, 29, 26, '支配者の顔色をうかがう者は多い。しかし、人をさばくのは主である。'),
('JPN', '箴言', 20, 29, 27, '不正を行う者は正しい人に忌み嫌われ、行いの真っ直ぐな人は悪しき者に忌み嫌われる。'),
('JPN', '箴言', 20, 30, 1, 'マサの人ヤケの子アグルのことば。イティエルに告げ、イティエルとウカルに告げたことば。'),
('JPN', '箴言', 20, 30, 2, 'まことに、私は粗野で、人ではない。私には人間としての分別がない。'),
('JPN', '箴言', 20, 30, 3, '私はまだ知恵も学ばず、聖なる方の知識も持っていない。'),
('JPN', '箴言', 20, 30, 4, 'だれが天に上り、また降りて来たのか。だれが風を両手のひらに集めたのか。だれが水を衣のうちに包んだのか。だれが地のすべての限界を堅く定めたのか。その名は何か、その子の名は何か。あなたは確かに知っている。'),
('JPN', '箴言', 20, 30, 5, '神のことばは、すべて精錬されている。神は、ご自分に身を避ける者の盾。'),
('JPN', '箴言', 20, 30, 6, '神のことばに付け足しをしてはならない。神があなたを責めて、あなたが偽り者とされないために。'),
('JPN', '箴言', 20, 30, 7, '二つのことをあなたにお願いします。私が死なないうちに、それをかなえてください。'),
('JPN', '箴言', 20, 30, 8, 'むなしいことと偽りのことばを、私から遠ざけてください。貧しさも富も私に与えず、ただ、私に定められた分の食物で、私を養ってください。'),
('JPN', '箴言', 20, 30, 9, '私が満腹してあなたを否み、「主とはだれだ」と言わないように。また、私が貧しくなって盗みをし、私の神の御名を汚すことのないように。'),
('JPN', '箴言', 20, 30, 10, 'しもべのことを、その主人に中傷してはならない。そうでないと、彼はあなたをののしり、あなたは罰を受けることになる。'),
('JPN', '箴言', 20, 30, 11, '自分の父をののしり、自分の母をたたえない世代。'),
('JPN', '箴言', 20, 30, 12, '自分をきよいと見るが、汚物を洗い落とさない世代。'),
('JPN', '箴言', 20, 30, 13, 'なんとも、その目が高ぶり、まぶたが上がっている世代。'),
('JPN', '箴言', 20, 30, 14, '歯が剣のようで、牙が刀のような世代。彼らは、地の苦しむ者を、人々の中の貧しい者を食い尽くす。'),
('JPN', '箴言', 20, 30, 15, '蛭には二人の娘がいて、「くれ、くれ」と言う。飽くことを知らないものが三つある。いや、四つあって、「もう十分だ」と言わない。'),
('JPN', '箴言', 20, 30, 16, 'よみ、不妊の胎、水に飽くことを知らない地、「もう十分だ」と言わない火。'),
('JPN', '箴言', 20, 30, 17, '自分の父を嘲り、母への従順を蔑む目は、谷の烏にえぐり取られ、鷲の子に食われる。'),
('JPN', '箴言', 20, 30, 18, '私にとって不思議なことが三つある。いや、四つあって、私はそれを知らない。'),
('JPN', '箴言', 20, 30, 19, '天にある鷲の道、岩の上にある蛇の道、海の真ん中にある船の道、おとめへの男の道。'),
('JPN', '箴言', 20, 30, 20, '姦淫する女の道もそのとおり。彼女は食べて口をぬぐい、「私は不法を行わなかった」と言う。'),
('JPN', '箴言', 20, 30, 21, '地は三つのことによって震える。いや、四つのことに耐えられない。'),
('JPN', '箴言', 20, 30, 22, '奴隷が王となり、愚か者がパンに満ち足り、'),
('JPN', '箴言', 20, 30, 23, '嫌われた女が夫を得、女奴隷が女主人の代わりとなることだ。'),
('JPN', '箴言', 20, 30, 24, 'この地上には小さいものが四つある。それは知恵者中の知恵者だ。'),
('JPN', '箴言', 20, 30, 25, '蟻は力のないものたちだが、夏のうちに食糧を確保する。'),
('JPN', '箴言', 20, 30, 26, '岩だぬきは強くないものたちだが、その巣を岩間に設ける。'),
('JPN', '箴言', 20, 30, 27, 'いなごには王はいないが、みな隊を組んで出陣する。'),
('JPN', '箴言', 20, 30, 28, 'ヤモリは手で捕まえられるが、王の宮殿にいる。'),
('JPN', '箴言', 20, 30, 29, '歩きぶりの堂々としたものが三つある。いや、堂々と歩くものが四つある。'),
('JPN', '箴言', 20, 30, 30, '獣の中で最も強く、何からも逃げない雄獅子、'),
('JPN', '箴言', 20, 30, 31, '誇らしげに歩くおんどりと雄やぎ、軍隊を引き連れた王。'),
('JPN', '箴言', 20, 30, 32, 'もし、あなたが高ぶって、愚かなことをしたり、企んだりしたら、手を口に当てよ。'),
('JPN', '箴言', 20, 30, 33, '乳をかき回すと凝乳ができる。鼻をねじると血が出る。怒りをかき回すと争いが起こる。'),
('JPN', '箴言', 20, 31, 1, 'マサの王レムエルが母から受けた戒めのことば。'),
('JPN', '箴言', 20, 31, 2, '私の子よ、何を語ろうか。私の胎の子よ、何を語ろうか。私の誓願の子よ、何を語ろうか。'),
('JPN', '箴言', 20, 31, 3, 'あなたの力を、女たちに費やしてはいけない。王を滅ぼす者たちに、歩みを委ねてはいけない。'),
('JPN', '箴言', 20, 31, 4, 'レムエルよ、これは王がすることではない。ぶどう酒を飲むのは王がすることではない。強い酒を飲むのは君主がすることではない。'),
('JPN', '箴言', 20, 31, 5, '酒を飲んで、定められたことを忘れ、苦しむ者みなへのさばきを曲げるといけないから。'),
('JPN', '箴言', 20, 31, 6, '強い酒は滅びようとしている者に、ぶどう酒は心の痛んでいる者に与えなさい。'),
('JPN', '箴言', 20, 31, 7, 'その人は飲んで自分の貧しさを忘れ、もう自分の労苦を思い出すことはない。'),
('JPN', '箴言', 20, 31, 8, '口のきけない人のために、口を開きなさい。すべての不幸な人の訴えのために。'),
('JPN', '箴言', 20, 31, 9, '口を開いて、正しくさばき、苦しむ人や貧しい人のためにさばきを行いなさい。'),
('JPN', '箴言', 20, 31, 10, 'しっかりした妻をだれが見つけられるだろう。彼女の値打ちは真珠よりもはるかに尊い。'),
('JPN', '箴言', 20, 31, 11, '夫の心は彼女を信頼し、彼は収益に欠けることがない。'),
('JPN', '箴言', 20, 31, 12, '彼女はその一生の間、夫に良いことをし、悪いことをしない。'),
('JPN', '箴言', 20, 31, 13, '羊毛や亜麻を手に入れ、喜んで自分の手でそれを仕上げる。'),
('JPN', '箴言', 20, 31, 14, '商人の船のように、遠い所から食糧を運んで来る。'),
('JPN', '箴言', 20, 31, 15, '夜明け前に起きて、家の者に食事を整え、召使いの女たちに用事を言いつける。'),
('JPN', '箴言', 20, 31, 16, 'よく調べて畑を手に入れ、自分の稼ぎでぶどう畑を作り、'),
('JPN', '箴言', 20, 31, 17, '腰に力強く帯を締め、腕に力を入れる。'),
('JPN', '箴言', 20, 31, 18, '収入が良いのを味わい、そのともしびは夜になっても消えない。'),
('JPN', '箴言', 20, 31, 19, '糸取り棒に手を伸ばし、手に糸巻きをつかむ。'),
('JPN', '箴言', 20, 31, 20, '苦しむ人に手を差し出し、貧しい人に手を差し伸べる。'),
('JPN', '箴言', 20, 31, 21, '家の者のために雪を恐れることはない。家の者はみな、紅の衣服で身を包んでいるから。'),
('JPN', '箴言', 20, 31, 22, '自分のための敷き物を作り、衣服は亜麻布と紫の撚り糸でできている。'),
('JPN', '箴言', 20, 31, 23, '夫は町囲みの中で人々によく知られ、土地の長老たちとともに座に着く。'),
('JPN', '箴言', 20, 31, 24, '彼女は亜麻布の衣服を作って売り、また、帯を作って商人に渡す。'),
('JPN', '箴言', 20, 31, 25, '力と気品をまとい、ほほえみながら後の日を待つ。'),
('JPN', '箴言', 20, 31, 26, '知恵をもって口を開き、その舌には恵みのおしえがある。'),
('JPN', '箴言', 20, 31, 27, '家の者の様子をよく見守り、怠惰のパンを食べない。'),
('JPN', '箴言', 20, 31, 28, 'その子たちは立ち上がって彼女をたたえ、夫も彼女をほめたたえて言う。'),
('JPN', '箴言', 20, 31, 29, '「力ある働きをする女は多いが、あなたは、そのすべてにまさっている」と。'),
('JPN', '箴言', 20, 31, 30, '麗しさは偽り。美しさは空しい。しかし、主を恐れる女はほめたたえられる。'),
('JPN', '箴言', 20, 31, 31, '彼女の手が稼いだ実を彼女に与え、そのわざを町囲みの中でほめたたえよ。'),
('JPN', '传道书', 21, 1, 1, 'エルサレムの王、ダビデの子、伝道者のことば。'),
('JPN', '传道书', 21, 1, 2, '空の空。伝道者は言う。空の空。すべては空。'),
('JPN', '传道书', 21, 1, 3, '日の下でどんなに労苦しても、それが人に何の益になるだろうか。'),
('JPN', '传道书', 21, 1, 4, '一つの世代が去り、次の世代が来る。しかし、地はいつまでも変わらない。'),
('JPN', '传道书', 21, 1, 5, '日は昇り、日は沈む。そしてまた、元の昇るところへと急ぐ。'),
('JPN', '传道书', 21, 1, 6, '風は南に吹き、巡って北に吹く。巡り巡って風は吹く。しかし、その巡る道に風は帰る。'),
('JPN', '传道书', 21, 1, 7, '川はみな海に流れ込むが、海は満ちることがない。川は流れる場所に、また帰って行く。'),
('JPN', '传道书', 21, 1, 8, 'すべてのことは物憂く、人は語ることさえできない。目は見て満足することがなく、耳も聞いて満ち足りることがない。'),
('JPN', '传道书', 21, 1, 9, '昔あったものは、これからもあり、かつて起こったことは、これからも起こる。日の下には新しいものは一つもない。'),
('JPN', '传道书', 21, 1, 10, '「これを見よ。これは新しい」と言われるものがあっても、それは、私たちよりはるか前の時代にすでにあったものだ。'),
('JPN', '传道书', 21, 1, 11, '前にあったことは記憶に残っていない。これから後に起こることも、さらに後の時代の人々には記憶されないだろう。'),
('JPN', '传道书', 21, 1, 12, '伝道者である私は、エルサレムでイスラエルの王であった。'),
('JPN', '传道书', 21, 1, 13, '私は、天の下で行われる一切のことについて、知恵を用いて尋ね、探り出そうと心に決めた。これは、神が人の子らに、従事するようにと与えられた辛い仕事だ。'),
('JPN', '传道书', 21, 1, 14, '私は、日の下で行われるすべてのわざを見たが、見よ、すべては空しく、風を追うようなものだ。'),
('JPN', '传道书', 21, 1, 15, '曲げられたものを、まっすぐにはできない。欠けているものを、数えることはできない。'),
('JPN', '传道书', 21, 1, 16, '私は自分の心にこう言った。「今や、私は、私より前にエルサレムにいただれよりも、知恵を増し加えた。私の心は多くの知恵と知識を得た。」'),
('JPN', '传道书', 21, 1, 17, '私は、知恵と知識を、狂気と愚かさを知ろうと心に決めた。それもまた、風を追うようなものであることを知った。'),
('JPN', '传道书', 21, 1, 18, '実に、知恵が多くなれば悩みも多くなり、知識が増す者には苛立ちも増す。'),
('JPN', '传道书', 21, 2, 1, '私は心の中で言った。「さあ、快楽を味わってみるがよい。楽しんでみるがよい。」しかし、これもまた、なんと空しいことか。'),
('JPN', '传道书', 21, 2, 2, '笑いか。私は言う。それは狂気だ。快楽か。それがいったい何だろう。'),
('JPN', '传道书', 21, 2, 3, '私は心の中で考えた。私の心は知恵によって導かれているが、からだはぶどう酒で元気づけよう。人の子がそのいのちの日数の間に天の下ですることについて、何が良いかを見るまでは、愚かさを身につけていよう。'),
('JPN', '传道书', 21, 2, 4, '私は自分の事業を拡張し、自分のために邸宅を建て、いくつものぶどう畑を設け、'),
('JPN', '传道书', 21, 2, 5, 'いくつもの庭と園を造り、そこにあらゆる種類の果樹を植えた。'),
('JPN', '传道书', 21, 2, 6, '木の茂った森を潤すためにいくつもの池も造った。'),
('JPN', '传道书', 21, 2, 7, '私は男女の奴隷を得、家で生まれた奴隷も何人もいた。私は、私より前にエルサレムにいただれよりも、多くの牛や羊を所有していた。'),
('JPN', '传道书', 21, 2, 8, '私はまた、自分のために銀や金、それに王たちの宝や諸州の宝も集めた。男女の歌い手を得、人の子らの快楽である、多くの側女を手に入れた。'),
('JPN', '传道书', 21, 2, 9, 'こうして私は偉大な者となった。私より前にエルサレムにいただれよりも。しかも、私の知恵は私のうちにとどまった。'),
('JPN', '传道书', 21, 2, 10, '自分の目の欲するものは何も拒まず、心の赴くままに、あらゆることを楽しんだ。実に私の心はどんな労苦も楽しんだ。これが、あらゆる労苦から受ける私の分であった。'),
('JPN', '传道书', 21, 2, 11, 'しかし、私は自分が手がけたあらゆる事業と、そのために骨折った労苦を振り返った。見よ。すべては空しく、風を追うようなものだ。日の下には何一つ益になるものはない。'),
('JPN', '传道书', 21, 2, 12, '私は振り返って、知恵と狂気と愚かさを見た。そもそも、王の跡を継ぐ者も、すでになされたことをするにすぎない。'),
('JPN', '传道书', 21, 2, 13, '私は見た。光が闇にまさっているように、知恵は愚かさにまさっていることを。'),
('JPN', '传道书', 21, 2, 14, '知恵のある者は頭に目があるが、愚かな者は闇の中を歩く。しかし私は、すべての者が同じ結末に行き着くことを知った。'),
('JPN', '传道书', 21, 2, 15, '私は心の中で言った。「私も愚かな者と同じ結末に行き着くのなら、なぜ、私は並外れて知恵ある者であったのか。」私は心の中で言った。「これもまた空しい」と。'),
('JPN', '传道书', 21, 2, 16, '事実、知恵のある者も愚かな者も、いつまでも記憶されることはない。日がたつと、一切は忘れられてしまう。なぜ、知恵のある者は愚かな者とともに死ぬのか。'),
('JPN', '传道书', 21, 2, 17, '私は生きていることを憎んだ。日の下で行われるわざは、私にとってはわざわいだからだ。確かに、すべては空しく、風を追うようなものだ。'),
('JPN', '传道书', 21, 2, 18, '私は、日の下で骨折った一切の労苦を憎んだ。跡を継ぐ者のために、それを残さなければならないからである。'),
('JPN', '传道书', 21, 2, 19, 'その者が知恵のある者か愚か者か、だれが知るだろうか。しかも、私が日の下で骨折り、知恵を使って行ったすべての労苦を、その者が支配するようになるのだ。これもまた空しい。'),
('JPN', '传道书', 21, 2, 20, '私は、日の下で骨折った一切の労苦を見回して、絶望した。'),
('JPN', '传道书', 21, 2, 21, 'なぜなら、どんなに人が知恵と知識と才能をもって労苦しても、何の労苦もしなかった者に、自分が受けた分を譲らなければならないからだ。これもまた空しく、大いに悪しきことだ。'),
('JPN', '传道书', 21, 2, 22, '実に、日の下で骨折った一切の労苦と思い煩いは、人にとって何なのだろう。'),
('JPN', '传道书', 21, 2, 23, 'その一生の間、その営みには悲痛と苛立ちがあり、その心は夜も休まらない。これもまた空しい。'),
('JPN', '传道书', 21, 2, 24, '人には、食べたり飲んだりして、自分の労苦に満足を見出すことよりほかに、何も良いことがない。そのようにすることもまた、神の御手によることであると分かった。'),
('JPN', '传道书', 21, 2, 25, '実に、神から離れて、だれが食べ、だれが楽しむことができるだろうか。'),
('JPN', '传道书', 21, 2, 26, 'なぜなら神は、ご自分が良しとする人には知恵と知識と喜びを与え、罪人には、神が良しとする人に渡すために、集めて蓄える仕事を与えられるからだ。これもまた空しく、風を追うようなものだ。'),
('JPN', '传道书', 21, 3, 1, 'すべてのことには定まった時期があり、天の下のすべての営みに時がある。'),
('JPN', '传道书', 21, 3, 2, '生まれるのに時があり、死ぬのに時がある。植えるのに時があり、植えた物を抜くのに時がある。'),
('JPN', '传道书', 21, 3, 3, '殺すのに時があり、癒やすのに時がある。崩すのに時があり、建てるのに時がある。'),
('JPN', '传道书', 21, 3, 4, '泣くのに時があり、笑うのに時がある。嘆くのに時があり、踊るのに時がある。'),
('JPN', '传道书', 21, 3, 5, '石を投げ捨てるのに時があり、石を集めるのに時がある。抱擁するのに時があり、抱擁をやめるのに時がある。'),
('JPN', '传道书', 21, 3, 6, '求めるのに時があり、あきらめるのに時がある。保つのに時があり、投げ捨てるのに時がある。'),
('JPN', '传道书', 21, 3, 7, '裂くのに時があり、縫うのに時がある。黙っているのに時があり、話すのに時がある。'),
('JPN', '传道书', 21, 3, 8, '愛するのに時があり、憎むのに時がある。戦いの時があり、平和の時がある。'),
('JPN', '传道书', 21, 3, 9, '働く者は労苦して何の益を得るだろうか。'),
('JPN', '传道书', 21, 3, 10, '私は、神が人の子らに従事するようにと与えられた仕事を見た。'),
('JPN', '传道书', 21, 3, 11, '神のなさることは、すべて時にかなって美しい。神はまた、人の心に永遠を与えられた。しかし人は、神が行うみわざの始まりから終わりまでを見極めることができない。'),
('JPN', '传道书', 21, 3, 12, '私は知った。人は生きている間に喜び楽しむほか、何も良いことがないのを。'),
('JPN', '传道书', 21, 3, 13, 'また、人がみな食べたり飲んだりして、すべての労苦の中に幸せを見出すことも、神の賜物であることを。'),
('JPN', '传道书', 21, 3, 14, '私は、神がなさることはすべて、永遠に変わらないことを知った。それに何かをつけ加えることも、それから何かを取り去ることもできない。人が神の御前で恐れるようになるため、神はそのようにされたのだ。'),
('JPN', '传道书', 21, 3, 15, '今あることは、すでにあったこと。これからあることも、すでにあったこと。追い求められてきたことを神はなおも求められる。'),
('JPN', '传道书', 21, 3, 16, '私はさらに日の下で、さばきの場に不正があり、正義の場に不正があるのを見た。'),
('JPN', '传道书', 21, 3, 17, '私は心の中で言った。「神は正しい人も悪しき者もさばく。そこでは、すべての営みとすべてのわざに、時があるからだ。」'),
('JPN', '传道书', 21, 3, 18, '私は心の中で人の子らについて言った。「神は彼らを試みて、自分たちが獣にすぎないことを、彼らが気づくようにされたのだ。」'),
('JPN', '传道书', 21, 3, 19, 'なぜなら、人の子の結末と獣の結末は同じ結末だからだ。これも死ねば、あれも死に、両方とも同じ息を持つ。それでは、人は獣にまさっているのか。まさってはいない。すべては空しいからだ。'),
('JPN', '传道书', 21, 3, 20, 'すべては同じ所に行く。すべてのものは土のちりから出て、すべてのものは土のちりに帰る。'),
('JPN', '传道书', 21, 3, 21, 'だれが知っているだろうか。人の子らの霊は上に昇り、獣の霊は地の下に降りて行くのを。'),
('JPN', '传道书', 21, 3, 22, '私は見た。人が自分のわざを楽しむことにまさる幸いはないことを。それが人の受ける分であるからだ。だれが、これから後に起こることを人に見せてくれるだろうか。'),
('JPN', '传道书', 21, 4, 1, '私は再び、日の下で行われる一切の虐げを見た。見よ、虐げられている者たちの涙を。しかし、彼らには慰める者がいない。彼らを虐げる者たちが権力をふるう。しかし、彼らには慰める者がいない。'),
('JPN', '传道书', 21, 4, 2, 'いのちがあって、生きながらえている人よりは、すでに死んだ死人に、私は祝いを申し上げる。'),
('JPN', '传道书', 21, 4, 3, 'また、この両者よりもっと良いのは、今までに存在しなかった者、日の下で行われる悪いわざを見なかった者だ。'),
('JPN', '传道书', 21, 4, 4, '私はまた、あらゆる労苦とあらゆる仕事の成功を見た。それは人間同士のねたみにすぎない。これもまた空しく、風を追うようなものだ。'),
('JPN', '传道书', 21, 4, 5, '愚かな者は腕組みをし、自分の身を食いつぶす。'),
('JPN', '传道书', 21, 4, 6, '片手に安らかさを満たすことは、両手に労苦を満たして風を追うのにまさる。'),
('JPN', '传道书', 21, 4, 7, '私は再び、日の下で空しいことを見た。'),
('JPN', '传道书', 21, 4, 8, 'ひとりぼっちで、仲間もなく、子も兄弟もいない人がいる。それでも彼の一切の労苦には終わりがなく、その目は富を求めて飽くことがない。そして「私はだれのために労苦し、楽しみもなく自分を犠牲にしているのか」とも言わない。これもまた空しく、辛い営みだ。'),
('JPN', '传道书', 21, 4, 9, '二人は一人よりもまさっている。二人の労苦には、良い報いがあるからだ。'),
('JPN', '传道书', 21, 4, 10, 'どちらかが倒れるときには、一人がその仲間を起こす。倒れても起こしてくれる者のいないひとりぼっちの人はかわいそうだ。'),
('JPN', '传道书', 21, 4, 11, 'また、二人が一緒に寝ると温かくなる。一人ではどうして温かくなるだろうか。'),
('JPN', '传道书', 21, 4, 12, '一人なら打ち負かされても、二人なら立ち向かえる。三つ撚りの糸は簡単には切れない。'),
('JPN', '传道书', 21, 4, 13, '貧しくても知恵のある若者は、忠告を受け入れなくなった年老いた愚かな王にまさる。'),
('JPN', '传道书', 21, 4, 14, 'そのような若者は、牢獄から出て王になる。たとえ、その王国で貧しく生まれた者であっても。'),
('JPN', '传道书', 21, 4, 15, '私は見た。日の下を歩む生きている者がみな、王に代わって立つ、後継の若者の側につくのを。'),
('JPN', '传道书', 21, 4, 16, 'その民すべてには終わりがない。彼を先にして続く人々には。後に来るその者たちも、後継の者を喜ばない。これもまた空しく、風を追うようなものだ。'),
('JPN', '传道书', 21, 5, 1, '神の宮へ行くときは、自分の足に気をつけよ。近くに行って聞くことは、愚かな者たちがいけにえを献げるのにまさる。彼らは自分たちが悪を行っていることを知らないからだ。'),
('JPN', '传道书', 21, 5, 2, '神の前では、軽々しく心焦ってことばを出すな。神は天におられ、あなたは地にいるからだ。だから、ことばを少なくせよ。'),
('JPN', '传道书', 21, 5, 3, '仕事が多ければ夢を見、ことばが多ければ愚かな者の声となる。'),
('JPN', '传道书', 21, 5, 4, '神に誓願を立てるときには、それを果たすのを遅らせてはならない。愚かな者は喜ばれない。誓ったことは果たせ。'),
('JPN', '传道书', 21, 5, 5, '誓って果たさないよりは、誓わないほうがよい。'),
('JPN', '传道书', 21, 5, 6, 'あなたの口が、あなた自身を罪に陥らせないようにせよ。使者の前で「あれは過失だ」と言ってはならない。神が、あなたの言うことを聞いて怒り、あなたの手のわざを滅ぼしてもよいだろうか。'),
('JPN', '传道书', 21, 5, 7, '夢が多く、ことばの多いところには空しさがある。ただ、神を恐れよ。'),
('JPN', '传道书', 21, 5, 8, 'ある州で、貧しい者が虐げられ、権利と正義が踏みにじられているのを見ても、そのことに驚いてはならない。その上役には、それを見張るもう一人の上役がいて、彼らよりももっと身分が高い者たちもいるからだ。'),
('JPN', '传道书', 21, 5, 9, '国にとっての何にもまさる利益は、農地が耕されるようにする王がいることである。'),
('JPN', '传道书', 21, 5, 10, '金銭を愛する者は金銭に満足しない。富を愛する者は収益に満足しない。これもまた空しい。'),
('JPN', '传道书', 21, 5, 11, '財産が増えると、寄食者も増える。持ち主にとって何の成功だろう。それを目で眺めているだけだ。'),
('JPN', '传道书', 21, 5, 12, '働く者は少し食べても多く食べても、心地よく眠る。富む者は満腹しても、安眠を妨げられる。'),
('JPN', '传道书', 21, 5, 13, '私は日の下に、痛ましいわざわいがあるのを見た。所有者に守られていた富が、その所有者自身に害を加えることだ。'),
('JPN', '传道书', 21, 5, 14, 'その富は不運な出来事で失われ、息子が生まれても、その者の手もとには何もない。'),
('JPN', '传道书', 21, 5, 15, '母の胎から出て来たときのように、裸で、来たときの姿で戻って行く。自分の労苦によって得る、自分の自由にすることのできるものを、何一つ持って行くことはない。'),
('JPN', '传道书', 21, 5, 16, 'これも痛ましいわざわいだ。出て来たときと全く同じように去って行く。風のために労苦して何の益になるだろうか。'),
('JPN', '传道书', 21, 5, 17, 'しかも、人は一生、闇の中で食事をする。多くの苛立ち、病気、そして激しい怒り。'),
('JPN', '传道书', 21, 5, 18, '見よ。私が良いと見たこと、好ましいこととは、こうだ。神がその人に与えたいのちの日数の間、日の下で骨折るすべての労苦にあって、良き物を楽しみ、食べたり飲んだりすることだ。これが人の受ける分なのだ。'),
('JPN', '传道书', 21, 5, 19, '実に神は、すべての人間に富と財を与えてこれを楽しむことを許し、各自が受ける分を受けて自分の労苦を喜ぶようにされた。これこそが神の賜物である。'),
('JPN', '传道书', 21, 5, 20, 'こういう人は、自分の生涯のことをあれこれ思い返さない。神が彼の心を喜びで満たされるからだ。'),
('JPN', '传道书', 21, 6, 1, '私が日の下で見た悪しきことがある。それは人の上に重くのしかかる。'),
('JPN', '传道书', 21, 6, 2, '神が富と財と誉れを与え、望むもので何一つ欠けることがない人がいる。しかし神は、この人がそれを楽しむことを許さず、見ず知らずの人がそれを楽しむようにされる。これは空しいこと、それは悪しき病だ。'),
('JPN', '传道书', 21, 6, 3, 'もし人が百人の子どもを持ち、多くの年月を生き、彼の年が多くなっても、彼が良き物に満足することなく、墓にも葬られなかったなら、私は言う。彼よりも死産の子のほうがましだと。'),
('JPN', '传道书', 21, 6, 4, 'その子は空しさの中に生まれて来て、闇の中に去って行き、その名は闇におおわれ、'),
('JPN', '传道书', 21, 6, 5, '日の光も見ず、何も知らない。しかし、この子のほうが彼よりは安らかだ。'),
('JPN', '传道书', 21, 6, 6, '彼が千年の倍も生きても、幸せな目にあわなければ。両者とも同じ所に行くではないか。'),
('JPN', '传道书', 21, 6, 7, '人の労苦はみな、自分の口のためである。しかし、その食欲は決して満たされない。'),
('JPN', '传道书', 21, 6, 8, '知恵のある者は、愚かな者より何がまさっているだろう。人の前でどう生きるかを知っている貧しい人も、何がまさっているだろうか。'),
('JPN', '传道书', 21, 6, 9, '目が見ることは、欲望のひとり歩きにまさる。これもまた空しく、風を追うようなものだ。'),
('JPN', '传道书', 21, 6, 10, '存在するようになったものは、すでにその名がつけられ、それが人間であることも知られている。その人は、自分より力のある者と言い争うことはできない。'),
('JPN', '传道书', 21, 6, 11, '多く語れば、それだけ空しさを増す。それは、人にとって何の益になるだろうか。'),
('JPN', '传道书', 21, 6, 12, 'だれが知るだろうか。影のように過ごす、空しい人生において、何が人のために良いことなのかを。だれが人に告げることができるだろうか。その人の後に、日の下で何が起こるかを。'),
('JPN', '传道书', 21, 7, 1, '名声は良い香油にまさり、死ぬ日は生まれる日にまさる。'),
('JPN', '传道书', 21, 7, 2, '祝宴の家に行くよりは、喪中の家に行くほうがよい。そこには、すべての人の終わりがあり、生きている者がそれを心に留めるようになるからだ。'),
('JPN', '传道书', 21, 7, 3, '悲しみは笑いにまさる。顔が曇ると心は良くなる。'),
('JPN', '传道书', 21, 7, 4, '知恵のある者の心は喪中の家にあり、愚かな者の心は楽しみの家にある。'),
('JPN', '传道书', 21, 7, 5, '知恵のある者の叱責を聞くのは、愚かな者の歌を聞くのにまさる。'),
('JPN', '传道书', 21, 7, 6, '愚かな者の笑いは、鍋の下の茨がはじける音のよう。これもまた空しい。'),
('JPN', '传道书', 21, 7, 7, '虐げは知恵のある者を狂わせ、賄賂は心を滅ぼす。'),
('JPN', '传道书', 21, 7, 8, '事の終わりは、その始まりにまさり、忍耐は、うぬぼれにまさる。'),
('JPN', '传道书', 21, 7, 9, '軽々しく心を苛立たせてはならない。苛立ちは愚かな者の胸にとどまるから。'),
('JPN', '传道书', 21, 7, 10, '「どうして、昔のほうが今より良かったのか」と言ってはならない。このような問いは、知恵によるのではない。'),
('JPN', '传道书', 21, 7, 11, '資産を伴う知恵は良い。日を見る人に益となる。'),
('JPN', '传道书', 21, 7, 12, '知恵の陰にいるのは、金銭の陰にいるようだ。知識の益は、知恵がその持ち主を生かすことにある。'),
('JPN', '传道书', 21, 7, 13, '神のみわざに目を留めよ。神が曲げたものをだれがまっすぐにできるだろうか。'),
('JPN', '传道书', 21, 7, 14, '順境の日には幸いを味わい、逆境の日にはよく考えよ。これもあれも、神のなさること。後のことを人に分からせないためである。'),
('JPN', '传道书', 21, 7, 15, '私はこの空しい人生において、すべてのことを見てきた。正しい人が正しいのに滅び、悪しき者が悪を行う中で長生きすることがある。'),
('JPN', '传道书', 21, 7, 16, 'あなたは正しすぎてはならない。自分を知恵のありすぎる者としてはならない。なぜ、あなたは自分を滅ぼそうとするのか。'),
('JPN', '传道书', 21, 7, 17, 'あなたは悪すぎてはいけない。愚かであってはいけない。時が来ないのに、なぜ死のうとするのか。'),
('JPN', '传道书', 21, 7, 18, '一つをつかみ、もう一つを手放さないのがよい。神を恐れる者は、この両方を持って出て行く。'),
('JPN', '传道书', 21, 7, 19, '知恵は町の十人の権力者よりも、知恵のある者を力づける。'),
('JPN', '传道书', 21, 7, 20, 'この地上に、正しい人は一人もいない。善を行い、罪に陥ることのない人は。'),
('JPN', '传道书', 21, 7, 21, 'また、人の語ることばをいちいち心に留めてはならない。しもべがあなたをののしるのを聞かないようにするために。'),
('JPN', '传道书', 21, 7, 22, 'あなた自身が他人を何度もののしったことを、あなたの心は知っているのだから。'),
('JPN', '传道书', 21, 7, 23, '私は、これらの一切を知恵によって試みた。私は言った。「私は知恵のある者になりたい」と。しかし、それは私には遠く及ばないことだった。'),
('JPN', '传道书', 21, 7, 24, '今までにあったことは、遠く、とても深い。だれがそれを見極めることができるだろうか。'),
('JPN', '传道书', 21, 7, 25, '私は心を転じて、知恵と道理を学び、探り出し、探し求めた。愚かさの悪と、狂気の愚かさを知ろうとした。'),
('JPN', '传道书', 21, 7, 26, '私は、女が死よりも苦々しいことに気がついた。女は罠であり、その心は網、その手は、かせである。神に良しとされる者は女から逃れるが、罪に陥る者は女に捕らえられる。'),
('JPN', '传道书', 21, 7, 27, '伝道者は言う。見よ。私が道理を見出そうとして、一つ一つに当たり、見出したことは次のとおりである。'),
('JPN', '传道书', 21, 7, 28, '私のたましいは、なおも探し求めたが、見出すことはなかった。私は千人のうちに、一人の男を見出したが、そのすべてのうちに、一人の女も見出さなかった。'),
('JPN', '传道书', 21, 7, 29, '私が見出した次のことだけに目を留めよ。神は人を真っ直ぐな者に造られたが、人は多くの理屈を探し求めたということだ。'),
('JPN', '传道书', 21, 8, 1, '知恵のある者とされるにふさわしいのはだれか。物事の解釈を知っているのはだれか。人の知恵は、その人の顔を輝かせ、その顔の固さを和らげる。'),
('JPN', '传道书', 21, 8, 2, '私は言う。王の命令を守れ。神への誓約があるから。'),
('JPN', '传道书', 21, 8, 3, '王の前から慌てて出て行くな。悪事に荷担するな。王は自分の望むままを行うから。'),
('JPN', '传道书', 21, 8, 4, '王のことばには権威がある。だれが、王に「何をするのか」と言えるだろうか。'),
('JPN', '传道书', 21, 8, 5, '命令を守る者はわざわいを知らない。知恵ある者の心は時とさばきを知っている。'),
('JPN', '传道书', 21, 8, 6, 'すべての営みには時とさばきがある。人に降りかかるわざわいは多い。'),
('JPN', '传道书', 21, 8, 7, '何が起こるかを知っている者はいない。いつ起こるかを、だれも告げることはできない。'),
('JPN', '传道书', 21, 8, 8, '風を支配し、風をとどめておくことのできる人はいない。死の日を支配することはできず、この戦いから免れる者はいない。そして、悪は悪の所有者を救い得ない。'),
('JPN', '传道书', 21, 8, 9, '私はこのすべてを見て、私の心を注いだ。日の下で行われる一切のわざについて、人が人を支配して、わざわいをもたらす時について。'),
('JPN', '传道书', 21, 8, 10, 'すると私は、悪しき者たちが葬られて去って行くのを見た。彼らは、聖なる方のところから離れ去り、わざを行ったその町で忘れられる。これもまた空しい。'),
('JPN', '传道书', 21, 8, 11, '悪い行いに対する宣告がすぐ下されないので、人の子らの心は、悪を行う思いで満ちている。'),
('JPN', '传道书', 21, 8, 12, '悪を百回行っても、罪人は長生きしている。しかし私は、神を恐れる者が神の御前で恐れ、幸せであることを知っている。'),
('JPN', '传道书', 21, 8, 13, '悪しき者には幸せがない。その生涯を影のように長くすることはできない。彼らが神の御前で恐れないからだ。'),
('JPN', '传道书', 21, 8, 14, '空しいことが地上で行われている。悪しき者の行いに対する報いを受ける正しい人もいれば、正しい人の行いに対する報いを受ける悪しき者もいる。私は言う。「これもまた空しい」と。'),
('JPN', '传道书', 21, 8, 15, 'だから私は快楽を賛美する。日の下では、食べて飲んで楽しむよりほかに、人にとっての幸いはない。これは、神が日の下で人に与える一生の間に、その労苦に添えてくださるものだ。'),
('JPN', '传道书', 21, 8, 16, '私が昼も夜も眠らずに知恵を知り、地上で行われる人の営みを見ようと心に決めたとき、'),
('JPN', '传道书', 21, 8, 17, 'すべては神のみわざであることが分かった。人は日の下で行われるみわざを見極めることはできない。人は労苦して探し求めても、見出すことはない。知恵のある者が知っていると思っても、見極めることはできない。'),
('JPN', '传道书', 21, 9, 1, 'まことに、私はこの一切を心に留め、このことすべてを調べた。正しい人も、知恵のある者も、彼らの働きも、神の御手の中にある。彼らの前にあるすべてのものが、それが愛なのか、憎しみなのか、人には分からない。'),
('JPN', '传道书', 21, 9, 2, 'すべてのことは、すべての人に同じように起こる。同じ結末が、正しい人にも、悪しき者にも、善人にも、きよい人にも、汚れた人にも、いけにえを献げる人にも、いけにえを献げない人にも来る。善人にも、罪人にも同様で、誓う者にも、誓うのを恐れる者にも同様だ。'),
('JPN', '传道书', 21, 9, 3, '日の下で行われることすべてのうちで最も悪いことは、同じ結末がすべての人に臨むということ。そのうえ、人の子らの心が悪に満ち、生きている間は彼らの心に狂気があり、その後で死人のところに行くということだ。'),
('JPN', '传道书', 21, 9, 4, 'しかし、人には拠り所がある。生ける者すべてのうちに数えられている者には。生きている犬は死んだ獅子にまさるのだ。'),
('JPN', '传道书', 21, 9, 5, '生きている者は自分が死ぬことを知っているが、死んだ者は何も知らない。彼らには、もはや何の報いもなく、まことに呼び名さえも忘れられる。'),
('JPN', '传道书', 21, 9, 6, '彼らの愛も憎しみも、ねたみもすでに消え失せ、日の下で行われることすべてにおいて、彼らには、もはや永遠に受ける分はない。'),
('JPN', '传道书', 21, 9, 7, 'さあ、あなたのパンを楽しんで食べ、陽気にあなたのぶどう酒を飲め。神はすでに、あなたのわざを喜んでおられる。'),
('JPN', '传道书', 21, 9, 8, 'いつもあなたは白い衣を着よ。頭には油を絶やしてはならない。'),
('JPN', '传道书', 21, 9, 9, 'あなたの空しい人生の間、あなたの愛する妻と生活を楽しむがよい。彼女は、あなたの空しい日々の間、日の下であなたに与えられた者だ。それが、生きている間に、日の下でする労苦から受けるあなたの分なのだ。'),
('JPN', '传道书', 21, 9, 10, 'あなたの手がなし得ると分かったことはすべて、自分の力でそれをせよ。あなたが行こうとしているよみには、わざも道理も知識も知恵もないからだ。'),
('JPN', '传道书', 21, 9, 11, '私は再び、日の下を見た。競走は足の速い人のものではなく、戦いは勇士のものではない。パンは知恵のある人のものではなく、富は悟りのある人のものではなく、愛顧は知識のある人のものではない。すべての人が時と機会に出会うからだ。'),
('JPN', '传道书', 21, 9, 12, 'しかも、人は自分の時を知らない。悪い網にかかった魚のように、罠にかかった鳥のように、人の子らも、わざわいの時が突然彼らを襲うと罠にかかる。'),
('JPN', '传道书', 21, 9, 13, '私はまた、知恵について、日の下でこのようなことを見た。それは私にとって大きなことであった。'),
('JPN', '传道书', 21, 9, 14, 'わずかの人々が住む小さな町があった。そこに大王が攻めて来て包囲し、それに対して大きな土塁を築いた。'),
('JPN', '传道书', 21, 9, 15, 'その町に、貧しい一人の知恵ある者がいて、自分の知恵を用いてその町を救った。しかし、だれもその貧しい人を記憶にとどめなかった。'),
('JPN', '传道书', 21, 9, 16, '私は言う。「知恵は力にまさる。しかし、貧しい者の知恵は蔑まれ、その人のことばは聞かれない」と。'),
('JPN', '传道书', 21, 9, 17, '知恵のある者の静かなことばは、愚かな者の間での支配者の叫びよりもよく聞かれる。'),
('JPN', '传道书', 21, 9, 18, '知恵は武器にまさり、一人の罪人は多くの良いことを打ち壊す。'),
('JPN', '传道书', 21, 10, 1, '死んだハエは、調香師の香油を臭くし、腐らせる。少しの愚かさは、知恵や栄誉よりも重い。'),
('JPN', '传道书', 21, 10, 2, '知恵のある者の心は右を向き、愚かな者の心は左を向く。'),
('JPN', '传道书', 21, 10, 3, '愚か者は、道を行くときにも思慮に欠け、自分が愚かであることを、皆に言いふらす。'),
('JPN', '传道书', 21, 10, 4, '支配者があなたに向かって立腹しても、あなたはその場を離れてはならない。冷静でいれば、大きな罪は離れて行くから。'),
('JPN', '传道书', 21, 10, 5, '私は、日の下に一つの悪があるのを見た。それは、権力者から出る過失のようなもの。'),
('JPN', '传道书', 21, 10, 6, '愚か者が非常に高い位につけられ、富む者が低い席に座しているのを、'),
('JPN', '传道书', 21, 10, 7, 'また、奴隷たちが馬に乗り、君主たちが奴隷のように地を歩くのを、私は見た。'),
('JPN', '传道书', 21, 10, 8, '穴を掘る者は自らそこに落ち、石垣を崩す者は蛇にかまれる。'),
('JPN', '传道书', 21, 10, 9, '石を切り出す者は石で傷つき、木を割る者は木で危険にさらされる。'),
('JPN', '传道书', 21, 10, 10, '斧が鈍くなったときは、刃を研がないならば、もっと力がいる。しかし、知恵は人を成功させるのに益になる。'),
('JPN', '传道书', 21, 10, 11, 'もし蛇がまじないにかからず、かみつくならば、それは蛇使いに何の益にもならない。'),
('JPN', '传道书', 21, 10, 12, '知恵のある者が口にすることばは恵み深く、愚かな者の唇は自分自身を吞み込む。'),
('JPN', '传道书', 21, 10, 13, '彼が口にすることばの始まりは、愚かなこと、彼の口の終わりは、悪しき狂気。'),
('JPN', '传道书', 21, 10, 14, '愚か者はよくしゃべる。人はこれから起こることを知らない。これから後に起こることを、だれが彼に告げることができるだろうか。'),
('JPN', '传道书', 21, 10, 15, '愚かな者の労苦は、自分自身を疲れさせる。彼は町に行く道さえ知らない。'),
('JPN', '传道书', 21, 10, 16, 'わざわいなことよ、あなたのような国は。王が若輩で、高官たちが朝からぜいたくな食事をする国は。'),
('JPN', '传道书', 21, 10, 17, '幸いなことよ、あなたのような国は。王が貴族の出であり、高官たちが、酔うためではなく力をつけるために、定まった時に食事をする国は。'),
('JPN', '传道书', 21, 10, 18, '怠けていると天井が落ち、手をこまねいていると雨漏りがする。'),
('JPN', '传道书', 21, 10, 19, 'パンを作るのは笑うため。ぶどう酒は人生を楽しませる。金銭はすべての必要に応じる。'),
('JPN', '传道书', 21, 10, 20, '心の中でさえ、王を呪ってはならない。寝室でも、富む者を呪ってはならない。なぜなら、空の鳥がその声を運び、翼のあるものがそのことを告げるからだ。'),
('JPN', '传道书', 21, 11, 1, 'あなたのパンを水の上に投げよ。ずっと後の日になって、あなたはそれを見出す。'),
('JPN', '传道书', 21, 11, 2, 'あなたの受ける分を七、八人に分けておけ。地上でどんなわざわいが起こるかをあなたは知らないのだから。'),
('JPN', '传道书', 21, 11, 3, '濃い雲が雨で満ちると、それは地上に降り注ぐ。木が南風や北風で倒れると、その木は倒れた場所にそのまま横たわる。'),
('JPN', '传道书', 21, 11, 4, '風を警戒している人は種を蒔かない。雨雲を見ている人は刈り入れをしない。'),
('JPN', '传道书', 21, 11, 5, 'あなたは妊婦の胎内の骨々のことと同様に、風の道がどのようなものかを知らない。そのように、あなたは一切を行われる神のみわざを知らない。'),
('JPN', '传道书', 21, 11, 6, '朝にあなたの種を蒔け。夕方にも手を休めてはいけない。あなたは、あれかこれかどちらが成功するのか、あるいは両方とも同じようにうまくいくのかを知らないのだから。'),
('JPN', '传道书', 21, 11, 7, '光は心地よく、日を見ることは目に快い。'),
('JPN', '传道书', 21, 11, 8, '人は長い年月を生きるなら、ずっと楽しむがよい。だが、闇の日も多くあることを忘れてはならない。すべて、起こることは空しい。'),
('JPN', '传道书', 21, 11, 9, '若い男よ、若いうちに楽しめ。若い日にあなたの心を喜ばせよ。あなたは、自分の思う道を、また自分の目の見るとおりに歩め。しかし、神がこれらすべてのことにおいて、あなたをさばきに連れて行くことを知っておけ。'),
('JPN', '传道书', 21, 11, 10, 'あなたの心から苛立ちを除け。あなたのからだから痛みを取り去れ。若さも青春も空しいからだ。'),
('JPN', '传道书', 21, 12, 1, 'あなたの若い日に、あなたの創造者を覚えよ。わざわいの日が来ないうちに、また「何の喜びもない」と言う年月が近づく前に。'),
('JPN', '传道书', 21, 12, 2, '太陽と光、月と星が暗くなる前に、また雨の後に雨雲が戻って来る前に。'),
('JPN', '传道书', 21, 12, 3, 'その日、家を守る者たちは震え、力のある男たちは身をかがめ、粉をひく女たちは少なくなって仕事をやめ、窓から眺めている女たちの目は暗くなる。'),
('JPN', '传道书', 21, 12, 4, '通りの扉は閉ざされ、臼をひく音もかすかになり、人は鳥の声に起き上がり、歌を歌う娘たちはみな、うなだれる。'),
('JPN', '传道书', 21, 12, 5, '人々はまた高いところを恐れ、道でおびえる。アーモンドの花は咲き、バッタは足取り重く歩き、風鳥木は花を開く。人はその永遠の家に向かって行き、嘆く者たちが通りを歩き回る。'),
('JPN', '传道书', 21, 12, 6, 'こうしてついに銀のひもは切れ、金の器は打ち砕かれ、水がめは泉の傍らで砕かれて、滑車が井戸のそばで壊される。'),
('JPN', '传道书', 21, 12, 7, '土のちりは元あったように地に帰り、霊はこれを与えた神に帰る。'),
('JPN', '传道书', 21, 12, 8, '空の空。伝道者は言う。すべては空。'),
('JPN', '传道书', 21, 12, 9, '伝道者は知恵ある者であった。そのうえ、知識を民に教えた。彼は思索し、探究し、多くの箴言をまとめた。'),
('JPN', '传道书', 21, 12, 10, '伝道者は適切なことばを探し求め、真理のことばをまっすぐに書き記した。'),
('JPN', '传道书', 21, 12, 11, '知恵のある者たちのことばは突き棒のようなもの、それらが編纂された書はよく打ち付けられた釘のようなもの。これらは一人の牧者によって与えられた。'),
('JPN', '传道书', 21, 12, 12, 'わが子よ、さらに次のことにも気をつけよ。多くの書物を書くのはきりがない。学びに没頭すると、からだが疲れる。'),
('JPN', '传道书', 21, 12, 13, '結局のところ、もうすべてが聞かされていることだ。神を恐れよ。神の命令を守れ。これが人間にとってすべてである。'),
('JPN', '传道书', 21, 12, 14, '神は、善であれ悪であれ、あらゆる隠れたことについて、すべてのわざをさばかれるからである。'),
('JPN', '雅歌', 22, 1, 1, 'ソロモンの雅歌'),
('JPN', '雅歌', 22, 1, 2, 'あの方が私に口づけしてくださったらよいのに。あなたの愛は、ぶどう酒にまさって麗しく、'),
('JPN', '雅歌', 22, 1, 3, 'あなたの香油は香り芳しく、あなたの名は、注がれた香油のよう。そのため、おとめたちはあなたを愛しています。'),
('JPN', '雅歌', 22, 1, 4, '私を引き寄せてください。私たちはあなたの後から急いで参ります。王は私を奥の間に伴われました。私たちはあなたにあって楽しみ喜び、あなたの愛をぶどう酒にまさってほめたたえます。あなたは心から愛されています。'),
('JPN', '雅歌', 22, 1, 5, 'エルサレムの娘たち。ケダルの天幕のように、ソロモンの幕のように、私は黒いけれども美しい。'),
('JPN', '雅歌', 22, 1, 6, 'あなたがたは私を見ないでください。私は日に焼けて、浅黒いのです。母の息子たちが私に怒りを燃やし、私を彼らのぶどう畑の番人にしたのです。でも、私は自分のぶどう畑の番はしませんでした。'),
('JPN', '雅歌', 22, 1, 7, '私のたましいの恋い慕う方。どうか私に教えてください。どこで羊を飼っておられるのですか。昼の間は、どこでそれを休ませるのですか。なぜ、私はあなたの仲間の羊の群れの傍らで、顔覆いをつけた女のようにしていなければならないのでしょう。'),
('JPN', '雅歌', 22, 1, 8, '女の中で最も美しいひとよ。あなたが知らないのなら、羊の群れの足跡を追って出て行き、羊飼いたちの住まいの傍らで、あなたの子やぎを飼いなさい。'),
('JPN', '雅歌', 22, 1, 9, 'わが愛する者よ。私はあなたをファラオの戦車の間にいる雌馬になぞらえよう。'),
('JPN', '雅歌', 22, 1, 10, '飾り輪のあるあなたの頬は美しい。宝石の首飾りがかけられたあなたの首も。'),
('JPN', '雅歌', 22, 1, 11, '私たちは金の飾り輪をあなたのために作ろう。そこに銀をちりばめて。'),
('JPN', '雅歌', 22, 1, 12, '王が長椅子に座っておられる間、私のナルドは香りを放っていました。'),
('JPN', '雅歌', 22, 1, 13, '私の愛する方は、私にとって、私の乳房の間に宿る没薬の袋。'),
('JPN', '雅歌', 22, 1, 14, '私の愛する方は、私にとって、エン・ゲディのぶどう畑にあるヘンナ樹の花房。'),
('JPN', '雅歌', 22, 1, 15, 'ああ、あなたは美しい。わが愛する者よ。ああ、あなたは美しい。あなたの目は鳩。'),
('JPN', '雅歌', 22, 1, 16, '私の愛する方。ああ、あなたはなんと美しく、慕わしい方。私たちの寝床も青々としています。'),
('JPN', '雅歌', 22, 1, 17, '私たちの家の梁は杉の木、私たちの垂木は糸杉。'),
('JPN', '雅歌', 22, 2, 1, '私はシャロンのばら、谷間のゆり。'),
('JPN', '雅歌', 22, 2, 2, 'わが愛する者が娘たちの間にいるのは、茨の中のゆりの花のようだ。'),
('JPN', '雅歌', 22, 2, 3, '私の愛する方が若者たちの間におられるのは、林の木々の中のりんごの木のようです。その木陰に私は心地よく座り、その実は私の口に甘いのです。'),
('JPN', '雅歌', 22, 2, 4, 'あの方は私を酒宴の席に伴ってくださいました。私の上に翻る、あの方の旗じるしは愛でした。'),
('JPN', '雅歌', 22, 2, 5, '干しぶどうの菓子で私を力づけ、りんごで元気づけてください。私は愛に病んでいるからです。'),
('JPN', '雅歌', 22, 2, 6, 'ああ、あの方の左の腕が私の頭の下にあって、右の腕が私を抱いてくださるとよいのに。'),
('JPN', '雅歌', 22, 2, 7, 'エルサレムの娘たち。私は、かもしかや野の雌鹿にかけてお願いします。揺り起こしたり、かき立てたりしないでください。愛がそうしたいと思うときまでは。'),
('JPN', '雅歌', 22, 2, 8, '私の愛する方の声がする。ほら、あの方が来られる。山を跳び越え、丘の上を跳ねて。'),
('JPN', '雅歌', 22, 2, 9, '私の愛する方は、かもしかや若い鹿のようです。ほら、あの方は私たちの壁の向こうでじっと立ち、窓からうかがい、格子越しに見ています。'),
('JPN', '雅歌', 22, 2, 10, '私の愛する方は、私に語りかけて言われます。「わが愛する者、私の美しいひとよ。さあ立って、出ておいで。'),
('JPN', '雅歌', 22, 2, 11, 'ご覧、冬は去り、雨も過ぎて行ったから。'),
('JPN', '雅歌', 22, 2, 12, '地には花が咲き乱れ、刈り入れの季節がやって来て、山鳩の声が、私たちの国中に聞こえる。'),
('JPN', '雅歌', 22, 2, 13, 'いちじくの木は実をならせ、ぶどうの木は花をつけて香りを放つ。わが愛する者、私の美しいひとよ。さあ立って、出ておいで。'),
('JPN', '雅歌', 22, 2, 14, '岩の裂け目、崖の隠れ場にいる私の鳩よ。私に顔を見せておくれ。あなたの声を聞かせておくれ。あなたの声は心地よく、あなたの顔は愛らしい。」'),
('JPN', '雅歌', 22, 2, 15, '私たちのために、あなたがたは狐を捕らえてください。ぶどう畑を荒らす小狐を。私たちのぶどう畑は花盛りですから。'),
('JPN', '雅歌', 22, 2, 16, '私の愛する方は私のもの。私はあの方のもの。あの方はゆりの花の間で群れを飼っています。'),
('JPN', '雅歌', 22, 2, 17, '私の愛する方よ。そよ風が吹き始め、影が逃げ去るまでに、あなたは戻って来て、険しい山々の上のかもしかや若い鹿のようになってください。'),
('JPN', '雅歌', 22, 3, 1, '私は夜、床についていても、私のたましいの恋い慕う方を捜していました。私が捜しても、あの方は見つかりませんでした。'),
('JPN', '雅歌', 22, 3, 2, '「さあ、起きて町を行き巡り、通りや広場で、私のたましいの恋い慕う方を捜して来よう。」私が捜しても、あの方は見つかりませんでした。'),
('JPN', '雅歌', 22, 3, 3, '町を行き巡る夜回りたちが私を見つけました。「私のたましいの恋い慕う方を、お見かけになりませんでしたか。」'),
('JPN', '雅歌', 22, 3, 4, '私は彼らのところを通り過ぎると間もなく、私のたましいの恋い慕う方を見つけました。私はこの方をしっかり捕まえて放さず、ついには私の母の家に、私を身ごもった人の奥の間に、お連れしました。'),
('JPN', '雅歌', 22, 3, 5, 'エルサレムの娘たち。私は、かもしかや野の雌鹿にかけてお願いします。揺り起こしたり、かき立てたりしないでください。愛がそうしたいと思うときまでは。'),
('JPN', '雅歌', 22, 3, 6, '煙の柱のように荒野から上って来るのは何だろう。没薬や乳香、隊商のあらゆる香料の粉末をくゆらせて来るのは。'),
('JPN', '雅歌', 22, 3, 7, '見よ、あれはソロモンの乗る輿。周りには、イスラエルの勇士の六十人衆がいる。'),
('JPN', '雅歌', 22, 3, 8, '彼らはみな剣を帯びた練達の戦士。それぞれ腰に剣を帯びて夜襲に備える。'),
('JPN', '雅歌', 22, 3, 9, 'ソロモン王は、レバノンの木で自分のために駕籠を作った。'),
('JPN', '雅歌', 22, 3, 10, 'その支柱は銀、背は金、座席は紫布で作り、内側には、エルサレムの娘たちの愛の切りばめ細工が施されている。'),
('JPN', '雅歌', 22, 3, 11, 'シオンの娘たち。ソロモン王を見に出かけなさい。王は、ご自分の婚礼の日、心の喜びの日に、母がかぶらせた冠をかぶっている。'),
('JPN', '雅歌', 22, 4, 1, 'ああ、あなたは美しい。わが愛する者よ。ああ、あなたは美しい。あなたの目は、ベールの向こうの鳩。髪は、ギルアデの山を下って来るやぎの群れのようだ。'),
('JPN', '雅歌', 22, 4, 2, '歯は、洗い場から上って来た、毛を刈られた雌羊の群れのよう。それはみな双子で、一方を失ったものはそれらの中にはいない。'),
('JPN', '雅歌', 22, 4, 3, '唇は紅の糸のようで、口は愛らしい。頬はベールの向こうで、ざくろの片割れのようだ。'),
('JPN', '雅歌', 22, 4, 4, '首は、兵器倉として建てられたダビデのやぐらのよう。その上には千の盾が掛けられ、すべて勇士の丸い小盾だ。'),
('JPN', '雅歌', 22, 4, 5, '二つの乳房は、ゆりの花の間で草を食べている双子のかもしか、二匹の子鹿のようだ。'),
('JPN', '雅歌', 22, 4, 6, 'そよ風が吹き始め、影が逃げ去るまでに、私は没薬の山、乳香の丘に行こう。'),
('JPN', '雅歌', 22, 4, 7, 'わが愛する者よ。あなたのすべては美しく、あなたには何の汚れもない。'),
('JPN', '雅歌', 22, 4, 8, '花嫁よ。私と一緒にレバノンから、私と一緒にレバノンから来ておくれ。アマナの頂から、セニルの頂、ヘルモンの頂から、獅子の洞穴、豹の山から下りて来ておくれ。'),
('JPN', '雅歌', 22, 4, 9, 'あなたは私の心を奪った。私の妹、花嫁よ。あなたは私の心を奪った。ただ一度のまなざしと、首飾りのただ一つの宝石で。'),
('JPN', '雅歌', 22, 4, 10, '私の妹、花嫁よ。あなたの愛は、ぶどう酒にまさって麗しく、あなたの香油の香りは、すべての香料にまさっている。'),
('JPN', '雅歌', 22, 4, 11, '花嫁よ。あなたの唇は蜂蜜を滴らせ、舌の裏には蜜と乳がある。衣の香りは、レバノンの香りのようだ。'),
('JPN', '雅歌', 22, 4, 12, '私の妹、花嫁は、閉じられた庭、閉じられた源、封じられた泉。'),
('JPN', '雅歌', 22, 4, 13, 'あなたの産み出すものは、最上の実を実らせるざくろの園、ナルドとともにヘンナ樹、'),
('JPN', '雅歌', 22, 4, 14, 'ナルドとサフラン、菖蒲とシナモンに、乳香の採れるすべての木、没薬とアロエに、香料の最上のものすべて、'),
('JPN', '雅歌', 22, 4, 15, '庭の泉、湧き水の井戸、レバノンからの流れ。'),
('JPN', '雅歌', 22, 4, 16, '北風よ、起きなさい。南風よ、吹きなさい。私の庭に吹いて、その香りを漂わせておくれ。私の愛する方が庭に入って、その最上の実を食べることができるように。'),
('JPN', '雅歌', 22, 5, 1, 'わが妹、花嫁よ、私は私の庭に入った。私の没薬を、私の香料とともに集め、私の蜂の巣を、私の蜂蜜とともに食べ、私のぶどう酒を、私の乳とともに飲んだ。食べよ。友たちよ、飲め。愛に酔え。'),
('JPN', '雅歌', 22, 5, 2, '私は眠っていましたが、心は目覚めていました。すると声がしました。私の愛する方が戸をたたいています。「わが妹、わが愛する者よ。私の鳩よ。汚れのないひとよ。戸を開けておくれ。私の頭は露にぬれ、髪の毛も夜のしずくでぬれているので。」'),
('JPN', '雅歌', 22, 5, 3, '私は衣を脱いでしまいました。どうして、また着られるでしょう。足も洗ってしまいました。どうして、また汚せるでしょう。'),
('JPN', '雅歌', 22, 5, 4, '私の愛する方が、戸の穴あたりに手を差し入れ、私の胸は、あの方のゆえにときめきました。'),
('JPN', '雅歌', 22, 5, 5, '私は起きて、私の愛する方のために戸を開けようとしました。私の手から没薬が滴り、私の指から没薬の液がかんぬきの取っ手に流れ落ちました。'),
('JPN', '雅歌', 22, 5, 6, '愛する方のために戸を開けると、愛する方は、背を向けて去って行きました。私は、あの方のことばで気を失うばかりでした。あの方を捜しても、見つけることができませんでした。あの方を呼んでも、あの方は答えられませんでした。'),
('JPN', '雅歌', 22, 5, 7, '町を巡回している夜回りたちが私を見つけて、私を打ち、傷つけました。城壁を守る者たちも、私のかぶり物をはぎ取りました。'),
('JPN', '雅歌', 22, 5, 8, 'エルサレムの娘たち。あなたがたにお願いします。私の愛する方を見つけたら、あの方に言ってください。私は愛に病んでいる、と。'),
('JPN', '雅歌', 22, 5, 9, 'あなたの愛する方は、ほかの親しい者たちより何がまさっているのですか。女の中で最も美しいひとよ。あなたの愛する方は、ほかの親しい者たちより何がまさっているのですか。あなたがそのように私たちに切に願うとは。'),
('JPN', '雅歌', 22, 5, 10, '私の愛する方は、輝いて赤く、万人に抜きん出ています。'),
('JPN', '雅歌', 22, 5, 11, 'その頭は純金。髪はなつめ椰子の枝で、烏のように黒く、'),
('JPN', '雅歌', 22, 5, 12, '目は乳で洗われ、池のほとりに住む、水の流れのそばの鳩のよう。'),
('JPN', '雅歌', 22, 5, 13, '頬は香料の花壇のようで、良い香りを放つ。唇はゆりの花。没薬の液を滴らせる。'),
('JPN', '雅歌', 22, 5, 14, '腕は金の棒でタルシシュの宝石がはめ込まれ、からだは象牙の細工でサファイアでおおわれている。'),
('JPN', '雅歌', 22, 5, 15, '足は大理石の柱で、純金の台座に据えられている。その姿はレバノンのよう。その杉の木のようにすばらしい。'),
('JPN', '雅歌', 22, 5, 16, 'その口は甘美そのもの。あの方のすべてがいとしい。これが私の愛する方、これが私の恋人です。エルサレムの娘たちよ。'),
('JPN', '雅歌', 22, 6, 1, 'あなたの愛する方はどこへ行かれたのでしょう。女の中で最も美しいひとよ。あなたの愛する方はどこへ向かわれたのでしょう。私たちも、あなたと一緒に捜しましょう。'),
('JPN', '雅歌', 22, 6, 2, '私の愛する方は、自分の庭へ、香料の花壇へ下って行かれました。園の中で群れを飼うために、ゆりの花を摘むために。'),
('JPN', '雅歌', 22, 6, 3, '私は、私の愛する方のもの。私の愛する方は私のもの。あの方はゆりの花の間で群れを飼っています。'),
('JPN', '雅歌', 22, 6, 4, 'わが愛する者よ。あなたはティルツァのように美しい。あなたはエルサレムのように愛らしい。だが、旗を掲げた軍勢のように恐れられる。'),
('JPN', '雅歌', 22, 6, 5, 'あなたの目を私からそらしておくれ。それが私を引きつける。あなたの髪は、ギルアデから下って来るやぎの群れのようだ。'),
('JPN', '雅歌', 22, 6, 6, '歯は、洗い場から上って来た雌羊の群れのよう。それはみな双子で、一方を失ったものはそれらの中にはいない。'),
('JPN', '雅歌', 22, 6, 7, '頬はベールの向こうで、ざくろの片割れのようだ。'),
('JPN', '雅歌', 22, 6, 8, '王妃は六十人、側女は八十人、おとめたちは数知れない。'),
('JPN', '雅歌', 22, 6, 9, '汚れのないひと、私の鳩はただ一人。彼女は、母にはひとり子、産んだ者にはまばゆい存在。娘たちは彼女を見て、幸いだと言い、王妃たち、側女たちも見て、彼女をほめた。'),
('JPN', '雅歌', 22, 6, 10, '「このひとはだれでしょう。暁のように見下ろし、月のように美しく、太陽のように明るく、旗を掲げた軍勢のように恐ろしい。」'),
('JPN', '雅歌', 22, 6, 11, '私はくるみの木の庭へ下って行きました。谷の新緑を見るために。ぶどうの木が芽を出したか、ざくろの花が咲いたかを見るために。'),
('JPN', '雅歌', 22, 6, 12, '気づいたら、私は民の高貴な人の車に乗せられていました。'),
('JPN', '雅歌', 22, 6, 13, '帰りなさい、帰りなさい。シュラムの女よ。帰りなさい、帰りなさい。私たちがあなたを見ることができるように。どうしてあなたがたはシュラムの女を見るのか。二つの陣の舞のように。'),
('JPN', '雅歌', 22, 7, 1, 'なんと美しいことか。高貴な人の娘よ、サンダルをはいたあなたの足は。あなたのももの丸みは飾りのようで、名人の手のわざだ。'),
('JPN', '雅歌', 22, 7, 2, 'ほぞは丸い杯。混ぜ合わせたぶどう酒は尽きない。腹は小麦色の山。ゆりの花で囲まれている。'),
('JPN', '雅歌', 22, 7, 3, '二つの乳房は、二匹の子鹿、双子のかもしかのようだ。'),
('JPN', '雅歌', 22, 7, 4, '首は象牙のやぐらのようで、目は、バテ・ラビムの門のそばのヘシュボンの池。鼻は、ダマスコの方を見張るレバノンのやぐらのようだ。'),
('JPN', '雅歌', 22, 7, 5, '頭はカルメル山のようにそびえ、髪の毛は紫の羊毛のよう。王はそのふさふさした髪のとりこになった。'),
('JPN', '雅歌', 22, 7, 6, 'ああ、人を喜ばせる愛よ。あなたはなんと美しく、麗しいことよ。'),
('JPN', '雅歌', 22, 7, 7, 'あなたの背たけはなつめ椰子の木のよう、乳房はその実の房のようだ。'),
('JPN', '雅歌', 22, 7, 8, '私は言った。「なつめ椰子の木に登り、その枝をつかみたい。あなたの乳房はぶどうの房のようであれ。息の香りはりんごのようであれ。'),
('JPN', '雅歌', 22, 7, 9, 'あなたの口は最良のぶどう酒のようであれ。」そのぶどう酒は、私の愛する方に滑らかに流れ、眠っている者たちの唇に流れる。'),
('JPN', '雅歌', 22, 7, 10, '私は、私の愛する方のもの。あの方は私を恋い慕う。'),
('JPN', '雅歌', 22, 7, 11, 'さあ、私の愛する方よ。私たちは野に出て行って、村で夜を過ごしましょう。'),
('JPN', '雅歌', 22, 7, 12, '私たちは朝早くからぶどう畑に行き、ぶどうの木が芽を出したか、ぶどうの木が花を咲かせたか、ざくろの花が咲いたかどうかを見ましょう。そこで私は、私の愛をあなたにささげます。'),
('JPN', '雅歌', 22, 7, 13, '恋なすびは香りを放ち、私たちの門のそばには、すべての最上の果物があります。新しいものも、古いものも。私の愛する方よ、これはあなたのために蓄えておいたものです。'),
('JPN', '雅歌', 22, 8, 1, 'ああ、もし、あなたが私の母の乳房を吸った私の兄弟のようであったなら、私が外であなたに会ってあなたに口づけしても、だれも私を蔑まないでしょうに。'),
('JPN', '雅歌', 22, 8, 2, '私はあなたを導いて、私を育ててくれた私の母の家にお連れして、香料を混ぜたぶどう酒、ざくろの果汁をあなたに飲ませて差し上げましょう。'),
('JPN', '雅歌', 22, 8, 3, 'ああ、あの方の左の腕が私の頭の下にあって、右の腕が私を抱いてくださるとよいのに。'),
('JPN', '雅歌', 22, 8, 4, 'エルサレムの娘たち。私はあなたがたにお願いします。揺り起こしたり、かき立てたりしないでください。愛がそうしたいと思うときまでは。'),
('JPN', '雅歌', 22, 8, 5, '自分の愛する方に寄りかかって、荒野から上って来る女の人はだれでしょう。私はりんごの木の下であなたの目を覚まさせた。そこは、あなたの母があなたのために産みの苦しみをした所。そこは、あなたを産んだ人が産みの苦しみをした所。'),
('JPN', '雅歌', 22, 8, 6, '封印のように、私をあなたの胸に、封印のように、あなたの腕に押印してください。愛は死のように強く、ねたみはよみのように激しいからです。その炎は火の炎、すさまじい炎です。'),
('JPN', '雅歌', 22, 8, 7, '大水もその愛を消すことができません。奔流もそれを押し流すことができません。もし、人が愛を得ようとして自分の財産をことごとく与えたなら、その人はただの蔑みを受けるだけです。'),
('JPN', '雅歌', 22, 8, 8, '私たちの妹は若く、乳房もない。私たちの妹に縁談のある日には、彼女のために何をしてあげようか。'),
('JPN', '雅歌', 22, 8, 9, 'もし彼女が城壁だったら、その上に銀の胸壁を建ててあげよう。彼女が戸だったら、杉の板でおおってあげよう。'),
('JPN', '雅歌', 22, 8, 10, '私は城壁、私の乳房はやぐらのよう。そのために、私はあの方の目には平安をもたらす者のようになりました。'),
('JPN', '雅歌', 22, 8, 11, 'ソロモンにはバアル・ハモンにぶどう畑があって、そのぶどう畑を、守る者たちに任せていた。それぞれは、そのぶどうの実に代えて銀千枚を納めることになっていた。'),
('JPN', '雅歌', 22, 8, 12, '私が持っているぶどう畑が私の前にある。ソロモンよ。あなたには銀千枚、その実を守る者には銀二百枚。'),
('JPN', '雅歌', 22, 8, 13, '庭の中に住む仲間たちは、あなたの声に耳を傾けている。私にそれを聞かせておくれ。'),
('JPN', '雅歌', 22, 8, 14, '私の愛する方よ、急いでください。かもしかのように、若い鹿のようになって、香料の山々へと。'),
('JPN', '以赛亚书', 23, 1, 1, 'アモツの子イザヤの幻。これは彼がユダとエルサレムについて、ユダの王ウジヤ、ヨタム、アハズ、ヒゼキヤの時代に見たものである。'),
('JPN', '以赛亚书', 23, 1, 2, '天よ、聞け。地も耳を傾けよ。主が語られるからだ。「子どもたちはわたしが育てて、大きくした。しかし、彼らはわたしに背いた。'),
('JPN', '以赛亚书', 23, 1, 3, '牛はその飼い主を、ろばは持ち主の飼葉桶を知っている。しかし、イスラエルは知らない。わたしの民は悟らない。」'),
('JPN', '以赛亚书', 23, 1, 4, 'わざわいだ。罪深き国、咎重き民、悪を行う者どもの子孫、堕落した子ら。彼らは主を捨て、イスラエルの聖なる方を侮り、背を向けて離れ去った。'),
('JPN', '以赛亚书', 23, 1, 5, 'あなたがたは、反抗に反抗を重ねてなおも、どこを打たれようというのか。頭は残すところなく病み、心臓もすべて弱っている。'),
('JPN', '以赛亚书', 23, 1, 6, '足の裏から頭まで健全なところはなく、傷、打ち傷、生傷。絞り出してももらえず、包んでももらえず、油で和らげてももらえない。'),
('JPN', '以赛亚书', 23, 1, 7, 'あなたがたの地は荒れ果て、あなたがたの町々は火で焼かれている。土地は、あなたがたの前で他国人が食い荒らし、他国人に破壊されたように、荒れ果てている。'),
('JPN', '以赛亚书', 23, 1, 8, 'しかし、娘シオンは残された。あたかも、ぶどう畑の小屋のように、きゅうり畑の番小屋のように、包囲された町のように。'),
('JPN', '以赛亚书', 23, 1, 9, 'もしも、万軍の主が私たちに生き残りの者をわずかでも残されなかったなら、私たちもソドムのようになり、ゴモラと同じになっていたであろう。'),
('JPN', '以赛亚书', 23, 1, 10, '聞け。ソドムの首領たちよ、主のことばを。耳を傾けよ。ゴモラの民よ、私たちの神のみおしえに。'),
('JPN', '以赛亚书', 23, 1, 11, '「あなたがたの多くのいけにえは、わたしにとって何になろう。──主は言われる──わたしは、雄羊の全焼のささげ物や、肥えた家畜の脂肪に飽きた。雄牛、子羊、雄やぎの血も喜ばない。'),
('JPN', '以赛亚书', 23, 1, 12, 'あなたがたは、わたしに会いに出て来るが、だれが、わたしの庭を踏みつけよとあなたがたに求めたのか。'),
('JPN', '以赛亚书', 23, 1, 13, 'もう、むなしいささげ物を携えて来るな。香の煙、それはわたしの忌み嫌うもの。新月の祭り、安息日、会合の召集──わたしは、不義と、きよめの集会に耐えられない。'),
('JPN', '以赛亚书', 23, 1, 14, 'あなたがたの新月の祭りや例祭を、わたしの心は憎む。それはわたしの重荷となり、それを担うのに疲れ果てた。'),
('JPN', '以赛亚书', 23, 1, 15, 'あなたがたが手を伸べ広げて祈っても、わたしはあなたがたから目をそらす。どんなに祈りを多くしても聞くことはない。あなたがたの手は血まみれだ。'),
('JPN', '以赛亚书', 23, 1, 16, '洗え。身を清めよ。わたしの目の前から、あなたがたの悪い行いを取り除け。悪事を働くのをやめよ。'),
('JPN', '以赛亚书', 23, 1, 17, '善をなすことを習い、公正を求め、虐げる者を正し、みなしごを正しくさばき、やもめを弁護せよ。」'),
('JPN', '以赛亚书', 23, 1, 18, '「さあ、来たれ。論じ合おう。──主は言われる──たとえ、あなたがたの罪が緋のように赤くても、雪のように白くなる。たとえ、紅のように赤くても、羊の毛のようになる。'),
('JPN', '以赛亚书', 23, 1, 19, 'あなたがたは、もし喜んで聞こうとするなら、この地の良い物を食べることができる。'),
('JPN', '以赛亚书', 23, 1, 20, 'しかし、もし拒んで背くなら、剣に食い尽くされる。──主の御口がそう語られる。」'),
('JPN', '以赛亚书', 23, 1, 21, 'どうして遊女になったのか、忠実な都が。公正があふれて、義がそこに宿っていたのに。今は人殺しばかりだ。'),
('JPN', '以赛亚书', 23, 1, 22, 'おまえの銀は金かすになった。おまえの良い酒も水で薄められている。'),
('JPN', '以赛亚书', 23, 1, 23, 'おまえの君主たちは強情者、盗人の仲間。みな賄賂を愛し、報酬を追い求める。みなしごを正しくさばかず、やもめの訴えも彼らには届かない。'),
('JPN', '以赛亚书', 23, 1, 24, '「それゆえ──万軍の主、イスラエルの力強き者である主のことば──ああ、わたしは逆らう者に思いを晴らし、わたしの敵に復讐する。'),
('JPN', '以赛亚书', 23, 1, 25, 'わたしは、わが手をおまえに対して向け、おまえの金かすを灰汁のように溶かし、その浮きかすをみな除く。'),
('JPN', '以赛亚书', 23, 1, 26, 'こうして、おまえをさばく者たちを以前のように、おまえに助言する者たちを最初のようにする。その後に、おまえは正義の町、忠実な都と呼ばれる。」'),
('JPN', '以赛亚书', 23, 1, 27, 'シオンは公正によって贖われ、その町の立ち返る者は義によって贖われる。'),
('JPN', '以赛亚书', 23, 1, 28, '背く者と罪人はともに破滅し、主を捨てる者は消え失せる。'),
('JPN', '以赛亚书', 23, 1, 29, 'まことに、彼らはあなたがたが慕った樫の木で恥を見、あなたがたは自ら選んだ園によって屈辱を受ける。'),
('JPN', '以赛亚书', 23, 1, 30, 'あなたがたは葉のしおれた樫の木のように、水のない園のようになるからだ。'),
('JPN', '以赛亚书', 23, 1, 31, '強い者は麻屑に、その行いは火花になり、二つとも燃えさかり、これを消す者はいない。'),
('JPN', '以赛亚书', 23, 2, 1, 'アモツの子イザヤが、ユダとエルサレムについて見たことば。'),
('JPN', '以赛亚书', 23, 2, 2, '終わりの日に、主の家の山は山々の頂に堅く立ち、もろもろの丘より高くそびえ立つ。そこにすべての国々が流れて来る。'),
('JPN', '以赛亚书', 23, 2, 3, '多くの民族が来て言う。「さあ、主の山、ヤコブの神の家に上ろう。主はご自分の道を私たちに教えてくださる。私たちはその道筋を進もう。」それは、シオンからみおしえが、エルサレムから主のことばが出るからだ。'),
('JPN', '以赛亚书', 23, 2, 4, '主は国々の間をさばき、多くの民族に判決を下す。彼らはその剣を鋤に、その槍を鎌に打ち直す。国は国に向かって剣を上げず、もう戦うことを学ばない。'),
('JPN', '以赛亚书', 23, 2, 5, 'ヤコブの家よ、さあ、私たちも主の光のうちを歩もう。'),
('JPN', '以赛亚书', 23, 2, 6, 'まことに、あなたは、あなたの民、ヤコブの家を捨てられました。彼らはペリシテ人のように東方からの者、卜者で満ち、異国人の子らであふれています。'),
('JPN', '以赛亚书', 23, 2, 7, 'その地は銀や金で満ち、財宝は限りなく、その地は馬で満ち、戦車の数も限りありません。'),
('JPN', '以赛亚书', 23, 2, 8, 'その地は偽りの神々で満ち、彼らは自分の手で造った物を、指で造った物を拝んでいます。'),
('JPN', '以赛亚书', 23, 2, 9, 'こうして人間はかがめられ、人は低くされます。彼らを赦さないでください。'),
('JPN', '以赛亚书', 23, 2, 10, '岩の間に入り、土の中に身を隠せ。主の恐るべき御顔を、その威光の輝きを避けて。'),
('JPN', '以赛亚书', 23, 2, 11, 'その日には、人間の高ぶりの目は低くされ、人々の思い上がりはかがめられ、主おひとりだけが高く上げられる。'),
('JPN', '以赛亚书', 23, 2, 12, 'まことに、万軍の主の日は、すべてのおごり高ぶる者、すべての誇る者の上にあり、これを低くする。'),
('JPN', '以赛亚书', 23, 2, 13, 'またそれは、高くそびえるレバノンのすべての杉の木と、バシャンのすべての樫の木、'),
('JPN', '以赛亚书', 23, 2, 14, 'すべての高い山々と、すべてのそびえる峰々、'),
('JPN', '以赛亚书', 23, 2, 15, 'すべてのそそり立つやぐらと、すべての堅固な城壁、'),
('JPN', '以赛亚书', 23, 2, 16, 'タルシシュのすべての船、すべての慕わしい船の上にある。'),
('JPN', '以赛亚书', 23, 2, 17, 'その日には、人間の高ぶりはかがめられ、人々の思い上がりは低くされ、主おひとりだけが高く上げられる。'),
('JPN', '以赛亚书', 23, 2, 18, '偽りの神々はことごとく消え失せる。'),
('JPN', '以赛亚书', 23, 2, 19, '主が立ち上がり、地を脅かすとき、人々は主の恐るべき御顔を、その威光の輝きを避けて、岩の洞穴や土の穴に入る。'),
('JPN', '以赛亚书', 23, 2, 20, 'その日、人は、自分が拝むために造った銀の偽りの神々と金の偽りの神々を、もぐらや、こうもりに投げやる。'),
('JPN', '以赛亚书', 23, 2, 21, '主が立ち上がり、地を脅かすとき、人々は、主の恐るべき御顔を、その威光の輝きを避けて、岩の割れ目や、巌の裂け目に入る。'),
('JPN', '以赛亚书', 23, 2, 22, '人間に頼るな。鼻で息をする者に。そんな者に、何の値打ちがあるか。'),
('JPN', '以赛亚书', 23, 3, 1, 'まことに、見よ、万軍の主、主はエルサレムとユダから、支えと頼みになるものを除かれる。すべての頼みのパン、すべての頼みの水、'),
('JPN', '以赛亚书', 23, 3, 2, '勇士と戦士、さばき人と預言者、占い師と長老、'),
('JPN', '以赛亚书', 23, 3, 3, '五十人隊の長と身分の高い者、助言者と賢い細工人、巧みにまじないをかける者を。'),
('JPN', '以赛亚书', 23, 3, 4, '「わたしは、若い者たちを彼らの君主とし、気まぐれ者に彼らを治めさせる。'),
('JPN', '以赛亚书', 23, 3, 5, '民はそれぞれ仲間同士で虐げ合い、若い者は年寄りに向かって尊大にふるまう。身分の低い者は高い者に向かって。'),
('JPN', '以赛亚书', 23, 3, 6, 'そのとき、人は父の家で自分の兄弟を捕らえてこう言う。『あなたは着る物を持っている。私たちの首領になってくれ。この乱れ果てた有様を、あなたの手で治めてくれ。』'),
('JPN', '以赛亚书', 23, 3, 7, 'その日、彼は声を張り上げて言う。『私は傷の手当てをする者にはなれない。家にはパンもなく、着る物もない。私を民の首領にはしないでくれ』と。'),
('JPN', '以赛亚书', 23, 3, 8, 'これは、エルサレムがつまずき、ユダが倒れたからであり、彼らの舌と行いが主に背き、主の栄光の現れに逆らったからである。'),
('JPN', '以赛亚书', 23, 3, 9, '彼らの顔つきがそれを表している。彼らは罪をソドムのようにあらわにし、隠そうとしなかった。彼らのたましいはわざわいだ。悪の報いを受けるのだから。'),
('JPN', '以赛亚书', 23, 3, 10, '正しい人は幸いだ、と言え。その人たちは自分の行いの実を食べる。'),
('JPN', '以赛亚书', 23, 3, 11, '悪しき者、悪人はわざわいだ。その手の報いは自分自身に降りかかる。'),
('JPN', '以赛亚书', 23, 3, 12, 'わが民は、幼子が虐げ、また女たちがこれを治める。わが民よ。あなたの案内人たちは迷わす者。あなたの歩む道をかき乱す。」'),
('JPN', '以赛亚书', 23, 3, 13, '主は論争するために立ち構え、もろもろの民をさばくために立たれる。'),
('JPN', '以赛亚书', 23, 3, 14, '主は、ご自分の民の長老たちや君主たちと、さばきの座に入られる。「あなたがたは、ぶどう畑を荒れすたらせた。貧しい者からかすめた物が自分たちの家にある。'),
('JPN', '以赛亚书', 23, 3, 15, 'なぜ、あなたがたは、わが民を砕き、貧しい者の顔を臼ですりつぶすのか。──万軍の神、主のことば。」'),
('JPN', '以赛亚书', 23, 3, 16, '主は言われた。「シオンの娘たちは高ぶり、首を伸ばし、色目を使って歩き、足に鈴を鳴らしながら小股で歩く。」'),
('JPN', '以赛亚书', 23, 3, 17, 'それで、主はシオンの娘たちの頭の頂をかさぶたでおおい、主は彼女たちの額をむき出しにされる。'),
('JPN', '以赛亚书', 23, 3, 18, 'その日、主はもろもろの飾りを除かれる。足飾り、髪の輪飾り、三日月形の飾り物、'),
('JPN', '以赛亚书', 23, 3, 19, '耳輪、腕輪、ベール、'),
('JPN', '以赛亚书', 23, 3, 20, '頭飾り、くるぶしの鎖、飾り帯、香の入れ物、お守り札、'),
('JPN', '以赛亚书', 23, 3, 21, '指輪、鼻輪、'),
('JPN', '以赛亚书', 23, 3, 22, '礼服、外套、羽織物、金入れ、'),
('JPN', '以赛亚书', 23, 3, 23, '手鏡、亜麻布の衣服、ターバン、かぶり物を。'),
('JPN', '以赛亚书', 23, 3, 24, 'こうして、芳香は悪臭となり、帯は荒縄、結い上げた髪ははげた頭、豪華な衣装は粗布の腰巻き、その美しさは焼き印となる。'),
('JPN', '以赛亚书', 23, 3, 25, 'あなたの男たちは剣に、あなたの勇士たちは戦いに倒れる。'),
('JPN', '以赛亚书', 23, 3, 26, 'シオンの門は悲しみ嘆き、さびれ果てて地の上に座す。'),
('JPN', '以赛亚书', 23, 4, 1, 'その日、七人の女が、一人の男にすがりついて言う。「私たちは自分のパンを食べ、自分の服を着ます。私たちがあなたの名で呼ばれるようにして、恥辱を取り去ってください。」'),
('JPN', '以赛亚书', 23, 4, 2, 'その日、主の若枝は麗しいものとなり、栄光となる。地の果実はイスラエルの逃れの者にとって、誇りとなり、輝きとなる。'),
('JPN', '以赛亚书', 23, 4, 3, 'シオンに残された者、エルサレムに残った者は、聖なる者と呼ばれるようになる。みなエルサレムに生きる者として書き記されている。'),
('JPN', '以赛亚书', 23, 4, 4, '主が、さばきの霊と焼き尽くす霊によって、シオンの娘たちの汚れを洗い落とし、エルサレムの血をその町の中から洗い流すとき、'),
('JPN', '以赛亚书', 23, 4, 5, '主は、シオンの山のすべての場所とその会合の上に、昼には雲を、夜には煙と燃え立つ火の輝きを創造される。それはすべての栄光の上に覆いとなり、'),
('JPN', '以赛亚书', 23, 4, 6, 'その仮庵は昼に暑さを避ける陰となり、嵐と雨から逃れる避け所、また隠れ家となる。'),
('JPN', '以赛亚书', 23, 5, 1, '「さあ、わたしは歌おう。わが愛する者のために。そのぶどう畑についての、わが愛の歌を。わが愛する者は、よく肥えた山腹にぶどう畑を持っていた。'),
('JPN', '以赛亚书', 23, 5, 2, '彼はそこを掘り起こして、石を除き、そこに良いぶどうを植え、その中にやぐらを立て、その中にぶどうの踏み場まで掘り、ぶどうがなるのを心待ちにしていた。ところが、酸いぶどうができてしまった。'),
('JPN', '以赛亚书', 23, 5, 3, '今、エルサレムの住民とユダの人よ、さあ、わたしとわがぶどう畑との間をさばけ。'),
('JPN', '以赛亚书', 23, 5, 4, 'わがぶどう畑になすべきことで、何かわたしがしなかったことがあるか。なぜ、ぶどうがなるのを心待ちにしていたのに、酸いぶどうができたのか。'),
('JPN', '以赛亚书', 23, 5, 5, 'さあ、今度はわたしがあなたがたに知らせよう。わたしが、わがぶどう畑に対してすることを。わたしはその垣を取り払い、荒れすたれるに任せ、その石垣を崩して、踏みつけられるままにする。'),
('JPN', '以赛亚书', 23, 5, 6, 'わたしはこれを滅びるままにしておく。枝は下ろされず、草は刈られず、茨やおどろが生い茂る。わたしは雨雲に命じて、この上に雨を降らせないようにする。」'),
('JPN', '以赛亚书', 23, 5, 7, '万軍の主のぶどう畑はイスラエルの家。ユダの人は、主が喜んで植えたもの。主は公正を望まれた。しかし見よ、流血。正義を望まれた。しかし見よ、悲鳴。'),
('JPN', '以赛亚书', 23, 5, 8, 'わざわいだ。家に家を連ね、畑に畑を隣り合わせる者たち。あなたがたは場所を残さず、自分たちだけこの地に住もうとしている。'),
('JPN', '以赛亚书', 23, 5, 9, '私の耳に万軍の主は告げられた。「必ず、多くの家は荒れすたれ、大きな美しい家々も住む者がいなくなる。'),
('JPN', '以赛亚书', 23, 5, 10, '十ツェメドのぶどう畑が一バテを産し、一ホメルの種が一エパを産するからだ。」'),
('JPN', '以赛亚书', 23, 5, 11, 'わざわいだ。朝早くから強い酒を追い求め、夜が更けるまで、ぶどう酒に身を委ねる者たち。'),
('JPN', '以赛亚书', 23, 5, 12, '彼らの酒宴には竪琴と琴、タンバリンと笛とぶどう酒がある。彼らは主のなさることに目を留めず、御手のわざを見もしない。'),
('JPN', '以赛亚书', 23, 5, 13, 'それゆえ、私の民は知識がないために捕らえ移される。その貴族たちは飢えた者となり、その民衆は渇きで干からびる。'),
('JPN', '以赛亚书', 23, 5, 14, 'それゆえ、よみは喉を広げ、果てしなく口を開ける。エルサレムの威光も、騒音も、どよめきも、そこでの歓声も、よみに落ち込む。'),
('JPN', '以赛亚书', 23, 5, 15, 'こうして人間はかがめられ、人は低くされる。高ぶる者の目も低くされる。'),
('JPN', '以赛亚书', 23, 5, 16, 'しかし、万軍の主はさばきによって高くなり、聖なる神は正義によって、自ら聖なることを示される。'),
('JPN', '以赛亚书', 23, 5, 17, '子羊は自分の牧場にいるように草を食べ、肥えた獣は廃墟にとどまって食をとる。'),
('JPN', '以赛亚书', 23, 5, 18, 'わざわいだ。噓を綱として咎を引き寄せる者。車の手綱でするように、罪を引き寄せる者たち。'),
('JPN', '以赛亚书', 23, 5, 19, '彼らは言う。「彼のすることを早くさせよ。急がせよ。それを見てみたい。イスラエルの聖なる方のご計画が近づいて、成就すればよい。それを知りたい」と。'),
('JPN', '以赛亚书', 23, 5, 20, 'わざわいだ。悪を善、善を悪と言う者たち。彼らは闇を光、光を闇とし、苦みを甘み、甘みを苦みとする。'),
('JPN', '以赛亚书', 23, 5, 21, 'わざわいだ。自分を知恵のある者と見なし、自分を悟りのある者と思い込む者たち。'),
('JPN', '以赛亚书', 23, 5, 22, 'わざわいだ。酒を飲むことにかけては勇士、強い酒を混ぜ合わせることにかけては豪の者。'),
('JPN', '以赛亚书', 23, 5, 23, '彼らは賄賂のために、悪者を正しいと宣言し、その悪者から正しい者たちの正しさを遠ざける。'),
('JPN', '以赛亚书', 23, 5, 24, 'それゆえ、火の舌が刈り株を焼き尽くし、枯れ草が炎の中に溶けゆくように、彼らの根は腐り、その花も、ちりのように舞い上がる。彼らが万軍の主のおしえをないがしろにし、イスラエルの聖なる方のことばを侮ったからだ。'),
('JPN', '以赛亚书', 23, 5, 25, 'それゆえ、主の怒りはその民に向かって燃え、これに御手を伸ばして打つ。山々は震え、彼らの屍は、通りで、あくたのようになる。それでも御怒りは収まらず、なおも御手は伸ばされている。'),
('JPN', '以赛亚书', 23, 5, 26, '主は遠く離れた国に旗を揚げ、地の果てから来るように合図される。すると見よ、それは急いで速やかに来る。'),
('JPN', '以赛亚书', 23, 5, 27, 'その中には、疲れる者も、つまずく者もいない。だれ一人、まどろまず、眠らず、その腰の帯は解かれず、履き物のひもは切れない。'),
('JPN', '以赛亚书', 23, 5, 28, 'その矢は研ぎ澄まされ、弓はみな張られ、馬のひづめは火打石のように、その車輪はつむじ風のように見える。'),
('JPN', '以赛亚书', 23, 5, 29, 'その吼え方は獅子のよう。若獅子のように吼え、うなり、獲物を捕らえる。奪って行くと、救い出せる者はいない。'),
('JPN', '以赛亚书', 23, 5, 30, 'その日、その民は海のとどろきのように、イスラエルにうなり声をあげる。地を見やると、見よ、闇と苦しみ。光さえ雨雲の中で暗くなる。'),
('JPN', '以赛亚书', 23, 6, 1, 'ウジヤ王が死んだ年に、私は、高く上げられた御座に着いておられる主を見た。その裾は神殿に満ち、'),
('JPN', '以赛亚书', 23, 6, 2, 'セラフィムがその上の方に立っていた。彼らにはそれぞれ六つの翼があり、二つで顔をおおい、二つで両足をおおい、二つで飛んでいて、'),
('JPN', '以赛亚书', 23, 6, 3, '互いにこう呼び交わしていた。「聖なる、聖なる、聖なる、万軍の主。その栄光は全地に満ちる。」'),
('JPN', '以赛亚书', 23, 6, 4, 'その叫ぶ者の声のために敷居の基は揺らぎ、宮は煙で満たされた。'),
('JPN', '以赛亚书', 23, 6, 5, '私は言った。「ああ、私は滅んでしまう。この私は唇の汚れた者で、唇の汚れた民の間に住んでいる。しかも、万軍の主である王をこの目で見たのだから。」'),
('JPN', '以赛亚书', 23, 6, 6, 'すると、私のもとにセラフィムのひとりが飛んで来た。その手には、祭壇の上から火ばさみで取った、燃えさかる炭があった。'),
('JPN', '以赛亚书', 23, 6, 7, '彼は、私の口にそれを触れさせて言った。「見よ。これがあなたの唇に触れたので、あなたの咎は取り除かれ、あなたの罪も赦された。」'),
('JPN', '以赛亚书', 23, 6, 8, '私は主が言われる声を聞いた。「だれを、わたしは遣わそう。だれが、われわれのために行くだろうか。」私は言った。「ここに私がおります。私を遣わしてください。」'),
('JPN', '以赛亚书', 23, 6, 9, 'すると主は言われた。「行って、この民に告げよ。『聞き続けよ。だが悟るな。見続けよ。だが知るな』と。'),
('JPN', '以赛亚书', 23, 6, 10, 'この民の心を肥え鈍らせ、その耳を遠くし、その目を固く閉ざせ。彼らがその目で見ることも、耳で聞くことも、心で悟ることも、立ち返って癒やされることもないように。」'),
('JPN', '以赛亚书', 23, 6, 11, '私が「主よ、いつまでですか」と言うと、主は言われた。「町々が荒れ果てて住む者がなく、家々にも人がいなくなり、土地も荒れ果てて荒れ地となる。'),
('JPN', '以赛亚书', 23, 6, 12, '主が人を遠くに移し、この地に見捨てられた場所が増えるまで。'),
('JPN', '以赛亚书', 23, 6, 13, 'そこには、なお十分の一が残るが、それさえも焼き払われる。しかし、切り倒されたテレビンや樫の木のように、それらの間に切り株が残る。この切り株こそ、聖なる裔。」'),
('JPN', '以赛亚书', 23, 7, 1, 'ウジヤの子のヨタムの子、ユダの王アハズの時代、アラムの王レツィンと、イスラエルの王レマルヤの子ペカが、戦いのためにエルサレムに上って来たが、これを攻めきれなかった時のことである。'),
('JPN', '以赛亚书', 23, 7, 2, 'ダビデの家に「アラムがエフライムと組んだ」という知らせがもたらされた。王の心も民の心も、林の木々が風に揺らぐように揺らいだ。'),
('JPN', '以赛亚书', 23, 7, 3, 'そのとき、主はイザヤに言われた。「あなたと、あなたの子シェアル・ヤシュブは、上の池の水道の端、布さらしの野への大路に出向いて行ってアハズに会い、'),
('JPN', '以赛亚书', 23, 7, 4, '彼に言え。『気を確かに持ち、落ち着いていなさい。恐れてはならない。あなたは、これら二つの煙る木切れの燃えさし、アラムのレツィンとレマルヤの子の燃える怒りに、心を弱らせてはならない。'),
('JPN', '以赛亚书', 23, 7, 5, 'アラムは、エフライムすなわちレマルヤの子とともに、あなたに対して悪事を企てて、'),
('JPN', '以赛亚书', 23, 7, 6, '「われわれはユダに上ってこれを脅かし、これに攻め入ってわがものとし、タベアルの子をその王にしよう」と言っているが、'),
('JPN', '以赛亚书', 23, 7, 7, '神である主はこう言われる。それは起こらない。それはあり得ない。'),
('JPN', '以赛亚书', 23, 7, 8, 'アラムのかしらはダマスコ、そのダマスコのかしらがレツィンだから。──エフライムは六十五年のうちに、打ちのめされて、一つの民ではなくなる──'),
('JPN', '以赛亚书', 23, 7, 9, 'エフライムのかしらはサマリア、そのサマリアのかしらがレマルヤの子だから。あなたがたは、信じなければ堅く立つことはできない。』」'),
('JPN', '以赛亚书', 23, 7, 10, '主はさらにアハズに告げられた。'),
('JPN', '以赛亚书', 23, 7, 11, '「あなたの神、主に、しるしを求めよ。よみの深みにでも、天の高みにでも。」'),
('JPN', '以赛亚书', 23, 7, 12, 'アハズは言った。「私は求めません。主を試みません。」'),
('JPN', '以赛亚书', 23, 7, 13, 'イザヤは言った。「さあ、聞け、ダビデの家よ。あなたがたは人々を煩わすことで足りず、私の神までも煩わすのか。'),
('JPN', '以赛亚书', 23, 7, 14, 'それゆえ、主は自ら、あなたがたに一つのしるしを与えられる。見よ、処女が身ごもっている。そして男の子を産み、その名をインマヌエルと呼ぶ。'),
('JPN', '以赛亚书', 23, 7, 15, 'この子は、悪を退けて善を選ぶことを知るころまで、凝乳と蜂蜜を食べる。'),
('JPN', '以赛亚书', 23, 7, 16, 'それは、その子が悪を退けて善を選ぶことを知る前に、あなたが恐怖を抱いている二人の王の土地が見捨てられるからだ。'),
('JPN', '以赛亚书', 23, 7, 17, '主は、あなたとあなたの民とあなたの父の家に、エフライムがユダから離れた日以来、まだ臨んだこともない日々をもたらす。それはアッシリアの王だ。」'),
('JPN', '以赛亚书', 23, 7, 18, 'その日になると、主はエジプトの幾筋もの川の果てにいるあの蠅、アッシリアの地にいるあの蜂に合図される。'),
('JPN', '以赛亚书', 23, 7, 19, 'すると彼らはみなやって来て、険しい谷、岩の割れ目、あらゆる茨の茂み、あらゆる水飲み場に巣くう。'),
('JPN', '以赛亚书', 23, 7, 20, 'その日、主は大河の向こうで雇ったかみそり、アッシリアの王を使って頭と足の毛を剃り、ひげまでも剃り落とす。'),
('JPN', '以赛亚书', 23, 7, 21, 'その日になると、一人の人が雌の子牛一頭と羊二匹を生かしておく。'),
('JPN', '以赛亚书', 23, 7, 22, 'これらが乳を多く出すので、彼は凝乳を食べるようになる。この地に残されたすべての者が凝乳と蜂蜜を食べるようになる。'),
('JPN', '以赛亚书', 23, 7, 23, 'その日になると、銀千枚に値する、ぶどう千株のある地所もみな、茨とおどろのものとなる。'),
('JPN', '以赛亚书', 23, 7, 24, '全土が茨とおどろになるので、人は弓矢を持って、そこに行く。'),
('JPN', '以赛亚书', 23, 7, 25, '鍬で耕されたすべての山にも、あなたは茨とおどろを恐れて、行かない。そこは牛が放たれて、羊の踏み歩く場所となる。'),
('JPN', '以赛亚书', 23, 8, 1, '主は私に言われた。「一つの大きな板を取り、その上に普通の文字で、『マヘル・シャラル・ハシュ・バズのため』と書け。'),
('JPN', '以赛亚书', 23, 8, 2, 'そうすれば、わたしは祭司ウリヤとエベレクヤの子ゼカリヤに、わたしの確かな証人として証言させる。」'),
('JPN', '以赛亚书', 23, 8, 3, 'それから私は女預言者に近づいた。彼女は身ごもって男の子を産んだ。すると、主は私に言われた。「その名をマヘル・シャラル・ハシュ・バズと名づけよ。'),
('JPN', '以赛亚书', 23, 8, 4, 'それは、この子が『お父さん。お母さん』と呼ぶことを知る前に、ダマスコの財宝とサマリアの分捕り物が、アッシリアの王の前に持ち去られて行くからである。」'),
('JPN', '以赛亚书', 23, 8, 5, '主はさらに、続けて私に言われた。'),
('JPN', '以赛亚书', 23, 8, 6, '「この民は、ゆるやかに流れるシロアハの水を拒み、レツィンとレマルヤの子を喜んでいる。'),
('JPN', '以赛亚书', 23, 8, 7, 'それゆえ、見よ。主は、強く水の豊かなあの大河の水、アッシリアの王とそのすべての栄光を彼らの上にあふれさせる。それはすべての運河にあふれ、すべての堤を越え、'),
('JPN', '以赛亚书', 23, 8, 8, 'ユダに勢いよく流れ込み、あふれみなぎって首にまで達する。その広げた翼は、インマヌエルよ、あなたの地をおおい尽くす。」'),
('JPN', '以赛亚书', 23, 8, 9, '諸国の民よ、打ち砕かれよ。遠く離れたすべての国々よ、耳を傾けよ。腰に帯をして、わななけ。腰に帯をして、わななけ。'),
('JPN', '以赛亚书', 23, 8, 10, 'はかりごとをめぐらせ。しかしそれは破られる。事を謀れ。しかしそれは成らない。神が私たちとともにおられるからだ。'),
('JPN', '以赛亚书', 23, 8, 11, 'まことに、主は強い御手をもって私を捕らえ、この民の道に歩まないよう、私を戒めてこう言われた。'),
('JPN', '以赛亚书', 23, 8, 12, '「あなたがたは、この民が謀反と呼ぶことを何一つ謀反と呼ぶな。この民が恐れるものを恐れてはならない。おびえてはならない。'),
('JPN', '以赛亚书', 23, 8, 13, '万軍の主、主を聖なる者とせよ。主こそ、あなたがたの恐れ。主こそ、あなたがたのおののき。'),
('JPN', '以赛亚书', 23, 8, 14, 'そうすれば、主が聖所となる。しかし、イスラエルの二つの家にとっては妨げの石、つまずきの岩となり、エルサレムの住民には罠となり、落とし穴となる。'),
('JPN', '以赛亚书', 23, 8, 15, '多くの者がそれにつまずき、倒れて打ち砕かれ、罠にかかって捕らえられる。'),
('JPN', '以赛亚书', 23, 8, 16, 'この証しの書を束ねよ。このおしえをわたしの弟子たちのうちで封印せよ。」'),
('JPN', '以赛亚书', 23, 8, 17, '私は主を待ち望む。ヤコブの家から御顔を隠しておられる方を。私はこの方に望みを置く。'),
('JPN', '以赛亚书', 23, 8, 18, '見よ。私と、主が私に下さった子たちは、シオンの山に住む万軍の主からのイスラエルでのしるしとなり、また不思議となっている。'),
('JPN', '以赛亚书', 23, 8, 19, '人々があなたがたに「霊媒や、ささやき、うめく口寄せに尋ねよ」と言っても、民は自分の神に尋ねるべきではないのか。生きている者のために、死人に尋ねなければならないのか。'),
('JPN', '以赛亚书', 23, 8, 20, 'ただ、みおしえと証しに尋ねなければならない。もし、このことばにしたがって語らないなら、その人に夜明けはない。'),
('JPN', '以赛亚书', 23, 8, 21, 'その人は迫害され、飢えて国を歩き回り、飢えて怒りに身を委ねる。顔を上に向け、自分の王と神を呪う。'),
('JPN', '以赛亚书', 23, 8, 22, '彼が地を見ると、見よ、苦難と暗闇、苦悩の闇、暗黒、追放された者。'),
('JPN', '以赛亚书', 23, 9, 1, 'しかし、苦しみのあったところに闇がなくなる。先にはゼブルンの地とナフタリの地は辱めを受けたが、後には海沿いの道、ヨルダンの川向こう、異邦の民のガリラヤは栄誉を受ける。'),
('JPN', '以赛亚书', 23, 9, 2, '闇の中を歩んでいた民は大きな光を見る。死の陰の地に住んでいた者たちの上に光が輝く。'),
('JPN', '以赛亚书', 23, 9, 3, 'あなたはその国民を増やし、その喜びを増し加えられる。彼らは、刈り入れ時に喜ぶように、分捕り物を分けるときに楽しむように、あなたの御前で喜ぶ。'),
('JPN', '以赛亚书', 23, 9, 4, 'あなたが、彼が負うくびきと肩の杖、彼を追い立てる者のむちを、ミディアンの日になされたように打ち砕かれるからだ。'),
('JPN', '以赛亚书', 23, 9, 5, 'まことに、戦場で履いたすべての履き物、血にまみれた衣服は焼かれて、火の餌食となる。'),
('JPN', '以赛亚书', 23, 9, 6, 'ひとりのみどりごが私たちのために生まれる。ひとりの男の子が私たちに与えられる。主権はその肩にあり、その名は「不思議な助言者、力ある神、永遠の父、平和の君」と呼ばれる。'),
('JPN', '以赛亚书', 23, 9, 7, 'その主権は増し加わり、その平和は限りなく、ダビデの王座に就いて、その王国を治め、さばきと正義によってこれを堅く立て、これを支える。今よりとこしえまで。万軍の主の熱心がこれを成し遂げる。'),
('JPN', '以赛亚书', 23, 9, 8, '主はヤコブに一つのことばを送られる。それはイスラエルに下る。'),
('JPN', '以赛亚书', 23, 9, 9, 'この民、エフライムとサマリアに住む者たちはみなそれを知り、高ぶり、思い上がって言う。'),
('JPN', '以赛亚书', 23, 9, 10, '「れんがが落ちたから、切り石で建て直そう。いちじく桑の木が切り倒されたから、杉の木でこれに代えよう。」'),
('JPN', '以赛亚书', 23, 9, 11, 'そこで主はレツィンに敵対する者たちをのし上がらせ、その敵たちをあおりたてる。'),
('JPN', '以赛亚书', 23, 9, 12, '東からはアラムが、西からはペリシテ人が、その口いっぱいにイスラエルを食らう。それでも御怒りは収まらず、なおも御手は伸ばされている。'),
('JPN', '以赛亚书', 23, 9, 13, 'しかし、この民は自分を打った方に帰らず、万軍の主を求めない。'),
('JPN', '以赛亚书', 23, 9, 14, 'そこで主はイスラエルから、かしらも尾も、なつめ椰子の葉も葦も一日のうちに断ち切られる。'),
('JPN', '以赛亚书', 23, 9, 15, 'そのかしらとは長老や身分の高い者。その尾とは偽りを教える預言者。'),
('JPN', '以赛亚书', 23, 9, 16, 'この民を導く者は迷わす者となり、彼らに導かれる者は惑わされる者となる。'),
('JPN', '以赛亚书', 23, 9, 17, 'それゆえ、主はその若い男たちを喜ばず、そのみなしごも、やもめも、あわれまない。皆が神を敬わず、悪を行い、すべての口が愚かなことを語っているからだ。それでも御怒りは収まらず、なおも御手は伸ばされている。'),
('JPN', '以赛亚书', 23, 9, 18, 'まことに、悪は火のように燃えさかり、茨とおどろをなめ尽くし、林の茂みに燃えついて、煙となって巻き上がる。'),
('JPN', '以赛亚书', 23, 9, 19, '万軍の主の激しい怒りによって地は焼かれ、民は火の餌食のようになり、だれも互いにいたわり合わない。'),
('JPN', '以赛亚书', 23, 9, 20, '右にかぶりついても、なお飢え、左に食らいついても、満たされず、それぞれ自分の腕の肉を食らう。'),
('JPN', '以赛亚书', 23, 9, 21, 'マナセはエフライムを、エフライムはマナセを、そして彼らはともにユダを敵とする。それでも御怒りは収まらず、なおも御手は伸ばされている。'),
('JPN', '以赛亚书', 23, 10, 1, 'わざわいだ。不義の掟を制定する者、不当な判決を書いている者たち。'),
('JPN', '以赛亚书', 23, 10, 2, '彼らは弱い者の訴えを退け、私の民のうちの貧しい者の権利をかすめる。こうして、やもめは彼らの餌食となり、みなしごたちは奪い取られる。'),
('JPN', '以赛亚书', 23, 10, 3, '訪れの日、遠くから嵐が来るときに、あなたがたはどうするのか。だれに助けを求めて逃げ、どこに自分の栄光を残すのか。'),
('JPN', '以赛亚书', 23, 10, 4, 'ただ、捕らわれ人の足もとに膝をつき、殺された者たちのそばに倒れるだけだ。それでも御怒りは収まらず、なおも御手は伸ばされている。'),
('JPN', '以赛亚书', 23, 10, 5, '「ああ、アッシリア、わたしの怒りのむち。わたしの憤りの杖は彼らの手にある。'),
('JPN', '以赛亚书', 23, 10, 6, 'わたしは、これを神を敬わない国に送り、わたしが激しく怒る民を襲えと、これに命じる。物を分捕らせ、獲物を奪わせ、道端の泥のように、これを踏みにじらせる。'),
('JPN', '以赛亚书', 23, 10, 7, 'しかし、彼自身はそうとは思わず、彼の心もそうは考えない。彼の心にあるのは滅ぼすこと、少なからぬ国々を絶ち滅ぼすことだ。'),
('JPN', '以赛亚书', 23, 10, 8, 'というのは、彼がこう思っているからだ。『私の高官たちはみな王ではないか。'),
('JPN', '以赛亚书', 23, 10, 9, 'カルノもカルケミシュのよう、ハマテもアルパデのようではないか。サマリアもダマスコのようではないか。'),
('JPN', '以赛亚书', 23, 10, 10, 'エルサレム、サマリアにまさる刻んだ像を持つ、偽りの神々の王国を私が手に入れたように、'),
('JPN', '以赛亚书', 23, 10, 11, '私はサマリアとその偽りの神々にしたように、エルサレムとその多くの偶像にも同じようにしないだろうか』と。」'),
('JPN', '以赛亚书', 23, 10, 12, '主はシオンの山、エルサレムで、ご自分のすべてのわざを成し遂げるとき、アッシリアの王の思い上がった心の果実、その高ぶる目の輝きを罰せられる。'),
('JPN', '以赛亚书', 23, 10, 13, 'それは彼がこう言ったからである。「私は自分の手の力でやった。私の知恵でやった。私は賢いからだ。私が諸国の民の境を取り払い、彼らの蓄えを奪い、全能者のように住民をおとしめた。'),
('JPN', '以赛亚书', 23, 10, 14, '私の手は、諸国の民の財宝を巣のようにつかみ、私は、見捨てられた卵を集めるように地のすべてのものを集めたが、翼をはためかす者も、口を大きく開ける者も、鳴く者もいなかった。」'),
('JPN', '以赛亚书', 23, 10, 15, '斧は、それを使って切る人に向かって高ぶることができるだろうか。のこぎりは、それをひく人に向かっておごることができるだろうか。それは、むちが、それを振り上げる人を動かし、杖が、木ではない人間を持ち上げるようなものではないか。'),
('JPN', '以赛亚书', 23, 10, 16, 'それゆえ、万軍の主、主はその最も肥え太った者たちをやつれさせ、その栄光のもとで、炎が燃え上がる。'),
('JPN', '以赛亚书', 23, 10, 17, 'イスラエルの光は火となり、その聖なる方は炎となる。燃え上がって、そのおどろと茨を一日のうちになめ尽くす。'),
('JPN', '以赛亚书', 23, 10, 18, '主はその美しい林も果樹園も、また、たましいも、からだも滅ぼし尽くし、それは病人が痩せ衰えるときのようになる。'),
('JPN', '以赛亚书', 23, 10, 19, 'その林の木の残りは数えるほどになり、子どもでもそれらを書き留められる。'),
('JPN', '以赛亚书', 23, 10, 20, 'その日になると、イスラエルの残りの者、ヤコブの家の逃れの者は、もう二度と自分を打つ者に頼らず、イスラエルの聖なる方、主に真実をもって頼る。'),
('JPN', '以赛亚书', 23, 10, 21, '残りの者、ヤコブの残りの者は、力ある神に立ち返る。'),
('JPN', '以赛亚书', 23, 10, 22, 'たとえ、あなたの民イスラエルが海の砂のようであっても、その中の残りの者だけが帰って来る。壊滅は定められ、義があふれようとしている。'),
('JPN', '以赛亚书', 23, 10, 23, 'すでに定められた全滅を、万軍の神、主は、全地のただ中で起こそうとしておられる。'),
('JPN', '以赛亚书', 23, 10, 24, 'それゆえ、万軍の神、主はこう言われる。「シオンに住むわたしの民よ、アッシリアを恐れるな。彼がむちであなたを打ち、エジプトがしたように杖をあなたに振り上げても。'),
('JPN', '以赛亚书', 23, 10, 25, 'もうほんの少しでわたしの憤りは終わり、わたしの怒りは彼らを滅ぼしてしまうから。'),
('JPN', '以赛亚书', 23, 10, 26, 'オレブの岩でミディアンを打ったときのように、万軍の主が彼にむちを振り上げる。杖を海にかざして、エジプトにしたようにそれを上げる。'),
('JPN', '以赛亚书', 23, 10, 27, 'その日になると、彼の重荷はあなたの肩から、彼のくびきはあなたの首から除かれる。くびきは脂肪のゆえに外される。」'),
('JPN', '以赛亚书', 23, 10, 28, '彼はアヤテに着き、ミグロンを過ぎ、ミクマスに荷を置く。'),
('JPN', '以赛亚书', 23, 10, 29, '彼らは峠を過ぎ、ゲバで野営する。ラマはおののき、サウルのギブアは逃げる。'),
('JPN', '以赛亚书', 23, 10, 30, '娘ガリムよ、甲高く叫べ。よく聞け、ライシャよ。哀れなアナトテ。'),
('JPN', '以赛亚书', 23, 10, 31, 'マデメナは逃げ去り、ゲビムの住民は避難する。'),
('JPN', '以赛亚书', 23, 10, 32, 'その日のうちに彼はノブで立ちとどまり、娘シオンの山、エルサレムの丘に向かって手を振り上げる。'),
('JPN', '以赛亚书', 23, 10, 33, '見よ、万軍の主、主が恐ろしい勢いで枝を切り払われる。丈の高いものは切り倒され、そびえたものは低くなる。'),
('JPN', '以赛亚书', 23, 10, 34, '主は林の茂みを鉄の斧で切り倒し、レバノンは力強い方によって倒される。'),
('JPN', '以赛亚书', 23, 11, 1, 'エッサイの根株から新芽が生え、その根から若枝が出て実を結ぶ。'),
('JPN', '以赛亚书', 23, 11, 2, 'その上に主の霊がとどまる。それは知恵と悟りの霊、思慮と力の霊、主を恐れる、知識の霊である。'),
('JPN', '以赛亚书', 23, 11, 3, 'この方は主を恐れることを喜びとし、その目の見るところによってさばかず、その耳の聞くところによって判決を下さず、'),
('JPN', '以赛亚书', 23, 11, 4, '正義をもって弱い者をさばき、公正をもって地の貧しい者のために判決を下す。口のむちで地を打ち、唇の息で悪しき者を殺す。'),
('JPN', '以赛亚书', 23, 11, 5, '正義がその腰の帯となり、真実がその胴の帯となる。'),
('JPN', '以赛亚书', 23, 11, 6, '狼は子羊とともに宿り、豹は子やぎとともに伏し、子牛、若獅子、肥えた家畜がともにいて、小さな子どもがこれを追って行く。'),
('JPN', '以赛亚书', 23, 11, 7, '雌牛と熊は草をはみ、その子たちはともに伏し、獅子も牛のように藁を食う。'),
('JPN', '以赛亚书', 23, 11, 8, '乳飲み子はコブラの穴の上で戯れ、乳離れした子は、まむしの巣に手を伸ばす。'),
('JPN', '以赛亚书', 23, 11, 9, 'わたしの聖なる山のどこにおいても、これらは害を加えず、滅ぼさない。主を知ることが、海をおおう水のように地に満ちるからである。'),
('JPN', '以赛亚书', 23, 11, 10, 'その日になると、エッサイの根はもろもろの民の旗として立ち、国々は彼を求め、彼のとどまるところは栄光に輝く。'),
('JPN', '以赛亚书', 23, 11, 11, 'その日、主は再び御手を伸ばし、ご自分の民の残りの者を買い取られる。彼らは、アッシリア、エジプト、パテロス、クシュ、エラム、シンアル、ハマテ、海の島々に残っている者たちである。'),
('JPN', '以赛亚书', 23, 11, 12, '主は国々のために旗を揚げ、イスラエルの散らされた者を取り集め、ユダの追い散らされた者を地の四隅から集められる。'),
('JPN', '以赛亚书', 23, 11, 13, 'エフライムのねたみは去り、ユダに敵する者は断ち切られる。エフライムはユダをねたまず、ユダもエフライムを敵としない。'),
('JPN', '以赛亚书', 23, 11, 14, '彼らは西の方、ペリシテ人の肩に飛びかかり、ともに東の子らからかすめ奪う。彼らはエドムとモアブにも手を伸ばし、アンモン人も彼らに従う。'),
('JPN', '以赛亚书', 23, 11, 15, '主はエジプトの海の入江を干上がらせ、また、その焼けつく風の中で御手をその川に向かって振り動かし、それを打って七つの水無し川とし、履き物のままで歩けるようにする。'),
('JPN', '以赛亚书', 23, 11, 16, '残されている御民の残りの者のためにアッシリアから大路が備えられる。イスラエルがエジプトの地から上って来た日に、イスラエルのために備えられたように。'),
('JPN', '以赛亚书', 23, 12, 1, 'その日、あなたは言う。「主よ、感謝します。あなたは私に怒られたのに、あなたの怒りは去り、私を慰めてくださったからです。」'),
('JPN', '以赛亚书', 23, 12, 2, '見よ、神は私の救い。私は信頼して恐れない。ヤハ、主は私の力、私のほめ歌。私のために救いとなられた。'),
('JPN', '以赛亚书', 23, 12, 3, 'あなたがたは喜びながら水を汲む。救いの泉から。'),
('JPN', '以赛亚书', 23, 12, 4, 'その日、あなたがたは言う。「主に感謝せよ。その御名を呼び求めよ。そのみわざを、もろもろの民の中に知らせよ。御名があがめられていることを語り告げよ。'),
('JPN', '以赛亚书', 23, 12, 5, '主をほめ歌え。主はすばらしいことをされた。これを全地に知らせよ。'),
('JPN', '以赛亚书', 23, 12, 6, 'シオンに住む者よ。大声をあげて喜び歌え。イスラエルの聖なる方は、あなたの中におられる大いなる方。」'),
('JPN', '以赛亚书', 23, 13, 1, 'バビロンについての宣告。これはアモツの子イザヤが見たものである。'),
('JPN', '以赛亚书', 23, 13, 2, '「はげ山の上に旗を掲げ、彼らに向かって声をあげ、手を振って、彼らを貴族の門に入らせよ。'),
('JPN', '以赛亚书', 23, 13, 3, 'わたしは、わたしに聖別された者たちに命じ、また、わが怒りを晴らす勇士たち、わが威光に歓喜する者たちを呼び集めた。」'),
('JPN', '以赛亚书', 23, 13, 4, 'おびただしい民にも似た、山々のとどろく音、集まって来る国々、王国のどよめく音がする。万軍の主が軍隊を召集しておられるのだ。'),
('JPN', '以赛亚书', 23, 13, 5, '彼らは遠い地から、天の果てからやって来る。全世界を滅ぼすための、主とその憤りの器だ。'),
('JPN', '以赛亚书', 23, 13, 6, '泣き叫べ。主の日は近い。それは全能者からの破壊としてやって来る。'),
('JPN', '以赛亚书', 23, 13, 7, 'それゆえ、すべての者は気力を失い、すべての人の心は萎える。'),
('JPN', '以赛亚书', 23, 13, 8, '彼らはおじ惑い、子を産む女が身もだえするように、苦しみと激しい痛みが彼らを襲う。彼らは炎のような顔で互いに驚く。'),
('JPN', '以赛亚书', 23, 13, 9, '「見よ、主の日が来る。憤りと燃える怒りの、残酷な日が。地は荒廃に帰し、主は罪人どもをそこから根絶やしにする。'),
('JPN', '以赛亚书', 23, 13, 10, '天の星、天のオリオン座はその光を放たず、太陽は日の出から暗く、月もその光を放たない。'),
('JPN', '以赛亚书', 23, 13, 11, 'わたしは、世界をその悪のゆえに罰し、悪しき者をその咎のゆえに罰する。不遜な者の誇りをくじき、横暴な者の高ぶりを低くする。'),
('JPN', '以赛亚书', 23, 13, 12, 'わたしは人を純金よりも、人間をオフィルの金よりも尊くする。'),
('JPN', '以赛亚书', 23, 13, 13, 'それゆえ、わたしは天を震わせる。大地はその基から揺れ動く。万軍の主の憤りによって、その燃える怒りの日に。'),
('JPN', '以赛亚书', 23, 13, 14, '追い立てられた、かもしかのように、集める者のいない羊の群れのようになって、彼らはそれぞれ自分の民の方に向かい、それぞれ自分の地へ逃げ去る。'),
('JPN', '以赛亚书', 23, 13, 15, '見つけられた者は、みな刺し殺され、連れて行かれた者は、みな剣に倒れる。'),
('JPN', '以赛亚书', 23, 13, 16, '彼らの幼子たちは目の前で八つ裂きにされ、家は略奪され、妻は犯される。'),
('JPN', '以赛亚书', 23, 13, 17, '見よ、わたしは彼らに対してメディア人を奮い立たせる。彼らは銀をものともせず、金さえ喜ばず、'),
('JPN', '以赛亚书', 23, 13, 18, 'その弓は若者たちを撃ち倒す。彼らは胎の実さえあわれまず、子どもたちにさえあわれみをかけない。'),
('JPN', '以赛亚书', 23, 13, 19, 'こうして、諸王国の誉れ、カルデア人の輝かしい誇りであるバビロンは、神がソドム、ゴモラを滅ぼしたときのようになる。'),
('JPN', '以赛亚书', 23, 13, 20, 'そこには永久に住む者もなく、代々にわたり、住みつく者もない。アラビア人もそこには天幕を張らず、牧者たちもそこに群れを伏させない。'),
('JPN', '以赛亚书', 23, 13, 21, 'そこには荒野の獣が伏し、彼らの家々には、みみずくがあふれる。そこには、だちょうも住み、雄やぎがそこで飛び跳ねる。'),
('JPN', '以赛亚书', 23, 13, 22, '山犬はその砦で、ジャッカルは豪華な宮殿でほえ交わす。その時が来るのは近く、その日はもう延ばされることはない。」'),
('JPN', '以赛亚书', 23, 14, 1, 'まことに、主はヤコブをあわれみ、再びイスラエルを選んで、彼らを自分たちの土地に憩わせる。寄留者も彼らに連なり、ヤコブの家に加わる。'),
('JPN', '以赛亚书', 23, 14, 2, '諸国の民は彼らを迎え、彼らのところに導き入れる。イスラエルの家は主の土地で、その寄留者を男奴隷、女奴隷として所有し、自分たちを捕らえた者を捕らわれ人にし、自分たちを追い立てた者を支配するようになる。'),
('JPN', '以赛亚书', 23, 14, 3, '主が、あなたの痛み、あなたへの激しい怒りを除き、あなたに負わせた過酷な労役を解いて、あなたを憩わせる日に、'),
('JPN', '以赛亚书', 23, 14, 4, 'あなたはバビロンの王について、このような嘲りの歌を歌って言う。「虐げる者はどのようにして果てたのか。横暴はどのようにして終わったのか。'),
('JPN', '以赛亚书', 23, 14, 5, '主が悪しき者の杖を、支配者の笏を折られたのだ。'),
('JPN', '以赛亚书', 23, 14, 6, '彼は激怒して諸国の民を討ち、絶え間なく彼らを討ち、怒って国々を容赦なく虐げて支配したものだったが。'),
('JPN', '以赛亚书', 23, 14, 7, '全地は安らかに憩い、喜びの歌声をあげる。'),
('JPN', '以赛亚书', 23, 14, 8, 'もみの木もレバノンの杉も、おまえのことを喜ぶ。『おまえが倒れ伏したときから、もう私たちを切り倒す者は上って来ない。』'),
('JPN', '以赛亚书', 23, 14, 9, 'よみは、下界でおまえが来るのを迎えようとざわめき、死者の霊たち、地のすべての指導者たちを揺り起こし、国々のすべての王をその王座から立ち上がらせる。'),
('JPN', '以赛亚书', 23, 14, 10, '彼らはみな、おまえに告げる。『おまえもまた、私たちのように弱くされ、私たちに似た者になった。』'),
('JPN', '以赛亚书', 23, 14, 11, 'おまえの誇り、おまえの琴の音はよみに落とされ、おまえの下には、うじ虫が敷かれ、虫けらがおまえの覆いとなる。'),
('JPN', '以赛亚书', 23, 14, 12, '明けの明星、暁の子よ。どうしておまえは天から落ちたのか。国々を打ち破った者よ。どうしておまえは地に切り倒されたのか。'),
('JPN', '以赛亚书', 23, 14, 13, 'おまえは心の中で言った。『私は天に上ろう。神の星々のはるか上に私の王座を上げ、北の果てにある会合の山で座に着こう。'),
('JPN', '以赛亚书', 23, 14, 14, '密雲の頂に上り、いと高き方のようになろう。』'),
('JPN', '以赛亚书', 23, 14, 15, 'だが、おまえはよみに落とされ、穴の底に落とされる。'),
('JPN', '以赛亚书', 23, 14, 16, 'おまえを見る者は、おまえを見つめ、おまえについて思いを巡らす。『この者が、地を震えさせ、王国を震え上がらせ、'),
('JPN', '以赛亚书', 23, 14, 17, '世界を荒野のようにし、町々を壊し、捕虜たちを家に帰さなかった者なのか。』'),
('JPN', '以赛亚书', 23, 14, 18, '諸国のすべての王たちはみな、それぞれ自分の墓で、尊ばれて眠っている。'),
('JPN', '以赛亚书', 23, 14, 19, 'しかしおまえは、忌み嫌われる枝のように、墓の外に投げ捨てられる。剣で刺し殺された者たちで、おまえはおおわれ、屍のように、墓穴に下る者たちに踏みつけられる。'),
('JPN', '以赛亚书', 23, 14, 20, 'おまえは墓の中で彼らとともになることはない。自分の地を滅ぼし、自分の民を虐殺したからだ。悪を行う者どもの子孫は永久に、その名を呼ばれることはない。'),
('JPN', '以赛亚书', 23, 14, 21, '彼の子らのために屠り場を備えよ。先祖の咎のためだ。彼らが立って地を占領し、世界の面を町々で満たさないように。」'),
('JPN', '以赛亚书', 23, 14, 22, '「わたしは彼らに向かって立ち上がる。──万軍の主のことば──わたしはバビロンから、その名も、残った者も、子孫も末裔も絶ち滅ぼす。──主のことば──'),
('JPN', '以赛亚书', 23, 14, 23, 'わたしはこれを針ねずみの領地、水のある沢とし、滅びのほうきで一掃する。──万軍の主のことば。」'),
('JPN', '以赛亚书', 23, 14, 24, '万軍の主は誓って言われた。「必ず、わたしの考えたとおりに事は成り、わたしの図ったとおりに成就する。'),
('JPN', '以赛亚书', 23, 14, 25, 'わたしはアッシリアをわたしの地で打ち破り、わたしの山で踏みつける。アッシリアのくびきは彼らの上から除かれ、その重荷は彼らの肩から除かれる。」'),
('JPN', '以赛亚书', 23, 14, 26, 'これが、全地に対して立てられた計画。これが、万国に対して伸ばされた御手。'),
('JPN', '以赛亚书', 23, 14, 27, '万軍の主が計画されたことを、だれがくつがえせるだろうか。御手が伸ばされている。だれがそれを押し戻せるだろうか。'),
('JPN', '以赛亚书', 23, 14, 28, 'アハズ王が死んだ年、この宣告があった。'),
('JPN', '以赛亚书', 23, 14, 29, '「喜ぶな、ペリシテの全土よ。おまえを打った杖が折られたからといって。蛇の根からまむしが出て、その実は、飛び回る燃える蛇となるのだから。'),
('JPN', '以赛亚书', 23, 14, 30, '弱い者たちの長子は養われ、貧しい者は安らかに伏す。しかし、わたしはおまえの根を飢えで死なせる。おまえの残りの者は殺される。'),
('JPN', '以赛亚书', 23, 14, 31, '門よ、泣き叫べ。町よ、叫べ。ペリシテの全土は震えおののけ。北から煙が上がり、その編隊から落伍する者がいないからだ。'),
('JPN', '以赛亚书', 23, 14, 32, '異邦の使者たちにどう答えるべきか。『主がシオンの礎を据えられたのだ。主の民の苦しむ者たちは、ここに身を避ける。』」'),
('JPN', '以赛亚书', 23, 15, 1, 'モアブについての宣告。「ああ、一夜のうちにアルは荒らされ、モアブは滅び失せる。ああ、一夜のうちにキルは荒らされ、モアブは滅び失せる。'),
('JPN', '以赛亚书', 23, 15, 2, 'モアブは宮に、ディボンは高き所に、泣くために上る。ネボとメデバのことでモアブは泣き叫ぶ。頭をみな剃り落とし、ひげもみな切り落として。'),
('JPN', '以赛亚书', 23, 15, 3, 'その通りでは、腰に粗布をまとい、その屋上や広場では、みな涙を流して泣き叫ぶ。'),
('JPN', '以赛亚书', 23, 15, 4, 'ヘシュボンとエルアレは叫び、その叫び声がヤハツまで聞こえる。それゆえ、モアブの武装した者たちはわめく。そのたましいはわななく。'),
('JPN', '以赛亚书', 23, 15, 5, 'わたしの心はモアブのために叫ぶ。逃げ延びる者たちはツォアルまで、エグラテ・シェリシヤまで逃れる。ああ、彼らはルヒテの坂を泣きながら登り、ホロナイムへの道で破滅の叫びをあげる。'),
('JPN', '以赛亚书', 23, 15, 6, 'ああ、ニムリムの水は荒廃した地となり、草は枯れ、若草も尽き果てて、緑もなくなる。'),
('JPN', '以赛亚书', 23, 15, 7, 'それゆえ彼らは、残していた物や蓄えていた物を、アラビム川を越えて運んで行く。'),
('JPN', '以赛亚书', 23, 15, 8, 'ああ、叫び声がモアブの領土に響き渡り、その泣き声がエグライムまで、その泣き声がベエル・エリムまで届く。'),
('JPN', '以赛亚书', 23, 15, 9, 'ああ、ディモンの水は血で満ちる。わたしはさらに、ディモンにわざわいをもたらす。モアブの逃れた者、その土地に残った者に、一頭の獅子を。」'),
('JPN', '以赛亚书', 23, 16, 1, '「おまえたちは、子羊をこの国の支配者に送れ。セラから荒野を経て、娘シオンの山に。'),
('JPN', '以赛亚书', 23, 16, 2, 'モアブの娘たちはアルノンの渡し場で、巣から放り出されて、逃げ惑う鳥のようになる。」'),
('JPN', '以赛亚书', 23, 16, 3, '「あなたは、助言を与え、事を決めよ。昼のさなかにも、あなたの影を夜のようにせよ。散らされた者をかくまい、逃れて来る者を渡すな。'),
('JPN', '以赛亚书', 23, 16, 4, 'あなたの中にモアブの散らされた者を宿らせ、荒らす者から逃れる者の隠れ家となれ。虐げる者が死んで破壊も終わり、踏みつける者が地から消え失せるとき、'),
('JPN', '以赛亚书', 23, 16, 5, '一つの王座が恵みによって堅く立てられる。ダビデの天幕で真実をもってそこに座すのは、さばきをし、公正を求め、速やかに義を行う者。'),
('JPN', '以赛亚书', 23, 16, 6, 'われわれはモアブの高ぶりを聞いた。彼は実に高慢だ。その誇りと高ぶりと不遜さ、その自慢話は正しくない。'),
('JPN', '以赛亚书', 23, 16, 7, 'それゆえ、モアブはモアブ自身のために泣き叫び、すべての者が泣き叫ぶ。ただ打ちのめされて、キル・ハレセテの干しぶどうの菓子のために嘆く。'),
('JPN', '以赛亚书', 23, 16, 8, 'ヘシュボンの畑もシブマのぶどうの木も枯れた。国々の主たちがその房を打ったのだ。その房はヤゼルに達し、荒野を巡り、つるは伸びて海を越えていたのに。'),
('JPN', '以赛亚书', 23, 16, 9, 'それゆえ、わたしはヤゼルのために、シブマのぶどうの木のために泣く。ヘシュボンとエルアレよ、わたしはわたしの涙でおまえをぬらす。おまえの夏の果物と収穫を喜ぶ声が絶えてしまったからだ。'),
('JPN', '以赛亚书', 23, 16, 10, '喜びと楽しみは果樹園から取り去られる。ぶどう畑の中で喜び歌うこともなく、大声で叫ぶこともない。踏み場でぶどう踏みをする者も、もう踏まない。わたしが喜びの声を絶えさせたのだ。'),
('JPN', '以赛亚书', 23, 16, 11, 'それゆえ、わたしのはらわたはモアブのために、わたしの内臓はキル・ヘレスのために、竪琴のようにわななく。'),
('JPN', '以赛亚书', 23, 16, 12, 'モアブが高き所に詣でて、そこで身が疲れ果てるまでのことをしても、その聖所に入って祈っても、何にもならない。」'),
('JPN', '以赛亚书', 23, 16, 13, 'これが、以前から主がモアブについて語っておられたことばである。'),
('JPN', '以赛亚书', 23, 16, 14, '今や主は次のように告げられる。「雇い人の年季と同じ三年のうちに、モアブの栄光は、そのおびただしい数の群衆とともに軽んじられ、残った者もしばらくすれば力がなくなる」と。'),
('JPN', '以赛亚书', 23, 17, 1, 'ダマスコについての宣告。「見よ。ダマスコは取り去られて都でなくなり、瓦礫の山となる。'),
('JPN', '以赛亚书', 23, 17, 2, 'アロエルの町々は捨てられて家畜の群れのものとなり、群れはそこに伏して、それを脅かす者はいなくなる。'),
('JPN', '以赛亚书', 23, 17, 3, 'エフライムは要塞を失い、ダマスコは王国を失う。アラムの残った者はイスラエルの子らの栄光のようになる。──万軍の主のことば。'),
('JPN', '以赛亚书', 23, 17, 4, 'その日、ヤコブの栄光は衰え、その肥えた肉は痩せ細る。'),
('JPN', '以赛亚书', 23, 17, 5, '刈り入れ人が立ち穂を集めて、その腕に穂を刈り入れるときのようになる。レファイムの谷で落ち穂を拾うときのように。'),
('JPN', '以赛亚书', 23, 17, 6, 'オリーブを打ち落とすときのように、取り残しの実が中に残される。こずえには二つ三つの熟れた実が、実りの多い枝には四つ五つが残される。──イスラエルの神、主のことば。」'),
('JPN', '以赛亚书', 23, 17, 7, 'その日、人は自分を造った方に目を留め、その目はイスラエルの聖なる方を見る。'),
('JPN', '以赛亚书', 23, 17, 8, '自分の手で造った祭壇に目を留めず、自分の指で造った物、アシェラ像や香の台は見ない。'),
('JPN', '以赛亚书', 23, 17, 9, 'その日、その堅固な町々は、森の中の見捨てられた場所、かつてイスラエル人によって見捨てられた山の頂のようになって、荒れ果てる。'),
('JPN', '以赛亚书', 23, 17, 10, 'あなたが救いの神を忘れ、あなたの力の岩を覚えていなかったからだ。それゆえ、あなたが好ましい植木を植え、他国のぶどうのつるをさしても、'),
('JPN', '以赛亚书', 23, 17, 11, 'あるいは、あなたが植えた日にそれを生長させ、朝のうちに種を芽生えさせても、病と癒やしがたい痛みの日には、その収穫は消え去る。'),
('JPN', '以赛亚书', 23, 17, 12, 'ああ、多くの国々の民のざわめき。彼らは、海のざわめきのようにざわめく。ああ、国民のどよめき。彼らは、激流のどよめきのようにどよめく。'),
('JPN', '以赛亚书', 23, 17, 13, '国民は、大水のどよめきのようにどよめく。しかしそれは、叱りつけると遠くへ逃げる。山の上で風に吹かれる籾殻のように、つむじ風の前でうず巻くちりのように、彼らは吹き飛ばされる。'),
('JPN', '以赛亚书', 23, 17, 14, '夕暮れには、見よ、突然の恐怖。夜明け前に彼らはいなくなる。これこそ、私たちから奪い取る者たちの取り分、私たちをかすめ奪う者たちが受ける割り当て。'),
('JPN', '以赛亚书', 23, 18, 1, 'ああ、羽コオロギの国よ。この国はクシュの幾多の川のかなたにあり、'),
('JPN', '以赛亚书', 23, 18, 2, 'パピルスの船を水に浮かべて、海路で使いを送る。すばやい使者よ、行け。背が高く肌の滑らかな国民のところへ。あちこちで恐れられている民のところへ。その国土を多くの川が分けている、力強い、踏みにじる国へ。'),
('JPN', '以赛亚书', 23, 18, 3, '世界のすべての住民よ。地に住むすべての者よ。山々に旗が揚がるときは見よ。角笛が吹き鳴らされるときは聞け。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '以赛亚书', 23, 18, 4, '主が私にこう言われたからだ。「わたしは静まり、わたしのところから眺める。照りつける日差しの暑さのように、刈り入れ時の暑さの中の雨雲のように。」'),
('JPN', '以赛亚书', 23, 18, 5, '刈り入れの前、花が終わって、花房が熟したぶどうになるとき、人はその枝を鎌で切り、そのつるを取って除き去るからだ。'),
('JPN', '以赛亚书', 23, 18, 6, 'それらはみなともに、山々の猛禽や野獣のために投げ捨てられる。猛禽はその上で夏を過ごし、野獣はみな、その上で冬を過ごす。'),
('JPN', '以赛亚书', 23, 18, 7, 'そのとき、背が高く肌の滑らかな民、あちこちで恐れられている民、その国土を多くの川が分けている、力強い踏みにじる国民から、万軍の主の名のある場所、シオンの山へ、万軍の主のために贈り物が運ばれて来る。'),
('JPN', '以赛亚书', 23, 19, 1, 'エジプトについての宣告。見よ。主は速い密雲に乗ってエジプトに来られる。エジプトの偽りの神々はその前にわななき、エジプト人の心も真底から萎える。'),
('JPN', '以赛亚书', 23, 19, 2, '「わたしはエジプト人を駆り立てて、エジプト人にはむかわせる。彼らは、兄弟は兄弟と、友人は友人と、町は町と、王国は王国と争い合う。'),
('JPN', '以赛亚书', 23, 19, 3, 'エジプトの霊はその中で衰える。わたしがその計画をかき乱すと、彼らは偽りの神々や死霊、霊媒や口寄せに伺いを立てる。'),
('JPN', '以赛亚书', 23, 19, 4, 'わたしはエジプト人を厳しい主人の手に引き渡す。力ある王が彼らを治める。──万軍の主、主のことば。」'),
('JPN', '以赛亚书', 23, 19, 5, '海の水は乾き、川は干上がり、涸れる。'),
('JPN', '以赛亚书', 23, 19, 6, '多くの運河は臭くなり、エジプトの川は、水かさが減って干上がり、葦や、い草も枯れ果てる。'),
('JPN', '以赛亚书', 23, 19, 7, 'ナイル川とその河口の水草も。その川の種床もみな涸れて、吹き飛ばされて何もない。'),
('JPN', '以赛亚书', 23, 19, 8, '漁師たちは悲しみ、ナイル川で釣りをする者もみな嘆き、水の上に網を打つ者も打ちしおれる。'),
('JPN', '以赛亚书', 23, 19, 9, '梳いた亜麻を扱う職人や白布を織る者は恥を見、'),
('JPN', '以赛亚书', 23, 19, 10, 'この国の機織人たちは砕かれ、雇われて働く者はみな心を痛める。'),
('JPN', '以赛亚书', 23, 19, 11, 'ツォアンの首長たちは全く愚か者だ。ファラオの知恵ある助言者たちも愚かなはかりごとをめぐらす。どうして、あなたがたはファラオに向かって「私は知恵ある者の子、昔の王たちの子です」と言えるのか。'),
('JPN', '以赛亚书', 23, 19, 12, 'あなたの知恵ある者たちは、いったいどこにいるのか。彼らがあなたに告げ、知らせればよい。万軍の主がエジプトに何を計画されたかを。'),
('JPN', '以赛亚书', 23, 19, 13, 'ツォアンの首長たちは愚かになり、メンフィスの首長たちは惑わされた。自分の諸族のかしらたちがエジプトをよろめかせたのだ。'),
('JPN', '以赛亚书', 23, 19, 14, '主がエジプトの中に混乱の霊を吹き入れられたので、彼らは、そのあらゆる行いによってエジプトをよろめかせる。まるで酔いどれが吐きながらよろめくように。'),
('JPN', '以赛亚书', 23, 19, 15, '頭も尾も、なつめ椰子の葉も葦も、エジプト人のために、なすべきわざがない。'),
('JPN', '以赛亚书', 23, 19, 16, 'その日、エジプト人は女のようになり、万軍の主が自分たちに向かって振り上げる御手の前に、恐れおののく。'),
('JPN', '以赛亚书', 23, 19, 17, 'ユダの地はエジプトにとって恐怖となる。これを思い出す者はみな、万軍の主がエジプトに対して図る計画のゆえにおののく。'),
('JPN', '以赛亚书', 23, 19, 18, 'その日、エジプトの地には、カナン語を話し、万軍の主に誓いを立てる五つの町が起こる。その一つは、イル・ハ・ヘレスと言われる。'),
('JPN', '以赛亚书', 23, 19, 19, 'その日、エジプトの地の真ん中には主のために一つの祭壇が建てられ、その国境のそばには主のために一つの石の柱が立てられる。'),
('JPN', '以赛亚书', 23, 19, 20, 'それはエジプトの地で、万軍の主のしるしとなり、証しとなる。彼らが虐げられて主に叫ぶと、主は彼らのために戦い、彼らを救い出す救い主を送られる。'),
('JPN', '以赛亚书', 23, 19, 21, 'そのようにして主はエジプト人にご自分を示し、その日、エジプト人は主を知る。そしていけにえとささげ物をもって仕え、主に誓願を立ててこれを果たす。'),
('JPN', '以赛亚书', 23, 19, 22, '主はエジプト人を打ち、打って彼らを癒やされる。彼らが主に立ち返れば、彼らの願いを聞き入れ、彼らを癒やされる。'),
('JPN', '以赛亚书', 23, 19, 23, 'その日、エジプトからアッシリアへの大路ができ、アッシリア人はエジプトに、エジプト人はアッシリアに行き、エジプト人はアッシリア人とともに主に仕える。'),
('JPN', '以赛亚书', 23, 19, 24, 'その日、イスラエルはエジプトとアッシリアと並ぶ第三のものとなり、大地の真ん中で祝福を受ける。'),
('JPN', '以赛亚书', 23, 19, 25, '万軍の主は祝福して言われる。「わたしの民エジプト、わたしの手で造ったアッシリア、わたしのゆずりの民イスラエルに祝福があるように。」'),
('JPN', '以赛亚书', 23, 20, 1, 'アッシリアの王サルゴンによって派遣されたタルタンが、アシュドデに来て、アシュドデと戦って、これを攻め取った年のこと。'),
('JPN', '以赛亚书', 23, 20, 2, '当時、主はアモツの子イザヤによって、すでにこう語っておられた。「行って、あなたの腰の粗布を解き、あなたの足の履き物を脱げ。」彼はそのようにし、裸になり、裸足で歩いていた。'),
('JPN', '以赛亚书', 23, 20, 3, '主は言われた。「わたしのしもべイザヤが、エジプトとクシュに対するしるし、また前兆として、三年間裸になり、裸足で歩いたように、'),
('JPN', '以赛亚书', 23, 20, 4, 'そのように、アッシリアの王はエジプトの捕虜とクシュの捕囚の民を、若い者も年寄りも裸にして、裸足のまま、尻をあらわにして、エジプトの恥をさらしたまま連れて行く。'),
('JPN', '以赛亚书', 23, 20, 5, '人々は、クシュを頼みとし、エジプトを誇りとしていたゆえに、打ちのめされ、また恥を見る。'),
('JPN', '以赛亚书', 23, 20, 6, 'その日、この海辺の住民は言う。『見よ。アッシリアの王の前から逃れようと、助けを求めて逃げて来たわれわれの拠り所がこの始末だ。われわれは、どうして助かることができるだろうか』と。」'),
('JPN', '以赛亚书', 23, 21, 1, '海の荒野についての宣告。ネゲブに吹きまくるつむじ風のように、それは荒野から、恐ろしい地からやって来る。'),
('JPN', '以赛亚书', 23, 21, 2, '厳しい幻が私に示された。裏切る者は裏切り、荒らす者は荒らす。エラムよ、上れ。メディアよ、囲め。すべての嘆きを私は終わらせる。'),
('JPN', '以赛亚书', 23, 21, 3, 'それゆえ、戦慄が私の腰に満ち、子を産む時のような苦しみが私をとらえる。私は心乱れて、聞くことができない。恐ろしさのあまり、見ることができない。'),
('JPN', '以赛亚书', 23, 21, 4, '私の心は迷い、戦慄が私を襲った。私が恋い慕ったたそがれも、私をおびえさせるものとなった。'),
('JPN', '以赛亚书', 23, 21, 5, '彼らは食卓を整え、座席を並べて、食べたり飲んだりしている。「立ち上がれ、首長たち。盾に油を塗れ。」'),
('JPN', '以赛亚书', 23, 21, 6, '主は私にこう言われた。「さあ、見張りを立たせ、見たことを告げさせよ。'),
('JPN', '以赛亚书', 23, 21, 7, '戦車や二列に並んだ騎兵、ろばに乗る者やらくだに乗る者を見たなら、よく注意を払わせよ。」'),
('JPN', '以赛亚书', 23, 21, 8, 'その人は、獅子のように叫んだ。「主よ。私は昼はいつも見張り場に立ち、夜ごとに自分の物見のやぐらについています。'),
('JPN', '以赛亚书', 23, 21, 9, '見てください。今、戦車や兵士、二列に並んだ騎兵が来ます。彼らは互いに言っています。『倒れた。バビロンは倒れた。その国の神々の、すべての刻んだ像も地に打ち砕かれた』と。」'),
('JPN', '以赛亚书', 23, 21, 10, '踏みにじられた私の民、打ち場の私の子らよ。イスラエルの神、万軍の主から聞いたことを、私はあなたがたに告げたのだ。'),
('JPN', '以赛亚书', 23, 21, 11, 'ドマについての宣告。セイルから私に叫ぶ者がある。「夜回りよ、今は夜の何時か。夜回りよ、今は夜の何時か。」'),
('JPN', '以赛亚书', 23, 21, 12, '夜回りは言った。「朝は来る。また夜も来る。尋ねたければ尋ねよ。もう一度、来るがよい。」'),
('JPN', '以赛亚书', 23, 21, 13, 'アラビアについての宣告。デダン人の隊商よ、アラビアの林に宿れ。'),
('JPN', '以赛亚书', 23, 21, 14, 'テマの地の住民よ、渇いている者を迎えて水をやれ。逃れて来た者にパンを与えよ。'),
('JPN', '以赛亚书', 23, 21, 15, '彼らは剣や抜き身の剣から、張られた弓や激しい戦いから逃れて来たのだから。'),
('JPN', '以赛亚书', 23, 21, 16, 'まことに、主は私にこう言われる。「雇い人の年季のように、もう一年でケダルのすべての栄光は尽きる。'),
('JPN', '以赛亚书', 23, 21, 17, 'ケダル人の勇士たちで、残る射手は数少なくなる。」まことに、イスラエルの神、主が告げられる。'),
('JPN', '以赛亚书', 23, 22, 1, '幻の谷についての宣告。これは、いったいどうしたことか。みな屋根に上ったりして。'),
('JPN', '以赛亚书', 23, 22, 2, '喧噪に満ちた騒がしい町、おごった都よ。おまえのうちの殺された者たちは、剣で刺し殺されたのでもなく戦死したのでもない。'),
('JPN', '以赛亚书', 23, 22, 3, 'おまえの首領たちは、こぞって逃げたが、弓を引かないうちに捕らえられた。おまえのうちの見つけられた者は、遠くへ逃げ去ったが、みな捕らえられた。'),
('JPN', '以赛亚书', 23, 22, 4, 'それゆえ、私は言う。「私から目をそらせ。私は激しく泣きたい。私の民、この娘の破滅のことで、無理に私を慰めるな。」'),
('JPN', '以赛亚书', 23, 22, 5, 'なぜなら、恐慌と蹂躙と混乱の日が、万軍の神、主から来るからだ。幻の谷には、城壁の崩壊、山に向かっての叫び。'),
('JPN', '以赛亚书', 23, 22, 6, 'エラムは矢筒を負い、戦車と兵士と騎兵を引き連れ、キルは盾の覆いを外した。'),
('JPN', '以赛亚书', 23, 22, 7, 'おまえの最も美しい平地は戦車で満ち、騎兵は城門に立ち並んだ。'),
('JPN', '以赛亚书', 23, 22, 8, 'こうして主はユダの覆いを除かれた。その日、おまえは森の宮殿の武器に目を向けた。'),
('JPN', '以赛亚书', 23, 22, 9, 'おまえたちはダビデの町に破れが多いのを見て、下の池の水を集めた。'),
('JPN', '以赛亚书', 23, 22, 10, 'また、エルサレムの家々を数え、その家々を取り壊して城壁を補強し、'),
('JPN', '以赛亚书', 23, 22, 11, '二重の城壁の間に貯水池を造って古い池の水を引いた。しかし、おまえたちはこれを造った方には目もくれず、遠い昔にこれを形造った方に目を留めなかった。'),
('JPN', '以赛亚书', 23, 22, 12, 'その日、万軍の神、主は呼びかけられた。「泣いて悲しみ、頭を剃って粗布をまとえ。」'),
('JPN', '以赛亚书', 23, 22, 13, 'しかし、なんとおまえたちは浮かれ楽しみ、牛を殺し、羊を屠り、肉を食べ、ぶどう酒を飲んで言っている。「飲めよ。食べよ。どうせ明日は死ぬのだ」と。'),
('JPN', '以赛亚书', 23, 22, 14, '万軍の主は私の耳に宣告された。「この咎は、おまえたちが死ぬまで決して赦されることはない。」万軍の神、主はそう言われた。'),
('JPN', '以赛亚书', 23, 22, 15, '万軍の神、主はこう言われる。「さあ、宮廷をつかさどるあの執事シェブナのところに行け。'),
('JPN', '以赛亚书', 23, 22, 16, '『あなたは自分のために、ここに墓を掘った。ここはあなたに何の関わりがあるのか。ここはあなたのだれに関わりがあるのか。高いところに自分の墓を掘ったり、岩に自分の住まいを刻んだりして。'),
('JPN', '以赛亚书', 23, 22, 17, 'ああ、勇者よ。主はあなたを遠くに投げやる。あなたをわしづかみにし、'),
('JPN', '以赛亚书', 23, 22, 18, 'あなたをまりのように丸めて、広々とした地に投げ捨てる。そこであなたは死ぬ。そこであなたの誇る戦車も。あなたの主人の家の恥さらしよ。'),
('JPN', '以赛亚书', 23, 22, 19, 'わたしがあなたをその立場から追放する。あなたは自分の地位から引き降ろされる。'),
('JPN', '以赛亚书', 23, 22, 20, 'その日、わたしはわたしのしもべ、ヒルキヤの子エルヤキムを召し、'),
('JPN', '以赛亚书', 23, 22, 21, '彼にあなたの長服を着せ、彼にあなたの飾り帯を締め、彼の手にあなたの権威を委ねる。彼はエルサレムの住民とユダの家の父となる。'),
('JPN', '以赛亚书', 23, 22, 22, 'わたしはまた、彼の肩にダビデの家の鍵を置く。彼が開くと、閉じる者はなく、彼が閉じると、開く者はない。'),
('JPN', '以赛亚书', 23, 22, 23, 'わたしは彼を杭として、確かな場所に打ち込む。彼はその父の家にとって栄光の座となる。'),
('JPN', '以赛亚书', 23, 22, 24, '彼の上に、父の家のすべての栄光がかけられる。子も孫も、すべての小さい器も、鉢からすべての壺に至るまで。'),
('JPN', '以赛亚书', 23, 22, 25, 'その日──万軍の主のことば──確かな場所に打ち込まれた杭は抜き取られ、折られて落ち、その上にかかっていた荷も取り壊される。──主はそう語られた。』」'),
('JPN', '以赛亚书', 23, 23, 1, 'ツロについての宣告。タルシシュの船よ、泣き叫べ。ツロは荒らされて家もなく、そこには入れない。キティムの地から、それは彼らに示される。'),
('JPN', '以赛亚书', 23, 23, 2, '海辺の住民よ、黙れ。海を渡るシドンの商人はおまえを富ませた。'),
('JPN', '以赛亚书', 23, 23, 3, '大海原で、シホルの穀物、ナイルの刈り入れがおまえの収穫となり、おまえは諸国の商いの場となった。'),
('JPN', '以赛亚书', 23, 23, 4, '「シドンよ、恥を見よ」と海が言う。海の砦がこう言っている。「私は産みの苦しみをせず、子を産まず、若い男を育てず、若い女を養ったこともない。」'),
('JPN', '以赛亚书', 23, 23, 5, 'このうわさがエジプトに達すると、人々はツロのうわさを聞いて、激しくもだえる。'),
('JPN', '以赛亚书', 23, 23, 6, '海辺の住民よ、タルシシュへ渡って、泣き叫べ。'),
('JPN', '以赛亚书', 23, 23, 7, 'これが、おまえたちが誇りとした町なのか。その起こりは古く、人々はその足で遠くに行って移り住んだのに。'),
('JPN', '以赛亚书', 23, 23, 8, 'だれが、王冠を戴くツロに対してこれを図ったのか。その商人は君主たちで、その貿易商は地で最も尊ばれていたのに。'),
('JPN', '以赛亚书', 23, 23, 9, '万軍の主がそれを図り、すべての麗しい誇りを汚して、地で最も尊ばれている者をみな卑しめられた。'),
('JPN', '以赛亚书', 23, 23, 10, '娘タルシシュよ、ナイル川のように自分の国にあふれよ。もうこれを制する者はいない。'),
('JPN', '以赛亚书', 23, 23, 11, '主は御手を海の上に伸ばし、王国を震わせた。主はカナンについて命令を下し、その砦を滅ぼし尽くした。'),
('JPN', '以赛亚书', 23, 23, 12, 'そして言われた。「もう二度と喜び躍るな。虐げられたおとめ、娘シドンよ、立ってキティムに渡れ。そこでも、おまえは休めない。」'),
('JPN', '以赛亚书', 23, 23, 13, '見よ、カルデア人の地を。この民はもはや存在しない。アッシリア人がこれを荒野の獣のものとして定めた。彼らは、自分の見張りやぐらを立て、宮殿をかすめて、そこを廃墟とした。'),
('JPN', '以赛亚书', 23, 23, 14, 'タルシシュの船よ、泣き叫べ。おまえたちの砦が荒らされたからだ。'),
('JPN', '以赛亚书', 23, 23, 15, 'その日になると、ツロは七十年の間忘れられる。一人の王の生涯ほどの期間である。七十年が終わると、ツロは遊女の歌のようになる。'),
('JPN', '以赛亚书', 23, 23, 16, '「竪琴を取り、町を巡れ、忘れられた遊女よ。うまく弾け、もっと歌え。思い出してもらうために。」'),
('JPN', '以赛亚书', 23, 23, 17, '七十年の終わりに、主はツロを顧みられる。彼女は再び遊女の報酬を得て、地のすべての王国と、地の面で淫行を行う。'),
('JPN', '以赛亚书', 23, 23, 18, 'その儲け、遊女の報酬は、主の聖なるものとなる。それは蓄えられず、積み立てられない。その儲けは、主の前に住む者たちが食べて満ち足り、上等の衣服を着るためのものとなるからだ。'),
('JPN', '以赛亚书', 23, 24, 1, '見よ。主は地を荒れ果てさせ、その面をくつがえして、住民を散らされる。'),
('JPN', '以赛亚书', 23, 24, 2, '民は祭司と等しくなり、男奴隷はその主人と、女奴隷はその女主人と、買い手は売り手と、貸し手は借り手と、債権者は債務者と等しくなる。'),
('JPN', '以赛亚书', 23, 24, 3, '地はすっかり荒れ果て、すべてかすめ奪われる。主がこのことばを語られたからである。'),
('JPN', '以赛亚书', 23, 24, 4, '地は嘆き悲しみ、衰える。世界はしおれ、衰える。地の最も高貴な人たちもしおれる。'),
('JPN', '以赛亚书', 23, 24, 5, '地はその住民の下で汚されている。彼らが律法を犯して定めを変え、永遠の契約を破ったからである。'),
('JPN', '以赛亚书', 23, 24, 6, 'それゆえ、のろいは地を食い尽くし、その地の住民は罰を受ける。それゆえ、地の住民は減り、わずかな者だけが残される。'),
('JPN', '以赛亚书', 23, 24, 7, '新しいぶどう酒は嘆き悲しみ、ぶどうの木はしおれ、心に喜びのある者もみな、うめく。'),
('JPN', '以赛亚书', 23, 24, 8, '陽気なタンバリンの音はやみ、はしゃぐ者たちの騒ぎも消え、陽気な竪琴の音もやむ。'),
('JPN', '以赛亚书', 23, 24, 9, '歌いながらぶどう酒を飲むこともなく、強い酒も、飲む者には苦い。'),
('JPN', '以赛亚书', 23, 24, 10, '都は壊されて荒れ地となり、すべての家は閉ざされて入れない。'),
('JPN', '以赛亚书', 23, 24, 11, '街には、ぶどう酒はなく、哀れな叫び声がある。すべての喜びは薄れ、地の楽しみは取り去られる。'),
('JPN', '以赛亚书', 23, 24, 12, 'その都にはただ荒廃だけが残り、城門は打ち砕かれて荒れ果てる。'),
('JPN', '以赛亚书', 23, 24, 13, 'まことに、大地の真ん中で、諸国の民の間で、オリーブを打ち落とすようなことが、ぶどうの収穫の後に取り残しの実を集めるようなことが起こる。'),
('JPN', '以赛亚书', 23, 24, 14, '彼らは声をあげて喜び歌い、西の方から主の威光をたたえて叫ぶ。'),
('JPN', '以赛亚书', 23, 24, 15, 'それゆえ、東の国々で主をあがめよ。西の島々で、イスラエルの神、主の御名を。'),
('JPN', '以赛亚书', 23, 24, 16, '地の果てから、私たちは、「正しい方に誉れあれ」というほめ歌を聞く。しかし私は言った。「私はだめだ、だめだ。ああ、悲しい。裏切り者が裏切った。裏切り者が裏切り、裏切った。」'),
('JPN', '以赛亚书', 23, 24, 17, '地上の住民よ。恐怖と落とし穴と罠があなたに臨む。'),
('JPN', '以赛亚书', 23, 24, 18, 'その恐怖の叫びから逃げる者は、その落とし穴に落ち、落とし穴から這い上がる者は、その罠に捕らえられる。天の窓が開かれ、地の基が震えるからだ。'),
('JPN', '以赛亚书', 23, 24, 19, '地は割れに割れ、地は破れに破れ、地は揺れに揺れる。'),
('JPN', '以赛亚书', 23, 24, 20, '地は酔いどれのようによろめき、仮小屋のように揺れ動く。地の背きはその上に重くのしかかり、地は倒れて、再び起き上がれない。'),
('JPN', '以赛亚书', 23, 24, 21, 'その日、主は天では天の大軍を、地では地の王たちを罰せられる。'),
('JPN', '以赛亚书', 23, 24, 22, '彼らは、囚人が地下牢に集められるように集められ、牢獄に閉じ込められ、何年かたった後に罰せられる。'),
('JPN', '以赛亚书', 23, 24, 23, '月は辱めを受け、太陽も恥を見る。万軍の主がシオンの山、エルサレムで王となり、栄光がその長老たちの前にあるからである。'),
('JPN', '以赛亚书', 23, 25, 1, '主よ、あなたは私の神。私はあなたをあがめ、御名をほめたたえます。あなたは遠い昔からの不思議なご計画を、まことに、真実に成し遂げられました。'),
('JPN', '以赛亚书', 23, 25, 2, 'あなたは町を石くれの山とし、城壁のある都を廃墟にされたので、他国人の宮殿は町から失せ、もう永久に建てられることはありません。'),
('JPN', '以赛亚书', 23, 25, 3, 'それゆえ、力強い民もあなたをほめたたえ、横暴な国々の都もあなたを恐れます。'),
('JPN', '以赛亚书', 23, 25, 4, 'あなたは弱っている者の砦、貧しい者の、苦しみのときの砦、嵐のときの避け所、暑さを避ける陰となられました。横暴な者たちの息は、壁に吹きつける嵐のようです。'),
('JPN', '以赛亚书', 23, 25, 5, '砂漠の日照りのように、あなたは他国人の騒ぎを抑えられます。暑さが濃い雲の陰で鎮まるように、横暴な者たちの歌は鎮められます。'),
('JPN', '以赛亚书', 23, 25, 6, '万軍の主は、この山の上で万民のために、脂の多い肉の宴会、良いぶどう酒の宴会、髄の多い脂身とよくこされたぶどう酒の宴会を開かれる。'),
('JPN', '以赛亚书', 23, 25, 7, 'この山の上で、万民の上をおおうベールを、万国の上にかぶさる覆いを取り除き、'),
('JPN', '以赛亚书', 23, 25, 8, '永久に死を吞み込まれる。神である主は、すべての顔から涙をぬぐい取り、全地の上からご自分の民の恥辱を取り除かれる。主がそう語られたのだ。'),
('JPN', '以赛亚书', 23, 25, 9, 'その日、人は言う。「見よ。この方こそ、待ち望んでいた私たちの神。私たちを救ってくださる。この方こそ、私たちが待ち望んでいた主。その御救いを楽しみ喜ぼう。」'),
('JPN', '以赛亚书', 23, 25, 10, '主の手がこの山にとどまるとき、モアブはそこで踏みつけられる。藁が汚水の中で踏みつけられるように。'),
('JPN', '以赛亚书', 23, 25, 11, '泳ぐ人が泳ごうとして手を伸ばすように、モアブはその中で手を伸ばす。しかし主は、その手の巧みさも、その高ぶりも低くされる。'),
('JPN', '以赛亚书', 23, 25, 12, 'おまえの要塞、そそり立つ城壁を主は引き倒して、低くし、地に投げつけて、ちりにまでされる。'),
('JPN', '以赛亚书', 23, 26, 1, 'その日、ユダの地でこの歌が歌われる。私たちには強い都がある。神はその城壁と塁で私たちを救ってくださる。'),
('JPN', '以赛亚书', 23, 26, 2, '城門を開けて、忠誠を尽くす正しい民を入らせよ。'),
('JPN', '以赛亚书', 23, 26, 3, '志の堅固な者を、あなたは全き平安のうちに守られます。その人があなたに信頼しているからです。'),
('JPN', '以赛亚书', 23, 26, 4, 'いつまでも主に信頼せよ。ヤハ、主は、とこしえの岩だから。'),
('JPN', '以赛亚书', 23, 26, 5, '主は高い所、そびえ立つ都に住む者を引き倒し、その都を低くして、地にまで下らせ、これを投げつけて、ちりにまで下らされる。'),
('JPN', '以赛亚书', 23, 26, 6, '足がこれを踏みつける。苦しむ者の足、弱い者の足の裏が。'),
('JPN', '以赛亚书', 23, 26, 7, '正しい人の行く道は平らです。あなたは正しい人の道をならし、平らにされます。'),
('JPN', '以赛亚书', 23, 26, 8, '主よ。まことに、あなたのさばきの道で私たちはあなたを待ち望みます。あなたの御名、あなたの呼び名は私のたましいの望みです。'),
('JPN', '以赛亚书', 23, 26, 9, '私のたましいは、夜にあなたを慕います。まことに、私の内なる霊はあなたを切に求めます。まことに、あなたのさばきが地に行われるとき、世界の住民は義を学びます。'),
('JPN', '以赛亚书', 23, 26, 10, '悪しき者は、恵みを受けても義を学びません。公正の地にあっても不正を行い、主のご威光を見ようともしません。'),
('JPN', '以赛亚书', 23, 26, 11, '主よ。あなたの御手が上げられても、彼らは見ようとしません。どうか彼らが、この民へのあなたの熱心を見て、恥じますように。まことに火が、あなたに逆らう者をなめ尽くしますように。'),
('JPN', '以赛亚书', 23, 26, 12, '主よ。あなたは私たちのために平和を備えてくださいます。まことに、私たちのすべてのわざも、あなたが私たちのためになさったことです。'),
('JPN', '以赛亚书', 23, 26, 13, '私たちの神、主よ。あなた以外の多くの君主が私たちを治めました。私たちはただあなただけを、あなたの御名を呼び求めます。'),
('JPN', '以赛亚书', 23, 26, 14, '彼らは死人であって、生き返りません。彼らは死者の霊であって、よみがえりません。それゆえ、あなたは彼らを罰して根絶やしにし、彼らについての記憶をすべて消し去られました。'),
('JPN', '以赛亚书', 23, 26, 15, '主よ。あなたはこの国民を増し加えられました。この国民を増し加え、ご自身の栄光を現し、この国のすべての境を広げられました。'),
('JPN', '以赛亚书', 23, 26, 16, '主よ。苦難の時に彼らはあなたを求め、あなたが懲らしめられたとき、彼らはうめきの声をあげました。'),
('JPN', '以赛亚书', 23, 26, 17, '子を産む時が近づいた妊婦が産みの苦しみで、もだえ叫ぶように、主よ、私たちは御前でそのようでした。'),
('JPN', '以赛亚书', 23, 26, 18, '私たちは身ごもり、産みの苦しみをしました。それはあたかも、風を産むようなものでした。私たちは救いを地にもたらさず、世界の住民はもう生まれてきません。'),
('JPN', '以赛亚书', 23, 26, 19, 'あなたの死人は生き返り、私の屍は、よみがえります。覚めよ、喜び歌え。土のちりの中にとどまる者よ。まことに、あなたの露は光の露。地は死者の霊を生き返らせます。'),
('JPN', '以赛亚书', 23, 26, 20, 'さあ、私の民よ。あなたの部屋に入り、うしろの戸を閉じよ。憤りが過ぎるまで、ほんのしばらく身を隠せ。'),
('JPN', '以赛亚书', 23, 26, 21, 'それは、主がまさにご自分のところから出て、地に住む者の咎を罰せられるからだ。地は、その上に流された血をあらわにし、そこで殺された者たちを再びおおうことはない。'),
('JPN', '以赛亚书', 23, 27, 1, 'その日、主は、鋭い大きな強い剣で、逃げ惑う蛇レビヤタンを、曲がりくねる蛇レビヤタンを罰し、海にいる竜を殺される。'),
('JPN', '以赛亚书', 23, 27, 2, '「その日、麗しいぶどう畑について歌え。'),
('JPN', '以赛亚书', 23, 27, 3, 'わたし、主はそれを見守る者。絶えずこれに水を注ぎ、だれも害を加えないように、夜も昼もこれを見守る。'),
('JPN', '以赛亚书', 23, 27, 4, 'わたしにもう憤りはない。もしも、茨とおどろがわたしと戦えば、わたしはそれを踏みつぶし、それをみな焼き払う。'),
('JPN', '以赛亚书', 23, 27, 5, 'あるいは、もしわたしという砦に頼りたければ、わたしと和を結ぶがよい。和をわたしと結ぶがよい。'),
('JPN', '以赛亚书', 23, 27, 6, '時が来れば、ヤコブは根を張り、イスラエルは芽を出し、花を咲かせ、世界の面を実で満たす。」'),
('JPN', '以赛亚书', 23, 27, 7, '主は、イスラエルを打った者を打ったように、イスラエルを打たれただろうか。イスラエルを殺した者を殺したように、イスラエルを殺されただろうか。'),
('JPN', '以赛亚书', 23, 27, 8, 'あなたは追い立て、追い出し、彼らと争い、東風の日に、激しい息で彼らを吹き払われた。'),
('JPN', '以赛亚书', 23, 27, 9, 'それゆえ、次のようにしてヤコブの不義は赦される。祭壇の石をすべて、粉々にされた石灰のようにし、アシェラ像と香の台を二度と立てなくすること、これが、自分の罪を除いて得る実のすべてだ。'),
('JPN', '以赛亚书', 23, 27, 10, '城壁のある町はひとり寂しく、捨て置かれた牧場のようになり、見捨てられて荒野のようになる。そこで子牛が草をはみ、そこに伏して、そこの木の小枝を食い滅ぼす。'),
('JPN', '以赛亚书', 23, 27, 11, '枝が枯れると、それは壊され、女たちが来て、それに火をつける。これは悟りのない民だからだ。それゆえ、これを造った方はあわれまず、これを形造った方は恵みをお与えにならない。'),
('JPN', '以赛亚书', 23, 27, 12, 'その日、主はあの大河からエジプト川まで穀物の穂を打ち落とされる。イスラエルの子らよ、あなたがたは一人ひとり拾い上げられる。'),
('JPN', '以赛亚书', 23, 27, 13, 'その日、大きな角笛が鳴り渡り、アッシリアの地にいる失われていた者や、エジプトの地に追いやられた者たちが来て、エルサレムの聖なる山で主を礼拝する。'),
('JPN', '以赛亚书', 23, 28, 1, 'わざわいだ。エフライムの酔いどれが誇りとする冠、その麗しい飾りの、しぼんでゆく花。これは、酔いつぶれた者たちの、肥えた谷の頂にある。'),
('JPN', '以赛亚书', 23, 28, 2, '見よ、主のもとには激しく力強いものがある。それは、突き刺さり荒れ狂う雹の嵐のようだ。激しい勢いで押し流す豪雨のようだ。主は御手をもってこれを地に下される。'),
('JPN', '以赛亚书', 23, 28, 3, 'エフライムの酔いどれが誇りとする冠は、足の下に踏みにじられる。'),
('JPN', '以赛亚书', 23, 28, 4, '肥えた谷の頂にあってこれを麗しく飾る花もしぼみ、夏前の初なりのいちじくの実のようになる。だれかがそれを見つけると、すぐに手に取り、吞み込んでしまう。'),
('JPN', '以赛亚书', 23, 28, 5, 'その日、万軍の主は、民の残りの者には輝かしい冠、栄えの飾り輪となり、'),
('JPN', '以赛亚书', 23, 28, 6, 'さばきの座に着く者にはさばきの霊となり、攻撃して来る者を城門で追い返す者には力となられる。'),
('JPN', '以赛亚书', 23, 28, 7, 'しかし、これらの者も、ぶどう酒でよろめき、強い酒でふらつく。祭司も預言者も強い酒でよろめき、ぶどう酒で混乱し、強い酒でふらつく。幻を見ながらよろめき、さばきを下すとき、よろける。'),
('JPN', '以赛亚书', 23, 28, 8, 'どの食卓も吐いた物であふれ、余すところもない。'),
('JPN', '以赛亚书', 23, 28, 9, '「彼は知識をだれに教えようとするのか。知らされたことをだれに悟らせようとするのか。乳離れした子にか。乳房から離された子にか。'),
('JPN', '以赛亚书', 23, 28, 10, '彼は言っている。『ツァウにツァウ、ツァウにツァウ、カウにカウ、カウにカウ、あっちにゼエル、こっちにゼエル』と。」'),
('JPN', '以赛亚书', 23, 28, 11, 'まことに主は、もつれた舌で、異国のことばでこの民に語られる。'),
('JPN', '以赛亚书', 23, 28, 12, '主は彼らに、「ここに憩いがある。疲れた者を憩わせよ。ここに休息がある」と言われたのに、彼らは聞こうとしなかった。'),
('JPN', '以赛亚书', 23, 28, 13, '主は彼らに告げられる。「ツァウにツァウ、ツァウにツァウ、カウにカウ、カウにカウ、あっちにゼエル、こっちにゼエル。」これは、彼らが歩くときうしろに倒れて砕かれ、罠にかかって捕らえられるためである。'),
('JPN', '以赛亚书', 23, 28, 14, 'それゆえ、嘲る者たちよ、主のことばを聞け。エルサレムでこの民を治める者たちよ。'),
('JPN', '以赛亚书', 23, 28, 15, 'あなたがたがこう言ったからだ。「われわれは死と契約を結び、よみと同盟を結んでいる。たとえ、洪水が押し寄せても、それはわれわれには届かない。われわれは、まやかしを避け所とし、偽りに身を隠してきたのだから。」'),
('JPN', '以赛亚书', 23, 28, 16, 'それゆえ、神である主はこう言われる。「見よ、わたしはシオンに一つの石を礎として据える。これは試みを経た石、堅く据えられた礎の、尊い要石。これに信頼する者は慌てふためくことがない。'),
('JPN', '以赛亚书', 23, 28, 17, 'わたしは公正を測り縄とし、義を重りとする。雹はまやかしの避け所を一掃し、水は隠れ家を押し流す。'),
('JPN', '以赛亚书', 23, 28, 18, 'あなたがたの、死との契約は解消され、よみとの同盟は成り立たない。みなぎる天罰が押し寄せると、あなたがたはそれに踏みにじられる。'),
('JPN', '以赛亚书', 23, 28, 19, 'それは押し寄せるたびに、あなたがたを捕らえる。しかも朝ごとに押し寄せる。昼にも夜にも。この知らせを悟るなら、ただ恐怖あるのみ。'),
('JPN', '以赛亚书', 23, 28, 20, 'まことに、寝床は身を伸ばすには短すぎ、覆いも身をくるむには狭すぎる。」'),
('JPN', '以赛亚书', 23, 28, 21, '実に、主は起き上がられる。ペラツィムの山での時のように。主は奮い立たれる。ギブオンの谷での時のように。みわざを行われるが、そのみわざは不可思議。働きをされるが、その働きは意外。'),
('JPN', '以赛亚书', 23, 28, 22, 'だから今、あなたがたは嘲ってはならない。あなたがたを縛るかせが、きつく締まることのないように。私は万軍の神、主から、全世界に下る定められた全滅について聞いているのだ。'),
('JPN', '以赛亚书', 23, 28, 23, 'あなたがたは、私の声に耳を傾けて聞け。私の言うことを注意して聞け。'),
('JPN', '以赛亚书', 23, 28, 24, '農夫は種を蒔くために、いつも耕してばかりいるだろうか。土地を起こし、ならしてばかりいるだろうか。'),
('JPN', '以赛亚书', 23, 28, 25, 'その地面をならしたら、ういきょうを蒔き、クミンの種を蒔き、小麦を畝に、大麦を定まった場所に、裸麦をその境に植えるではないか。'),
('JPN', '以赛亚书', 23, 28, 26, '農夫は厳しく指導され、彼の神は彼に教える。'),
('JPN', '以赛亚书', 23, 28, 27, 'ういきょうは打穀機で打たれず、クミンの上では脱穀車の車輪を回さない。ういきょうは杖で、クミンは棒で打たれるのである。'),
('JPN', '以赛亚书', 23, 28, 28, 'パンのために麦は砕かれるが、打穀をいつまでも続けることはしない。脱穀車の車輪を回すことはしても、馬がこれを砕くことはない。'),
('JPN', '以赛亚书', 23, 28, 29, 'これも万軍の主のもとから出ること。その摂理は奇しく、その英知は偉大である。'),
('JPN', '以赛亚书', 23, 29, 1, '「ああ、アリエル、アリエル。ダビデが陣を敷いた都よ。年に年を加え、祭りを巡り来させよ。'),
('JPN', '以赛亚书', 23, 29, 2, 'わたしはアリエルを虐げるので、そこにはうめきと嘆きが起こり、わたしにとっては祭壇の炉のようになる。'),
('JPN', '以赛亚书', 23, 29, 3, 'わたしは、あなたの周りに陣を敷き、前哨部隊で囲み、あなたに対して塁を築く。'),
('JPN', '以赛亚书', 23, 29, 4, 'あなたは低くされ、地の中から語りかけ、あなたのことばは、ちりの中からつぶやく。あなたの声は、死人の霊のように地の中から出て、あなたのことばは、ちりの中からささやく。'),
('JPN', '以赛亚书', 23, 29, 5, 'しかし、敵の群れは細かいほこりのようになり、横暴な者の群れは吹き飛ぶ籾殻のようになる。しかも、それは突然、不意に起こる。'),
('JPN', '以赛亚书', 23, 29, 6, '万軍の主はあなたを訪れる。雷と地震と大きな音をもって、つむじ風と暴風と焼き尽くす火の炎をもって。'),
('JPN', '以赛亚书', 23, 29, 7, 'アリエルに戦いを挑むすべての民の群れ、これを攻めて、取り囲み、これを虐げる者たちはみな、夢のようになり、夜の幻のようになる。'),
('JPN', '以赛亚书', 23, 29, 8, '飢えた者が夢の中で食べ、目が覚めると、その飢えは満たされず、渇いている者が夢の中で飲み、目が覚めると、実に疲れて喉が渇いているように、シオンの山に戦いを挑むすべての民の群れもこのようになる。」'),
('JPN', '以赛亚书', 23, 29, 9, '驚き、たじろげ。目を閉ざされて、盲目となれ。彼らは酔うが、ぶどう酒のせいではない。ふらつくが、強い酒のせいではない。'),
('JPN', '以赛亚书', 23, 29, 10, '主はあなたがたの上に深い眠りの霊を注ぎ、預言者というあなたがたの目を閉ざし、先見者というあなたがたの頭をおおわれた。'),
('JPN', '以赛亚书', 23, 29, 11, 'そのため、あなたがたにとっては、すべての幻が、封じられた書物のことばのようになった。読み書きのできる人に渡して、「どうか、これを読んでください」と言っても、「それは封じられているから読めない」と言い、'),
('JPN', '以赛亚书', 23, 29, 12, 'また、読み書きのできない人にその書物を渡して、「どうか、これを読んでください」と言っても、「私は読み書きができない」と答えるであろう。'),
('JPN', '以赛亚书', 23, 29, 13, '主は言われた。「それは、この民が口先でわたしに近づき、唇でわたしを敬いながら、その心がわたしから遠く離れているからだ。彼らがわたしを恐れるのは、人間の命令を教え込まれてのことである。'),
('JPN', '以赛亚书', 23, 29, 14, 'それゆえ、見よ、わたしはこの民に再び、不思議なこと、驚くべきことをする。この民の知恵ある者の知恵は滅び、悟りある者の悟りは隠される。」'),
('JPN', '以赛亚书', 23, 29, 15, 'わざわいだ。主に自分のはかりごとを深く隠す者たち。彼らは闇の中で事を行い、そして言う。「だれが私たちを見ているだろう。だれが私たちを知っているだろう」と。'),
('JPN', '以赛亚书', 23, 29, 16, 'ああ、あなたがたは物を逆さに考えている。陶器師を粘土と同じに見なしてよいだろうか。造られた者がそれを造った者に「彼は私を造らなかった」と言い、陶器が陶器師に「彼にはわきまえがない」と言えるだろうか。'),
('JPN', '以赛亚书', 23, 29, 17, 'もうしばらくすれば、確かに、レバノンは果樹園に変わり、果樹園は森に見えるようになる。'),
('JPN', '以赛亚书', 23, 29, 18, 'その日、耳の聞こえない人が、書物のことばを聞き、目の見えない人の目が、暗黒と闇から物を見る。'),
('JPN', '以赛亚书', 23, 29, 19, '柔和な者は主によってますます喜び、貧しい者はイスラエルの聖なる方によって楽しむ。'),
('JPN', '以赛亚书', 23, 29, 20, '横暴な者はいなくなり、嘲る者は絶え果て、よこしまなことを企む者はみな絶ち滅ぼされるからだ。'),
('JPN', '以赛亚书', 23, 29, 21, '彼らはことばで他人を罪に陥れ、城門で戒めを与える者に罠を仕掛け、正しい人を、理由もなく押しのける。'),
('JPN', '以赛亚书', 23, 29, 22, 'それゆえ、アブラハムを贖い出された主は、ヤコブの家についてこう言われる。「今からヤコブは恥を見ることがなく、今から顔が青ざめることはない。'),
('JPN', '以赛亚书', 23, 29, 23, '彼が自分の子らを見て、自分たちの中にわたしの手のわざを見るとき、彼らはわたしの名を聖とし、ヤコブの聖なる者を聖として、イスラエルの神を恐れるからだ。'),
('JPN', '以赛亚书', 23, 29, 24, '心迷う者は理解を得、不平を言う者も教訓を得る。」'),
('JPN', '以赛亚书', 23, 30, 1, '「わざわいだ、頑なな子ら。──主のことば──彼らははかりごとをめぐらすが、わたしによらず、同盟を結ぶが、わたしの霊によらず、罪に罪を増し加えるばかりだ。'),
('JPN', '以赛亚书', 23, 30, 2, '彼らはエジプトに下って行こうとするが、わたしの指示を仰がない。ファラオの保護のもとに身を避け、エジプトの陰に隠れようとする。'),
('JPN', '以赛亚书', 23, 30, 3, 'しかし、ファラオの保護に頼ることはあなたがたの恥となり、エジプトの陰に身を隠すことは恥辱となる。'),
('JPN', '以赛亚书', 23, 30, 4, 'その首長たちがツォアンにいても、その使者たちがハネスに着いても、'),
('JPN', '以赛亚书', 23, 30, 5, '彼らはみな辱められる。自分たちにとって役に立たない民のゆえに。その民は彼らの助けとならず、役にも立たない。かえって恥となり、そしりの的となる。」'),
('JPN', '以赛亚书', 23, 30, 6, 'ネゲブの獣についての宣告。「苦難と苦悩の地を通り、雌獅子や雄獅子、まむしや、飛び回る燃える蛇のいるところを通り、彼らはその財宝をろばの背に載せ、宝物をらくだのこぶに載せて、役にも立たない民のところに運ぶ。'),
('JPN', '以赛亚书', 23, 30, 7, 'エジプトの助けは空しく、当てにならない。だから、わたしはこれを『何もしないラハブ』と呼ぶ。」'),
('JPN', '以赛亚书', 23, 30, 8, '「今、行って、彼らの前でこれを板に書き、書物にこれを記し、後の日のために永遠の証しとせよ。'),
('JPN', '以赛亚书', 23, 30, 9, '彼らは反逆の民、噓つきの子ら、主のおしえを聞こうとしない子らだから。'),
('JPN', '以赛亚书', 23, 30, 10, '彼らは予見者に『見るな』と言い、先見者にはこう言う。『われわれについて正しいことを幻で見るな。われわれに心地よいことを語り、だましごとを預言せよ。'),
('JPN', '以赛亚书', 23, 30, 11, '道から外れ、道筋からそれ、われわれの前からイスラエルの聖なる方を消せ。』」'),
('JPN', '以赛亚书', 23, 30, 12, 'それゆえ、イスラエルの聖なる方はこう言われる。「あなたがたは、わたしの言うことを退けて、虐げと悪巧みに拠り頼み、これに頼った。'),
('JPN', '以赛亚书', 23, 30, 13, 'それゆえ、このあなたがたの不義は、そそり立つ城壁に広がって今にもそれを倒す裂け目のようになる。その倒壊は瞬く間に来る。'),
('JPN', '以赛亚书', 23, 30, 14, 'その倒壊は、陶器師の壺が容赦なく打ち砕かれるときのよう。その破片の中には、炉から火を取り、水溜めから水を汲むかけらさえ見つからない。」'),
('JPN', '以赛亚书', 23, 30, 15, 'イスラエルの聖なる方、神である主はこう言われた。「立ち返って落ち着いていれば、あなたがたは救われ、静かにして信頼すれば、あなたがたは力を得る。」しかし、あなたがたはこれを望まなかった。'),
('JPN', '以赛亚书', 23, 30, 16, 'あなたがたは言った。「いや、私たちは馬で逃げよう」と。そう言うなら、あなたがたは逃げてみよ。また、「私たちは早馬で」と言った。そう言うなら、あなたがたの追っ手はなお速い。'),
('JPN', '以赛亚书', 23, 30, 17, '一人の脅しによって千人が逃げ、五人の脅しによってあなたがたは逃げる。ついには、残る者が山の頂の旗ざお、丘の上の旗のようになる。'),
('JPN', '以赛亚书', 23, 30, 18, 'それゆえ主は、あなたがたに恵みを与えようとして待ち、それゆえ、あわれみを与えようと立ち上がられる。主が義の神であるからだ。幸いなことよ、主を待ち望むすべての者は。'),
('JPN', '以赛亚书', 23, 30, 19, 'ああ、シオンの民、エルサレムに住む者。もうあなたは泣くことはない。あなたの叫ぶ声に応え、主は必ず恵みを与え、それを聞くとき、あなたに答えてくださる。'),
('JPN', '以赛亚书', 23, 30, 20, 'たとえ主があなたがたに苦しみのパンと虐げの水を与えても、あなたを教える方はもう隠れることはなく、あなたの目はあなたを教える方を見続ける。'),
('JPN', '以赛亚书', 23, 30, 21, 'あなたが右に行くにも左に行くにも、うしろから「これが道だ。これに歩め」と言うことばを、あなたの耳は聞く。'),
('JPN', '以赛亚书', 23, 30, 22, 'あなたは、銀をかぶせた刻んだ像と、金をかぶせた鋳物の像を汚れたものと見なし、不浄の物としてそれをまき散らし、これに「出て行け」と言う。'),
('JPN', '以赛亚书', 23, 30, 23, 'あなたが土地に蒔くあなたの種に主は雨を降らせてくださる。それで、その土地の産する食物はみずみずしく豊かである。その日、あなたの家畜の群れは広々とした牧場で草をはむ。'),
('JPN', '以赛亚书', 23, 30, 24, '土地を耕す牛やろばは、シャベルや熊手でふるい分けられた味の良いまぐさを食べる。'),
('JPN', '以赛亚书', 23, 30, 25, '大いなる殺戮の日、やぐらの倒れる日に、高い山、そびえる丘の上すべてに、水の流れる運河ができる。'),
('JPN', '以赛亚书', 23, 30, 26, '主がその民の傷を包み、その打たれた傷を癒やされる日に、月の光は太陽の光のようになり、太陽の光は七倍になって、七日分の光のようになる。'),
('JPN', '以赛亚书', 23, 30, 27, '見よ、主の御名が遠くから来る。立ち上る濃い煙とともに、怒りに燃えて。その唇は憤りに満ち、舌は焼き尽くす火のよう。'),
('JPN', '以赛亚书', 23, 30, 28, 'その息は、あふれて首まで達する流れのようだ。それは国々を破滅のふるいにかけ、諸国の民のあごに、迷い出させる手綱をかける。'),
('JPN', '以赛亚书', 23, 30, 29, 'あなたがたには、聖なる祭りの祝いの夜のような歌があり、主の山、イスラエルの岩に行くために笛に合わせて進む者のような、心の喜びがある。'),
('JPN', '以赛亚书', 23, 30, 30, 'しかし、主は威厳ある御声を聞かせ、大雨、嵐、雹の石で、激しい怒りと、焼き尽くす火の炎とともに、下される御腕を見せる。'),
('JPN', '以赛亚书', 23, 30, 31, '主の御声を聞いてアッシリアは打ちのめされる。主が杖でこれを打たれる。'),
('JPN', '以赛亚书', 23, 30, 32, '主が下す懲らしめの杖がしなるたびに、タンバリンと竪琴が鳴らされる。主は武器を振り回して、これと戦う。'),
('JPN', '以赛亚书', 23, 30, 33, 'すでにトフェトも整えられ、実に王のためにも備えられている。それは深く、広くなっていて、そこには火と多くの薪がある。主の息が硫黄の流れのように、それを燃やす。'),
('JPN', '以赛亚书', 23, 31, 1, 'ああ、助けを求めてエジプトに下る者たち。彼らは馬に頼り、数が多いといって戦車に、非常に強いといって騎兵に拠り頼み、イスラエルの聖なる方に目を向けず、主を求めない。'),
('JPN', '以赛亚书', 23, 31, 2, 'しかし、主は知恵のある方。わざわいをもたらし、みことばを取り消さない。主は、悪を行う者の家と、不法を行う者を助ける者に対して立ち上がる。'),
('JPN', '以赛亚书', 23, 31, 3, 'エジプト人は人間であって神ではなく、彼らの馬も肉であって霊ではない。主が御手を伸ばされると、助ける者はつまずき、助けられる者は倒れて、皆ともに滅び果てる。'),
('JPN', '以赛亚书', 23, 31, 4, 'まことに、主は私にこう言われる。「獅子、あるいは若獅子が獲物に向かって吼えるとき、たとえ大勢の牧者がそこに呼び集められても、獅子は彼らの声にひるむことなく、彼らの騒ぎにも動じない。そのように、万軍の主は下って来て、シオンの山とその丘の上で戦う。'),
('JPN', '以赛亚书', 23, 31, 5, '万軍の主は、舞い飛ぶ鳥のようにエルサレムを守る。これを守って救い出し、これを助けて解放する。」'),
('JPN', '以赛亚书', 23, 31, 6, '帰れ、イスラエルの子らよ。あなたがたが反抗を強めているその方のもとに。'),
('JPN', '以赛亚书', 23, 31, 7, 'その日、イスラエルの子らは、それぞれ銀の偽りの神々や、金の偽りの神々を退ける。それらは、あなたがたが自分の手で自分のために造ったもので、そのことは罪過となっている。'),
('JPN', '以赛亚书', 23, 31, 8, '「アッシリアは人のものでない剣に倒れ、人間のものでない剣が彼らを食い尽くす。アッシリアは剣の前から逃げ、若い男たちは苦役に服する。'),
('JPN', '以赛亚书', 23, 31, 9, 'その岩は恐怖のために過ぎ去り、その首長たちも旗を捨て、おののき逃げ去る。──シオンに火を持ち、エルサレムにかまどを持つ主のことば。」'),
('JPN', '以赛亚书', 23, 32, 1, '見よ。一人の王が義によって治め、首長たちは公正によって支配する。'),
('JPN', '以赛亚书', 23, 32, 2, '彼らはそれぞれ、風を避ける避け所、嵐を避ける隠れ場のようになり、砂漠にある水の流れ、乾ききった地にある、大きな岩の陰のようになる。'),
('JPN', '以赛亚书', 23, 32, 3, '見る者の目は固く閉じることがなく、聞く者の耳は注意深く聞く。'),
('JPN', '以赛亚书', 23, 32, 4, '性急な者の心も知識を悟り、もつれた舌もはっきりと早口で語る。'),
('JPN', '以赛亚书', 23, 32, 5, 'もはや、愚か者が高貴な人とは呼ばれず、ならず者が上流の人とは言われない。'),
('JPN', '以赛亚书', 23, 32, 6, 'なぜなら、愚か者は愚かなことを語って、心で不法を企み、不敬虔なことを行って、主に向かって迷いごとを語るからだ。飢えている者を飢えさせて、渇いている者に飲み物を与えない。'),
('JPN', '以赛亚书', 23, 32, 7, 'ならず者、そのやり方は悪質だ。彼は悪事を企み、貧しい者が正しいことを申し立てても、偽りを語って、苦しむ者を滅ぼす。'),
('JPN', '以赛亚书', 23, 32, 8, 'しかし、高貴な人は高貴なことを計画し、高貴なことに堅く立つ。'),
('JPN', '以赛亚书', 23, 32, 9, '「安逸を貪る女たちよ。立ち上がって、わたしの声を聞け。うぬぼれている娘たちよ。わたしのことばに耳を傾けよ。'),
('JPN', '以赛亚书', 23, 32, 10, 'うぬぼれている女たちよ。一年と少しの日がたつと、あなたがたはわななく。ぶどうの収穫がなくなり、その取り入れもやって来ないからだ。'),
('JPN', '以赛亚书', 23, 32, 11, '安逸を貪る女たちよ、震えよ。うぬぼれている女たちよ、わななけ。着物を脱いで裸になり、腰に粗布をまとえ。'),
('JPN', '以赛亚书', 23, 32, 12, '胸を打って嘆け。麗しい畑、実り豊かなぶどうの木のために。'),
('JPN', '以赛亚书', 23, 32, 13, '茨やおどろが生い茂る、わたしの民の土地のために。そして、楽しい家々のすべて、おごる都のために。'),
('JPN', '以赛亚书', 23, 32, 14, 'なぜなら、宮殿は見捨てられ、町の騒ぎもさびれ、オフェルと見張りの塔は、いつまでも荒れ野に、野ろばの喜ぶところ、群れの牧場になるからだ。」'),
('JPN', '以赛亚书', 23, 32, 15, 'しかし、ついに、いと高き所から私たちに霊が注がれ、荒野が果樹園となり、果樹園が森と見なされるようになる。'),
('JPN', '以赛亚书', 23, 32, 16, '公正は荒野に宿り、義は果樹園に住む。'),
('JPN', '以赛亚书', 23, 32, 17, '義が平和をつくり出し、義がとこしえの平穏と安心をもたらすとき、'),
('JPN', '以赛亚书', 23, 32, 18, '私の民は、平和な住まい、安全な家、安らかな憩いの場に住む。'),
('JPN', '以赛亚书', 23, 32, 19, 'あの森は雹が降って倒れ、あの町は全く卑しめられる。'),
('JPN', '以赛亚书', 23, 32, 20, 'ああ、幸いなことよ。すべての水のほとりに種を蒔き、牛とろばを放し飼いするあなたがたは。'),
('JPN', '以赛亚书', 23, 33, 1, 'わざわいだ。自分は踏みにじられなかったのに、人を踏みにじり、裏切られなかったのに、人を裏切るあなたは。自分が踏みにじることを終えるとき、あなたは踏みにじられ、裏切りをやめるとき、あなたは裏切られる。'),
('JPN', '以赛亚书', 23, 33, 2, '主よ、あわれんでください。私たちはあなたを待ち望みます。朝ごとに私たちの腕となり、苦難の時の、私たちの救いとなってください。'),
('JPN', '以赛亚书', 23, 33, 3, 'その鳴りとどろく声に、もろもろの民は逃げ、あなたが立ち上がると、国々は散らされます。'),
('JPN', '以赛亚书', 23, 33, 4, 'あなたがたの分捕り物は、いなごの若虫が集まるように集められ、いなごの群れが飛びつくように人々はそれに飛びつく。'),
('JPN', '以赛亚书', 23, 33, 5, '主はいと高き方で、高い所に住み、シオンを公正と義で満たされる。'),
('JPN', '以赛亚书', 23, 33, 6, '主はあなたの時を堅く支え、救いと知恵と知識の富となられる。主を恐れることは、その財宝である。'),
('JPN', '以赛亚书', 23, 33, 7, '見よ。彼らの勇士は通りで叫び、平和の使者たちは激しく泣く。'),
('JPN', '以赛亚书', 23, 33, 8, '大路は荒れ果てて、道行く者は途絶え、契約は破られて、町々は捨てられ、人は顧みられることがない。'),
('JPN', '以赛亚书', 23, 33, 9, '地は喪に服してしおれ、レバノンは辱めを受けて枯れ果てる。シャロンは荒れ野のようになり、バシャンもカルメルも葉を振り落とす。'),
('JPN', '以赛亚书', 23, 33, 10, '「今、わたしは立ち上がる。──主は言われる──今、わたしは自らを高く上げ、今、わたしは自らを高める。'),
('JPN', '以赛亚书', 23, 33, 11, 'あなたがたは枯れ草をはらみ、藁を産む。あなたがたの息は、自分たちを食い尽くす火だ。'),
('JPN', '以赛亚书', 23, 33, 12, '諸国の民は焼かれて石灰となり、刈り取られて火をつけられる茨となる。」'),
('JPN', '以赛亚书', 23, 33, 13, '「遠くの者よ、わたしのしたことを聞け。近くの者よ、わたしの力あるわざを知れ。」'),
('JPN', '以赛亚书', 23, 33, 14, '罪人たちはシオンでわななき、神を敬わない者たちを震えがとらえる。「私たちのうち、だれが焼き尽くす火に耐えられるか。私たちのうち、だれが、とこしえに燃える炉に耐えられるか。」'),
('JPN', '以赛亚书', 23, 33, 15, '義を行う者、公正を語る者、強奪による利得を退ける者、手を振って賄賂を受け取らない者、耳をふさいで流血について聞かない者、目を閉じて悪いことを見ない者。'),
('JPN', '以赛亚书', 23, 33, 16, 'このような人は高い所に住み、その砦は岩場の上の要害である。彼のパンは備えられ、彼の水は確保される。'),
('JPN', '以赛亚书', 23, 33, 17, 'あなたの目は麗しい王を見、遠くまで広がる国を眺める。'),
('JPN', '以赛亚书', 23, 33, 18, 'あなたの心は、恐ろしかったことを思い巡らす。「数えた者はどこにいるのか。量った者はどこにいるのか。やぐらを数えた者はどこにいるのか。」'),
('JPN', '以赛亚书', 23, 33, 19, 'あなたはもう横柄な民を見ない。難しくて聞き取れない外国語を、口ごもって、わけの分からないことばを話す民を。'),
('JPN', '以赛亚书', 23, 33, 20, '私たちの祝祭の都、シオンを見よ。あなたの目は、安らかな住まい、移ることのない天幕、エルサレムを見る。その杭はとこしえに抜かれず、その綱は一本も切られない。'),
('JPN', '以赛亚书', 23, 33, 21, 'しかも、そこには威厳ある主が私たちとともにいてくださる。そこには多くの川があり、幅の広い川がある。櫂で漕ぐ舟もそこを通わず、大船もそこを通らない。'),
('JPN', '以赛亚书', 23, 33, 22, 'まことに、主は私たちをさばく方、主は私たちに法を定める方、主は私たちの王、この方が私たちを救われる。'),
('JPN', '以赛亚书', 23, 33, 23, 'あなたの帆の綱は解け、帆柱の基に結ぶこともできず、帆を張ることもできない。そのとき、おびただしい数の分捕り物が分けられ、足の萎えた者も獲物をかすめる。'),
('JPN', '以赛亚书', 23, 33, 24, 'そこに住む者は「私は病気だ」とは言わず、そこに住む民の咎は除かれる。'),
('JPN', '以赛亚书', 23, 34, 1, '国々よ、近づいて聞け。諸国の民よ、耳を傾けよ。地とそこに満ちているものよ、聞け。世界とそこから生え出たすべてのものよ。'),
('JPN', '以赛亚书', 23, 34, 2, '主がすべての国に向かって激しく怒り、そのすべての軍勢に向かって憤り、彼らを聖絶し、虐殺されるにまかされたからだ。'),
('JPN', '以赛亚书', 23, 34, 3, '彼らの殺された者は投げ捨てられ、その死体は悪臭を放ち、山々はその血によって溶ける。'),
('JPN', '以赛亚书', 23, 34, 4, '天の万象は朽ち果て、天は巻物のように巻かれる。その万象は枯れ落ちる。ぶどうの木から葉が枯れ落ちるように。いちじくの木から実がしぼんで落ちるように。'),
('JPN', '以赛亚书', 23, 34, 5, '「まことに、天でわたしの剣は血に浸されている。見よ。これがエドムの上に、わたしが聖絶すると定めた民の上に下る。」'),
('JPN', '以赛亚书', 23, 34, 6, '主の剣は血で満ち、脂肪で肥えている。子羊とやぎの血、雄羊の腎臓の脂肪で。主がボツラでいけにえを屠り、エドムの地で大虐殺をされるからだ。'),
('JPN', '以赛亚书', 23, 34, 7, '野牛は彼らとともに、雄牛は荒馬とともに倒れる。彼らの地には血が染み込み、その土は脂肪で肥える。'),
('JPN', '以赛亚书', 23, 34, 8, 'それは主の復讐の日であり、シオンの訴えのために仇を返す年だからだ。'),
('JPN', '以赛亚书', 23, 34, 9, 'エドムの川はピッチに、その土は硫黄に変わる。その地は燃えるピッチになる。'),
('JPN', '以赛亚书', 23, 34, 10, 'それは夜も昼も消えず、その煙はいつまでも立ち上る。そこは代々にわたって廃墟となり、もうそこを通る者はだれもいない。'),
('JPN', '以赛亚书', 23, 34, 11, 'ふくろうと針ねずみがそこをわがものとし、みみずくと烏がそこに住む。主はその上に茫漠の測り縄を張り、空虚の重りを下げる。'),
('JPN', '以赛亚书', 23, 34, 12, 'そのおもだった人たちで、王権を宣言する者は、そこにはいない。すべての首長たちもいなくなる。'),
('JPN', '以赛亚书', 23, 34, 13, 'その宮殿には茨が生え、要塞には、いらくさやあざみが生え、ジャッカルの住みか、だちょうの住む所となる。'),
('JPN', '以赛亚书', 23, 34, 14, '荒野の獣は山犬に会い、野やぎはその友を呼ぶ。そこには夜の鳥も憩い、自分の休み場を見つける。'),
('JPN', '以赛亚书', 23, 34, 15, '蛇もそこに巣を作って卵を産み、それをかえして自分の陰に集める。鳶もそれぞれ自分の伴侶と、そこに集まる。'),
('JPN', '以赛亚书', 23, 34, 16, '主の書物を調べて読め。これらのもののうち、どれも失われていない。それぞれ自分の伴侶を欠くものはない。それは、主の口がこれを命じ、主の御霊がこれらを集めたからである。'),
('JPN', '以赛亚书', 23, 34, 17, '主はこれらのもののためにくじを引き、御手が測り縄で測って彼らに分け与えたので、彼らはとこしえまでもこれを所有し、代々にわたってここに住む。'),
('JPN', '以赛亚书', 23, 35, 1, '荒野と砂漠は喜び、荒れ地は喜び躍り、サフランのように花を咲かせる。'),
('JPN', '以赛亚书', 23, 35, 2, '盛んに花を咲かせ、歓喜して歌う。これに、レバノンの栄光と、カルメルやシャロンの威光が授けられるので、彼らは主の栄光、私たちの神の威光を見る。'),
('JPN', '以赛亚书', 23, 35, 3, '弱った手を強め、よろめく膝をしっかりさせよ。'),
('JPN', '以赛亚书', 23, 35, 4, '心騒ぐ者たちに言え。「強くあれ。恐れるな。見よ。あなたがたの神が、復讐が、神の報いがやって来る。神は来て、あなたがたを救われる。」'),
('JPN', '以赛亚书', 23, 35, 5, 'そのとき、目の見えない者の目は開かれ、耳の聞こえない者の耳は開けられる。'),
('JPN', '以赛亚书', 23, 35, 6, 'そのとき、足の萎えた者は鹿のように飛び跳ね、口のきけない者の舌は喜び歌う。荒野に水が湧き出し、荒れ地に川が流れるからだ。'),
('JPN', '以赛亚书', 23, 35, 7, '焼けた地は沢となり、潤いのない地は水の湧くところとなり、ジャッカルが伏したねぐらは葦やパピルスの茂みとなる。'),
('JPN', '以赛亚书', 23, 35, 8, 'そこに大路があり、その道は「聖なる道」と呼ばれる。汚れた者はそこを通れない。これは、その道を行く者たちのもの。そこを愚か者がさまようことはない。'),
('JPN', '以赛亚书', 23, 35, 9, 'そこには獅子もおらず、猛獣もそこに上って来ることはなく、そこには何も見つからない。贖われた者たちだけがそこを歩む。'),
('JPN', '以赛亚书', 23, 35, 10, '主に贖われた者たちは帰って来る。彼らは喜び歌いながらシオンに入り、その頭にはとこしえの喜びを戴く。楽しみと喜びがついて来て、悲しみと嘆きは逃げ去る。'),
('JPN', '以赛亚书', 23, 36, 1, 'ヒゼキヤ王の第十四年のことであった。アッシリアの王センナケリブが、ユダのすべての城壁のある町々に攻め上り、これを取った。'),
('JPN', '以赛亚书', 23, 36, 2, 'アッシリアの王は、ラブ・シャケを大軍とともにラキシュからエルサレムのヒゼキヤ王のところへ送った。ラブ・シャケは布さらしの野への大路にある、上の池の水道のそばに立った。'),
('JPN', '以赛亚书', 23, 36, 3, 'ヒルキヤの子である宮廷長官エルヤキム、書記シェブナ、およびアサフの子である史官ヨアフは、彼のところに出て行った。'),
('JPN', '以赛亚书', 23, 36, 4, 'ラブ・シャケは彼らに言った。「ヒゼキヤに伝えよ。大王、アッシリアの王がこう言っておられる。『いったい、おまえは何に拠り頼んでいるのか。'),
('JPN', '以赛亚书', 23, 36, 5, '口先だけのことばが、戦略であり戦力だと言うのか。今おまえは、だれに拠り頼んでいるのか。私に反逆しているが。'),
('JPN', '以赛亚书', 23, 36, 6, 'おまえは、あの傷んだ葦の杖、エジプトに拠り頼んでいるが、それは、それに寄りかかる者の手を刺し貫くだけだ。エジプトの王ファラオは、すべて彼に拠り頼む者にそうするのだ。'),
('JPN', '以赛亚书', 23, 36, 7, 'おまえは私に「われわれは、われわれの神、主に拠り頼む」と言う。その主とは、ヒゼキヤがその高き所と祭壇を取り除いて、ユダとエルサレムに「この祭壇の前で拝め」と言った、そういう主ではないか。'),
('JPN', '以赛亚书', 23, 36, 8, 'さあ今、私の主君、アッシリアの王と賭けをしないか。もし、おまえのほうで乗り手をそろえることができるのなら、おまえに二千頭の馬を与えよう。'),
('JPN', '以赛亚书', 23, 36, 9, 'おまえは戦車と騎兵のことでエジプトに拠り頼んでいるが、私の主君の最も小さい家来である総督一人さえ追い返せないのだ。'),
('JPN', '以赛亚书', 23, 36, 10, '今、私がこの国を滅ぼすために上って来たのは、主を差し置いてのことであろうか。主が私に「この国に攻め上って、これを滅ぼせ」と言われたのだ。』」'),
('JPN', '以赛亚书', 23, 36, 11, 'エルヤキムとシェブナとヨアフは、ラブ・シャケに言った。「どうか、しもべたちにはアラム語で話してください。われわれはアラム語が分かりますから。城壁の上にいる民が聞いているところでは、われわれにユダのことばで話さないでください。」'),
('JPN', '以赛亚书', 23, 36, 12, 'ラブ・シャケは言った。「私の主君がこれらのことを告げに私を遣わされたのは、おまえの主君や、おまえのためだろうか。むしろ、城壁の上に座っている者たちのためではないか。彼らはおまえたちと一緒に、自分の糞を食らい、自分の尿を飲むようになるのだ。」'),
('JPN', '以赛亚书', 23, 36, 13, 'ラブ・シャケは突っ立って、ユダのことばで大声で叫んだ。「大王、アッシリアの王のことばを聞け。'),
('JPN', '以赛亚书', 23, 36, 14, '王はこう言っておられる。『ヒゼキヤにごまかされるな。あれは、おまえたちを救い出すことができないからだ。'),
('JPN', '以赛亚书', 23, 36, 15, 'ヒゼキヤは、「主が必ずわれわれを救い出してくださる。この都は決してアッシリアの王の手に渡されることはない」と言って、おまえたちに主を信頼させようとするが、そうはさせない。』'),
('JPN', '以赛亚书', 23, 36, 16, 'ヒゼキヤの言うことを聞くな。アッシリアの王がこう言っておられるからだ。『私と和を結び、私に降伏せよ。そうすれば、おまえたちはみな、自分のぶどうと自分のいちじくを食べ、自分の井戸の水を飲めるようになる。'),
('JPN', '以赛亚书', 23, 36, 17, 'その後私は来て、おまえたちの国と同じような国におまえたちを連れて行く。そこは穀物と新しいぶどう酒の地、パンとぶどう畑の地である。'),
('JPN', '以赛亚书', 23, 36, 18, 'ヒゼキヤが、「主はわれわれを救い出してくださる」と言っても、おまえたちは、そそのかされないようにせよ。国々の神々は、それぞれ自分の国をアッシリアの王の手から救い出しただろうか。'),
('JPN', '以赛亚书', 23, 36, 19, 'ハマテやアルパデの神々は今、どこにいるのか。セファルワイムの神々はどこにいるのか。彼らはサマリアを私の手から救い出したか。'),
('JPN', '以赛亚书', 23, 36, 20, 'これらの国々のすべての神々のうち、だれが自分たちの国を私の手から救い出したか。主がエルサレムを私の手から救い出せるとでもいうのか。』」'),
('JPN', '以赛亚书', 23, 36, 21, '人々は黙って、彼に一言も答えなかった。「彼に答えるな」というのが、王の命令だったからである。'),
('JPN', '以赛亚书', 23, 36, 22, 'ヒルキヤの子である宮廷長官エルヤキム、書記シェブナ、アサフの子である史官ヨアフは、自分たちの衣を引き裂いてヒゼキヤのもとに行き、ラブ・シャケのことばを告げた。'),
('JPN', '以赛亚书', 23, 37, 1, 'ヒゼキヤ王はこれを聞くと衣を引き裂き、粗布を身にまとって主の宮に入った。'),
('JPN', '以赛亚书', 23, 37, 2, '彼は、宮廷長官エルヤキム、書記シェブナ、年長の祭司たちに粗布を身にまとわせて、預言者である、アモツの子イザヤのところに遣わした。'),
('JPN', '以赛亚书', 23, 37, 3, '彼らはイザヤに言った。「ヒゼキヤはこう言っておられます。『今日は、苦難と懲らしめと屈辱の日です。子どもが生まれようとしているのに、それを産み出す力がないからです。'),
('JPN', '以赛亚书', 23, 37, 4, 'おそらく、あなたの神、主は、ラブ・シャケのことばを聞かれたことでしょう。彼の主君、アッシリアの王が、生ける神をそしるために彼を遣わしたのです。あなたの神、主は、お聞きになったそのことばをとがめられます。あなたは、まだいる残りの者のために祈りの声をあげてください。』」'),
('JPN', '以赛亚书', 23, 37, 5, 'ヒゼキヤ王の家来たちがイザヤのもとに来たとき、'),
('JPN', '以赛亚书', 23, 37, 6, 'イザヤは彼らに言った。「あなたがたの主君にこう言いなさい。『主はこう言われる。あなたが聞いたあのことば、アッシリアの王の若い者たちがわたしをののしった、あのことばを恐れるな。'),
('JPN', '以赛亚书', 23, 37, 7, '今、わたしは彼のうちに霊を置く。彼は、あるうわさを聞いて、自分の国に引き揚げる。わたしはその国で彼を剣で倒す。』」'),
('JPN', '以赛亚书', 23, 37, 8, 'ラブ・シャケは退いて、リブナを攻めていたアッシリアの王と落ち合った。王がラキシュから移動したことを聞いていたからである。'),
('JPN', '以赛亚书', 23, 37, 9, '王は、クシュの王ティルハカについて、「彼があなたと戦うために出て来ている」との知らせを聞いた。アッシリアの王はそれを聞くと、使者たちをヒゼキヤに送って言った。'),
('JPN', '以赛亚书', 23, 37, 10, '「ユダの王ヒゼキヤにこう伝えよ。『おまえが信頼するおまえの神にだまされてはいけない。エルサレムはアッシリアの王の手に渡されないと言っているが。'),
('JPN', '以赛亚书', 23, 37, 11, 'おまえは、アッシリアの王たちがすべての国々にしたこと、それらを絶滅させたことを確かに聞いている。それでも、おまえだけは救い出されるというのか。'),
('JPN', '以赛亚书', 23, 37, 12, '私の先祖は、ゴザン、ハラン、レツェフ、またテラサルにいたエデンの人々を滅ぼしたが、その国々の神々は彼らを救い出したか。'),
('JPN', '以赛亚书', 23, 37, 13, 'ハマテの王、アルパデの王、セファルワイムの町の王、ヘナやイワの王はどこにいるか。』」'),
('JPN', '以赛亚书', 23, 37, 14, 'ヒゼキヤは、使者の手からその手紙を受け取って読み、主の宮に上って行き、それを主の前に広げた。'),
('JPN', '以赛亚书', 23, 37, 15, 'ヒゼキヤは主に祈った。'),
('JPN', '以赛亚书', 23, 37, 16, '「ケルビムの上に座しておられるイスラエルの神、万軍の主よ。ただ、あなただけが、地のすべての王国の神です。あなたが天と地を造られました。'),
('JPN', '以赛亚书', 23, 37, 17, '主よ。御耳を傾けて聞いてください。主よ。御目を開いてご覧ください。生ける神をそしるために言ってよこしたセンナケリブのことばをみな聞いてください。'),
('JPN', '以赛亚书', 23, 37, 18, '主よ。アッシリアの王たちが、すべての国々とその国土を廃墟としたのは事実です。'),
('JPN', '以赛亚书', 23, 37, 19, '彼らはその神々を火に投げ込みました。それらが神ではなく、人の手のわざ、木や石にすぎなかったので、彼らはこれを滅ぼすことができたのです。'),
('JPN', '以赛亚书', 23, 37, 20, '私たちの神、主よ。今、私たちを彼の手から救ってください。そうすれば、地のすべての王国は、あなただけが主であることを知るでしょう。」'),
('JPN', '以赛亚书', 23, 37, 21, 'アモツの子イザヤは、ヒゼキヤのところに人を送って言った。「イスラエルの神、主はこう言われる。『あなたはアッシリアの王センナケリブについて、わたしに祈った。』'),
('JPN', '以赛亚书', 23, 37, 22, '主が彼について語られたことばは、このとおりである。『処女である娘シオンはおまえを蔑み、おまえを嘲る。娘エルサレムは、おまえのうしろで頭を振る。'),
('JPN', '以赛亚书', 23, 37, 23, 'おまえはだれをそしり、だれをののしったのか。だれに向かって声をあげ、高慢な目を上げたのか。イスラエルの聖なる者に対してだ。'),
('JPN', '以赛亚书', 23, 37, 24, 'おまえはしもべたちを通して、主をそしって言った。「多くの戦車を率いて、私は山々の頂に、レバノンの奥深くに上って行った。そのそびえる杉の木と美しいもみの木を切り倒し、その果ての高地、木の茂った園にまで入って行った。'),
('JPN', '以赛亚书', 23, 37, 25, '私は井戸を掘って水を飲み、足の裏でエジプトのすべての川を干上がらせた」と。'),
('JPN', '以赛亚书', 23, 37, 26, 'おまえは聞かなかったのか。遠い昔に、わたしがそれをなし、大昔に、わたしがそれを計画し、今、それを果たしたことを。それで、おまえは城壁のある町々を荒らして廃墟の石くれの山としたのだ。'),
('JPN', '以赛亚书', 23, 37, 27, 'その住民は力失せ、打ちのめされて恥を見て、野の草や青菜、育つ前に干からびる屋根の草のようになった。'),
('JPN', '以赛亚书', 23, 37, 28, 'おまえが座るのも、出て行くのも、おまえが入るのも、わたしはよく知っている。わたしに向かっていきり立つのも。'),
('JPN', '以赛亚书', 23, 37, 29, 'おまえがわたしに向かっていきり立ち、おまえの安逸がわたしの耳に届いたので、わたしはおまえの鼻に鉤輪を、口にくつわをはめ、おまえを、もと来た道に引き戻す。』'),
('JPN', '以赛亚书', 23, 37, 30, 'あなたへのしるしは、こうである。『今年は、落ち穂から生えたものを食べ、二年目は、それから生えたものを食べ、三年目は、種を蒔いて刈り入れ、ぶどう畑を作ってその実を食べる。'),
('JPN', '以赛亚书', 23, 37, 31, 'ユダの家の中の逃れの者、残された者は、下に根を張り、上に実を結ぶ。'),
('JPN', '以赛亚书', 23, 37, 32, 'エルサレムから残りの者が、シオンの山から、逃れの者が出て来るからである。万軍の主の熱心がこれを成し遂げる。』'),
('JPN', '以赛亚书', 23, 37, 33, 'それゆえ、アッシリアの王について、主はこう言われる。『彼はこの都に侵入しない。また、ここに矢を放たず、これに盾をもって迫らず、塁を築いてこれを攻めることもない。'),
('JPN', '以赛亚书', 23, 37, 34, '彼は、もと来た道を引き返し、この都には入らない──主のことば──。'),
('JPN', '以赛亚书', 23, 37, 35, 'わたしはこの都を守って、これを救う。わたしのために、わたしのしもべダビデのために。』」'),
('JPN', '以赛亚书', 23, 37, 36, '主の使いが出て行き、アッシリアの陣営で十八万五千人を打ち殺した。人々が翌朝早く起きて見ると、なんと、彼らはみな死体となっていた。'),
('JPN', '以赛亚书', 23, 37, 37, 'アッシリアの王センナケリブは陣をたたんで去り、帰ってニネベに住んだ。'),
('JPN', '以赛亚书', 23, 37, 38, '彼が自分の神ニスロクの神殿で拝んでいたとき、その息子たち、アデラメレクとサルエツェルは、剣で彼を打ち殺した。彼らはアララテの地へ逃れ、彼の子エサル・ハドンが代わって王となった。'),
('JPN', '以赛亚书', 23, 38, 1, 'そのころ、ヒゼキヤは病気になって死にかかっていた。そこへ、アモツの子、預言者イザヤが来て、彼に言った。「主はこう言われる。『あなたの家を整理せよ。あなたは死ぬ。治らない。』」'),
('JPN', '以赛亚书', 23, 38, 2, 'ヒゼキヤは顔を壁に向け、主に祈った。'),
('JPN', '以赛亚书', 23, 38, 3, '「ああ、主よ、どうか思い出してください。私が、真実と全き心をもって、あなたの御前に歩み、あなたの御目にかなうことを行ってきたことを。」ヒゼキヤは大声で泣いた。'),
('JPN', '以赛亚书', 23, 38, 4, 'そのとき、イザヤに次のような主のことばがあった。'),
('JPN', '以赛亚书', 23, 38, 5, '「行ってヒゼキヤに告げよ。『あなたの父ダビデの神、主はこう言われる。わたしはあなたの祈りを聞いた。あなたの涙も見た。見よ。わたしはあなたの寿命にもう十五年を加える。'),
('JPN', '以赛亚书', 23, 38, 6, 'わたしはアッシリアの王の手からあなたとこの都を救い出し、この都を守る。'),
('JPN', '以赛亚书', 23, 38, 7, '次のことが、あなたへの主からのしるしである。主は約束したこのことを成就する。'),
('JPN', '以赛亚书', 23, 38, 8, '見よ。わたしは、アハズの日時計に落ちた時計の影を十度後に戻す。』」すると、日時計に落ちた日が十度戻った。'),
('JPN', '以赛亚书', 23, 38, 9, 'ユダの王ヒゼキヤが病気になって、その病気から回復したときに記したもの。'),
('JPN', '以赛亚书', 23, 38, 10, '私は言った。生涯の半ばで私はよみの門に入る。私は残りの年を失ってしまったのだ。'),
('JPN', '以赛亚书', 23, 38, 11, '私は言った。私は主を、生ける者の地で主を見ることはない。私は、死人の国の住人とともにあり、再び人を見ることもない。'),
('JPN', '以赛亚书', 23, 38, 12, '私の住まいは牧者の天幕のように引き抜かれ、私から取り去られた。私は、機織りのように自分のいのちを巻いた。主は私を、機から断ち切られる。昼から夜へと、あなたは私を終わりに近づけられます。'),
('JPN', '以赛亚书', 23, 38, 13, '私は朝まで叫びました。主は雄獅子のように私のすべての骨を砕かれます。昼から夜へと、あなたは私を終わりに近づけられます。'),
('JPN', '以赛亚书', 23, 38, 14, '燕や鶴のように私は泣き、鳩のようにうめきました。私の目は上を仰いで衰えました。主よ、私は虐げられています。私の保証人となってください。'),
('JPN', '以赛亚书', 23, 38, 15, '何を私は語れるでしょう。主が私に語り、主が自ら行われたのに。私は自分のすべての年月、自分のたましいの苦しみのゆえに、ゆっくりと歩んで行きます。'),
('JPN', '以赛亚书', 23, 38, 16, '主よ、これらによって人は生きるのです。私の霊のいのちも、すべてこれらに従っています。どうか私を健やかにし、私を生かしてください。'),
('JPN', '以赛亚书', 23, 38, 17, 'ああ、私の味わった苦い苦しみは平安のためでした。あなたは私のたましいを慕い、滅びの穴から引き離されました。あなたは私のすべての罪を、あなたのうしろに投げやられました。'),
('JPN', '以赛亚书', 23, 38, 18, 'よみはあなたをほめたたえず、死はあなたを賛美せず、穴に下る者たちはあなたの真実を待ち望みません。'),
('JPN', '以赛亚书', 23, 38, 19, '生きている者、ただ生きている者だけが、今日の私のように、あなたをほめたたえます。父は子らにあなたの真実について知らせます。'),
('JPN', '以赛亚书', 23, 38, 20, '主は私を救ってくださる。私たちは生きている日々の間、主の宮で琴を奏でよう。'),
('JPN', '以赛亚书', 23, 38, 21, 'イザヤは言った。「ひとかたまりの干しいちじくを持って来させ、腫物の上に塗りなさい。そうすれば治ります。」'),
('JPN', '以赛亚书', 23, 38, 22, 'ヒゼキヤは言った。「私が主の宮に上れるしるしは何ですか。」'),
('JPN', '以赛亚书', 23, 39, 1, 'そのころ、バルアダンの子、バビロンの王メロダク・バルアダンは使者を遣わして、手紙と贈り物をヒゼキヤに届けた。彼は病気だったが元気になった、と聞いたからである。'),
('JPN', '以赛亚书', 23, 39, 2, 'ヒゼキヤは彼らを喜び、宝庫、銀、金、香料、高価な油、一切の武器庫、彼の宝物倉にあるすべての物を彼らに見せた。ヒゼキヤがその家の中、および国中で、彼らに見せなかった物は一つもなかった。'),
('JPN', '以赛亚书', 23, 39, 3, '預言者イザヤはヒゼキヤ王のところに来て、彼に尋ねた。「あの人たちは何と言いましたか。どこから来たのですか。」ヒゼキヤは「遠い国、バビロンから私のところに来ました」と答えた。'),
('JPN', '以赛亚书', 23, 39, 4, 'イザヤは言った。「彼らはあなたの家で何を見たのですか。」ヒゼキヤは答えた。「私の家の中のすべての物を見ました。私の宝物倉の中で彼らに見せなかった物は一つもありません。」'),
('JPN', '以赛亚书', 23, 39, 5, 'イザヤはヒゼキヤに言った。「万軍の主のことばを聞きなさい。'),
('JPN', '以赛亚书', 23, 39, 6, '見よ。あなたの家にある物、あなたの父祖たちが今日まで蓄えてきた物がすべて、バビロンへ運び去られる日々が来る。何一つ残されることはない──主は言われる──。'),
('JPN', '以赛亚书', 23, 39, 7, 'また、あなたが生む、あなた自身の息子たちの中には、捕らえられてバビロンの王の宮殿で宦官となる者がいる。」'),
('JPN', '以赛亚书', 23, 39, 8, 'ヒゼキヤはイザヤに言った。「あなたが告げてくれた主のことばはありがたい。」彼は、自分が生きている間は平和と安定があるだろう、と思ったのである。'),
('JPN', '以赛亚书', 23, 40, 1, '「慰めよ、慰めよ、わたしの民を。──あなたがたの神は仰せられる──'),
('JPN', '以赛亚书', 23, 40, 2, 'エルサレムに優しく語りかけよ。これに呼びかけよ。その苦役は終わり、その咎は償われている、と。そのすべての罪に代えて、二倍のものを主の手から受けている、と。」'),
('JPN', '以赛亚书', 23, 40, 3, '荒野で叫ぶ者の声がする。「主の道を用意せよ。荒れ地で私たちの神のために、大路をまっすぐにせよ。'),
('JPN', '以赛亚书', 23, 40, 4, 'すべての谷は引き上げられ、すべての山や丘は低くなる。曲がったところはまっすぐになり、険しい地は平らになる。'),
('JPN', '以赛亚书', 23, 40, 5, 'このようにして主の栄光が現されると、すべての肉なる者がともにこれを見る。まことに主の御口が語られる。」'),
('JPN', '以赛亚书', 23, 40, 6, '「叫べ」と言う者の声がする。「何と叫びましょうか」と人は言う。「人はみな草のよう。その栄えはみな野の花のようだ。'),
('JPN', '以赛亚书', 23, 40, 7, '主の息吹がその上に吹くと、草はしおれ、花は散る。まことに民は草だ。'),
('JPN', '以赛亚书', 23, 40, 8, '草はしおれ、花は散る。しかし、私たちの神のことばは永遠に立つ。」'),
('JPN', '以赛亚书', 23, 40, 9, 'シオンに良い知らせを伝える者よ、高い山に登れ。エルサレムに良い知らせを伝える者よ、力の限り声をあげよ。声をあげよ。恐れるな。ユダの町々に言え。「見よ、あなたがたの神を。」'),
('JPN', '以赛亚书', 23, 40, 10, '見よ。神である主は力をもって来られ、その御腕で統べ治める。見よ。その報いは主とともにあり、その報酬は主の御前にある。'),
('JPN', '以赛亚书', 23, 40, 11, '主は羊飼いのように、その群れを飼い、御腕に子羊を引き寄せ、懐に抱き、乳を飲ませる羊を優しく導く。'),
('JPN', '以赛亚书', 23, 40, 12, 'だれが手のひらで水を量り、手の幅で天を測り、地のちりを升に盛り、山々を天秤で量ったのか。もろもろの丘を秤で。'),
('JPN', '以赛亚书', 23, 40, 13, 'だれが主の霊を推し量り、主の助言者として主に教えたのか。'),
('JPN', '以赛亚书', 23, 40, 14, '主はだれと相談して悟りを得られたのか。だれが公正の道筋を主に教えて、知識を授け、英知の道を知らせたのか。'),
('JPN', '以赛亚书', 23, 40, 15, '見よ。国々は手桶の一しずく、秤の上のごみのように見なされる。見よ。主は島々をちりのように取り上げる。'),
('JPN', '以赛亚书', 23, 40, 16, 'レバノンも、薪にするには足りない。その獣も、全焼のささげ物にするには足りない。'),
('JPN', '以赛亚书', 23, 40, 17, 'すべての国々も主の前では無いに等しく、主には、空しく何もないものと見なされる。'),
('JPN', '以赛亚书', 23, 40, 18, 'あなたがたは神をだれになぞらえ、神をどんな似姿に似せようとするのか。'),
('JPN', '以赛亚书', 23, 40, 19, '鋳物師は鋳像を鋳て造り、金細工人はそれに金をかぶせ、銀の鎖を作る。'),
('JPN', '以赛亚书', 23, 40, 20, '貧しい者は、奉納物として朽ちない木を選び、巧みな細工人を探して、動かない彫像を据える。'),
('JPN', '以赛亚书', 23, 40, 21, 'あなたがたは知らないのか。聞いていないのか。初めから、告げられていなかったのか。悟っていなかったのか。地の基のことを。'),
('JPN', '以赛亚书', 23, 40, 22, '主は、地をおおう天蓋の上に住む方。地の住民はバッタのようだ。主は、天を薄絹のように延べ広げ、これを天幕のように張って住まわれる。'),
('JPN', '以赛亚书', 23, 40, 23, '君主たちを無に帰し、地をさばく者たちを空しいものとされる。'),
('JPN', '以赛亚书', 23, 40, 24, '彼らが植えられ、蒔かれ、いよいよ地に根を張ろうとするとき、主はそれに風を吹きつけ、彼らは枯れる。暴風がそれを藁のように散らす。'),
('JPN', '以赛亚书', 23, 40, 25, '「それなのに、あなたがたは、わたしをだれになぞらえ、だれと比べようとするのか」と聖なる方は言われる。'),
('JPN', '以赛亚书', 23, 40, 26, 'あなたがたは目を高く上げて、だれがこれらを創造したかを見よ。この方はその万象を数えて呼び出し、一つ一つ、その名をもって呼ばれる。この方は精力に満ち、その力は強い。一つも漏れるものはない。'),
('JPN', '以赛亚书', 23, 40, 27, 'ヤコブよ、なぜ言うのか。イスラエルよ、なぜ言い張るのか。「私の道は主に隠れ、私の訴えは私の神に見過ごされている」と。'),
('JPN', '以赛亚书', 23, 40, 28, 'あなたは知らないのか。聞いたことがないのか。主は永遠の神、地の果てまで創造した方。疲れることなく、弱ることなく、その英知は測り知れない。'),
('JPN', '以赛亚书', 23, 40, 29, '疲れた者には力を与え、精力のない者には勢いを与えられる。'),
('JPN', '以赛亚书', 23, 40, 30, '若者も疲れて力尽き、若い男たちも、つまずき倒れる。'),
('JPN', '以赛亚书', 23, 40, 31, 'しかし、主を待ち望む者は新しく力を得、鷲のように、翼を広げて上ることができる。走っても力衰えず、歩いても疲れない。'),
('JPN', '以赛亚书', 23, 41, 1, '「島々よ、わたしの前で静まれ。諸国の民よ、新しく力を得よ。近寄れ。そして語れ。われわれは、ともに、さばきに近づこう。'),
('JPN', '以赛亚书', 23, 41, 2, 'だれが一人の者を東から起こし、その行く先々で勝利を収めさせるのか。だれが彼の前に国々を渡し、王たちを踏みにじらせるのか。彼はその剣で彼らをちりのようにし、その弓で藁のように追い散らす。'),
('JPN', '以赛亚书', 23, 41, 3, '彼は彼らを追い、難なく進んで行く。まだ自分の足で行ったことのない道を。'),
('JPN', '以赛亚书', 23, 41, 4, 'だれが、最初から代々の人々に呼びかけてこれらをなし、これらを行ったのか。主であるわたしだ。わたしは初めであり、また終わりとともにある。わたしがそれだ。'),
('JPN', '以赛亚书', 23, 41, 5, '島々は見て恐れる。地の果ては震えながら、近づき、やって来る。'),
('JPN', '以赛亚书', 23, 41, 6, '彼らは助け合い、その兄弟に『強くあれ』と言う。'),
('JPN', '以赛亚书', 23, 41, 7, '鋳物師は金細工人を励まし、金槌で打つ者は、鉄床をたたく者を励まして、はんだ付けについて『それで良い』と言い、釘で打ち付けて動かないようにする。'),
('JPN', '以赛亚书', 23, 41, 8, 'だがイスラエルよ、あなたはわたしのしもべ。わたしが選んだヤコブよ、あなたは、わたしの友アブラハムの裔だ。'),
('JPN', '以赛亚书', 23, 41, 9, 'わたしはあなたを地の果てから連れ出し、地の隅々から呼び出して言った。『あなたは、わたしのしもべ。わたしはあなたを選んで、退けなかった』と。'),
('JPN', '以赛亚书', 23, 41, 10, '恐れるな。わたしはあなたとともにいる。たじろぐな。わたしがあなたの神だから。わたしはあなたを強くし、あなたを助け、わたしの義の右の手で、あなたを守る。'),
('JPN', '以赛亚书', 23, 41, 11, '見よ。あなたに向かっていきり立つ者はみな恥を見て辱められ、あなたと争う者たちは無いもののようになって滅びる。'),
('JPN', '以赛亚书', 23, 41, 12, 'あなたと言い争う者を探しても、あなたは見つけることができず、あなたと戦う者たちは、全く無いもののようになってしまう。'),
('JPN', '以赛亚书', 23, 41, 13, 'わたしがあなたの神、主であり、あなたの右の手を固く握り、『恐れるな。わたしがあなたを助ける』と言う者だからである。'),
('JPN', '以赛亚书', 23, 41, 14, '恐れるな。虫けらのヤコブ、イスラエルの人々。わたしがあなたを助ける。──主のことば──あなたを贖う者はイスラエルの聖なる者。'),
('JPN', '以赛亚书', 23, 41, 15, '見よ。わたしはあなたを鋭く新しい両刃の打穀機とする。あなたは山々を踏みつけて粉々に砕き、丘を籾殻のようにする。'),
('JPN', '以赛亚书', 23, 41, 16, 'あなたがそれをあおぐと、風が運び去り、暴風がそれをまき散らす。あなたは主にあって喜び、イスラエルの聖なる者によって誇る。'),
('JPN', '以赛亚书', 23, 41, 17, '苦しむ者や貧しい者が水を求めてもそれはなく、その舌は渇きで干からびる。わたし、主は彼らに答え、イスラエルの神は彼らを見捨てない。'),
('JPN', '以赛亚书', 23, 41, 18, 'わたしは裸の丘に川を開く。平地のただ中には泉を。荒野を水のある沢とし、砂漠の地を水の源とする。'),
('JPN', '以赛亚书', 23, 41, 19, 'わたしは荒野に、杉、アカシヤ、ミルトス、オリーブの木を植え、荒れ地に、もみの木、すずかけの木、檜をともに植える。'),
('JPN', '以赛亚书', 23, 41, 20, 'それは、主の手がこれを行い、イスラエルの聖なる者がこれを創造したことを、彼らが見て知り、心に留めて、ともに悟るためである。'),
('JPN', '以赛亚书', 23, 41, 21, 'あなたがたの訴えを出せ。──主は言われる──あなたがたの証拠を持って来い。──ヤコブの王は言われる──'),
('JPN', '以赛亚书', 23, 41, 22, '持って来て、後に起ころうとする事を告げよ。前の事は何であったのかを告げよ。そうすれば、われわれもそれを心に留め、後の事を知ることができるだろう。または、来たるべき事をわれわれに聞かせよ。'),
('JPN', '以赛亚书', 23, 41, 23, '後に起ころうとすることを告げよ。そうすれば、われわれは、あなたがたが神々であることを知るだろう。良いことでも悪いことでもしてみよ。そうすれば、われわれはともに見て驚くだろう。'),
('JPN', '以赛亚书', 23, 41, 24, '見よ、あなたがたは無に等しい。あなたがたの行いは空しい。あなたがたを選ぶ者は忌まわしい。'),
('JPN', '以赛亚书', 23, 41, 25, 'わたしが北から人を起こすと、彼は来て、日の昇るところから、わたしの名を呼ぶ。彼は長官たちを漆喰のように踏む。陶器師が粘土を踏みつけるように。'),
('JPN', '以赛亚书', 23, 41, 26, 'だれが、初めから告げて、われわれが知るようにしたか。だれが、あらかじめわれわれに告げて、『それは正しい』と言うようにしたか。告げた者は一人もなく、聞かせた者も一人もなく、あなたがたの言うことを聞いた者も一人もいなかった。'),
('JPN', '以赛亚书', 23, 41, 27, 'わたしが最初にシオンに『見よ、それらはここにある』と言い、わたしがエルサレムに『良い知らせを伝える者を与える』と言った。'),
('JPN', '以赛亚书', 23, 41, 28, 'しかし、見回しても、だれもいない。彼らの中には助言者がいない。わたしが尋ねても返事のできる者が。'),
('JPN', '以赛亚书', 23, 41, 29, '見よ、彼らはみな偽りで、そのなすことは空しい。彼らの鋳像は風のようで何もない。」'),
('JPN', '以赛亚书', 23, 42, 1, '「見よ。わたしが支えるわたしのしもべ、わたしの心が喜ぶ、わたしの選んだ者。わたしは彼の上にわたしの霊を授け、彼は国々にさばきを行う。'),
('JPN', '以赛亚书', 23, 42, 2, '彼は叫ばず、言い争わず、通りでその声を聞かせない。'),
('JPN', '以赛亚书', 23, 42, 3, '傷んだ葦を折ることもなく、くすぶる灯芯を消すこともなく、真実をもってさばきを執り行う。'),
('JPN', '以赛亚书', 23, 42, 4, '衰えず、くじけることなく、ついには地にさばきを確立する。島々もそのおしえを待ち望む。」'),
('JPN', '以赛亚书', 23, 42, 5, '天を創造し、これを延べ広げ、地とその産物を押し広げ、その上にいる民に息を与え、そこを歩む者たちに霊を授けた神なる主はこう言われる。'),
('JPN', '以赛亚书', 23, 42, 6, '「わたし、主は、義をもってあなたを召し、あなたの手を握る。あなたを見守り、あなたを民の契約として、国々の光とする。'),
('JPN', '以赛亚书', 23, 42, 7, 'こうして、見えない目を開き、囚人を牢獄から、闇の中に住む者たちを獄屋から連れ出す。'),
('JPN', '以赛亚书', 23, 42, 8, 'わたしは主、これがわたしの名。わたしは、わたしの栄光をほかの者に、わたしの栄誉を、刻んだ像どもに与えはしない。'),
('JPN', '以赛亚书', 23, 42, 9, '初めのことは、見よ、すでに起こった。新しいことを、わたしは告げる。それが起こる前にあなたがたに聞かせる。」'),
('JPN', '以赛亚书', 23, 42, 10, '新しい歌を主に歌え。その栄誉を、地の果てから。海に下る者、そこを渡るすべての者、島々とそこに住む者よ。'),
('JPN', '以赛亚书', 23, 42, 11, '荒野とその町々、ケダル人が住む村々よ、声をあげよ。セラに住む者たちは喜び歌え。山々の頂から声高らかに叫べ。'),
('JPN', '以赛亚书', 23, 42, 12, '主に栄光を帰せよ。島々にその栄誉を告げ知らせよ。'),
('JPN', '以赛亚书', 23, 42, 13, '主は勇士のように出で立ち、戦士のように激しく奮い立ち、ときの声をあげて叫び、敵に向かって力を見せつける。'),
('JPN', '以赛亚书', 23, 42, 14, '「久しく、わたしは黙っていた。静かにして自分を抑えていた。今は、子を産む女のようにうめき、激しい息づかいであえぐ。'),
('JPN', '以赛亚书', 23, 42, 15, 'わたしは山や丘を荒らし、そのすべての青草を枯らし、川を中州ばかりにし、沢を涸らす。'),
('JPN', '以赛亚书', 23, 42, 16, 'わたしは目の見えない人に、知らない道を歩ませ、知らない通り道を行かせる。彼らの前で闇を光に、起伏のある地を平らにする。これらのことをわたしは行い、彼らを見捨てはしない。'),
('JPN', '以赛亚书', 23, 42, 17, '彫像に拠り頼み、鋳像に向かって『あなたがたこそ私たちの神々』と言う者は、退けられて恥を見る。'),
('JPN', '以赛亚书', 23, 42, 18, '耳の聞こえない者たちよ、聞け。目の見えない者たちよ、目を凝らして見よ。'),
('JPN', '以赛亚书', 23, 42, 19, 'わたしのしもべほど目の見えない者が、だれかほかにいるだろうか。わたしが送る使者ほど耳の聞こえない者が、ほかにいるだろうか。わたしと和解した者のような目の見えない者、主のしもべのような目の見えない者が、だれかほかにいるだろうか。'),
('JPN', '以赛亚书', 23, 42, 20, 'あなたは多くを見ながら、心を留めない。耳が開いているのに、聞こうとしない。」'),
('JPN', '以赛亚书', 23, 42, 21, '主はご自分の義のために望まれた。みおしえを広め、これを輝かすことを。'),
('JPN', '以赛亚书', 23, 42, 22, 'しかし、これは、かすめ奪われ略奪された民、彼らはみな穴の中に陥れられ、獄屋に閉じ込められた。かすめ奪われても、助け出す者はなく、略奪されても、返せと言う者もいない。'),
('JPN', '以赛亚书', 23, 42, 23, 'あなたがたのうち、だれがこれに耳を傾け、後々のために注意して聞くだろうか。'),
('JPN', '以赛亚书', 23, 42, 24, 'だれがヤコブを、奪い取る者に渡したのか。イスラエルを、かすめ奪う者に。それは主ではないか。私たちはこの方の前に罪ある者となり、主の道に歩もうとせず、そのおしえに聞き従わなかった。'),
('JPN', '以赛亚书', 23, 42, 25, 'そこで主は、憤ってこれに怒りを注ぎ、激しい戦いをこれに向けた。それがあたりを焼き尽くしても彼は悟らず、自分に燃えついても心に留めなかった。'),
('JPN', '以赛亚书', 23, 43, 1, 'だが今、主はこう言われる。ヤコブよ、あなたを創造した方、イスラエルよ、あなたを形造った方が。「恐れるな。わたしがあなたを贖ったからだ。わたしはあなたの名を呼んだ。あなたは、わたしのもの。'),
('JPN', '以赛亚书', 23, 43, 2, 'あなたが水の中を過ぎるときも、わたしは、あなたとともにいる。川を渡るときも、あなたは押し流されず、火の中を歩いても、あなたは焼かれず、炎はあなたに燃えつかない。'),
('JPN', '以赛亚书', 23, 43, 3, 'わたしはあなたの神、主、イスラエルの聖なる者、あなたの救い主であるからだ。わたしはエジプトをあなたの身代金とし、クシュとセバをあなたの代わりとする。'),
('JPN', '以赛亚书', 23, 43, 4, 'わたしの目には、あなたは高価で尊い。わたしはあなたを愛している。だから、わたしは人をあなたの代わりにし、国民をあなたのいのちの代わりにする。'),
('JPN', '以赛亚书', 23, 43, 5, '恐れるな。わたしがあなたとともにいるからだ。わたしは東からあなたの子孫を来させ、西からあなたを集める。'),
('JPN', '以赛亚书', 23, 43, 6, '北に向かっては『引き渡せ』と言い、南に向かっては『引き止めるな』と言う。わたしの息子たちを遠くから来させ、娘たちを地の果てから来させよ。'),
('JPN', '以赛亚书', 23, 43, 7, 'わたしの名で呼ばれるすべての者は、わたしの栄光のために、わたしがこれを創造した。これを形造り、また、これを造った。'),
('JPN', '以赛亚书', 23, 43, 8, '目があっても見えない民、耳があっても聞こえない者たちを連れ出せ。'),
('JPN', '以赛亚书', 23, 43, 9, 'すべての国々をともに集わせ、諸国の民を集めよ。彼らのうちのだれが、われわれにこのことを告げ、初めのことを聞かせることができるだろうか。彼らが自分たちの証人を出して証言し、人々がそれを聞いて、『本当だ』と言うようにせよ。'),
('JPN', '以赛亚书', 23, 43, 10, 'あなたがたはわたしの証人、──主のことば──わたしが選んだわたしのしもべである。これは、あなたがたが知って、わたしを信じ、わたしがその者であることを悟るためだ。わたしより前に造られた神はなく、わたしより後にも、それはいない。'),
('JPN', '以赛亚书', 23, 43, 11, 'わたし、このわたしが主であり、ほかに救い主はいない。'),
('JPN', '以赛亚书', 23, 43, 12, 'このわたしが、告げ、救い、聞かせたのだ。あなたがたのうちに、異なる神はいなかった。だから、あなたがたはわたしの証人。──主のことば──わたしが神だ。'),
('JPN', '以赛亚书', 23, 43, 13, 'これから後もわたしは神だ。わたしの手から救い出せる者はない。わたしが事を行えば、だれがそれを戻せるだろうか。」'),
('JPN', '以赛亚书', 23, 43, 14, 'あなたがたを贖う、イスラエルの聖なる方、主はこう言われる。「あなたがたのために、わたしはバビロンに使いを送り、彼らをことごとく逃亡者として下らせる。カルデア人を彼らの喜びの船で。'),
('JPN', '以赛亚书', 23, 43, 15, 'わたしは主、あなたがたの聖なる者、イスラエルの創造者、あなたがたの王である。」'),
('JPN', '以赛亚书', 23, 43, 16, '海の中に道を、激しく流れる水の中に通り道を設け、'),
('JPN', '以赛亚书', 23, 43, 17, '戦車と馬、強力な軍勢を引き出した主はこう言われる。「彼らはみな倒れて起き上がれず、灯芯のように消え失せる。'),
('JPN', '以赛亚书', 23, 43, 18, '先のことに心を留めるな。昔のことに目を留めるな。'),
('JPN', '以赛亚书', 23, 43, 19, '見よ、わたしは新しいことを行う。今、それが芽生えている。あなたがたは、それを知らないのか。必ず、わたしは荒野に道を、荒れ地に川を設ける。'),
('JPN', '以赛亚书', 23, 43, 20, '野の獣、ジャッカルや、だちょうも、わたしをあがめる。わたしが荒野に水を、荒れ地に川を流れさせ、わたしの民、わたしの選んだ者に飲ませるからだ。'),
('JPN', '以赛亚书', 23, 43, 21, 'わたしのためにわたしが形造ったこの民は、わたしの栄誉を宣べ伝える。'),
('JPN', '以赛亚书', 23, 43, 22, 'しかし、ヤコブよ、あなたはわたしを呼び求めなかった。むしろ、イスラエルよ、あなたはわたしのことで疲れ果てた。'),
('JPN', '以赛亚书', 23, 43, 23, 'あなたはわたしに全焼のささげ物の羊を携えて来ることはなく、いけにえを献げてわたしをあがめようともしなかった。わたしは穀物のささげ物のことであなたに苦労をさせず、乳香のことで、あなたを煩わせてもいない。'),
('JPN', '以赛亚书', 23, 43, 24, 'あなたはわたしのために、金で菖蒲を買わず、いけにえの脂肪で、わたしを満足させなかった。かえって、あなたの罪でわたしに苦労をさせ、あなたの咎でわたしを煩わせただけだ。'),
('JPN', '以赛亚书', 23, 43, 25, 'わたし、このわたしは、わたし自身のためにあなたの背きの罪をぬぐい去り、もうあなたの罪を思い出さない。'),
('JPN', '以赛亚书', 23, 43, 26, 'わたしに思い出させよ。ともにさばきに向かおう。あなたが正しいとされるために、あなたのほうから申し立てよ。'),
('JPN', '以赛亚书', 23, 43, 27, 'あなたの最初の先祖は罪を犯し、あなたの仲保者たちはわたしに背いた。'),
('JPN', '以赛亚书', 23, 43, 28, 'それで、わたしは聖所のつかさたちを汚し、ヤコブが聖絶されるように、イスラエルがののしられるようにした。」'),
('JPN', '以赛亚书', 23, 44, 1, '「今、聞け。わたしのしもべヤコブ、わたしの選んだイスラエルよ。'),
('JPN', '以赛亚书', 23, 44, 2, 'あなたを造り、あなたを母の胎内にいるときから形造り、あなたを助ける主はこう言う。恐れるな。わたしのしもべヤコブ、わたしの選んだエシュルンよ。'),
('JPN', '以赛亚书', 23, 44, 3, 'わたしは潤いのない地に水を注ぎ、乾いたところに豊かな流れを注ぎ、わたしの霊をあなたの子孫に、わたしの祝福をあなたの末裔に注ぐ。'),
('JPN', '以赛亚书', 23, 44, 4, '彼らは流れのほとりの柳の木のように、青草の間に芽生える。'),
('JPN', '以赛亚书', 23, 44, 5, 'ある者は『私は主のもの』と言い、ある者はヤコブの名で自分を呼び、ある者は手に『主のもの』と記してイスラエルの名を名乗る。」'),
('JPN', '以赛亚书', 23, 44, 6, 'イスラエルの王である主、これを贖う方、万軍の主はこう言われる。「わたしは初めであり、わたしは終わりである。わたしのほかに神はいない。'),
('JPN', '以赛亚书', 23, 44, 7, 'わたしが永遠の民を起こしたときから、だれが、わたしのように宣言して、これを告げることができたか。これをわたしの前で並べ立ててみよ。彼らに未来のこと、来たるべきことを告げさせてみよ。'),
('JPN', '以赛亚书', 23, 44, 8, 'おののくな。恐れるな。わたしが、以前からあなたに聞かせ、告げてきたではないか。あなたがたはわたしの証人。わたしのほかに神があるか。ほかに岩はない。わたしは知らない。'),
('JPN', '以赛亚书', 23, 44, 9, '偶像を造る者はみな、空しい。彼らが慕うものは何の役にも立たない。それら自身が彼らの証人だ。見ることもできず、知ることもできない。彼らはただ恥を見るだけだ。'),
('JPN', '以赛亚书', 23, 44, 10, 'だれが神を造り、偶像を鋳たのか。何の役にも立たないものを。'),
('JPN', '以赛亚书', 23, 44, 11, '見よ、その人の仲間たちはみな恥を見る。それを細工した者が人間にすぎないからだ。彼らはみな集まり、立つがよい。彼らはおののいて、ともに恥を見る。'),
('JPN', '以赛亚书', 23, 44, 12, '鉄で細工する者は工具を用い、炭火の上で細工し、金槌でこれを形造り、力ある腕でそれを造る。腹が減ると、力がなくなり、水を飲まないと、疲れてしまう。'),
('JPN', '以赛亚书', 23, 44, 13, '木で細工する者は測り縄で測り、朱で輪郭をとり、かんなで削り、コンパスで線を引き、人の形に造り、人間の立派な姿に仕上げて、神殿に安置する。'),
('JPN', '以赛亚书', 23, 44, 14, '杉の木を切り、うばめ樫や樫の木を選んで、林の木の中で自分のために育てる。月桂樹を植えると、大雨がそれを生長させる。'),
('JPN', '以赛亚书', 23, 44, 15, 'それは人間のために薪になり、人はその一部を取って暖をとり、これを燃やしてパンを焼く。また、これで神を造って拝み、これを偶像に仕立てて、これにひれ伏す。'),
('JPN', '以赛亚书', 23, 44, 16, '半分を火に燃やし、その半分の上で肉を食べ、肉をあぶって満腹する。また、温まって、『ああ、温まった。炎が見える』と言う。'),
('JPN', '以赛亚书', 23, 44, 17, 'その残りで神を造って自分の偶像とし、ひれ伏してそれを拝み、こう祈る。『私を救ってください。あなたは私の神だから』と。'),
('JPN', '以赛亚书', 23, 44, 18, '彼らはよく知りもせず、理解もしない。その目はふさがれていて見ることもできず、その心が賢くなることはない。'),
('JPN', '以赛亚书', 23, 44, 19, '彼らは考え直すこともなく、このように言う知識も英知もない。『私は、その半分を火に燃やし、その炭火の上でパンを焼き、肉をあぶって食べている。それなのに、その残りで忌み嫌うべきものを造り、木の切れ端の前にひれ伏すのか。』'),
('JPN', '以赛亚书', 23, 44, 20, '灰を食物とする者は、心が欺かれ、惑わされて、自分を救い出せず、『私の右の手に偽りはないか』とさえ言わない。'),
('JPN', '以赛亚书', 23, 44, 21, 'ヤコブよ、これらのことを心に留めよ。イスラエルよ、あなたはわたしのしもべ。わたしがあなたを形造った。あなたは、わたし自身のしもべだ。イスラエルよ、あなたはわたしに忘れられることがない。'),
('JPN', '以赛亚书', 23, 44, 22, 'わたしは、あなたの背きを雲のように、あなたの罪をかすみのように消し去った。わたしに帰れ。わたしがあなたを贖ったからだ。」'),
('JPN', '以赛亚书', 23, 44, 23, '天よ、喜び歌え。主がこれを成し遂げられたから。地の底よ、喜び叫べ。山々よ、喜びの歌声をあげよ。林と、そのすべての木々も。主がヤコブを贖い、イスラエルのうちに栄光を現されたからだ。'),
('JPN', '以赛亚书', 23, 44, 24, 'あなたを贖い、あなたを母の胎内で形造った方、主はこう言われる。「わたしは万物を造った主である。わたしはひとりで天を延べ広げ、ただ、わたしだけで、地を押し広げた。'),
('JPN', '以赛亚书', 23, 44, 25, 'わたしは易者のしるしを打ち壊し、占い師を狂わせ、知恵ある者を退けて、その知識を愚かにする。'),
('JPN', '以赛亚书', 23, 44, 26, '主のしもべのことばを成就させ、使者たちの計画を成し遂げさせる。エルサレムについては『人が住むようになる』と言い、ユダの町々については『町々は再建され、その廃墟はわたしが復興させる』と言う。'),
('JPN', '以赛亚书', 23, 44, 27, '淵については『干上がれ。わたしはおまえの豊かな流れを涸らす』と言う。'),
('JPN', '以赛亚书', 23, 44, 28, 'キュロスについては『彼はわたしの牧者。わたしの望むことをすべて成し遂げる』と言う。エルサレムについては『再建される。神殿はその基が据えられる』と言う。」'),
('JPN', '以赛亚书', 23, 45, 1, '主は、油注がれた者キュロスについてこう言われる。「わたしは彼の右手を握り、彼の前に諸国を下らせ、王たちの腰の帯を解き、彼の前に扉を開いて、その門を閉じさせないようにする。'),
('JPN', '以赛亚书', 23, 45, 2, 'わたしはあなたの前を進み、険しい地を平らにし、青銅の扉を打ち砕き、鉄のかんぬきをへし折る。'),
('JPN', '以赛亚书', 23, 45, 3, 'わたしは秘められている財宝と、ひそかなところに隠された宝をあなたに与える。それは、わたしが主であり、あなたの名を呼ぶ者、イスラエルの神であることをあなたが知るためだ。'),
('JPN', '以赛亚书', 23, 45, 4, 'わたしのしもべヤコブのため、わたしが選んだイスラエルのために、わたしはあなたを、あなたの名で呼ぶ。あなたはわたしを知らないが、わたしはあなたに肩書きを与える。'),
('JPN', '以赛亚书', 23, 45, 5, 'わたしが主である。ほかにはいない。わたしのほかに神はいない。あなたはわたしを知らないが、わたしはあなたに力を帯びさせる。'),
('JPN', '以赛亚书', 23, 45, 6, 'それは、日の昇る方からも西からも、わたしのほかには、だれもいないことを、人々が知るためだ。わたしが主である。ほかにはいない。'),
('JPN', '以赛亚书', 23, 45, 7, 'わたしは光を造り出し、闇を創造し、平和をつくり、わざわいを創造する。わたしは主、これらすべてを行う者。'),
('JPN', '以赛亚书', 23, 45, 8, '天よ、上から滴らせよ。雲よ、義を降らせよ。地よ、開け。天地が救いを実らせるように。正義をともに芽生えさせよ。わたしは主。わたしがこれを創造した。」'),
('JPN', '以赛亚书', 23, 45, 9, 'ああ、自分を形造った方に抗議する者よ。陶器は土の器の一つにすぎないのに、粘土が自分を形造る者に言うだろうか。「何を作るのか」とか「あなたが作った物には手がついていない」と。'),
('JPN', '以赛亚书', 23, 45, 10, 'わざわいだ。自分の父に「なぜ子を生むのか」と言い、母に「なぜ産みの苦しみをするのか」と言う者。'),
('JPN', '以赛亚书', 23, 45, 11, 'イスラエルの聖なる方、これを形造った方、主はこう言われる。「これから起こることを、わたしに尋ねよ。わたしの子たちについて、またわたしの手のわざについて、あなたはわたしに命じるのか。'),
('JPN', '以赛亚书', 23, 45, 12, 'このわたしが地を造り、その上に人間を創造した。このわたしが手で天を延べ広げ、その万象に命じたのだ。'),
('JPN', '以赛亚书', 23, 45, 13, 'このわたしが義をもって彼を奮い立たせ、彼の道をことごとく平らにする。彼がわたしの都を建て直し、わたしの捕囚の民を解放する。代価を払ってでもなく、賄賂によってでもない。──万軍の主は言われる。」'),
('JPN', '以赛亚书', 23, 45, 14, '主はこう言われる。「エジプトの産物とクシュの商品、それに背の高いセバ人も、あなたのところにやって来て、あなたのものとなる。彼らはあなたの後に従い、鎖につながれてやって来る。そして、あなたにひれ伏して、あなたに祈る。『神はただあなたのところにだけおられ、ほかにはなく、ほかに神々はいない』と。」'),
('JPN', '以赛亚书', 23, 45, 15, 'イスラエルの神、救い主よ。まことに、あなたはご自分を隠す神。'),
('JPN', '以赛亚书', 23, 45, 16, '偶像を細工する者どもはみな恥を見、辱めを受ける。彼らはともに、辱めのうちに去る。'),
('JPN', '以赛亚书', 23, 45, 17, 'イスラエルは主によって救われ、永遠の救いに入れられる。あなたがたは恥を見ることも辱めを受けることもない。永遠に至るまで。'),
('JPN', '以赛亚书', 23, 45, 18, '天を創造した方、すなわち神、地を形造り、これを仕上げた方、これを堅く立てた方、これを茫漠としたものとして創造せず、住む所として形造った方、まことに、この主が言われる。「わたしは主。ほかにはいない。'),
('JPN', '以赛亚书', 23, 45, 19, 'わたしは隠れたところ、闇の地の場所で、語らなかった。茫漠としたところで、ヤコブの子孫に『わたしを尋ね求めよ』とは言わなかった。わたしは主。正義を語り、公正を告げる者。'),
('JPN', '以赛亚书', 23, 45, 20, '諸国からの逃亡者たちよ。集まって来て、ともに近づけ。彼らは自分たちの木の偶像を担ぐ者、救えもしない神に祈る者たちで、知識がない。'),
('JPN', '以赛亚书', 23, 45, 21, '告げよ。証拠を出せ。ともに相談せよ。だれが、これを昔から聞かせ、以前からこれを告げたのか。わたし、主ではなかったか。わたしのほかに神はいない。正しい神、救い主、わたしをおいて、ほかにはいない。'),
('JPN', '以赛亚书', 23, 45, 22, '地の果てのすべての者よ。わたしを仰ぎ見て救われよ。わたしが神だ。ほかにはいない。'),
('JPN', '以赛亚书', 23, 45, 23, 'わたしは自分にかけて誓う。ことばは、義のうちにわたしの口から出て、決して戻ることはない。すべての膝はわたしに向かってかがめられ、すべての舌は誓い、'),
('JPN', '以赛亚书', 23, 45, 24, 'わたしについて、『ただ主にだけ、正義と力がある』と言う。主に向かっていきり立つ者はみな、主のもとに来て恥を見る。'),
('JPN', '以赛亚书', 23, 45, 25, 'イスラエルの子孫はみな主によって義とされ、主を誇りとする。」'),
('JPN', '以赛亚书', 23, 46, 1, '「ベルはひざまずき、ネボはかがむ。彼らの像は獣と家畜に載せられる。あなたがたの荷物は、疲れた動物の重荷となって運ばれる。'),
('JPN', '以赛亚书', 23, 46, 2, '彼らはともにかがみ、ひざまずく。重荷を解くこともできず、自分自身も捕らわれの身となって行く。'),
('JPN', '以赛亚书', 23, 46, 3, 'ヤコブの家よ、わたしに聞け。イスラエルの家のすべての残りの者よ。胎内にいたときから担がれ、生まれる前から運ばれた者よ。'),
('JPN', '以赛亚书', 23, 46, 4, 'あなたがたが年をとっても、わたしは同じようにする。あなたがたが白髪になっても、わたしは背負う。わたしはそうしてきたのだ。わたしは運ぶ。背負って救い出す。'),
('JPN', '以赛亚书', 23, 46, 5, 'わたしをだれになぞらえて比べ、わたしをだれと並べて、なぞらえるのか。'),
('JPN', '以赛亚书', 23, 46, 6, '袋から金を惜しげなく出し、銀を天秤で量る者たちは、金細工人を雇って、それで神を造り、ひざまずいては、これを拝む。'),
('JPN', '以赛亚书', 23, 46, 7, '彼らはこれを肩に担いで運び、それがあったところに安置すると、それはそこに立ったままである。これはその場所から動かない。これに叫んでも答えず、苦しみから救ってもくれない。'),
('JPN', '以赛亚书', 23, 46, 8, 'このことを思い出し、勇み立て。背く者たちよ、心に思い返せ。'),
('JPN', '以赛亚书', 23, 46, 9, '遠い大昔のことを思い出せ。わたしが神である。ほかにはいない。わたしのような神はいない。'),
('JPN', '以赛亚书', 23, 46, 10, 'わたしは後のことを初めから告げ、まだなされていないことを昔から告げ、『わたしの計画は成就し、わたしの望むことをすべて成し遂げる』と言う。'),
('JPN', '以赛亚书', 23, 46, 11, 'わたしは東から猛禽を、遠い地から、わたしの計画を行う者を呼ぶ。わたしは語って、それを来たらせ、計画を立てて、それを実行する。'),
('JPN', '以赛亚书', 23, 46, 12, 'わたしに聞け、頑なな者たちよ。正義から遠く離れている者たちよ。'),
('JPN', '以赛亚书', 23, 46, 13, 'わたしは、わたしの義を近づける。それは遠くはない。わたしの救いが遅れることはない。わたしはシオンに救いを、イスラエルにわたしの栄えを与える。」'),
('JPN', '以赛亚书', 23, 47, 1, '「おとめ、娘バビロンよ。下って行って、土の上に座れ。娘カルデア人たちよ。王座のない地面に座れ。あなたはもう、優しい上品な女と呼ばれることはないからだ。'),
('JPN', '以赛亚书', 23, 47, 2, 'ひき臼を取って粉をひけ。ベールを取り去り、裾をまくってすねを出し、川を渡れ。'),
('JPN', '以赛亚书', 23, 47, 3, 'あなたの裸はあらわにされ、恥もさらされる。わたしは復讐をする。だれ一人容赦しない。」'),
('JPN', '以赛亚书', 23, 47, 4, '私たちを贖う方、その名は万軍の主、イスラエルの聖なる方。'),
('JPN', '以赛亚书', 23, 47, 5, '「娘カルデア人たちよ。黙って座り、闇に入れ。あなたはもう、国々の女王と呼ばれることはないからだ。'),
('JPN', '以赛亚书', 23, 47, 6, 'わたしは、わたしの民を怒って、わたしのゆずりの民を汚し、彼らをあなたの手に渡したが、あなたは彼らをあわれまず、老人にも、ひどく重いくびきを負わせた。'),
('JPN', '以赛亚书', 23, 47, 7, 'あなたは『いつまでも女王でいよう』と考えて、これらのことを心に留めず、自分の終わりのことを思うことさえしなかった。'),
('JPN', '以赛亚书', 23, 47, 8, 'だから今、これを聞け。楽しみにふけり、安心して住む女よ。心の中で、『私だけは特別だ。私はやもめにはならないし、子を失うことも知らなくてすむ』と言う者よ。'),
('JPN', '以赛亚书', 23, 47, 9, '子を失うことと、やもめになること、この二つが一日のうちに、瞬く間にあなたのところにやって来る。あなたがどんなに多く呪術を行っても、どんなに呪文の力が強くとも、これらは突然あなたを見舞う。'),
('JPN', '以赛亚书', 23, 47, 10, 'あなたは自分の悪に拠り頼み、『私を見ている者はいない』と言う。あなたの知恵と知識、これがあなたを迷わせた。だから、あなたは心の中で言う。『私だけは特別だ。』'),
('JPN', '以赛亚书', 23, 47, 11, 'しかし、わざわいがあなたを見舞う。それを払いのける呪文をあなたは知らない。災難があなたを襲うが、あなたはそれを避けることができない。破滅は知らないうちに、突然あなたにやって来る。'),
('JPN', '以赛亚书', 23, 47, 12, 'さあ、若いときからの使い古しの呪文や多くの呪術を使って立ち上がれ。あるいは役立つかもしれない。脅かすことができるかもしれない。'),
('JPN', '以赛亚书', 23, 47, 13, '助言する者が多すぎて、あなたは疲れている。さあ、天を観測する者、星を見る者、あなたに起こることを新月ごとに知らせる者を立たせて、あなたを救わせてみよ。'),
('JPN', '以赛亚书', 23, 47, 14, '見よ。彼らは刈り株のようになり、火が彼らを焼き尽くす。彼らは自分のいのちを炎の手から救い出すこともできない。これは身を暖める炭火でもなく、その前に座れる火でもない。'),
('JPN', '以赛亚书', 23, 47, 15, 'あなたが若いときから仕え、取り引きしてきた者たちは、このようになる。彼らはそれぞれ自分勝手に迷い出る。あなたを救う者は一人もいない。」'),
('JPN', '以赛亚书', 23, 48, 1, 'これを聞け、ヤコブの家よ。あなたはイスラエルの名で呼ばれ、ユダの源から出て、主の御名によって誓い、イスラエルの神を呼び求めるが、真実をもってせず、また正義をもってしない。'),
('JPN', '以赛亚书', 23, 48, 2, '実に彼らは聖なる都の出だと自称し、その名が万軍の主であるイスラエルの神に寄りかかっている。'),
('JPN', '以赛亚书', 23, 48, 3, '「かつて起こったことは、前からわたしが告げていた。それらはわたしの口から出て、わたしはそれらを聞かせた。にわかに、わたしは行い、それは成就した。'),
('JPN', '以赛亚书', 23, 48, 4, 'あなたが頑なであり、首筋は鉄の腱、額は青銅だと知っているので、'),
('JPN', '以赛亚书', 23, 48, 5, 'わたしは、かねてからあなたに告げ、まだ起こらないうちに聞かせたのだ。『私の偶像がこれをした』とか『私の彫像や鋳た像がこれを命じた』とかあなたが言わないようにするためだ。'),
('JPN', '以赛亚书', 23, 48, 6, 'あなたは聞いた。さあ、これらすべてを見よ。あなたがたは告げ知らせないのか。わたしは今から、新しいことを、あなたの知らない秘め事をあなたに聞かせる。'),
('JPN', '以赛亚书', 23, 48, 7, 'それは今、創造された。ずっと前からではない。今日まで、あなたはこれを聞いたこともない。『ああ、私は知っていた』とあなたが言わないようにするためだ。'),
('JPN', '以赛亚书', 23, 48, 8, 'あなたは聞いたこともなく、知っていたこともない。ずっと前から、あなたの耳は開かれていなかった。わたしは、あなたが必ず裏切ることを、母の胎内にいるときから背く者と呼ばれていたことを知っていたからだ。'),
('JPN', '以赛亚书', 23, 48, 9, 'わたしの名のために怒りを遅らせ、わたしの栄誉のためにそれを抑えて、わたしはあなたを絶ち滅ぼさなかった。'),
('JPN', '以赛亚书', 23, 48, 10, '見よ。わたしはあなたを錬ったが、銀のようにではない。わたしは苦しみの炉であなたを試した。'),
('JPN', '以赛亚书', 23, 48, 11, 'わたしのため、わたしのために、わたしはこれを行う。どうしてわたしの名が汚されてよかろうか。わたしの栄光を、ほかの者に与えはしない。'),
('JPN', '以赛亚书', 23, 48, 12, 'わたしに聞け、ヤコブよ。わたしが呼び出したイスラエルよ。わたしがそれだ。わたしが初めであり、また、終わりである。'),
('JPN', '以赛亚书', 23, 48, 13, 'まことに、わたしの手が地の基を定め、わたしの右の手が天を延べ広げた。わたしが呼びかけると、それらはこぞって立ち上がる。'),
('JPN', '以赛亚书', 23, 48, 14, 'みな集まって聞け。彼らのうち、だれがこれらのことを告げたのか。主に愛される者が、主の喜ばれることをバビロンに行う。主の御腕はカルデア人に向かう。'),
('JPN', '以赛亚书', 23, 48, 15, 'わたしが、このわたしが語り、彼を呼んだのだ。わたしは彼を来させ、彼の行うことを成功させる。'),
('JPN', '以赛亚书', 23, 48, 16, 'わたしに近づいて、これを聞け。わたしは初めから、隠れたところでは語らなかった。それが起こったときから、わたしはそこにいた。」今、神である主は、私をその御霊とともに遣わされた。'),
('JPN', '以赛亚书', 23, 48, 17, 'イスラエルの聖なる方、あなたを贖う主はこう言われる。「わたしはあなたの神、主である。わたしはあなたに益になることを教え、あなたの歩むべき道にあなたを導く。'),
('JPN', '以赛亚书', 23, 48, 18, 'あなたがわたしの命令に耳を傾けてさえいれば、あなたの平安は川のように、正義は海の波のようになったであろうに。'),
('JPN', '以赛亚书', 23, 48, 19, 'あなたの子孫は砂のように、あなたの身から出る者は真砂のようになったであろうに。その名はわたしの前から断たれることも、滅ぼされることもなかったであろうに。」'),
('JPN', '以赛亚书', 23, 48, 20, 'バビロンから出よ。カルデアから逃れよ。喜びの声をあげて、これを告げ、聞かせよ。地の果てにまで響き渡らせよ。「主が、そのしもべヤコブを贖われた」と言え。'),
('JPN', '以赛亚书', 23, 48, 21, '主が荒れ果てた地を通らされたときも、彼らは渇くことがなかった。主は彼らのために岩から水を流れ出させ、岩を裂いて水をほとばしり出させられた。'),
('JPN', '以赛亚书', 23, 48, 22, '「悪しき者には平安がない。」主はそう言われる。'),
('JPN', '以赛亚书', 23, 49, 1, '島々よ、私に聞け。遠い国々の民よ、耳を傾けよ。主は、生まれる前から私を召し、母の胎内にいたときから私の名を呼ばれた。'),
('JPN', '以赛亚书', 23, 49, 2, '主は私の口を鋭い剣のようにし、御手の陰に私をかくまい、私を研ぎ澄まされた矢とし、主の矢筒の中に私を隠された。'),
('JPN', '以赛亚书', 23, 49, 3, 'そして、私に言われた。「あなたはわたしのしもべ。イスラエルよ、わたしはあなたのうちに、わたしの栄光を現す。」'),
('JPN', '以赛亚书', 23, 49, 4, 'しかし私は言った。「私は無駄な骨折りをして、いたずらに空しく自分の力を使い果たした。それでも、私の正しい訴えは主とともにあり、私の報いは私の神とともにある。」'),
('JPN', '以赛亚书', 23, 49, 5, '今、主は言われる。ヤコブをご自分のもとに帰らせ、イスラエルをご自分のもとに集めるために、母の胎内で私をご自分のしもべとして形造った方が言われる。私は主の御目に重んじられ、私の神は私の力となられた。'),
('JPN', '以赛亚书', 23, 49, 6, '主は言われる。「あなたがわたしのしもべであるのは、ヤコブの諸部族を立たせ、イスラエルのうちの残されている者たちを帰らせるという、小さなことのためだけではない。わたしはあなたを国々の光とし、地の果てにまでわたしの救いをもたらす者とする。」'),
('JPN', '以赛亚书', 23, 49, 7, 'イスラエルを贖う方、その聖なる方、主は、人に蔑まれている者、国民に忌み嫌われている者に、支配者たちの奴隷に向かってこう言われる。「王たちは見て立ち上がり、首長たちもひれ伏す。真実である主、あなたを選んだイスラエルの聖なる者のゆえに。」'),
('JPN', '以赛亚书', 23, 49, 8, '主はこう言われる。「恵みの時に、わたしはあなたに答え、救いの日に、わたしはあなたを助ける。わたしはあなたを見守り、あなたを民の契約とし、国を復興して、荒れ果てたゆずりの地を受け継がせる。'),
('JPN', '以赛亚书', 23, 49, 9, 'わたしは捕らわれ人には『出よ』と言い、闇の中にいる者には『姿を現せ』と言う。彼らは道すがら羊を飼い、裸の丘のいたるところが彼らの牧場となる。'),
('JPN', '以赛亚书', 23, 49, 10, '彼らは飢えず、渇かず、炎熱も太陽も彼らを打たない。彼らをあわれむ者が彼らを導き、湧き出る水のほとりに連れて行くからだ。'),
('JPN', '以赛亚书', 23, 49, 11, 'わたしは、わたしの山々をすべて道とし、わたしの大路を高くする。'),
('JPN', '以赛亚书', 23, 49, 12, '見よ。ある者は遠くから来る。見よ。ある者は北から西から、また、ある者はシニムの地から来る。」'),
('JPN', '以赛亚书', 23, 49, 13, '天よ、喜びの声をあげよ。地よ、小躍りせよ。山々よ、歓喜の声をあげよ。主がご自分の民を慰め、その苦しむ者をあわれまれるからだ。'),
('JPN', '以赛亚书', 23, 49, 14, 'しかし、シオンは言った。「主は私を見捨てた。主は私を忘れた」と。'),
('JPN', '以赛亚书', 23, 49, 15, '「女が自分の乳飲み子を忘れるだろうか。自分の胎の子をあわれまないだろうか。たとえ女たちが忘れても、このわたしは、あなたを忘れない。'),
('JPN', '以赛亚书', 23, 49, 16, '見よ、わたしは手のひらにあなたを刻んだ。あなたの城壁は、いつもわたしの前にある。'),
('JPN', '以赛亚书', 23, 49, 17, 'あなたの子どもたちは急いでやって来る。あなたを破壊し、廃墟とした者たちは、あなたのところから出て行く。'),
('JPN', '以赛亚书', 23, 49, 18, '目を上げて、あたりを見回せ。彼らはみな集まって、あなたのところに来る。わたしは生きている──主のことば──。あなたは必ず、彼らをみな飾り物として身に着け、花嫁のように彼らを帯に結ぶ。'),
('JPN', '以赛亚书', 23, 49, 19, 'あなたの廃墟と荒れ跡と滅びた地は、今に、住むには狭すぎるようになり、あなたを吞み込んだ者たちは遠くへ離れ去る。'),
('JPN', '以赛亚书', 23, 49, 20, 'あなたが子を失った後に生まれた子らが、再びあなたの耳に言う。『この場所は私には狭すぎる。私が住めるように場所を広くしてください』と。'),
('JPN', '以赛亚书', 23, 49, 21, 'そのとき、あなたは心の中で言うだろう。『だれが私に、この者たちを産んでくれたのだろう。私は子に死なれた女、子を産めない女、捕囚のさすらい人であったのに。だれがこの者たちを育てたのだろう。私は、ただひとり残されていたのに、この者たちはどこから来たのだろう。』」'),
('JPN', '以赛亚书', 23, 49, 22, '神である主はこう言われる。「見よ。わたしは国々に向かって手を上げ、わたしの旗を諸国の民に向かって揚げる。彼らは、あなたの息子たちを懐に抱いて来る。あなたの娘たちは肩に担がれて来る。'),
('JPN', '以赛亚书', 23, 49, 23, '王たちはあなたの世話をする者となり、王妃たちはあなたの乳母となる。彼らは顔を地に付けて、あなたを伏し拝み、あなたの足のちりをなめる。あなたは、わたしが主であることを知る。わたしを待ち望む者は恥を見ることがない。」'),
('JPN', '以赛亚书', 23, 49, 24, '奪われた物を勇士から取り戻せるだろうか。捕らわれ人を横暴な者から救い出せるだろうか。'),
('JPN', '以赛亚书', 23, 49, 25, 'まことに、主はこう言われる。「捕らわれ人は勇士から取り戻され、奪われた物も横暴な者から奪い返される。あなたが争う者と、このわたしが争い、あなたの子らを、このわたしが救う。'),
('JPN', '以赛亚书', 23, 49, 26, 'わたしは、あなたを虐げる者に彼ら自身の肉を食らわせる。彼らは甘いぶどう酒に酔うように、自分自身の血に酔う。すべての肉なる者が、わたしが主、あなたの救い主、あなたの贖い主、ヤコブの力強き者であることを知る。」'),
('JPN', '以赛亚书', 23, 50, 1, '主はこう言われる。「わたしがあなたがたの母を追い出したという離縁状はどこにあるのか。わたしがあなたがたを売ったという、わたしの債権者とはだれなのか。見よ。あなたがたは自分たちの咎のために売られ、自分たちの背きのために、母は追い出されたのだ。'),
('JPN', '以赛亚书', 23, 50, 2, 'なぜ、わたしが来たときだれもいなかったのか。わたしが呼んだのに、だれも答えなかったのか。わたしの手が短くて贖うことができないのか。わたしには救い出す力がないというのか。見よ。わたしは叱って海を干上がらせ、多くの川を荒野とする。その魚は水がなくて臭くなり、渇きのために死に絶える。'),
('JPN', '以赛亚书', 23, 50, 3, 'わたしは天を闇でおおい、粗布をその覆いとする。」'),
('JPN', '以赛亚书', 23, 50, 4, '神である主は、私に弟子の舌を与え、疲れた者をことばで励ますことを教え、朝ごとに私を呼び覚まし、私の耳を呼び覚まして、私が弟子として聞くようにされる。'),
('JPN', '以赛亚书', 23, 50, 5, '神である主は私の耳を開いてくださった。私は逆らわず、うしろに退きもせず、'),
('JPN', '以赛亚书', 23, 50, 6, '打つ者に背中を任せ、ひげを抜く者に頬を任せ、侮辱されても、唾をかけられても、顔を隠さなかった。'),
('JPN', '以赛亚书', 23, 50, 7, 'しかし、神である主は私を助けてくださる。それゆえ、私は侮辱されることがない。それゆえ、私は顔を火打石のようにして自分が恥を見ないことを知っている。'),
('JPN', '以赛亚书', 23, 50, 8, '私を義とする方が近くにいてくださる。だれが私と争うのか。さあ、ともに立とう。だれが私をさばく者となるのか。私のところに出て来るがよい。'),
('JPN', '以赛亚书', 23, 50, 9, '見よ。神である主が私を助けてくださる。だれが私を不義に定めるのか。見よ。彼らはみな衣のように古び、シミが彼らを食い尽くす。'),
('JPN', '以赛亚书', 23, 50, 10, 'あなたがたのうちで主を恐れ、主のしもべの声に聞き従うのはだれか。闇の中を歩くのに光を持たない人は、主の御名に信頼し、自分の神に拠り頼め。'),
('JPN', '以赛亚书', 23, 50, 11, '見よ。あなたがたはみな、火をともし、燃えさしを身に帯びている。あなたがたは自分たちの火の明かりを持ち、火をつけた燃えさしを持って歩くがよい。このことは、わたしの手によってあなたがたに起こり、あなたがたは苦悶の場所で伏し倒れる。'),
('JPN', '以赛亚书', 23, 51, 1, '「義を追い求める者、主を尋ね求める者よ、わたしに聞け。あなたがたが切り出された岩、掘り出された穴に目を留めよ。'),
('JPN', '以赛亚书', 23, 51, 2, 'あなたがたの父アブラハムと、あなたがたを産んだサラのことを考えてみよ。わたしが彼一人を呼び出し、彼を祝福し、彼を増やしたのだ。'),
('JPN', '以赛亚书', 23, 51, 3, 'まことに、主はシオンを慰め、そのすべての廃墟を慰めて、その荒野をエデンのようにし、その砂漠を主の園のようにする。そこには楽しみと喜びがあり、感謝と歌声がある。'),
('JPN', '以赛亚书', 23, 51, 4, 'わたしの民よ、わたしに心を留めよ。わたしの国民よ、わたしに耳を傾けよ。おしえはわたしのもとから出て、わたしが、わたしのさばきを諸国の民の光と定めるからだ。'),
('JPN', '以赛亚书', 23, 51, 5, 'わたしの義は近く、わたしの救いは現れた。わたしの腕は諸国の民をさばく。島々はわたしを待ち望み、わたしの腕に期待をかける。'),
('JPN', '以赛亚书', 23, 51, 6, '目を天に上げよ。また、下の地を見よ。まことに、天は煙のように消え失せ、地も衣のように古びて、その上に住む者はブヨのように死ぬ。しかし、わたしの救いはとこしえに続き、わたしの義は絶えることがない。'),
('JPN', '以赛亚书', 23, 51, 7, '義を知る者たちよ、わたしに聞け。心にわたしのおしえを持つ民よ、人のそしりを恐れるな。彼らの、ののしりにくじけるな。'),
('JPN', '以赛亚书', 23, 51, 8, 'まことに、シミが彼らを衣のように食い尽くし、虫が彼らを羊毛のように食い尽くす。しかし、わたしの義はとこしえに続き、わたしの救いは代々にわたる。」'),
('JPN', '以赛亚书', 23, 51, 9, '目覚めよ、目覚めよ。力をまとえ、主の御腕よ。目覚めよ。昔の日、いにしえの代のように。ラハブを切り刻み、竜を刺し殺したのは、あなたではないか。'),
('JPN', '以赛亚书', 23, 51, 10, '海を、大いなる淵の水を干上がらせ、海の底に道を設けて、贖われた人々が通るようにしたのは、あなたではないか。'),
('JPN', '以赛亚书', 23, 51, 11, '主に贖われた者たちは帰って来る。彼らは喜び歌いながらシオンに入り、その頭には、とこしえの喜びを戴く。楽しみと喜びがついて来て、悲しみと嘆きは逃げ去る。'),
('JPN', '以赛亚书', 23, 51, 12, '「わたし、わたしこそ、あなたがたを慰める者。あなたは何者なのか。死ななければならない人間や、草にも等しい人の子を恐れるとは。'),
('JPN', '以赛亚书', 23, 51, 13, '天を延べ広げ、地の基を定め、あなたを造った主を、あなたは忘れ、一日中、絶えず、虐げる者の憤りにおののいている。まるで滅びに定められているかのように。その虐げる者の憤りはどこにあるのか。'),
('JPN', '以赛亚书', 23, 51, 14, 'うずくまる捕らわれ人もすぐに解き放たれ、死んで穴に下ることはなく、パンにも事欠かない。'),
('JPN', '以赛亚书', 23, 51, 15, 'わたしはあなたの神、主。海をかき立て、波をとどろかせる。その名は万軍の主。'),
('JPN', '以赛亚书', 23, 51, 16, 'わたしのことばをあなたの口に置き、この手の陰にあなたをかばい、天を置き、地の基を定め、『あなたはわたしの民だ』とシオンに言う。」'),
('JPN', '以赛亚书', 23, 51, 17, '目覚めよ、目覚めよ。エルサレムよ、立ち上がれ。あなたは主の手から憤りの杯を飲み、よろめかす大杯を飲み干した。'),
('JPN', '以赛亚书', 23, 51, 18, '彼女が産んだすべての子らのうち、だれも彼女を導く者はなく、彼女が育てたすべての子らのうち、だれも彼女の手を取る者はない。'),
('JPN', '以赛亚书', 23, 51, 19, 'これら二つのことがあなたを見舞った。だれがあなたのために嘆くだろうか。暴行と破滅、飢饉と剣。どのようにして、あなたを慰めようか。'),
('JPN', '以赛亚书', 23, 51, 20, 'あなたの子たちは気を失い、すべての通りで倒れ伏す。網にかかった大かもしかのように。彼らには、主の憤りと、あなたの神のとがめが満ちている。'),
('JPN', '以赛亚书', 23, 51, 21, 'それゆえ、さあ、これを聞け。苦しむ者よ。酔っていても酒のせいでない者よ。'),
('JPN', '以赛亚书', 23, 51, 22, 'あなたの主、ご自分の民を弁護するあなたの神、主はこう言われる。「見よ。わたしはあなたの手から、よろめかす杯を取り上げた。あなたはわたしの憤りの大杯をもう二度と飲むことはない。'),
('JPN', '以赛亚书', 23, 51, 23, 'わたしはこれを、あなたを悩ます者たちの手に渡す。彼らは、かつてあなたに『ひれ伏せ。われわれは乗り越えて行こう』と言った。それで、あなたは背中を地面のように、また歩道のようにして、彼らが乗り越えて行くのに任せた。」'),
('JPN', '以赛亚书', 23, 52, 1, '目覚めよ、目覚めよ。力をまとえ、シオンよ。あなたの美しい衣をまとえ、聖なる都エルサレムよ。無割礼の汚れた者は、もう二度とあなたの中に入っては来ない。'),
('JPN', '以赛亚书', 23, 52, 2, 'ちりを払い落として立ち上がり、元の座に着け、エルサレムよ。あなたの首からかせを振りほどけ、捕らわれの女、娘シオンよ。'),
('JPN', '以赛亚书', 23, 52, 3, 'まことに、主はこう言われる。「あなたがたは、ただで売られた。だから、金を払わずに買い戻される」と。'),
('JPN', '以赛亚书', 23, 52, 4, 'まことに、神である主はこう言われる。「わたしの民は初め、エジプトに下って行って、そこに寄留した。また、アッシリア人がゆえなく彼らを苦しめた。'),
('JPN', '以赛亚书', 23, 52, 5, 'さあ今、ここでわたしは何をしよう──主のことば──。わたしの民はただで奪い取られ、彼らの支配者たちは悲しみ嘆いている──主のことば──。また、わたしの名は一日中、絶えず侮られている。'),
('JPN', '以赛亚书', 23, 52, 6, 'それゆえ、わたしの民はわたしの名を知るようになる。それゆえ、その日彼らは、わたしが『ここにわたしがいる』と告げる者であることを知るようになる。」'),
('JPN', '以赛亚书', 23, 52, 7, '良い知らせを伝える人の足は、山々の上にあって、なんと美しいことか。平和を告げ知らせ、幸いな良い知らせを伝え、救いを告げ知らせ、「あなたの神は王であられる」とシオンに言う人の足は。'),
('JPN', '以赛亚书', 23, 52, 8, 'あなたの見張りの声がする。彼らは声を張り上げ、ともに喜び歌っている。彼らは、主がシオンに戻られるのを目の当たりにするからだ。'),
('JPN', '以赛亚书', 23, 52, 9, 'エルサレムの廃墟よ、ともに大声をあげて喜び歌え。主がその民を慰め、エルサレムを贖われたからだ。'),
('JPN', '以赛亚书', 23, 52, 10, '主はすべての国々の目の前に聖なる御腕を現された。地の果てのすべての者が私たちの神の救いを見る。'),
('JPN', '以赛亚书', 23, 52, 11, '去れ、去れ。そこから出て行け。汚れたものに触れてはならない。その中から出て行き、身を清めよ。主の器を運ぶ者たちよ。'),
('JPN', '以赛亚书', 23, 52, 12, 'あなたがたは慌てて出なくてもよい。逃げるように去らなくてもよい。主があなたがたの前を進み、イスラエルの神がしんがりとなられるからだ。'),
('JPN', '以赛亚书', 23, 52, 13, '「見よ、わたしのしもべは栄える。彼は高められて上げられ、きわめて高くなる。'),
('JPN', '以赛亚书', 23, 52, 14, '多くの者があなたを見て驚き恐れたように、その顔だちは損なわれて人のようではなく、その姿も人の子らとは違っていた。'),
('JPN', '以赛亚书', 23, 52, 15, 'そのように、彼は多くの国々に血を振りまく。王たちは彼の前で口をつぐむ。彼らが告げられていないことを見、聞いたこともないことを悟るからだ。」'),
('JPN', '以赛亚书', 23, 53, 1, '私たちが聞いたことを、だれが信じたか。主の御腕はだれに現れたか。'),
('JPN', '以赛亚书', 23, 53, 2, '彼は主の前に、ひこばえのように生え出た。砂漠の地から出た根のように。彼には見るべき姿も輝きもなく、私たちが慕うような見栄えもない。'),
('JPN', '以赛亚书', 23, 53, 3, '彼は蔑まれ、人々からのけ者にされ、悲しみの人で、病を知っていた。人が顔を背けるほど蔑まれ、私たちも彼を尊ばなかった。'),
('JPN', '以赛亚书', 23, 53, 4, 'まことに、彼は私たちの病を負い、私たちの痛みを担った。それなのに、私たちは思った。神に罰せられ、打たれ、苦しめられたのだと。'),
('JPN', '以赛亚书', 23, 53, 5, 'しかし、彼は私たちの背きのために刺され、私たちの咎のために砕かれたのだ。彼への懲らしめが私たちに平安をもたらし、その打ち傷のゆえに、私たちは癒やされた。'),
('JPN', '以赛亚书', 23, 53, 6, '私たちはみな、羊のようにさまよい、それぞれ自分勝手な道に向かって行った。しかし、主は私たちすべての者の咎を彼に負わせた。'),
('JPN', '以赛亚书', 23, 53, 7, '彼は痛めつけられ、苦しんだ。だが、口を開かない。屠り場に引かれて行く羊のように、毛を刈る者の前で黙っている雌羊のように、彼は口を開かない。'),
('JPN', '以赛亚书', 23, 53, 8, '虐げとさばきによって、彼は取り去られた。彼の時代の者で、だれが思ったことか。彼が私の民の背きのゆえに打たれ、生ける者の地から絶たれたのだと。'),
('JPN', '以赛亚书', 23, 53, 9, '彼の墓は、悪者どもとともに、富む者とともに、その死の時に設けられた。彼は不法を働かず、その口に欺きはなかったが。'),
('JPN', '以赛亚书', 23, 53, 10, 'しかし、彼を砕いて病を負わせることは主のみこころであった。彼が自分のいのちを代償のささげ物とするなら、末長く子孫を見ることができ、主のみこころは彼によって成し遂げられる。'),
('JPN', '以赛亚书', 23, 53, 11, '「彼は自分のたましいの激しい苦しみのあとを見て、満足する。わたしの正しいしもべは、その知識によって多くの人を義とし、彼らの咎を負う。'),
('JPN', '以赛亚书', 23, 53, 12, 'それゆえ、わたしは多くの人を彼に分け与え、彼は強者たちを戦勝品として分かち取る。彼が自分のいのちを死に明け渡し、背いた者たちとともに数えられたからである。彼は多くの人の罪を負い、背いた者たちのために、とりなしをする。」'),
('JPN', '以赛亚书', 23, 54, 1, '「子を産まない不妊の女よ、喜び歌え。産みの苦しみを知らない女よ、喜び叫べ。夫に捨てられた女の子どもは、夫のある女の子どもよりも多いからだ。──主は言われる──'),
('JPN', '以赛亚书', 23, 54, 2, 'あなたの天幕の場所を広げ、住まいの幕を惜しみなく張り、綱を長くし、杭を強固にせよ。'),
('JPN', '以赛亚书', 23, 54, 3, 'あなたは右と左に増え広がり、あなたの子孫は国々を所有し、荒れ果てた町々を人の住む所とするからだ。'),
('JPN', '以赛亚书', 23, 54, 4, '恐れるな。あなたは恥を見ないから。恥じるな。あなたは辱めを受けないから。まことに、あなたは若いときの恥を忘れ、やもめ時代の屈辱を再び思い出すことはない。'),
('JPN', '以赛亚书', 23, 54, 5, 'なぜなら、あなたの夫はあなたを造った者、その名は万軍の主。あなたの贖い主はイスラエルの聖なる者、全地の神と呼ばれているからだ。'),
('JPN', '以赛亚书', 23, 54, 6, '主はあなたを、夫に捨てられた、心に悲しみのある女と呼んだが、若いころの妻をどうして見捨てられるだろうか。──あなたの神は仰せられる──'),
('JPN', '以赛亚书', 23, 54, 7, 'わたしはほんの少しの間、あなたを見捨てたが、大いなるあわれみをもって、あなたを集める。'),
('JPN', '以赛亚书', 23, 54, 8, '怒りがあふれて、少しの間、わたしは、顔をあなたから隠したが、永遠の真実の愛をもって、あなたをあわれむ。──あなたを贖う方、主は言われる。'),
('JPN', '以赛亚书', 23, 54, 9, 'これは、わたしにはノアの日のようだ。ノアの洪水が、再び地にやって来ることはないと、わたしは誓った。そのように、わたしはあなたを怒らず、あなたを責めないと、わたしは誓う。'),
('JPN', '以赛亚书', 23, 54, 10, 'たとえ山が移り、丘が動いても、わたしの真実の愛はあなたから移らず、わたしの平和の契約は動かない。──あなたをあわれむ方、主は言われる。'),
('JPN', '以赛亚书', 23, 54, 11, '苦しめられ、嵐にもてあそばれ、慰められなかった女よ。見よ。わたしはアンチモンであなたの石をおおい、サファイアであなたの基を定める。'),
('JPN', '以赛亚书', 23, 54, 12, 'あなたの塔を紅玉にし、あなたの門をきらめく石にし、あなたの境をすべて宝石にする。'),
('JPN', '以赛亚书', 23, 54, 13, 'あなたの子たちはみな、主によって教えられ、あなたの子たちには豊かな平安がある。'),
('JPN', '以赛亚书', 23, 54, 14, 'あなたは義によって堅く立てられる。虐げから離れていよ。恐れることはない。恐怖から離れていよ。それが近づくことはない。'),
('JPN', '以赛亚书', 23, 54, 15, '見よ。攻め寄せる者があっても、それはわたしから出たのではない。あなたに攻め寄せる者は、あなたの前に倒れる。'),
('JPN', '以赛亚书', 23, 54, 16, '見よ。炭火を吹きおこし武器を作り出す職人を創造したのは、わたしである。それを壊す破壊者を創造したのもわたしである。'),
('JPN', '以赛亚书', 23, 54, 17, 'あなたを攻めるために作られる武器は、どれも役に立たなくなる。また、あなたを責め立てるどんな舌も、さばきのときに、あなたがそれを不義に定める。これが、主のしもべたちの受け継ぐ分、わたしから受ける彼らの義である。──主のことば。」'),
('JPN', '以赛亚书', 23, 55, 1, '「ああ、渇いている者はみな、水を求めて出て来るがよい。金のない者も。さあ、穀物を買って食べよ。さあ、金を払わないで、穀物を買え。代価を払わないで、ぶどう酒と乳を。'),
('JPN', '以赛亚书', 23, 55, 2, 'なぜ、あなたがたは、食糧にもならないもののために金を払い、腹を満たさないもののために労するのか。わたしによく聞き従い、良いものを食べよ。そうすれば、あなたがたは脂肪で元気づく。'),
('JPN', '以赛亚书', 23, 55, 3, '耳を傾け、わたしのところに出て来い。聞け。そうすれば、あなたがたは生きる。わたしはあなたがたと永遠の契約を結ぶ。それは、ダビデへの確かで真実な約束である。'),
('JPN', '以赛亚书', 23, 55, 4, '見よ。わたしは彼を諸国の民への証人とし、諸国の民の君主とし、司令官とした。'),
('JPN', '以赛亚书', 23, 55, 5, '見よ。あなたが、あなたの知らない国民を呼び寄せると、あなたを知らない国民が、あなたのところに走って来る。これは、あなたの神、主、イスラエルの聖なる者のゆえである。主があなたを輝かせたからだ。」'),
('JPN', '以赛亚书', 23, 55, 6, '主を求めよ、お会いできる間に。呼び求めよ、近くにおられるうちに。'),
('JPN', '以赛亚书', 23, 55, 7, '悪しき者は自分の道を、不法者は自分のはかりごとを捨て去れ。主に帰れ。そうすれば、主はあわれんでくださる。私たちの神に帰れ。豊かに赦してくださるから。'),
('JPN', '以赛亚书', 23, 55, 8, '「わたしの思いは、あなたがたの思いと異なり、あなたがたの道は、わたしの道と異なるからだ。──主のことば──'),
('JPN', '以赛亚书', 23, 55, 9, '天が地よりも高いように、わたしの道は、あなたがたの道よりも高く、わたしの思いは、あなたがたの思いよりも高い。'),
('JPN', '以赛亚书', 23, 55, 10, '雨や雪は、天から降って、もとに戻らず、地を潤して物を生えさせ、芽を出させて、種蒔く人に種を与え、食べる人にパンを与える。'),
('JPN', '以赛亚书', 23, 55, 11, 'そのように、わたしの口から出るわたしのことばも、わたしのところに、空しく帰って来ることはない。それは、わたしが望むことを成し遂げ、わたしが言い送ったことを成功させる。'),
('JPN', '以赛亚书', 23, 55, 12, 'まことに、あなたがたは喜びをもって出て行き、平安のうちに導かれて行く。山と丘は、あなたがたの前で喜びの歌声をあげ、野の木々もみな、手を打ち鳴らす。'),
('JPN', '以赛亚书', 23, 55, 13, '茨の代わりに、もみの木が生え、おどろの代わりにミルトスが生える。これは主の記念となり、絶えることのない永遠のしるしとなる。」'),
('JPN', '以赛亚书', 23, 56, 1, '主はこう言われる。「公正を守り、正義を行え。わたしの救いが来るのは近いからだ。わたしの義が現れるのも。」'),
('JPN', '以赛亚书', 23, 56, 2, '幸いなことよ。安息日を守って、これを汚さず、どんな悪事からもその手を守る人は。このように行う人、このことを堅く保つ人の子は。'),
('JPN', '以赛亚书', 23, 56, 3, '主に連なる異国の民は言ってはならない。「主はきっと、私をその民から切り離される」と。宦官も言ってはならない。「ああ、私は枯れ木だ」と。'),
('JPN', '以赛亚书', 23, 56, 4, 'なぜなら、主がこう言われるからだ。「わたしの安息日を守り、わたしの喜ぶことを選び、わたしの契約を堅く保つ宦官たちには、'),
('JPN', '以赛亚书', 23, 56, 5, 'わたしの家、わたしの城壁の内で、息子、娘にもまさる記念の名を与え、絶えることのない永遠の名を与える。'),
('JPN', '以赛亚书', 23, 56, 6, 'また、主に連なって主に仕え、主の名を愛して、そのしもべとなった異国の民が、みな安息日を守ってこれを汚さず、わたしの契約を堅く保つなら、'),
('JPN', '以赛亚书', 23, 56, 7, 'わたしの聖なる山に来させて、わたしの祈りの家で彼らを楽しませる。彼らの全焼のささげ物やいけにえは、わたしの祭壇の上で受け入れられる。なぜならわたしの家は、あらゆる民の祈りの家と呼ばれるからだ。'),
('JPN', '以赛亚书', 23, 56, 8, '──イスラエルの散らされた者たちを集める方、神である主のことば──すでに集められた者たちに、わたしはさらに集めて加える。」'),
('JPN', '以赛亚书', 23, 56, 9, '野のすべての獣よ。やって来て貪り食うがよい。林の中のすべての獣も。'),
('JPN', '以赛亚书', 23, 56, 10, '神の見張り人は目が見えず、みな何も知らない。彼らはみな口のきけない犬、ほえることもできない。あえいで、横になり、眠りを貪る。'),
('JPN', '以赛亚书', 23, 56, 11, 'この犬どもは貪欲で、足ることを知らない。彼らは牧者なのに、悟ることがない。だれもがみな、自分勝手な道に向かって行く。一人残らず、自分の利得に。'),
('JPN', '以赛亚书', 23, 56, 12, '「やって来い。ぶどう酒を持って来るから、強い酒を浴びるほど飲もう。明日も今日と同じだろう。もっと、すばらしいかもしれない。」'),
('JPN', '以赛亚书', 23, 57, 1, '「義人は滅びるが、心に留める者はいない。誠実な人は取り去られるが、気づく者はいない。義人は、わざわいを前にして取り去られる。'),
('JPN', '以赛亚书', 23, 57, 2, 'その人は平安に入り、まっすぐに歩む人は、自分の寝床で休むことができる。'),
('JPN', '以赛亚书', 23, 57, 3, 'しかし、あなたがた、女卜者の子ら、姦夫と遊女の子孫よ。ここに近寄れ。'),
('JPN', '以赛亚书', 23, 57, 4, 'あなたがたは、だれをからかい、だれに向かって口を大きく開き、舌を出すのか。あなたがたは背きの子、偽りの末裔ではないか。'),
('JPN', '以赛亚书', 23, 57, 5, 'あなたがたは、樫の木の間や、青々と茂るあらゆる木の下で、身を焦がし、谷や、岩の裂け目で子どもを屠っているではないか。'),
('JPN', '以赛亚书', 23, 57, 6, '谷川の滑らかな石があなたの分、それら、それらこそが、あなたの受ける割り当て。それらに、あなたは注ぎのぶどう酒を注ぎ、穀物のささげ物を献げているが、こんな物で、わたしが慰められるだろうか。'),
('JPN', '以赛亚书', 23, 57, 7, 'そびえる高い山の上に、あなたは寝床を設け、そこにも上って行って、いけにえを献げた。'),
('JPN', '以赛亚书', 23, 57, 8, 'あなたは、扉と柱のうしろに、自分を記念する像を置いた。あなたはわたしを捨てて裸になり、そこに上って自分の寝床を広げ、彼らと契りを結び、彼らの寝床を愛し、彼らの象徴物を見た。'),
('JPN', '以赛亚书', 23, 57, 9, 'あなたは油を携えて王のところまで旅し、香料を増し加え、使者たちを遠くまで送り出し、よみにまでも下らせた。'),
('JPN', '以赛亚书', 23, 57, 10, 'あなたは、長い旅に疲れても、『あきらめた』とは言わなかった。あなたは元気を回復し、それで弱らなかった。'),
('JPN', '以赛亚书', 23, 57, 11, 'あなたは、だれにおじけ、だれを恐れて、まやかしを言うのか。あなたはわたしのことを思い出さず、心にも留めなかった。わたしが久しく黙っていたので、わたしを恐れないのではないか。'),
('JPN', '以赛亚书', 23, 57, 12, 'わたしは、あなたの義のわざと、あなたの行いの数々を告げよう。しかし、それらはあなたにとって役には立たない。'),
('JPN', '以赛亚书', 23, 57, 13, 'あなたが叫ぶとき、あなたが集めたものどもに、あなたを救わせよ。風が、それらをみな運び去り、もやがそれらを連れ去ってしまう。しかし、わたしに身を寄せる者は、地を受け継ぎ、わたしの聖なる山を所有することができる。'),
('JPN', '以赛亚书', 23, 57, 14, '──主は言われる──盛り上げよ。土を盛り上げて、道を整えよ。わたしの民の道から、つまずきを取り除け。」'),
('JPN', '以赛亚书', 23, 57, 15, 'いと高くあがめられ、永遠の住まいに住み、その名が聖である方が、こう仰せられる。「わたしは、高く聖なる所に住み、砕かれた人、へりくだった人とともに住む。へりくだった人たちの霊を生かし、砕かれた人たちの心を生かすためである。'),
('JPN', '以赛亚书', 23, 57, 16, 'わたしは、永遠に争うことはなく、いつまでも怒ってはいない。わたしから出た霊が衰え果てるからだ。わたしが造ったいのちの息が。'),
('JPN', '以赛亚书', 23, 57, 17, '彼の不正な利得の咎のために、わたしは怒った。わたしは顔を隠して彼を打ち、そして怒った。しかし彼はなお背いて、自分の思う道を行った。'),
('JPN', '以赛亚书', 23, 57, 18, '彼の道を見たが、それでもわたしは彼を癒やす。わたしは彼を導いて、彼とその嘆き悲しむ者たちに、慰めを報いる。'),
('JPN', '以赛亚书', 23, 57, 19, 'わたしは唇の実を創造する者。平安あれ。遠くの者にも近くの者にも平安あれ。わたしは彼を癒やす。──主は言われる──'),
('JPN', '以赛亚书', 23, 57, 20, 'しかし、悪しき者は荒れ狂う海のようだ。まことに、それは鎮まることができず、その水は海草と泥を吐き出す。'),
('JPN', '以赛亚书', 23, 57, 21, '悪しき者には平安がない。──私の神はそう仰せられる。」'),
('JPN', '以赛亚书', 23, 58, 1, '「精一杯大声で叫べ。角笛のように声をあげよ。わたしの民に彼らの背きを、ヤコブの家にその罪を告げよ。'),
('JPN', '以赛亚书', 23, 58, 2, 'このわたしを、彼らは日ごとに求め、わたしの道を知ることを望んでいる。義を行い、神の定めを捨てたことのない国のように、彼らは正しいさばきをわたしに求め、神に近づくことを望んでいる。'),
('JPN', '以赛亚书', 23, 58, 3, '『なぜあなたは、私たちが断食したのに、ご覧にならず、自らを戒めたのに、認めてくださらないのですか。』見よ。あなたがたは断食の日に自分の好むことをし、あなたがたの労働者をみな、追い立てる。'),
('JPN', '以赛亚书', 23, 58, 4, '見よ。あなたがたが断食をするのは、争いとけんかのためであり、不当に拳で殴るためだ。あなたがたが今のように断食するのでは、いと高き所に、その声は届かない。'),
('JPN', '以赛亚书', 23, 58, 5, 'わたしの好む断食、人が自らを戒める日とは、このようなものだろうか。葦のように頭を垂れ、粗布と灰を敷き広げることなのか。これを、あなたがたは断食と呼び、主に喜ばれる日と呼ぶのか。'),
('JPN', '以赛亚书', 23, 58, 6, 'わたしの好む断食とはこれではないか。悪の束縛を解き、くびきの縄目をほどき、虐げられた者たちを自由の身とし、すべてのくびきを砕くことではないか。'),
('JPN', '以赛亚书', 23, 58, 7, '飢えた者にあなたのパンを分け与え、家のない貧しい人々を家に入れ、裸の人を見てこれに着せ、あなたの肉親を顧みることではないか。'),
('JPN', '以赛亚书', 23, 58, 8, 'そのとき、あなたの光が暁のように輝き出て、あなたの回復は速やかに起こる。あなたの義はあなたの前を進み、主の栄光があなたのしんがりとなる。'),
('JPN', '以赛亚书', 23, 58, 9, 'そのとき、あなたが呼ぶと主は答え、あなたが叫び求めると、『わたしはここにいる』と主は言う。もし、あなたの間から、くびきを除き去り、虐げの指をさすことや、邪悪なことばを取り去り、'),
('JPN', '以赛亚书', 23, 58, 10, '飢えた者に心を配り、苦しむ者の願いを満たすなら、あなたの光は闇の中に輝き上り、あなたの暗闇は真昼のようになる。'),
('JPN', '以赛亚书', 23, 58, 11, '主は絶えずあなたを導いて、焼けつく土地でも食欲を満たし、骨を強くする。あなたは、潤された園のように、水の涸れない水源のようになる。'),
('JPN', '以赛亚书', 23, 58, 12, 'あなたのうちのある者は、昔の廃墟を建て直し、あなたは代々にわたる礎を築き直し、『破れを繕う者、通りを住めるように回復する者』と呼ばれる。'),
('JPN', '以赛亚书', 23, 58, 13, 'もし、あなたが安息日に出歩くことをやめ、わたしの聖日に自分の好むことをせず、安息日を『喜びの日』と呼び、主の聖日を『栄えある日』と呼び、これを尊んで、自分の道を行かず、自分の好むことを求めず、無駄口を慎むなら、'),
('JPN', '以赛亚书', 23, 58, 14, 'そのとき、あなたは主をあなたの喜びとする。わたしはあなたに地の高い所を踏み行かせ、あなたの父ヤコブのゆずりの地であなたを養う。──主の御口がそう語られる。」')
on conflict (version, book, chapter, verse) do nothing;
